    if (list.length) {
      warn('登记名互为前缀：' + list.join('、') + '（命中时按最长的那个算；建议把名字改成互不为前缀）');
    }
    return list;
  }
  /* 文字写进 label（.qr--button-label），别覆盖按钮元素本身 */
  function labelTarget(node) {
    try {
      if (node && node.querySelector) {
