        if (l) { return l; }
      }
    } catch (e) { }
    return node;
  }
  function findNode(name) {
    try {
      var nodes = HDOC.querySelectorAll('.qr--button-label, .qr--button, #qr--bar button, [data-qr-button]');
      for (var i = 0; i < nodes.length; i++) {
        /* 这一段文字的「主人」必须是这个按钮：避免把别人的按钮画成自己 */
