    var d = normDef(def);
    if (!d || find(d.name)) { return false; }
    try { (HOST.__hubDefs = HOST.__hubDefs || []).push(def); } catch (e) { }
    BUTTONS.push(d);
    BUTTONS.sort(function (a, b) { return a.order - b.order; });
    ensureButtons();
    bindEvents();
    paint();
    auditNames();
