}

/* ⚠️ 硬规则：对比度四件套三项 !important 在 panel 作用域下 */
html[data-kami-skin="civdawn"] .kami-root[data-kami-comp="panel"] .kami-number,
html[data-kami-skin="civdawn"] .kami-root[data-kami-comp="panel"] .kami-text,
