}

html[data-kami-skin="civdawn"][data-kami-scheme="light"] .kami-root[data-kami-comp="panel"] .kami-number,
html[data-kami-skin="civdawn"][data-kami-scheme="light"] .kami-root[data-kami-comp="panel"] .kami-text,
html[data-kami-skin="civdawn"][data-kami-scheme="light"] .kami-root[data-kami-comp="panel"] .kami-textarea,
