  width: 5.5em;
}

/* 滑杆控件 */
html[data-kami-skin="civdawn"] .kami-range {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 6px;
  border-radius: 3px;
  background-color: var(--kami-card-2);
  border: 1px solid var(--kami-line);
