}
html[data-kami-skin="civdawn"] .kami-range::-webkit-slider-thumb:hover {
  transform: scale(1.15);
}

/* 开关控件 */
html[data-kami-skin="civdawn"] .kami-switch {
  position: relative;
  display: inline-flex;
  align-items: center;
