    radial-gradient(circle at 70% 80%, rgba(0, 0, 0, calc(0.12 * var(--kami-cd-texture-op) / 100)) 1.5px, transparent 1.5px),
    repeating-linear-gradient(45deg, rgba(0, 0, 0, calc(0.02 * var(--kami-cd-texture-op) / 100)) 0 1px, transparent 1px 6px);
