/* 3. ochre：赭红岩彩晕染 */
html[data-kami-skin="civdawn"][data-kami-effects~="ochre"] .kami-item.is-on,
html[data-kami-skin="civdawn"][data-kami-effects~="ochre"] .kami-item[aria-pressed="true"],
