  box-shadow: inset 0 0 0 1px var(--kami-accent), 0 0 calc(var(--kami-glow-size) * 1.5) rgba(217, 101, 59, 0.4);
}

/* 4. ember：燧石微光 */
html[data-kami-skin="civdawn"][data-kami-effects~="ember"] .kami-dot[data-kami-on="1"] {
  box-shadow: 0 0 var(--kami-glow-size) var(--kami-glow), 0 0 calc(var(--kami-glow-size) * 2) rgba(217, 101, 59, 0.3);
