}

/* ==========================================================================
 * 17 · 动画关键帧（@keyframes ≥ 3 个）
 * ======================================================================== */
@keyframes kami-cd-ember-pulse {
  0%, 100% {
    box-shadow: 0 0 4px var(--kami-glow), 0 0 8px var(--kami-glow);
    transform: scale(1);
  }
  50% {
    box-shadow: 0 0 8px var(--kami-glow), 0 0 16px var(--kami-glow);
    transform: scale(1.12);
  }
}

@keyframes kami-cd-carve-in {
  0% {
    opacity: 0;
    transform: translateY(var(--kami-enter-y, 4px));
  }
  100% {
    opacity: 1;
    transform: translateY(0);
  }
}

