  --kami-shadow: 0 10px 26px -10px rgba(0, 0, 0, 0.8), 0 0 0 1px rgba(0, 0, 0, 0.5);
  --kami-shadow-sm: 0 2px 8px rgba(0, 0, 0, 0.5);
  --kami-blur: 0px;              /* CRT 是玻璃，不是毛玻璃：不用 backdrop-filter */

  /* —— 布局与尺寸：方角机身 —— */
  --kami-r-xs: 3px;
  --kami-r-sm: 4px;
  --kami-r-md: 6px;
