  --kami-justify: stretch;

  /* —— 文本与排版：整台机器都是等宽字 —— */
  --kami-fs-scale: 1;
  --kami-fs: calc(14px * var(--kami-fs-scale));
  --kami-fs-xs: calc(var(--kami-fs) * .8);
  --kami-fs-sm: calc(var(--kami-fs) * .9);
  --kami-fs-lg: calc(var(--kami-fs) * 1.15);
  --kami-lh: 1.66;
