  --kami-ls-title: .08em;
  --kami-font: ui-monospace, SFMono-Regular, Menlo, Consolas, "Liberation Mono", "Cascadia Mono", "Microsoft YaHei", monospace;
  --kami-font-title: var(--kami-font);
