}
html[data-kami-skin="grokbot"] .kami-item.is-on .kami-item-main,
html[data-kami-skin="grokbot"] .kami-item[aria-pressed="true"] .kami-item-main {
  color: var(--kami-clay-plate);
  font-weight: 600;
}
html[data-kami-skin="grokbot"] .kami-item.is-on .kami-card-title,
html[data-kami-skin="grokbot"] .kami-item[aria-pressed="true"] .kami-card-title { color: var(--kami-clay-plate); }
html[data-kami-skin="grokbot"] .kami-item.is-on .kami-card-body,
html[data-kami-skin="grokbot"] .kami-item[aria-pressed="true"] .kami-card-body { color: var(--kami-clay-sink); }
/* 选中卡是「反相墨块」（炭面），所以里面徽章的色相要换回**亮级那一套**，
   否则暗级色压在炭面上会掉到 2:1 左右。 */
html[data-kami-skin="grokbot"] .kami-item.is-on,
html[data-kami-skin="grokbot"] .kami-item[aria-pressed="true"] {
  --kami-kind-action: #cb8e6b;
  --kami-kind-fun: #b29b3f;
  --kami-kind-plot: #3daf85;
  --kami-kind-info: #5fa4c7;
  --kami-kind-persona: #be87d5;
  --kami-kind-nsfw: #d484a2;
  --kami-kind-other: #c6c5c1;
}
html[data-kami-skin="grokbot"] .kami-item.is-on .kami-chip,
html[data-kami-skin="grokbot"] .kami-item[aria-pressed="true"] .kami-chip {
  background-color: transparent;
  border-color: var(--kami-clay-line-strong);
  color: var(--kami-clay-sink);
}
/* 面板（炭底）里的选中条目卡：反过来 —— 一块黏土白，炭字。
   底色是浅的，所以徽章的七个色相要换回**暗级那一套**。 */
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] .kami-item.is-on,
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] .kami-item[aria-pressed="true"] {
  background-color: var(--kami-clay-plate-flat);
  border-color: var(--kami-clay-plate-flat);
  color: var(--kami-clay-ink);
  --kami-kind-action: #7f4b2d;
  --kami-kind-fun: #645723;
  --kami-kind-plot: #23634c;
  --kami-kind-info: #2a5d77;
  --kami-kind-persona: #7f379e;
  --kami-kind-nsfw: #963558;
  --kami-kind-other: #3f3f45;
}
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] .kami-item.is-on .kami-item-main,
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] .kami-item[aria-pressed="true"] .kami-item-main,
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] .kami-item.is-on .kami-card-title,
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] .kami-item[aria-pressed="true"] .kami-card-title {
  color: var(--kami-clay-ink);
  font-weight: 600;
}

/* ⚠️ 2026-09-21：原来这里挂着「选中条目卡左缘那两只眼」（一条 10×13 的 ::before +
   给文字让位的 15px 左内边距）。用户裁定删掉，已整段移除，**没有替代画法** ——
   开 / 关两态现在靠三样区分：① 面反相（面板里 白 ⇄ 凹槽灰，实测对白卡 1.30:1 的填充差）；
   ② 边换成墨色（对白卡 15.79:1）；③ 字重 600。前两样是颜色与明度，第三样不是，
   所以「不只靠颜色」这条纪律仍然成立。 */
/* 没选中的条目：字降到「次要」而不是「看不清」，仍然 ≥ 4.5:1 */
html[data-kami-skin="grokbot"] .kami-item[aria-pressed="false"] .kami-item-main { color: var(--kami-fg-dim); }

/* —— 面板里的条目卡：103 张卡看的就是「开着的这张一眼认出来」 —— */
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] .kami-item[aria-pressed="false"] {
  background-color: var(--kami-bg-soft);
  background-image: none;
  border-color: var(--kami-line);
}
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] .kami-item[aria-pressed="false"] .kami-item-main {
  color: var(--kami-fg-dim);
}
/* 非当前模型的条目：锁死。面压住、字仍看得清（对 #202024 是 6.2:1），
   光标与悬停反馈全部收掉，但不整块降透明度（那会把字一起弄糊） */
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] .kami-item[disabled],
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] .kami-item[disabled]:hover,
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] .kami-item[disabled]:active {
  background-color: var(--kami-bg-soft);
  background-image: none;
  border-color: var(--kami-line);
  box-shadow: none;
  transform: none;
  opacity: 1;
  cursor: not-allowed;
}
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] .kami-item[disabled] .kami-item-main { color: var(--kami-fg-mute); }

/* —— 未选中 / 选中的卡片：边界必须看得见（第三处报障）——
   ⚠️ 面板里的卡是**套着**的：`.kami-card > .kami-card-body > .kami-grid > .kami-item.kami-card`，
   而上面那套令牌翻转对**两层都生效** —— 内外两层都吃 --kami-card，翻出来都是 #f2f1ee，
   于是内层卡的填充和外层容器**一模一样**（实测 1.00:1），边又只有 --kami-line 那一档
   （对白卡 1.6:1）—— 整张卡就这么「融」进容器里，用户报的就是这一处。
   （同一份实测里另有一条对照：面板里的皮肤卡单独贴在炭底上时是 16.42:1，看得见；
   问题只出在「卡里的卡」。）

   定调：**一档明度的填充 + 一条看得见的边**，两样都写死成 clay 令牌，不跟着翻转走 ——
     · 未选中：填充 --kami-clay-sink（凹槽那一档）＝对白卡 1.30:1、对炭底 13.00:1；
       边 --kami-clay-line-strong ＝对白卡 5.90:1、对炭底 3.20:1；两种底上都过 3:1。
     · 选中：填充仍是黏土白／墨块，但边改用墨色 --kami-clay-ink（对白卡 15.79:1），
       免得「白卡里的选中卡」也只靠填充差说话。
   开/关两态的差别**不只靠颜色**：选中态另有「字重 600」这一样（2026-09-21 起，
   原来的「左缘两只眼 + 文字左让 15px」已按用户裁定删除）。 */
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] .kami-item[aria-pressed="false"],
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] .kami-item:not(.is-on):not([aria-pressed="true"]),
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] .kami-card .kami-card:not(.is-on):not([aria-pressed="true"]) {
  background-color: var(--kami-clay-sink);
  background-image: none;
  border-color: var(--kami-clay-line-strong);
}
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] .kami-item.is-on,
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] .kami-item[aria-pressed="true"] {
  border-color: var(--kami-clay-ink);
}
/* 引导面板里的「行式开关」也走同一条规矩：关态原来只有 --kami-line（对炭底 1.57:1），
   整行边界等于没有，和背景连成一片。关/开两态的**非颜色**差别另有状态文案
   （已开启 / 已关闭），所以这里只补边界，不动它的高亮。

   ⚠️ 这一条必须带 !important：引导的排版层是 `50-引导.js` 用 `#kami-guide-panel …`
   （带 id）注入的，id 特异性压过任何纯类名选择器，而契约 §4.4 又不许皮肤规则挂面板 id ——
   没有别的杠杆。取值与引导自己给开态描边用的 --kami-accent-line 在暗色下同值（#6e6e78），
   亮色下也同为 #62626a，所以开态外观一点没变，只有关态从 1.57:1 抬到 3.68:1。 */
html[data-kami-skin="grokbot"] .kami-root .kami-guide-switchrow {
  border-color: var(--kami-line-strong) !important;
}

/* 注释入口与注释正文（两块面板共用 —— 不写 #kami-preset-panel，
   否则引导面板里的 ⓘ 吃不到样式，用户已经报过这个不一致） */
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] .kami-card-note[data-kami-note-mark] {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.5em;
  height: 1.5em;
  margin-left: 6px;
  border: var(--kami-border-w) solid var(--kami-line-strong);
  border-radius: var(--kami-r-pill);
  background-color: var(--kami-bg-soft);
  color: var(--kami-fg);
  font-size: var(--kami-fs-xs);
  line-height: 1;
  cursor: pointer;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] .kami-card-note[data-kami-note-mark]:hover,
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] .kami-card-note[data-kami-note-mark]:focus-visible {
  background-color: var(--kami-accent);
  border-color: var(--kami-accent);
  color: var(--kami-accent-fg);
}
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] .kami-card-note[data-kami-note] {
  display: block;
  margin: var(--kami-gap) 0 0;
  /* 注释正文块：圆角 r=8，内边距跟控件那一档走（10/14），
     文字离圆弧 9.7px（上一版写死 8/12，只剩 7.7px）。 */
  padding: var(--kami-pad-y) var(--kami-pad-x);
  border: var(--kami-border-w) solid var(--kami-line);
  border-left: 3px solid var(--kami-accent);
  border-radius: var(--kami-r-xs);
  background-color: var(--kami-card-2);
  color: var(--kami-fg-dim);
  font-size: var(--kami-fs-xs);
  line-height: 1.56;
  white-space: pre-wrap;
  word-break: break-word;
  text-align: left;
}
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] .kami-card-note[data-kami-note][hidden] { display: none; }

html[data-kami-skin="grokbot"] .kami-body { padding: var(--kami-gap-lg) var(--kami-pad-lg-x) var(--kami-pad-lg-y); }
html[data-kami-skin="grokbot"] .kami-root:not([data-kami-comp="panel"]) .kami-body {
  /* 消息楼层里也一样要留出左右内边距（原来这里只改 padding-top，
     左右跟着 .kami-body 的简写走不到，控件直接贴到 blob 的圆角边上）。 */
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x) calc(var(--kami-pad-lg-y) + 2px);
}
html[data-kami-skin="grokbot"] .kami-bar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--kami-gap);
  margin-bottom: var(--kami-gap-lg);
}
html[data-kami-skin="grokbot"] .kami-bar > :last-child { margin-left: auto; }
html[data-kami-skin="grokbot"] .kami-foot {
  display: flex;
  align-items: center;
  gap: var(--kami-gap);
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
  border-top: var(--kami-border-w) solid var(--kami-line);
  font-size: var(--kami-fs-xs);
  color: var(--kami-fg-mute);
}
html[data-kami-skin="grokbot"] .kami-foot > .kami-chip { margin-left: auto; }

/* ==========================================================================
 * 9 · 正文：markdown 白块 / 原文凹槽（全是实色面）
 * ======================================================================== */
html[data-kami-skin="grokbot"] .kami-md {
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
  border: var(--kami-border-w) solid var(--kami-clay-line);
