html[data-kami-skin="grokbot"] .kami-md h1,
html[data-kami-skin="grokbot"] .kami-md h2,
html[data-kami-skin="grokbot"] .kami-md h3,
html[data-kami-skin="grokbot"] .kami-md h4,
html[data-kami-skin="grokbot"] .kami-md h5,
html[data-kami-skin="grokbot"] .kami-md h6 {
  margin: 1em 0 .42em;
  font-family: var(--kami-font-title);
  font-weight: var(--kami-fw-title);
