html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] .kami-md th,
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] .kami-md td { border-color: var(--kami-line); }
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] .kami-md th { background-color: var(--kami-bg-soft); }
