/* ==========================================================================
 * 10 · 表单：滑杆 / 数字框 / 开关（全是实色块）
 * ======================================================================== */
html[data-kami-skin="grokbot"] .kami-field {
  display: flex;
  align-items: center;
  gap: var(--kami-gap);
  padding: var(--kami-pad-y) 0;
