html[data-kami-skin="grokbot"] .kami-field:has(.kami-sub) { align-items: flex-start; }
html[data-kami-skin="grokbot"] .kami-field:has(.kami-sub) > .kami-field-label { flex: 1 1 55%; }
html[data-kami-skin="grokbot"] .kami-field:has(.kami-sub) > .kami-field-value { margin-left: auto; padding-top: 2px; }
html[data-kami-skin="grokbot"] .kami-field-label > .kami-sub { display: block; margin-top: 3px; line-height: 1.5; }
html[data-kami-skin="grokbot"] .kami-field-value { flex: none; display: flex; align-items: center; gap: var(--kami-gap); }
/* 滑杆：一条实色轨道 + 一块实色方块滑块（方块是为了不跟「胶囊化一切」）。
   两套底是反的，所以轨道/已填段也反过来画：
   · 默认（黏土白底，消息楼层）：深色已填段（#212126）+ 浅灰轨道（#73737d）
   · 面板作用域（炭底）：反过来 —— 浅色已填段 + 深一点儿的轨道（见下面那条） */
html[data-kami-skin="grokbot"] .kami-range {
  -webkit-appearance: none;
  appearance: none;
  flex: 0 1 108px;
  width: 108px;
  min-width: 66px;
  height: 34px;
  padding: 0;
  border: 0;
  border-radius: var(--kami-r-pill);
  background-color: transparent;
  background-image:
    linear-gradient(90deg, rgba(33, 33, 38, 1) 0 100%),
    linear-gradient(180deg, rgba(115, 115, 125, 1) 0 100%);
  background-repeat: no-repeat;
  background-position: 9px 50%, 0 50%;
  background-size: calc(var(--kami-value, 0) * (100% - 18px)) 8px, 100% 10px;
  cursor: pointer;
}
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] .kami-range {
  background-image:
    linear-gradient(90deg, rgba(242, 241, 238, 1) 0 100%),
    linear-gradient(180deg, rgba(110, 110, 120, 1) 0 100%);
}
html[data-kami-skin="grokbot"] .kami-range::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 18px;
  height: 22px;
  border: 2px solid var(--kami-bg);
  border-radius: 5px;
  background-color: #f2f1ee;
  box-shadow: none;
}
html[data-kami-skin="grokbot"] .kami-range::-moz-range-track { height: 10px; border-radius: 999px; background-color: #6e6e78; border: 0; }
html[data-kami-skin="grokbot"] .kami-range::-moz-range-progress { height: 8px; border-radius: 999px; background-color: #f2f1ee; }
html[data-kami-skin="grokbot"] .kami-range::-moz-range-thumb {
  width: 18px;
  height: 22px;
  border: 2px solid #131316;
  border-radius: 5px;
  background-color: #f2f1ee;
  box-shadow: none;
}
html[data-kami-skin="grokbot"] .kami-range:focus-visible { outline-offset: 4px; }
/* 数字输入框：实色实心字，绝不与底同色。
   ⚠️ text-align 只作用于**数字框**（2026-09-21 修）：这条规则原来挂在裸类名
   `.kami-number` 上，而压缩面板把同一个类名复用到 select / textarea / 文本框上，
   于是「摘要提示词」的正文与角色下拉全变成右对齐（用户真机报的）。
   现在 `.kami-number` 只给 input[type=number] 用，文本 / 多行 / 下拉各有自己的类。 */
/* 宽度：66 → 88px（2026-09-21 用户裁定「色块皮肤下各变量输入框的宽度变大」）。
   面板里的变量框（🌟 设置变量 / 引导变量页）原来 66px 只够四位数字，看着像个小格子；
   88px 与滑杆（108px）在同一节奏上，五位数字也不挤。 */
html[data-kami-skin="grokbot"] .kami-number {
  width: 88px;
  min-height: var(--kami-row-h);
  padding: var(--kami-pad-y) var(--kami-pad-x);
  border: var(--kami-border-w) solid var(--kami-line-strong);
  border-radius: var(--kami-r-sm);
  background-color: var(--kami-bg-soft);
  color: var(--kami-fg);
  font-family: var(--kami-font-mono);
  font-size: var(--kami-fs-xs);
  box-shadow: none;
}
html[data-kami-skin="grokbot"] input.kami-number[type="number"] { text-align: right; }
html[data-kami-skin="grokbot"] .kami-number:focus-visible { border-color: var(--kami-accent); }

/* —— 单行文本框 / 多行文本框 / 下拉选单（契约 §4.2：.kami-text / .kami-textarea / .kami-select）——
   2026-09-21 新增登记。此前全项目只有压缩面板在造 <textarea> 与 <select>，而六份样式表里
   **一条下拉框规则都没有** —— 真机上就是浏览器默认样式（用户报「所有皮肤都没有下拉选单组件」）。
   下拉必须 `appearance:none` 才有自己的高度与描边，箭头只能自绘（两层线性渐变拼一个 V）。
   宽度不写死：面板的布局层（LAYOUT_CSS）会把它撑满字段行。 */
html[data-kami-skin="grokbot"] .kami-text,
html[data-kami-skin="grokbot"] .kami-textarea,
html[data-kami-skin="grokbot"] .kami-select {
  min-height: var(--kami-row-h);
  padding: var(--kami-pad-y) var(--kami-pad-x);
  text-align: left;
  border: var(--kami-border-w) solid var(--kami-line-strong);
  border-radius: var(--kami-r-sm);
  background-color: var(--kami-bg-soft);
  color: var(--kami-fg);
  font-family: var(--kami-font);
  font-size: var(--kami-fs-sm);
  letter-spacing: var(--kami-ls);
  box-shadow: none;
}
html[data-kami-skin="grokbot"] .kami-textarea { resize: vertical; line-height: 1.6; }
html[data-kami-skin="grokbot"] .kami-text:focus-visible,
html[data-kami-skin="grokbot"] .kami-textarea:focus-visible,
html[data-kami-skin="grokbot"] .kami-select:focus-visible { border-color: var(--kami-accent); }
html[data-kami-skin="grokbot"] .kami-select {
  -webkit-appearance: none;
  appearance: none;
  /* 右侧多留 16px 给自绘箭头，免得长选项压到它身上 */
  padding-right: calc(var(--kami-pad-x) + 16px);
  text-overflow: ellipsis;
  background-image:
    linear-gradient(45deg, rgba(0, 0, 0, 0) 50%, var(--kami-fg-mute) 50%),
    linear-gradient(135deg, var(--kami-fg-mute) 50%, rgba(0, 0, 0, 0) 50%);
  background-repeat: no-repeat;
  background-position: calc(100% - 14px) calc(50% + 1px), calc(100% - 10px) calc(50% + 1px);
  background-size: 4px 4px, 4px 4px;
  cursor: pointer;
}
/* 面板里的数字输入框：契约 §4.4 —— 必须显式写 background-color + color + color-scheme，
   三项都带 !important。酒馆「用户设置 → 自定义 CSS」里
   input[type="number"] { background-color: var(--ui-color-sec) !important } 会盖掉这里的底；
   而皮肤头部 .kami-root input { color: inherit } 会把字压成次要色。
   多块面板共用同一个 <input class="kami-number">，一条 panel 作用域规则同时命中。
   实测：字 #ecebe8 压底 #202024 = 11.4:1（这是一度「底与字相近」的那一处）。
   ⚠️ 2026-09-21：选择器扩到 `.kami-text` / `.kami-textarea` / `.kami-select` ——
   用户自定义 CSS 对 select 与 textarea 各有一条 !important 深漆，漏一类就是黑底黑字。
   这里用的是 `background-color` 而不是 `background` 简写：简写会把上面 `.kami-select`
   自绘箭头的 background-image 一起重置掉。 */
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] input.kami-number,
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] input.kami-text,
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] textarea.kami-textarea,
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] select.kami-select {
  color: var(--kami-fg) !important;
  background-color: var(--kami-bg-soft) !important;
  border-color: var(--kami-line-strong) !important;
  color-scheme: dark !important;
}
/* 开关：轨道 + 旋钮。关着＝钮在左、轨道是凹槽；开着＝钮移到右端、轨道变黏土白。
   2026-09-21 起轨道里那枚「小斜胶囊 / 两只黑眼睛」整段删除（用户裁定一处不留），
   开 / 关只靠**钮的位置**这一样非颜色差别，加上轨道明度与描边。 */
html[data-kami-skin="grokbot"] .kami-switch { position: relative; display: inline-flex; align-items: center; cursor: pointer; }
html[data-kami-skin="grokbot"] .kami-switch-input {
  position: absolute;
  left: 0;
  top: 0;
  width: 100%;
  height: 100%;
  opacity: 0;
  pointer-events: none;
}
html[data-kami-skin="grokbot"] .kami-switch-track {
  position: relative;
  display: block;
  width: 52px;
  height: 30px;
  border: var(--kami-border-w) solid var(--kami-line-strong);
  border-radius: var(--kami-r-pill);
  background-color: var(--kami-bg-soft);
  background-image: none;
  box-shadow: none;
  transition: background-color var(--kami-dur) var(--kami-ease), border-color var(--kami-dur) var(--kami-ease);
}
html[data-kami-skin="grokbot"] .kami-switch-knob {
  position: absolute;
  left: 3px;
  top: 3px;
  width: 22px;
  height: 22px;
  /* 旋钮给一条 --kami-line-strong 的实线边（亮面上的白钮压在浅轨上时，
     只靠填充差只有 1.29:1，等于没画；这条边让「钮在哪」在任何一档底上都看得见：
     对深轨 3.2:1、对浅轨 4.5:1）。平面皮肤的分界只靠实线，这里也一样。
     形状是**圆角方块**，不是胶囊：滑块（range）用的也是方块，两处一致。 */
  border: 2px solid var(--kami-line-strong);
  border-radius: 6px;
  background-color: #f2f1ee;
  background-image: none;
  box-shadow: none;
  transition: transform var(--kami-dur) var(--kami-ease);
}
html[data-kami-skin="grokbot"] .kami-switch-input:checked + .kami-switch-track {
  background-color: var(--kami-accent);
  border-color: var(--kami-accent);
}
html[data-kami-skin="grokbot"] .kami-switch-input:checked + .kami-switch-track .kami-switch-knob {
  background-color: var(--kami-accent-fg);
  transform: translateX(22px);
}
html[data-kami-skin="grokbot"] .kami-switch-input:focus-visible + .kami-switch-track {
  outline: 2px solid var(--kami-accent);
  outline-offset: 2px;
}
html[data-kami-skin="grokbot"] .kami-root:not([data-kami-comp="panel"]) .kami-switch-track {
  background-color: var(--kami-clay-sink);
  border-color: var(--kami-clay-line-strong);
}
html[data-kami-skin="grokbot"] .kami-root:not([data-kami-comp="panel"]) .kami-switch-input:checked + .kami-switch-track {
  background-color: var(--kami-clay-choice);
  border-color: var(--kami-clay-choice);
}
html[data-kami-skin="grokbot"] .kami-root:not([data-kami-comp="panel"]) .kami-switch-input:checked + .kami-switch-track .kami-switch-knob {
  background-color: var(--kami-clay-plate);
}

/* ==========================================================================
 * 11 · 标签页：实色胶囊片，选中＝反相墨块
 * ======================================================================== */
html[data-kami-skin="grokbot"] .kami-tabs {
  display: flex;
  flex: 0 0 auto;
  min-height: 48px;
  gap: var(--kami-gap);
  padding: 0 var(--kami-pad-lg-x);
  border-bottom: var(--kami-border-w) solid var(--kami-line);
  background-color: transparent;
  overflow-x: auto;
  scrollbar-width: none;
}
html[data-kami-skin="grokbot"] .kami-tabs::-webkit-scrollbar { display: none; }
html[data-kami-skin="grokbot"] .kami-tab {
  flex: none;
  position: relative;
  margin: 8px 0;
  padding: 0 14px;
  min-height: 32px;
  border: 0;
  border-radius: var(--kami-r-pill);
  background-color: transparent;
  color: var(--kami-fg-dim);
  font-size: var(--kami-fs-sm);
  letter-spacing: var(--kami-ls);
  cursor: pointer;
  transition: color var(--kami-dur-fast) var(--kami-ease), background-color var(--kami-dur-fast) var(--kami-ease);
}
@media (hover: hover) {
  html[data-kami-skin="grokbot"] .kami-tab:hover { background-color: var(--kami-bg-soft); color: var(--kami-fg); }
}
/* 选中＝反相墨块 + 字加粗（形状与字重都变，不只靠颜色） */
html[data-kami-skin="grokbot"] .kami-tab[aria-selected="true"] {
  background-color: var(--kami-accent);
  color: var(--kami-accent-fg);
  font-weight: var(--kami-fw-title);
}

/* ==========================================================================
 * 12 · 面板与抽屉：炭黑底板 + 1px 实线
 * ======================================================================== */
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] .kami-drop {
  display: flex;
  flex-direction: column;
  overflow: hidden;
  pointer-events: auto;
}
html[data-kami-skin="grokbot"] .kami-drop > .kami-body { flex: 1 1 auto; min-height: 0; }
html[data-kami-skin="grokbot"] .kami-drop > .kami-head,
html[data-kami-skin="grokbot"] .kami-drop > .kami-tabs,
html[data-kami-skin="grokbot"] .kami-drop > .kami-foot { flex: 0 0 auto; }
/* 四段的左右内边距都等于 --kami-pad-lg-x，于是对齐成一条竖线 */
html[data-kami-skin="grokbot"] .kami-drop > .kami-head { padding-left: var(--kami-pad-lg-x); padding-right: var(--kami-pad-lg-x); }
html[data-kami-skin="grokbot"] .kami-drop > .kami-tabs { padding-left: var(--kami-pad-lg-x); padding-right: var(--kami-pad-lg-x); }
html[data-kami-skin="grokbot"] .kami-drop > .kami-body { padding-left: var(--kami-pad-lg-x); padding-right: var(--kami-pad-lg-x); }
html[data-kami-skin="grokbot"] .kami-drop > .kami-foot { padding-left: var(--kami-pad-lg-x); padding-right: var(--kami-pad-lg-x); }
html[data-kami-skin="grokbot"] .kami-drop > .kami-foot .kami-sub { margin-left: 0; }
html[data-kami-skin="grokbot"] .kami-drop .kami-card { margin-bottom: var(--kami-gap-lg); }
html[data-kami-skin="grokbot"] .kami-drop .kami-card:last-child { margin-bottom: 0; }
html[data-kami-skin="grokbot"] .kami-drop .kami-collapse-head { gap: var(--kami-gap); margin-bottom: 2px; }
html[data-kami-skin="grokbot"] .kami-drop .kami-card-note + .kami-card-note { margin-top: 2px; }

/* —— 面板里卡片的**内边距**（2026-09-21 用户报障后重做）——
   ⚠️ 用户原话：「皮肤管理面板内显示下面的条状容器内的内容边距太小，这个问题也存在于
   预设设置面板与压缩面板里，几乎所有的卡片内边距都很小」。量出来的账：
     · 行动选项前端（消息楼层）的卡片 = 16 / 20，文字墨水盒离圆角内缘 **15.3px**（用户说舒服的就是它）；
     · 面板里的 `.kami-card` 被一条 `padding: 0` 的覆盖规则压平 → 余量 **-4.7px**（文字贴在圆角上）；
     · 「显示」那张条状容器更惨：卡没有内边距，行只剩 `.kami-field` 自己那 **左右各 2px**，
       标签离卡左缘实测 2.6px。
   → 清零那条**删掉**，卡片吃回 `.kami-card` 基线的 16 / 20；字段行不再自己补内边距；
     卡头 / 卡标题 / 注释正文也不再各补一层（那是给「没有内边距的卡」打的补丁，现在多余）。

   ⚠️ **例外**：卡里直接装着**条目网格**的（🌟 的卡片组与模型卡、引导模型页的模型卡）。
   2026-09-21 用户二次报障：「预设面板和引导面板模型页的卡片内部卡片就和父容器卡片没有内边距」
   —— 原因是这条例外当初写成了 `padding-left/right: 0`，卡里的条目卡直接贴到卡边
   （引导模型页实测：卡 442px、卡内条目卡离卡左缘 **1px**）。
   现在**不归零，只收一档到 12px**（4px 阶梯里的 12，和条目卡自己的内边距同值，节奏一致）：
   这样卡边有肉、条目网格又不会因为再收一层而被挤成竖排名字。 */
html[data-kami-skin="grokbot"] .kami-drop .kami-card:has(> .kami-card-body > .kami-grid) {
  padding-left: 12px;
  padding-right: 12px;
}
/* 这类卡的卡头 / 卡标题 / 注释正文不再自己补**左右**内边距（卡已经给了 12px）；
   上下仍由卡自己的 padding 与各段自己的 margin 管。 */
html[data-kami-skin="grokbot"] .kami-drop .kami-card:not(.kami-item):has(> .kami-card-body > .kami-grid) > .kami-card-head,
html[data-kami-skin="grokbot"] .kami-drop .kami-card:not(.kami-item):has(> .kami-card-body > .kami-grid) > .kami-card-title {
  padding-left: 0;
  padding-right: 0;
}
html[data-kami-skin="grokbot"] .kami-drop .kami-card:not(.kami-item):has(> .kami-card-body > .kami-grid) > .kami-card-note {
  padding-left: 0;
  padding-right: 0;
}
html[data-kami-skin="grokbot"] .kami-drop .kami-card > .kami-card-body:has(> .kami-grid) {
  padding-top: var(--kami-gap-lg);
  padding-bottom: 0;
}

/* —— 卡内卡的「标题栏」（2026-09-21 用户报「卡片有标题栏 / 卡内卡时特别丑」）——
   病根：模型卡的卡头是 `button.kami-card-head.kami-btn.kami-btn--ghost`，而 `.kami-btn`
   是一条**胶囊**（r=999px）＋ 居中对齐 ＋ 宽度按内容收缩 —— 于是它变成一枚悬在方形白卡
   里的小药丸：实测卡宽 369px、卡头只有 267px 宽、右边空掉 100px，跟整张卡的矩形语言
   完全不搭；卡里再套一层同样圆角、同样颜色的条目卡，就成了「三层圆角套娃」。
   定调：面板里的卡头一律做成**与卡同宽的矩形标题条** —— 小圆角、左对齐、满宽、
   铺一层凹槽底色（未选中）/ 墨块（选中），字由上面那对令牌翻过来。 */
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] button.kami-card-head.kami-btn {
  width: 100%;
  min-height: 0;
  justify-content: flex-start;
  text-align: left;
  border-radius: var(--kami-r-sm);
  background-color: var(--kami-clay-sink);
  border-color: var(--kami-clay-line);
  color: var(--kami-clay-ink);
}
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] button.kami-card-head.kami-btn.is-on,
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] button.kami-card-head.kami-btn[aria-pressed="true"] {
  background-color: var(--kami-clay-ink);
  border-color: var(--kami-clay-ink);
  color: var(--kami-clay-plate);
}
/* 标题条里的计数 chip：底色跟标题条一样会「融」进去，改成透明底 + 随字色的边 */
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] button.kami-card-head.kami-btn .kami-chip {
  background-color: transparent;
  border-color: currentColor;
  color: inherit;
}
/* ── 卡头里那枚标题（2026-09-26 用户报「模型卡片标题栏被选中是黑底黑字，完全看不清」）──
   病因：`.kami-item.is-on .kami-card-title { color: var(--kami-clay-ink) }`（墨）
   与卡头自己的底 `.kami-card-head.is-on { background-color: var(--kami-clay-ink) }`（也是墨）
   撞在一起 —— 实测 1.0:1。**不是这一轮新引入的**：面板里 clay 一族一直是浅色那套，
   这两条从写下那天就互相抵消，只是没人盯过模型页那一栏。
   另一处是这一轮带出来的：暗色下消息楼层不再翻黏土白之后，**未选中**的卡头标题吃的是
   `--kami-fg`（白），压在卡头的 `--kami-clay-sink`（浅灰）上 → 1.05:1，同样看不见。
   修法：卡头里的标题**不再让那两条通用规则决定颜色**，直接按卡头自己那一对来 ——
   未选中＝浅槽底＋墨字，选中＝墨底＋黏土白字。两条都用明确令牌，不依赖继承与翻转。 */
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] button.kami-card-head.kami-btn .kami-card-title {
  color: var(--kami-clay-ink);
}
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] button.kami-card-head.kami-btn.is-on .kami-card-title,
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] button.kami-card-head.kami-btn[aria-pressed="true"] .kami-card-title {
  color: var(--kami-clay-plate);
}
/* 卡内卡的层级：外层卡 r=16，卡里的条目卡收到 r=12，两层不再同形同色 */
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] .kami-card .kami-card:not(.kami-card-head) {
  border-radius: var(--kami-r-sm);
}
/* 贴底抽屉：几何由脚本下发（data-kami-layout="sheet"），皮肤补一个抓手与上圆下方 */
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] .kami-drop[data-kami-layout="sheet"] {
  border-radius: var(--kami-panel-r) var(--kami-panel-r) 0 0;
  border-bottom: 0;
}
html[data-kami-skin="grokbot"] .kami-drop[data-kami-layout="sheet"] > .kami-head { padding-top: calc(var(--kami-pad-lg-y) + 10px); }
html[data-kami-skin="grokbot"] .kami-drop[data-kami-layout="sheet"] > .kami-head::before {
  content: "";
  position: absolute;
  left: 50%;
  top: 8px;
  width: 44px;
  height: 4px;
  margin-left: -22px;
  border-radius: var(--kami-r-pill);
  background-color: var(--kami-line-strong);
}
html[data-kami-skin="grokbot"] .kami-drop[data-kami-layout="sheet"] .kami-resize { display: none; }
html[data-kami-skin="grokbot"] .kami-resize {
  position: absolute;
  right: 0;
  bottom: 0;
  width: 24px;
  height: 24px;
  cursor: nwse-resize;
  background-image: repeating-linear-gradient(135deg, var(--kami-line-strong) 0 2px, rgba(0, 0, 0, 0) 2px 6px);
  background-repeat: no-repeat;
  background-position: 100% 100%;
  background-size: 16px 16px;
}
html[data-kami-skin="grokbot"] .kami-scroll {
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: var(--kami-line-strong) transparent;
}
html[data-kami-skin="grokbot"] .kami-scroll::-webkit-scrollbar { width: 10px; height: 10px; }
html[data-kami-skin="grokbot"] .kami-scroll::-webkit-scrollbar-track { background-color: transparent; }
html[data-kami-skin="grokbot"] .kami-scroll::-webkit-scrollbar-thumb {
  border: 3px solid rgba(0, 0, 0, 0);
  border-radius: var(--kami-r-pill);
  background-color: var(--kami-line-strong);
  background-clip: content-box;
}
/* 条目密集的面板（一屏上百张卡）：列宽收到 100px，图标 + 名字刚好两行。
   条件写成**结构条件**「网格里直接装着条目卡」，不是面板 id ——
   皮肤管理面板的网格里装的是 .kami-card，所以不会跟着被压窄。
   ⚠️ 2026-09-21 修：条件原来只认 `> .kami-item`，而**带注释的条目卡外面多包了一层
   `.kami-item-note`**（src/scripts/_preset-cards.js 的 buildItemCard），直接子元素
   就不是 .kami-item 了 —— 于是「一组里每张卡都带注释」的网格判据落空，退回
   `--kami-items-min: 15rem`，367px 的宽度只排得下**一列**。用户报的
   「带注释说明的卡片都是单列」就是这一处：预览台探针实测那一格是
   「367px → 1 列 卡367x53 间距12」，同一页另外八个网格都是「3 列 卡117」。
   修法是把两种直接子元素都算进来（结构判据不变，仍然不挂面板 id）。 */
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] .kami-grid:has(> .kami-item, > .kami-item-note) {
  --kami-items-min: 100px;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, var(--kami-items-min)), 1fr));
  gap: var(--kami-gap);
}
/* 注释外包层（契约 §4.2）：网格里占满一格，条目卡在上、注释正文在下。
   .kami-item-note 自己没有内边距，但**是网格项**，所以要显式声明列宽行为
   （min-width:0 免得长注释把格子撑破）。 */
html[data-kami-skin="grokbot"] .kami-root .kami-item-note {
  display: flex;
  flex-direction: column;
  min-width: 0;
}
/* 注释正文与它上面那张卡之间只留 4px：原来是「卡片底 0 + 注释 margin-top 8」，
   用户报「注释和卡片本体距离太远」。 */
html[data-kami-skin="grokbot"] .kami-root .kami-item-note > .kami-card-note[data-kami-note] {
  margin-top: 4px;
}
/* 条目卡的内部间距：四周 12px（4px 阶梯：10 → 12，圆角 r=16 时文字离圆弧 7.3px），
   卡与卡之间 8px。2026-09-21 试过抬到 14，但条目卡在面板里只有 117px 宽，
   再收 4px 会把「DS/GLM底部破限」这类名字多折一行 —— 保持 12，靠外面那层
   卡片内边距（16/20）来给整块网格留呼吸。 */
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] .kami-item {
  padding: 12px;
  min-height: 44px;
}
/* 条目名角标（emoji）：从名字里摘出来钉在卡角，只占高度不占宽度。
   条件同样是结构条件：只有带 data-kami-corner 的徽章才进角标模式，
   否则普通 kind 徽章会被一并绝对定位到卡角上。 */
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] .kami-item.kami-card { position: relative; }
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] .kami-item > .kami-badge[data-kami-corner] {
  position: absolute;
  top: 6px;
  right: 6px;
  left: auto;
  z-index: 2;
  padding: 0;
  border: 0;
  border-radius: 0;
  background-color: transparent;
  background-image: none;
  font-size: var(--kami-fs-xs);
  line-height: 1.2;
  letter-spacing: 0;
  color: var(--kami-fg-dim);
  pointer-events: none;
}
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] .kami-item > .kami-badge[data-kami-corner="tl"],
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] .kami-item > .kami-badge[data-kami-corner="bl"] {
  right: auto;
  left: 6px;
}
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] .kami-item > .kami-badge[data-kami-corner="br"],
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] .kami-item > .kami-badge[data-kami-corner="bl"] {
  top: auto;
  bottom: 6px;
}
/* 让出高度：1.4em 取的是**卡片**的字号（--kami-fs-sm），ⓘ 的 1.4em 取的是它自己的
   --kami-fs-xs；fs-sm > fs-xs，所以这一项必然盖过角标本体的高，再加 --kami-pad-y
   盖过角标的 top 偏移 —— 紧凑密度档（pad-y 8px）下也仍然成立。
   旧值 calc(12px + .5em) 只给到 18.75px，而 ⓘ 从 top:6px 起占 18px（底边 24px），
   实测还剩 12 × 5.3 = 63px² 压在条目名上（2026-09-25 修）。 */
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] .kami-item:has(> .kami-badge[data-kami-corner="tl"], > .kami-badge[data-kami-corner="tr"], > .kami-card-note[data-kami-corner="tr"]) {
  padding-top: calc(var(--kami-pad-y) + 1.4em);
}
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] .kami-item:has(> .kami-badge[data-kami-corner="bl"], > .kami-badge[data-kami-corner="br"]) {
  padding-bottom: calc(var(--kami-pad-y) + 1.4em);
}

/* ==========================================================================
 * 13 · 空态 / 内联提示 / 皮肤预览缩略
 * ======================================================================== */
html[data-kami-skin="grokbot"] .kami-empty {
  position: relative;
  margin: var(--kami-gap) 0;
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x) var(--kami-pad-lg-y) calc(var(--kami-pad-lg-x) + 18px);
  border: var(--kami-border-w) dashed var(--kami-line-strong);
  border-radius: var(--kami-r-md);
  background-color: transparent;
  color: var(--kami-fg-dim);
  font-size: var(--kami-fs-sm);
  box-shadow: none;
}
/* 空态那一枚：一小块实心圆角方块（原来是「还没睁开的单眼」，2026-09-21 删） */
html[data-kami-skin="grokbot"] .kami-empty::before {
  content: "";
  position: absolute;
  left: var(--kami-pad-lg-x);
  top: 50%;
  width: 5px;
  height: 11px;
  margin-top: -5.5px;
  border-radius: 1.5px;
  background-color: var(--kami-fg-mute);
}
html[data-kami-skin="grokbot"] .kami-toast {
  position: relative;
  margin: 0 var(--kami-pad-lg-x) var(--kami-pad-lg-y);
  padding: var(--kami-pad-y) var(--kami-pad-x);
  border: var(--kami-border-w) solid var(--kami-line-strong);
  border-radius: var(--kami-r-sm);
  background-color: var(--kami-card);
  color: var(--kami-fg);
  font-size: var(--kami-fs-xs);
  letter-spacing: .02em;
  box-shadow: none;
  animation: kami-grokbot-unseal var(--kami-dur) var(--kami-ease-out) both;
}
html[data-kami-skin="grokbot"] .kami-toast.is-bad {
  color: var(--kami-warn);
  border-color: var(--kami-warn);
  background-color: var(--kami-card);
}
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] .kami-toast { margin: 0 0 var(--kami-gap-lg); }
html[data-kami-skin="grokbot"] .kami-preview {
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  gap: 5px;
  aspect-ratio: 16 / 7;
  margin-top: var(--kami-gap-lg);
  padding: 10px;
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-md);
  background-color: var(--kami-bg-soft);
  background-image: none;
  box-shadow: none;
  overflow: hidden;
}
html[data-kami-skin="grokbot"] .kami-preview i {
  display: block;
  height: 5px;
  border-radius: var(--kami-r-pill);
  background-color: var(--kami-line-strong);
}
/* 缩略图：一块白 blob 压在凹槽上。原来右下角还画了参考图那张脸的两只黑眼睛，
   2026-09-21 按用户裁定整段删除（一处不留）。 */
html[data-kami-skin="grokbot"] .kami-preview i:first-child {
  width: 58%;
  height: 10px;
  border-radius: 8px 6px 9px 5px / 7px 5px 8px 6px;
  background-color: var(--kami-clay-plate);
}
html[data-kami-skin="grokbot"] .kami-preview i:nth-child(2) { width: 80%; }
html[data-kami-skin="grokbot"] .kami-preview i:nth-child(3) { width: 66%; }
html[data-kami-skin="grokbot"] .kami-preview i:nth-child(4) { width: 40%; }
html[data-kami-skin="grokbot"] .kami-card.is-on,
html[data-kami-skin="grokbot"] .kami-card[aria-pressed="true"] {
  border-color: var(--kami-accent);
  box-shadow: inset 0 0 0 1px var(--kami-accent);
}
/* 「使用中 / 当前」那一枚小胶囊：这是整套皮肤唯一一处把颜色当状态用的地方
   （焦点环是另一处）。青玉对卡面 #1e1e22 = 5.6:1，够 4.5。 */
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] .kami-card.is-on .kami-chip,
html[data-kami-skin="grokbot"] .kami-root[data-kami-comp="panel"] .kami-card[aria-pressed="true"] .kami-chip {
  color: var(--kami-kind-focus);
  border-color: var(--kami-kind-focus);
}

/* ==========================================================================
 * 14 · 高级特效（平面皮肤：三条都是「多画一块实色 / 一条实线」，不是光影）
 * ======================================================================== */

/* —— grain · 色块颗粒：四个实心点状 radial-gradient 拼出的哑光噪点 ——
   不用 url()、不用 SVG 滤镜；静态、零运行时；只作用在 .kami-surface。 */
html[data-kami-skin="grokbot"][data-kami-effects~="grain"] .kami-root .kami-surface {
  background-image: var(--kami-texture);
  background-repeat: repeat;
  background-size: 27px 27px, 31px 31px, 23px 23px, 37px 37px;
  background-position: 0 0, 9px 13px, 17px 5px, 5px 21px;
}
html[data-kami-skin="grokbot"][data-kami-effects~="grain"] .kami-root .kami-shell.kami-surface {
  background-image: var(--kami-texture);
  background-repeat: repeat;
  background-size: 27px 27px, 31px 31px, 23px 23px, 37px 37px;
  background-position: 0 0, 9px 13px, 17px 5px, 5px 21px;
}
html[data-kami-skin="grokbot"][data-kami-effects~="grain"] .kami-root[data-kami-comp="panel"] .kami-drop.kami-surface {
  background-image: var(--kami-texture);
}

/* —— sheen · 顶部描边：参考图那圈「上方亮一线」的边缘，用一条 1px 硬边做出来 ——
   滑杆 --kami-gb-sheen 调它的不透明度（0 = 关掉）。 */
html[data-kami-skin="grokbot"][data-kami-effects~="sheen"] .kami-root .kami-surface {
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, calc(var(--kami-gb-sheen) / 100));
}
html[data-kami-skin="grokbot"][data-kami-effects~="sheen"] .kami-root[data-kami-comp="panel"] .kami-drop.kami-surface {
  box-shadow:
    var(--kami-shadow),
    inset 0 1px 0 rgba(255, 255, 255, calc(var(--kami-gb-sheen) / 100));
}
html[data-kami-skin="grokbot"][data-kami-effects~="sheen"] .kami-root:not([data-kami-comp="panel"]) .kami-shell.kami-surface {
  box-shadow:
    var(--kami-shadow),
    inset 0 1px 0 rgba(255, 255, 255, calc(var(--kami-gb-sheen) / 100));
}

/* —— breathe · 团子喘气：承载面整体极慢地涨缩一点点（只动 transform） ——
   幅度走滑杆 --kami-gb-breathe（%）：0 = 不动，100 = 1.012 倍。
   ⚠️ 这个令牌此前**只登记在 skin.json 里、CSS 既没给默认值也没消费**，滑杆拖了没反应
   （.audit/check-skin.mjs 的 params.breathe.token 报 FAIL）。2026-09-25 补上默认值与
   var() 消费；55（默认值）→ scale 1.0066，与原来写死的 1.006 基本一致，观感不变。 */
html[data-kami-skin="grokbot"][data-kami-effects~="breathe"] .kami-root .kami-surface {
  transform-origin: 50% 62%;
  animation: kami-grokbot-breathe 7.4s var(--kami-ease) infinite;
}

/* ==========================================================================
 * 15 · 关键帧
 * ======================================================================== */
@keyframes kami-grokbot-breathe {
  0%, 100% { transform: scale(1); }
  46% { transform: scale(calc(1 + var(--kami-gb-breathe) / 100 * .012)); }
}
@keyframes kami-grokbot-unseal {
  from { opacity: 0; transform: translateY(calc(var(--kami-enter-y) * -1)) scale(var(--kami-enter-scale)); }
  to { opacity: 1; transform: none; }
}
@keyframes kami-grokbot-pop {
  0% { transform: scale(1); }
  44% { transform: scale(1.03); }
  100% { transform: scale(1); }
}

/* ==========================================================================
 * 16 · 密度档位
 * --------------------------------------------------------------------------
 * 三档同样走 4px 阶梯，只是起点不同：宽松 18/12 与 24/20 ＞ 舒适 14/10 与 20/16
 * ＞ 紧凑 12/8 与 16/12。**每一档的容器内边距都不低于 12px**，
 * 也就是「文字离圆角」在紧凑档也仍然成立（圆角 r=16 时余量 ≥11px）。
 * ======================================================================== */
html[data-kami-skin="grokbot"][data-kami-density="compact"] .kami-root {
  --kami-pad-x: 12px;
  --kami-pad-y: 8px;
  --kami-pad-lg-x: 16px;
  --kami-pad-lg-y: 12px;
  --kami-gap: 6px;
  --kami-gap-lg: 10px;
  --kami-row-h: 40px;
  --kami-items-min: 13.5rem;
}
html[data-kami-skin="grokbot"][data-kami-density="roomy"] .kami-root {
  --kami-pad-x: 18px;
  --kami-pad-y: 12px;
  --kami-pad-lg-x: 24px;
  --kami-pad-lg-y: 20px;
  --kami-gap: 10px;
  --kami-gap-lg: 16px;
  --kami-row-h: 46px;
  --kami-items-min: 17.5rem;
}

/* ==========================================================================
 * 17 · 亮色方案：底板也翻成黏土白（同一套黑白关系，反过来）
 * ======================================================================== */
html[data-kami-skin="grokbot"][data-kami-scheme="light"] .kami-root {
  --kami-fg: #16161a;
  --kami-fg-dim: #3f3f45;
  --kami-fg-mute: #56565c;
  --kami-accent: #16161a;
  --kami-accent-fg: #f2f1ee;
  --kami-accent-soft: #e3e2de;
  --kami-accent-line: #62626a;
  --kami-bg: #e6e5e1;
  --kami-bg-soft: #d9d8d4;
  --kami-card: #f2f1ee;
  --kami-card-2: #e6e5e1;
  --kami-card-hover: #fbfaf7;
  --kami-line: #c3c2be;
  --kami-line-strong: #62626a;
  --kami-t1: rgba(22, 22, 26, .04);
  --kami-t2: rgba(22, 22, 26, .08);
  --kami-t3: rgba(22, 22, 26, .17);
  --kami-warn: #8f2f27;
  --kami-shadow: 0 2px 0 rgba(22, 22, 26, .18);
  --kami-shadow-sm: 0 1px 0 rgba(22, 22, 26, .14);
  --kami-glow: #ffffff;
  /* 亮色方案下**两块面板都是浅底**（面板翻成黏土白、消息楼层本来就是黏土白），
     所以七个色相一律用暗级那一套。 */
  --kami-kind-action: #7f4b2d;
  --kami-kind-fun: #645723;
  --kami-kind-plot: #23634c;
  --kami-kind-info: #2a5d77;
  --kami-kind-persona: #7f379e;
  --kami-kind-nsfw: #963558;
  --kami-kind-other: #3f3f45;
  --kami-kind-focus: #23634c;
}
html[data-kami-skin="grokbot"][data-kami-scheme="light"] .kami-root[data-kami-comp="panel"] .kami-drop {
  background-color: var(--kami-bg);
  background-image: none;
  border-color: var(--kami-line);
  color: var(--kami-fg);
  box-shadow: var(--kami-shadow);
}
html[data-kami-skin="grokbot"][data-kami-scheme="light"] .kami-root[data-kami-comp="panel"] .kami-card {
  background-color: var(--kami-card);
  background-image: none;
  color: var(--kami-fg);
}
html[data-kami-skin="grokbot"][data-kami-scheme="light"] .kami-root[data-kami-comp="panel"] input.kami-number,
html[data-kami-skin="grokbot"][data-kami-scheme="light"] .kami-root[data-kami-comp="panel"] input.kami-text,
