/* ==========================================================================
 * 1 · 令牌全集（默认亮色：晨曦蔚蓝 + 通透水晶）
 * ======================================================================== */
html[data-kami-skin="isekai"] .kami-root {
  /* —— 风格性文案槽位（契约 §3.7） —— */
  --kami-label-think-title: 咏唱推演;
  --kami-label-think-title-open: 魔法全览;
  --kami-label-options-title: 抉择分支;

  /* —— 色彩：晨曦白 + 苍蓝黑 + 转生蔚蓝 —— */
