  --kami-fg-dim: #3d4a66;        /* 次要文字：暮色苍灰蓝，对白底 8.5:1 */
  --kami-fg-mute: #596785;       /* 最弱文字：冰蓝冷灰，对白底 4.9:1，对卡片底 >= 4.6:1 */
  --kami-accent: #2563eb;        /* 强调色：转生魔力蔚蓝，纯白字在其上 5.5:1 */
  --kami-accent-fg: #ffffff;     /* 强调底上的文字：纯白反字 */
  --kami-accent-soft: rgba(37, 99, 235, 0.10); /* 蔚蓝微光淡晕 */
  --kami-accent-line: rgba(37, 99, 235, 0.55); /* 蔚蓝魔力描边 */

  --kami-bg: #f0f5fc;            /* 容器背景：天空晨曦白 */
  --kami-bg-soft: #e5edf8;       /* 次级容器背景：柔和浅蓝底 */
  --kami-card: #ffffff;          /* 卡片背景：纯白水晶卡 */
  --kami-card-2: #eaf1fa;        /* 卡片内正文/引用块浅底 */
  --kami-card-hover: #f5f9ff;    /* 卡片悬停：微光天蓝纯白（不透明色） */
  --kami-line: rgba(59, 108, 230, 0.16);          /* 常规分隔线：淡蓝细线 */
  --kami-line-strong: rgba(37, 99, 235, 0.45);   /* 强调描边：魔力实线 >= 3.2:1 */
  --kami-t1: rgba(37, 99, 235, 0.04);
  --kami-t2: rgba(37, 99, 235, 0.08);
  --kami-t3: rgba(37, 99, 235, 0.16);
  --kami-warn: #e11d48;          /* 警示色：绯红水晶 */
  --kami-shadow: 0 10px 30px -4px rgba(37, 99, 235, 0.12), 0 3px 10px rgba(18, 28, 48, 0.05);
  --kami-shadow-sm: 0 2px 8px rgba(37, 99, 235, 0.10);
  --kami-blur: 16px;             /* 毛玻璃通透量 */

  /* —— 布局与尺寸（圆润阶梯） —— */
  --kami-r-xs: 4px;
  --kami-r-sm: 8px;
  --kami-r-md: 12px;
  --kami-r-lg: 16px;
  --kami-r-pill: 999px;
  --kami-border-w: 1px;
  --kami-pad-x: 12px;
  --kami-pad-y: 8px;
  --kami-pad-lg-x: 16px;
  --kami-pad-lg-y: 14px;
  --kami-gap: 8px;
  --kami-gap-lg: 12px;
  --kami-row-h: 40px;            /* 控件行高基准 >= 40px */
  --kami-icon: 16px;
  --kami-maxw: none;
  --kami-items-min: 15.5rem;
  --kami-panel-w: 430px;
  --kami-panel-h: 570px;
  --kami-list-dir: column;
  --kami-justify: stretch;

  /* —— 文本与排版（动漫粗体标题栈） —— */
  --kami-fs-scale: 1;
  --kami-fs: calc(15px * var(--kami-fs-scale));
  --kami-fs-xs: calc(var(--kami-fs) * .78);
  --kami-fs-sm: calc(var(--kami-fs) * .88);
  --kami-fs-lg: calc(var(--kami-fs) * 1.15);
  --kami-lh: 1.62;
  --kami-ls: .015em;
  --kami-ls-title: .06em;
  --kami-font: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", "WenQuanYi Micro Hei", sans-serif;
  --kami-font-title: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Microsoft YaHei", "SimHei", "Heiti SC", sans-serif;
  --kami-font-mono: ui-monospace, SFMono-Regular, "Cascadia Mono", Consolas, "Liberation Mono", monospace;
  --kami-fw: 450;
  --kami-fw-title: 800;          /* 动漫感粗体标题 */
  --kami-title-transform: none;

  /* —— 装饰与微光材质 —— */
  --kami-texture: linear-gradient(135deg, rgba(255, 255, 255, 0.6) 0%, rgba(240, 245, 252, 0.3) 100%);
  --kami-glow: rgba(59, 130, 246, 0.45);
  --kami-glow-size: 6px;
  --kami-surface-clip: none;
  --kami-accent-mark: 3px;

  /* —— 动效 —— */
  --kami-dur-fast: .12s;
  --kami-dur: .20s;
  --kami-dur-slow: .32s;
  --kami-ease: cubic-bezier(.22, .72, .3, 1);
  --kami-ease-out: cubic-bezier(.16, 1, .3, 1);
  --kami-enter-y: 6px;
  --kami-enter-scale: .97;
  --kami-stagger: 20ms;

  /* —— 语义色（异世界轻小说魔法属性色，白底对比度均 >= 5.5:1） —— */
  --kami-kind-action: #1d62c2;   /* 勇者行动 · 圣剑蔚蓝 (7.1:1) */
  --kami-kind-persona: #a8216b;  /* 魔王性格 · 蔷薇洋红 (7.3:1) */
  --kami-kind-plot: #157347;     /* 世界推进 · 精灵翠绿 (6.3:1) */
  --kami-kind-info: #0f768a;     /* 魔法信息 · 贤者青绿 (5.8:1) */
  --kami-kind-fun: #9e5700;      /* 异界日常 · 琥珀亮橙 (5.5:1) */
  --kami-kind-nsfw: #be185d;     /* 魅魔契约 · 绚烂绯红 (6.2:1) */
  --kami-kind-other: #4b5568;    /* 冒险杂记 · 星晶石灰 (7.2:1) */

  /* —— 皮肤私有参数默认值 —— */
  --kami-isekai-radius: 14px;
  --kami-isekai-gloss: 40;

  /* —— 压淡档位 —— */
  --kami-dim-soft: .60;
  --kami-dim-lock: .42;

  box-sizing: border-box;
  color: var(--kami-fg);
  font-family: var(--kami-font);
  font-size: var(--kami-fs);
  font-weight: var(--kami-fw);
  line-height: var(--kami-lh);
  letter-spacing: var(--kami-ls);
  font-variant-numeric: tabular-nums;
  text-align: left;
  text-rendering: optimizeLegibility;
  word-break: break-word;
  -webkit-tap-highlight-color: transparent;
}

/* ==========================================================================
