html[data-kami-skin="isekai"] .kami-root[data-kami-comp="panel"] .kami-item[disabled]:active {
  background-color: var(--kami-card);
  background-image: none;
  border-color: var(--kami-line);
  box-shadow: none;
  transform: none;
  opacity: var(--kami-dim-lock, .42);
  color: var(--kami-fg-mute);
  cursor: default;
}

html[data-kami-skin="isekai"] .kami-root[data-kami-comp="panel"] .kami-item[disabled]:hover::before,
html[data-kami-skin="isekai"] .kami-root[data-kami-comp="panel"] .kami-item[disabled]:hover::after {
  transform: none;
  opacity: 0;
}

html[data-kami-skin="isekai"] .kami-root[data-kami-comp="panel"] .kami-item[disabled]:hover > .kami-badge {
  transform: none;
}

/* ==========================================================================
 * 7 · 结构与等高约束（契约 §4.2 硬规则）
 * ======================================================================== */
html[data-kami-skin="isekai"] .kami-root .kami-item-note {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

html[data-kami-skin="isekai"] .kami-root .kami-item-note > .kami-card {
  flex: 1 1 auto;
}

html[data-kami-skin="isekai"] .kami-root .kami-pv,
html[data-kami-skin="isekai"] .kami-root .kami-pv-frame,
html[data-kami-skin="isekai"] .kami-root .kami-guide-pv,
html[data-kami-skin="isekai"] .kami-root .kami-guide-pv-frame {
  pointer-events: none;
}

html[data-kami-skin="isekai"] .kami-root .kami-deco {
  display: none;
}

html[data-kami-skin="isekai"] .kami-root .kami-d20 {
  pointer-events: auto;
}

html[data-kami-skin="isekai"] .kami-d20-face {
  background: var(--kami-accent);
}

html[data-kami-skin="isekai"] .kami-d20-face > i {
  background: var(--kami-card);
  color: var(--kami-fg);
  font-family: var(--kami-font-title);
}

/* ==========================================================================
 * 8 · 外壳、通透水晶面与通用头部
 * ======================================================================== */
html[data-kami-skin="isekai"] .kami-shell {
  position: relative;
  display: block;
  background-color: var(--kami-bg);
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-lg);
  box-shadow: var(--kami-shadow);
  overflow: hidden;
  transition: border-color var(--kami-dur) var(--kami-ease), box-shadow var(--kami-dur) var(--kami-ease);
}

@supports ((backdrop-filter: blur(2px)) or (-webkit-backdrop-filter: blur(2px))) {
  html[data-kami-skin="isekai"] .kami-shell {
    -webkit-backdrop-filter: blur(var(--kami-blur));
    backdrop-filter: blur(var(--kami-blur));
  }
}

html[data-kami-skin="isekai"] .kami-surface {
  background-image: var(--kami-texture);
}

html[data-kami-skin="isekai"] .kami-head {
  position: relative;
  display: flex;
  align-items: center;
  gap: var(--kami-gap);
  min-height: var(--kami-row-h);
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
  background-color: var(--kami-card);
}

html[data-kami-skin="isekai"] .kami-head:not(.kami-collapse-head) {
  border-bottom: var(--kami-border-w) solid var(--kami-line);
}

html[data-kami-skin="isekai"] .kami-head[data-kami-drag] {
  cursor: move;
  user-select: none;
}

html[data-kami-skin="isekai"] .kami-collapse-head {
  cursor: pointer;
  user-select: none;
}

/* 状态点（异世界水晶星芒点） */
html[data-kami-skin="isekai"] .kami-dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: var(--kami-r-pill);
  background-color: var(--kami-accent);
  flex-shrink: 0;
  box-shadow: 0 0 var(--kami-glow-size) var(--kami-glow);
  transition: transform var(--kami-dur-fast) var(--kami-ease), background-color var(--kami-dur-fast) var(--kami-ease);
}

html[data-kami-skin="isekai"] .kami-dot[data-kami-on="1"] {
  background-color: var(--kami-accent);
  transform: scale(1.3);
  box-shadow: 0 0 8px var(--kami-accent);
}

/* 进度点（向导 .kami-dots） */
html[data-kami-skin="isekai"] .kami-dots .kami-dot {
  opacity: .38;
}

html[data-kami-skin="isekai"] .kami-dots .kami-dot[data-kami-on="1"] {
  opacity: 1;
}

/* 标题与副信息（动漫粗体标题） */
html[data-kami-skin="isekai"] .kami-title {
  font-family: var(--kami-font-title);
  font-weight: var(--kami-fw-title);
  font-size: var(--kami-fs);
  letter-spacing: var(--kami-ls-title);
  text-transform: var(--kami-title-transform);
  color: var(--kami-fg);
  line-height: 1.2;
}

html[data-kami-skin="isekai"] .kami-sub {
  font-size: var(--kami-fs-xs);
  color: var(--kami-fg-mute);
  white-space: nowrap;
}

html[data-kami-skin="isekai"] .kami-actions {
  display: flex;
  align-items: center;
  gap: var(--kami-gap);
  margin-left: auto;
  flex: none;
}

html[data-kami-skin="isekai"] .kami-body {
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
}

html[data-kami-skin="isekai"] .kami-foot {
  display: flex;
  align-items: center;
  gap: var(--kami-gap);
  padding: var(--kami-pad-y) var(--kami-pad-lg-x);
  border-top: var(--kami-border-w) solid var(--kami-line);
  font-size: var(--kami-fs-xs);
  color: var(--kami-fg-mute);
  background-color: var(--kami-card);
}

/* 组件内操作行 */
html[data-kami-skin="isekai"] .kami-bar {
  display: flex;
  align-items: center;
  gap: var(--kami-gap);
  margin-bottom: var(--kami-gap);
}

html[data-kami-skin="isekai"] .kami-bar > :last-child {
  margin-left: auto;
}

/* ==========================================================================
 * 9 · 按钮与分段切换
 * ======================================================================== */
html[data-kami-skin="isekai"] .kami-btn,
html[data-kami-skin="isekai"] .kami-icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: var(--kami-row-h);
  padding: var(--kami-pad-y) var(--kami-pad-x);
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-sm);
  background: var(--kami-card);
  color: var(--kami-fg);
  font-size: var(--kami-fs-sm);
  font-weight: 600;
  cursor: pointer;
  box-shadow: var(--kami-shadow-sm);
  transition: background var(--kami-dur-fast) var(--kami-ease),
              border-color var(--kami-dur-fast) var(--kami-ease),
              color var(--kami-dur-fast) var(--kami-ease),
              transform var(--kami-dur-fast) var(--kami-ease),
              box-shadow var(--kami-dur-fast) var(--kami-ease);
}

html[data-kami-skin="isekai"] .kami-icon-btn {
  min-width: var(--kami-row-h);
  padding: 0;
  font-size: var(--kami-icon);
}

html[data-kami-skin="isekai"] .kami-btn--ghost {
  background: transparent;
  box-shadow: none;
  border-color: var(--kami-line);
}

html[data-kami-skin="isekai"] .kami-root .kami-btn--primary {
  background: linear-gradient(135deg, var(--kami-accent) 0%, #3b82f6 100%);
  border-color: var(--kami-accent);
  color: var(--kami-accent-fg);
  box-shadow: 0 4px 12px rgba(37, 99, 235, 0.28);
}

html[data-kami-skin="isekai"] .kami-btn.is-on {
  background: var(--kami-accent-soft);
  border-color: var(--kami-accent-line);
  color: var(--kami-accent);
  font-weight: 700;
}

@media (hover: hover) {
  html[data-kami-skin="isekai"] .kami-btn:hover,
  html[data-kami-skin="isekai"] .kami-icon-btn:hover {
    background: var(--kami-card-hover);
    border-color: var(--kami-line-strong);
    transform: translateY(-1px);
    box-shadow: 0 4px 12px rgba(37, 99, 235, 0.15);
  }
  html[data-kami-skin="isekai"] .kami-btn--primary:hover {
    filter: brightness(1.08);
    transform: translateY(-1px);
    box-shadow: 0 6px 16px rgba(37, 99, 235, 0.35);
  }
}

html[data-kami-skin="isekai"] .kami-btn:active,
html[data-kami-skin="isekai"] .kami-icon-btn:active {
  transform: translateY(1px);
  box-shadow: none;
}

/* 分段切换控件（Segmented Switch） */
html[data-kami-skin="isekai"] .kami-seg {
  display: inline-flex;
  gap: 2px;
  padding: 3px;
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-sm);
  background: var(--kami-bg-soft);
}

html[data-kami-skin="isekai"] .kami-seg-item {
  border: 0;
  border-radius: calc(var(--kami-r-sm) - 2px);
  background: transparent;
  color: var(--kami-fg-dim);
  font-size: var(--kami-fs-xs);
  font-weight: 600;
  letter-spacing: var(--kami-ls);
  padding: 5px 10px;
  cursor: pointer;
  transition: background var(--kami-dur-fast) var(--kami-ease),
              color var(--kami-dur-fast) var(--kami-ease),
              box-shadow var(--kami-dur-fast) var(--kami-ease);
}

html[data-kami-skin="isekai"] .kami-seg-item.is-on {
  background: var(--kami-card);
  color: var(--kami-accent);
  box-shadow: 0 2px 6px rgba(37, 99, 235, 0.15);
}

/* ==========================================================================
 * 10 · 卡片、列表项与小标签
 * ======================================================================== */
html[data-kami-skin="isekai"] .kami-card {
  position: relative;
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-md);
  background-color: var(--kami-card);
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
  box-shadow: var(--kami-shadow-sm);
  transition: border-color var(--kami-dur) var(--kami-ease),
              box-shadow var(--kami-dur) var(--kami-ease),
              transform var(--kami-dur) var(--kami-ease);
}

html[data-kami-skin="isekai"] .kami-card-head {
  display: flex;
  align-items: center;
  gap: var(--kami-gap);
  margin-bottom: 6px;
}

html[data-kami-skin="isekai"] .kami-card-title {
  font-family: var(--kami-font-title);
  font-weight: var(--kami-fw-title);
  font-size: var(--kami-fs-sm);
  color: var(--kami-fg);
}

html[data-kami-skin="isekai"] .kami-card-note {
  font-size: var(--kami-fs-xs);
  color: var(--kami-fg-mute);
}

html[data-kami-skin="isekai"] .kami-card-body {
  display: block;
  font-size: var(--kami-fs-sm);
  color: var(--kami-fg-dim);
  line-height: var(--kami-lh);
}

html[data-kami-skin="isekai"] .kami-list {
  display: flex;
  flex-direction: var(--kami-list-dir);
  justify-content: var(--kami-justify);
  gap: var(--kami-gap);
}

html[data-kami-skin="isekai"] .kami-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, var(--kami-items-min)), 1fr));
  gap: var(--kami-gap);
}

/* 列表项条目卡（整卡即按钮） */
html[data-kami-skin="isekai"] .kami-item {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 4px;
  width: 100%;
  text-align: left;
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-md);
  background-color: var(--kami-card);
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
  cursor: pointer;
  box-shadow: var(--kami-shadow-sm);
  transition: background-color var(--kami-dur) var(--kami-ease),
              border-color var(--kami-dur) var(--kami-ease),
              transform var(--kami-dur) var(--kami-ease),
              box-shadow var(--kami-dur) var(--kami-ease);
}

@media (hover: hover) {
  html[data-kami-skin="isekai"] .kami-item:hover {
    background-color: var(--kami-card-hover);
    border-color: var(--kami-accent-line);
    transform: translateY(-2px);
    box-shadow: 0 6px 18px rgba(37, 99, 235, 0.16);
  }
}

html[data-kami-skin="isekai"] .kami-item:active {
  transform: translateY(0);
}

html[data-kami-skin="isekai"] .kami-item.is-demo {
  opacity: .62;
  cursor: default;
}

html[data-kami-skin="isekai"] .kami-item-main {
  min-width: 0;
}

html[data-kami-skin="isekai"] .kami-item-side {
  flex: none;
  margin-left: auto;
  color: var(--kami-fg-mute);
  font-size: var(--kami-fs-sm);
  font-weight: 700;
}

/* 选中激活态（契约硬规则：不仅靠颜色，反转文字色并加强描边与光泽） */
html[data-kami-skin="isekai"] .kami-item.is-on,
html[data-kami-skin="isekai"] .kami-item[aria-pressed="true"] {
  background-color: var(--kami-accent-soft);
  border-color: var(--kami-accent);
  box-shadow: 0 0 0 1px var(--kami-accent), 0 4px 14px rgba(37, 99, 235, 0.20);
}

html[data-kami-skin="isekai"] .kami-item.is-on .kami-card-title,
html[data-kami-skin="isekai"] .kami-item[aria-pressed="true"] .kami-card-title {
  color: var(--kami-accent);
  font-weight: 800;
}

/* 徽章与小标签 */
html[data-kami-skin="isekai"] .kami-badge,
html[data-kami-skin="isekai"] .kami-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex: none;
  padding: 2px 8px;
  border-radius: var(--kami-r-pill);
  border: var(--kami-border-w) solid currentColor;
  font-size: var(--kami-fs-xs);
  font-weight: 600;
  line-height: 1.4;
  white-space: nowrap;
}

html[data-kami-skin="isekai"] .kami-chip {
  border-color: var(--kami-line);
  color: var(--kami-fg-dim);
  background: var(--kami-t1);
}

/* ==========================================================================
 * 11 · 折叠与展开动画
 * ======================================================================== */
html[data-kami-skin="isekai"] .kami-chev {
  flex: none;
  font-size: calc(var(--kami-icon) * .85);
  color: var(--kami-fg-mute);
  transition: transform var(--kami-dur) var(--kami-ease), color var(--kami-dur) var(--kami-ease);
}

html[data-kami-skin="isekai"] .kami-collapse[data-kami-open="1"] > .kami-head .kami-chev {
  transform: rotate(90deg);
  color: var(--kami-accent);
}

html[data-kami-skin="isekai"] .kami-collapse > .kami-body {
  display: none;
}

html[data-kami-skin="isekai"] .kami-collapse[data-kami-open="1"] > .kami-body {
  display: block;
  animation: kami-isekai-in var(--kami-dur-slow) var(--kami-ease-out) backwards;
}

/* ==========================================================================
 * 12 · 正文 Markdown、代码与原文渲染
 * ======================================================================== */
html[data-kami-skin="isekai"] .kami-md {
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
  border-radius: var(--kami-r-md);
  background-color: var(--kami-card-2);
  border: var(--kami-border-w) solid var(--kami-line);
  font-size: var(--kami-fs-sm);
  color: var(--kami-fg-dim);
  line-height: var(--kami-lh);
}

html[data-kami-skin="isekai"] .kami-md > :first-child { margin-top: 0; }
html[data-kami-skin="isekai"] .kami-md > :last-child { margin-bottom: 0; }
html[data-kami-skin="isekai"] .kami-md p { margin: .5em 0; }

html[data-kami-skin="isekai"] .kami-md h1,
html[data-kami-skin="isekai"] .kami-md h2,
html[data-kami-skin="isekai"] .kami-md h3,
html[data-kami-skin="isekai"] .kami-md h4,
html[data-kami-skin="isekai"] .kami-md h5,
html[data-kami-skin="isekai"] .kami-md h6 {
  margin: .9em 0 .4em;
  font-family: var(--kami-font-title);
  font-weight: var(--kami-fw-title);
  font-size: var(--kami-fs);
  color: var(--kami-fg);
}
html[data-kami-skin="isekai"] .kami-md h1 { font-size: calc(var(--kami-fs) * 1.18); }
html[data-kami-skin="isekai"] .kami-md h2 { font-size: calc(var(--kami-fs) * 1.08); }
html[data-kami-skin="isekai"] .kami-md h4,
html[data-kami-skin="isekai"] .kami-md h5,
html[data-kami-skin="isekai"] .kami-md h6 { font-size: var(--kami-fs); }

html[data-kami-skin="isekai"] .kami-md code {
  font-family: var(--kami-font-mono);
  font-size: .88em;
  padding: 2px 6px;
  border-radius: var(--kami-r-xs);
  background: var(--kami-t2);
  color: var(--kami-accent);
  font-weight: 600;
}

html[data-kami-skin="isekai"] .kami-md pre {
  margin: .6em 0;
  padding: var(--kami-pad-y) var(--kami-pad-x);
  border-radius: var(--kami-r-sm);
  background: var(--kami-card);
  border: var(--kami-border-w) solid var(--kami-line);
  overflow-x: auto;
}

html[data-kami-skin="isekai"] .kami-md pre code {
  background: none;
  padding: 0;
  color: var(--kami-fg);
  font-weight: normal;
}

html[data-kami-skin="isekai"] .kami-md blockquote {
  margin: .6em 0;
  padding: 4px 0 4px 12px;
  border-left: var(--kami-accent-mark) solid var(--kami-accent);
  color: var(--kami-fg-mute);
  background: var(--kami-t1);
  border-radius: 0 var(--kami-r-xs) var(--kami-r-xs) 0;
}

html[data-kami-skin="isekai"] .kami-md ul,
html[data-kami-skin="isekai"] .kami-md ol {
  margin: .5em 0;
  padding-left: 1.4em;
}

html[data-kami-skin="isekai"] .kami-md li {
  margin: .2em 0;
}
/* 嵌套层级：缩进加深一档，圆点/序号压暗一档，条目行距收紧 */
html[data-kami-skin="isekai"] .kami-md li > ul,
html[data-kami-skin="isekai"] .kami-md li > ol {
  margin-top: .25em;
  margin-bottom: .15em;
}
html[data-kami-skin="isekai"] .kami-md li::marker { color: var(--kami-accent); }
html[data-kami-skin="isekai"] .kami-md li li::marker { color: var(--kami-fg-mute); }

html[data-kami-skin="isekai"] .kami-md em {
  font-style: italic;
  color: var(--kami-fg-dim);
}
html[data-kami-skin="isekai"] .kami-md img {
  max-width: 100%;
  height: auto;
  display: inline-block;
  border-radius: var(--kami-r-sm);
  border: var(--kami-border-w) solid var(--kami-line);
}

html[data-kami-skin="isekai"] .kami-md strong {
  color: var(--kami-fg);
  font-weight: 700;
}

html[data-kami-skin="isekai"] .kami-md a {
  color: var(--kami-accent);
  text-decoration: underline;
  text-underline-offset: 3px;
  font-weight: 600;
}

html[data-kami-skin="isekai"] .kami-md hr {
  border: 0;
  border-top: var(--kami-border-w) solid var(--kami-line);
  margin: .9em 0;
}

html[data-kami-skin="isekai"] .kami-md table {
  border-collapse: collapse;
  width: 100%;
  font-size: var(--kami-fs-xs);
}

html[data-kami-skin="isekai"] .kami-md th,
html[data-kami-skin="isekai"] .kami-md td {
  border: var(--kami-border-w) solid var(--kami-line);
  padding: 5px 8px;
}
/* 窄屏表格不撑破：手机档把表变成可横滚的块 */
@media (max-width: 560px) {
  html[data-kami-skin="isekai"] .kami-md table {
    display: block;
    max-width: 100%;
    overflow-x: auto;
  }
}

html[data-kami-skin="isekai"] .kami-raw {
  margin: 0;
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
  border-radius: var(--kami-r-md);
  background: var(--kami-card-2);
  border: var(--kami-border-w) solid var(--kami-line);
  font-family: var(--kami-font-mono);
  font-size: var(--kami-fs-xs);
  line-height: 1.6;
  color: var(--kami-fg-dim);
  white-space: pre-wrap;
  overflow-x: auto;
}

/* ==========================================================================
 * 13 · 表单控件（字段、滑杆、开关）
 * ======================================================================== */
html[data-kami-skin="isekai"] .kami-field {
  display: flex;
  align-items: center;
  gap: var(--kami-gap);
  padding: var(--kami-pad-y) 0;
}

html[data-kami-skin="isekai"] .kami-field-label {
  flex: 1 1 auto;
  min-width: 0;
