}

html[data-kami-skin="isekai"] .kami-switch-input:focus-visible + .kami-switch-track {
  outline: 2px solid var(--kami-accent);
  outline-offset: 2px;
}

/* ==========================================================================
 * 14 · 面板骨架、Tabs、进度点、滚动条与贴底抽屉
 * ======================================================================== */
/* 标签页 */
html[data-kami-skin="isekai"] .kami-tabs {
  display: flex;
