  background-color: var(--kami-card);
  overflow-x: auto;
  scrollbar-width: none;
  -webkit-mask-image: linear-gradient(90deg, #000 calc(100% - 24px), transparent 100%);
  mask-image: linear-gradient(90deg, #000 calc(100% - 24px), transparent 100%);
}

html[data-kami-skin="isekai"] .kami-tabs::-webkit-scrollbar {
  display: none;
}

html[data-kami-skin="isekai"] .kami-tab {
  flex: none;
  border: 0;
  border-bottom: var(--kami-accent-mark) solid transparent;
