}

/* 面板定位舞台与本体 */
html[data-kami-skin="isekai"] .kami-root[data-kami-comp="panel"] {
  position: fixed;
  inset: 0;
  top: 0; right: 0; bottom: 0; left: 0;
  width: auto; height: auto; min-height: 0;
  margin: 0;
  z-index: 30000;
  pointer-events: none;
}

html[data-kami-skin="isekai"] .kami-root .kami-drop.kami-drop {
  position: absolute;
  left: var(--kami-panel-x, 50%);
  top: var(--kami-panel-y, 72px);
  width: var(--kami-panel-w, min(430px, calc(100% - 24px)));
  height: var(--kami-panel-h, 570px);
  max-height: calc(100% - 24px);
  pointer-events: auto;
  background-color: var(--kami-bg);
  border: var(--kami-border-w) solid var(--kami-line);
