}

/* 贴底抽屉 */
html[data-kami-skin="isekai"] .kami-root .kami-drop.kami-drop[data-kami-layout="sheet"] {
  left: 0; right: 0; top: auto; bottom: 0;
  width: auto; height: 78%; max-height: 78%;
