  border-bottom: 0;
}

@media (max-width: 768px) {
  html[data-kami-skin="isekai"] .kami-root .kami-drop.kami-drop:not([data-kami-layout]) {
    left: 0; right: 0; top: auto; bottom: 0;
    width: auto; height: 78%; max-height: 78%;
