}

html[data-kami-skin="isekai"] .kami-toast {
  margin-top: var(--kami-gap);
  padding: var(--kami-pad-y) var(--kami-pad-x);
  border-radius: var(--kami-r-sm);
  border: var(--kami-border-w) solid var(--kami-line);
  background: var(--kami-card);
  font-size: var(--kami-fs-xs);
  color: var(--kami-fg);
  box-shadow: var(--kami-shadow-sm);
  animation: kami-isekai-in var(--kami-dur) var(--kami-ease-out) backwards;
}

html[data-kami-skin="isekai"] .kami-toast.is-bad {
  color: var(--kami-warn);
  border-color: currentColor;
}

/* ==========================================================================
 * 15 · 注释系统与角标定位
 * ======================================================================== */
/* 角标定位 */
html[data-kami-skin="isekai"] .kami-root[data-kami-comp="panel"] .kami-item.kami-card {
  position: relative;
}

html[data-kami-skin="isekai"] .kami-root[data-kami-comp="panel"] .kami-item > .kami-badge {
  position: absolute;
  top: 2px;
