html[data-kami-skin="isekai"] .kami-root[data-kami-comp="panel"] .kami-item > .kami-badge[data-kami-corner="tl"],
html[data-kami-skin="isekai"] .kami-root[data-kami-comp="panel"] .kami-item > .kami-badge[data-kami-corner="bl"] {
  right: auto;
  left: 4px;
}

html[data-kami-skin="isekai"] .kami-root[data-kami-comp="panel"] .kami-item > .kami-badge[data-kami-corner="br"],
html[data-kami-skin="isekai"] .kami-root[data-kami-comp="panel"] .kami-item > .kami-badge[data-kami-corner="bl"] {
  top: auto;
  bottom: 2px;
}

html[data-kami-skin="isekai"] .kami-root[data-kami-comp="panel"] .kami-item:has(> .kami-badge[data-kami-corner="tl"], > .kami-badge[data-kami-corner="tr"], > .kami-card-note[data-kami-corner="tr"]) {
  padding-top: calc(var(--kami-pad-lg-y) + 0.4em);
}

html[data-kami-skin="isekai"] .kami-root[data-kami-comp="panel"] .kami-item:has(> .kami-badge[data-kami-corner="bl"], > .kami-badge[data-kami-corner="br"]) {
  padding-bottom: calc(var(--kami-pad-lg-y) + 0.4em);
}

/* 注释标记 ⓘ */
html[data-kami-skin="isekai"] .kami-root[data-kami-comp="panel"] .kami-card-note[data-kami-note-mark] {
  flex: none;
