  border-radius: 0 var(--kami-r-xs) var(--kami-r-xs) 0;
  background: var(--kami-card-2);
  color: var(--kami-fg-dim);
  font-size: var(--kami-fs-xs);
  line-height: 1.55;
  white-space: pre-wrap;
  word-break: break-word;
  text-align: left;
}

html[data-kami-skin="isekai"] .kami-root[data-kami-comp="panel"] .kami-card-note[data-kami-note][hidden] {
  display: none;
}

/* 面板网格判据 */
html[data-kami-skin="isekai"] .kami-root[data-kami-comp="panel"] .kami-grid:has(> .kami-item, > .kami-item-note) {
