}
html[data-kami-skin="isekai"] .kami-item[data-kami-kind="action"]:hover {
  border-color: var(--kami-kind-action);
  box-shadow: 0 4px 12px rgba(29, 98, 194, 0.18);
}

/* 2. 性格 · 蔷薇洋红 */
html[data-kami-skin="isekai"] .kami-root [data-kami-kind="persona"] {
