  border-color: var(--kami-kind-other);
  box-shadow: 0 4px 12px rgba(75, 85, 104, 0.18);
}

/* ==========================================================================
 * 17 · 皮肤特效（prism / crystal / starlight / gradient）
 * ======================================================================== */
/* 特效 1：棱镜高光 */
html[data-kami-skin="isekai"][data-kami-effects~="prism"] .kami-head {
  border-top: 2px solid transparent;
  border-image: linear-gradient(90deg, #38bdf8 0%, #818cf8 50%, #c084fc 100%) 1;
}

html[data-kami-skin="isekai"][data-kami-effects~="prism"] .kami-card-head {
  border-bottom: 1px solid rgba(129, 140, 248, 0.25);
  padding-bottom: 4px;
}

/* 特效 2：通透水晶 */
html[data-kami-skin="isekai"][data-kami-effects~="crystal"] .kami-shell {
  box-shadow: 0 12px 36px -6px rgba(56, 189, 248, 0.18), 0 0 0 1px rgba(255, 255, 255, 0.7) inset;
}

