  box-shadow: 0 4px 16px rgba(56, 189, 248, 0.08), 0 0 0 1px rgba(255, 255, 255, 0.8) inset;
}

/* 特效 3：星芒微粒 */
html[data-kami-skin="isekai"][data-kami-effects~="starlight"] .kami-dot {
  animation: kami-isekai-glow 2.4s ease-in-out infinite alternate;
}

html[data-kami-skin="isekai"][data-kami-effects~="starlight"] .kami-btn--primary {
  position: relative;
  overflow: hidden;
