html[data-kami-skin="isekai"][data-kami-effects~="starlight"] .kami-btn--primary::after {
  content: "";
  position: absolute;
  top: -50%; left: -50%; width: 200%; height: 200%;
  background: linear-gradient(60deg, transparent 40%, rgba(255, 255, 255, 0.25) 50%, transparent 60%);
  transform: rotate(25deg);
  animation: kami-isekai-shine 4s ease-in-out infinite;
}

/* 特效 4：晨曦微光 */
html[data-kami-skin="isekai"][data-kami-effects~="gradient"] .kami-surface {
  background-image:
    radial-gradient(circle at 10% 20%, rgba(56, 189, 248, 0.08) 0%, transparent 50%),
    radial-gradient(circle at 90% 80%, rgba(192, 132, 252, 0.08) 0%, transparent 50%);
}

html[data-kami-skin="isekai"][data-kami-effects~="gradient"] .kami-head {
  background: linear-gradient(135deg, var(--kami-card) 0%, var(--kami-card-2) 100%);
}

/* ==========================================================================
 * 18 · 关键帧动画与容器查询
 * ======================================================================== */
@keyframes kami-isekai-in {
  from {
    opacity: 0;
    transform: translateY(calc(var(--kami-enter-y) * -1)) scale(var(--kami-enter-scale));
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes kami-isekai-glow {
  from {
    box-shadow: 0 0 4px var(--kami-accent);
  }
  to {
    box-shadow: 0 0 10px #38bdf8, 0 0 16px rgba(129, 140, 248, 0.6);
  }
}

@keyframes kami-isekai-shine {
  0% { transform: translateX(-100%) rotate(25deg); }
  25%, 100% { transform: translateX(100%) rotate(25deg); }
}

@keyframes kami-isekai-pulse {
  0% { transform: scale(1); }
  50% { transform: scale(1.04); }
  100% { transform: scale(1); }
}

@container (max-width: 400px) {
  html[data-kami-skin="isekai"] .kami-card-head {
    flex-wrap: wrap;
  }
}

/* ==========================================================================
 * 19 · 移动端与窄屏媒体查询（硬性规范：两档只调令牌）
