html[data-kami-skin="manga"] .kami-root [hidden] {
  display: none !important;
}

html[data-kami-skin="manga"] .kami-root img {
  max-width: 100%;
}

html[data-kami-skin="manga"] .kami-root .kami-deco {
  display: none;
}

html[data-kami-skin="manga"] .kami-root .kami-d20::before,
html[data-kami-skin="manga"] .kami-root .kami-d20::after {
  content: none;
}

/* ==========================================================================
 * 3 · 档位响应：明暗 / 密度 / 动效
 * ======================================================================== */
/* 明暗方案：暗色（夜墨分镜） */
html[data-kami-skin="manga"][data-kami-scheme="dark"] .kami-root {
  --kami-fg: #f0f2f6;            /* 原纸白字 */
  --kami-fg-dim: #b2b6c3;        /* 银铅草稿灰 */
  --kami-fg-mute: #7c8292;       /* 暗铅灰 */
  --kami-accent: #ff4b5a;        /* 荧光朱红 */
  --kami-accent-fg: #111215;     /* 强调底上的浓黑字 */
  --kami-accent-soft: rgba(255, 75, 90, 0.18);
  --kami-accent-line: #ff4b5a;

  --kami-bg: #121316;            /* 暗夜原稿墨底 */
  --kami-bg-soft: #191c22;       /* 次级暗墨底 */
  --kami-card: #1a1c22;          /* 分镜暗格 */
  --kami-card-2: #22252e;        /* 内嵌暗部网点底 */
  --kami-card-hover: #22252e;    /* 悬停底（不透明） */
  --kami-line: #363a45;          /* 亮墨线 */
  --kami-line-strong: #f0f2f6;   /* 强调白色描边 */
  --kami-t1: rgba(240, 242, 246, 0.05);
  --kami-t2: rgba(240, 242, 246, 0.10);
  --kami-t3: rgba(240, 242, 246, 0.18);
  --kami-warn: #ff4b5a;
  --kami-shadow: 4px 4px 0px #000000;
  --kami-shadow-sm: 2px 2px 0px #000000;

  --kami-texture: radial-gradient(circle at center, rgba(240, 242, 246, calc(var(--kami-mg-dot-op, 35) * 0.003)) 1.2px, transparent 1.3px);

  --kami-kind-action: #5aa2e8;
  --kami-kind-persona: #e86095;
  --kami-kind-plot: #4ecd84;
  --kami-kind-info: #4dc2dc;
  --kami-kind-fun: #e89e3a;
  --kami-kind-nsfw: #ff5c77;
  --kami-kind-other: #9ca2b0;
}

/* 密度档位 */
html[data-kami-skin="manga"][data-kami-density="compact"] .kami-root {
  --kami-pad-x: 9px;
  --kami-pad-y: 5px;
  --kami-pad-lg-x: 12px;
  --kami-pad-lg-y: 10px;
  --kami-gap: 6px;
  --kami-gap-lg: 9px;
  --kami-row-h: 36px;
}

html[data-kami-skin="manga"][data-kami-density="roomy"] .kami-root {
  --kami-pad-x: 15px;
  --kami-pad-y: 10px;
  --kami-pad-lg-x: 20px;
  --kami-pad-lg-y: 18px;
  --kami-gap: 10px;
  --kami-gap-lg: 15px;
  --kami-row-h: 46px;
}

/* 动效档位 */
html[data-kami-skin="manga"][data-kami-motion="calm"] .kami-root {
  --kami-dur-fast: .06s;
  --kami-dur: .12s;
  --kami-dur-slow: .18s;
  --kami-enter-y: 2px;
  --kami-stagger: 8ms;
}

html[data-kami-skin="manga"][data-kami-motion="off"] .kami-root {
  --kami-dur-fast: 1ms;
  --kami-dur: 1ms;
  --kami-dur-slow: 1ms;
  --kami-enter-y: 0px;
  --kami-enter-scale: 1;
  --kami-stagger: 0ms;
  animation: none !important;
  transition: none !important;
}

html[data-kami-skin="manga"][data-kami-motion="off"] .kami-root *,
html[data-kami-skin="manga"][data-kami-motion="off"] .kami-root *::before,
html[data-kami-skin="manga"][data-kami-motion="off"] .kami-root *::after {
  animation: none !important;
  transition: none !important;
}

@media (prefers-reduced-motion: reduce) {
  html[data-kami-skin="manga"] .kami-root {
    --kami-dur-fast: 1ms;
    --kami-dur: 1ms;
    --kami-dur-slow: 1ms;
    --kami-enter-y: 0px;
    --kami-enter-scale: 1;
    --kami-stagger: 0ms;
    animation: none !important;
    transition: none !important;
  }
  html[data-kami-skin="manga"] .kami-root *,
  html[data-kami-skin="manga"] .kami-root *::before,
  html[data-kami-skin="manga"] .kami-root *::after {
    animation: none !important;
    transition: none !important;
  }
}

/* ==========================================================================
 * 4 · 焦点与可访问性
 * ======================================================================== */
html[data-kami-skin="manga"] .kami-root :focus-visible {
  outline: 2px solid var(--kami-accent);
  outline-offset: 2px;
}

/* ==========================================================================
 * 5 · 控件对比度四件套（硬性三项 !important：阻击宿主与用户自定义深色 CSS 污染）
 * ======================================================================== */
html[data-kami-skin="manga"] .kami-root[data-kami-comp="panel"] .kami-number,
html[data-kami-skin="manga"] .kami-root[data-kami-comp="panel"] .kami-text,
html[data-kami-skin="manga"] .kami-root[data-kami-comp="panel"] .kami-textarea,
html[data-kami-skin="manga"] .kami-root[data-kami-comp="panel"] .kami-select {
  background-color: var(--kami-card) !important;
  color: var(--kami-fg) !important;
  color-scheme: light !important;
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-sm);
  padding: 6px 10px;
  box-shadow: 2px 2px 0px var(--kami-line);
  transition: border-color var(--kami-dur-fast) var(--kami-ease), box-shadow var(--kami-dur-fast) var(--kami-ease);
}

html[data-kami-skin="manga"] .kami-root[data-kami-comp="panel"] .kami-number:focus,
html[data-kami-skin="manga"] .kami-root[data-kami-comp="panel"] .kami-text:focus,
html[data-kami-skin="manga"] .kami-root[data-kami-comp="panel"] .kami-textarea:focus,
html[data-kami-skin="manga"] .kami-root[data-kami-comp="panel"] .kami-select:focus {
  border-color: var(--kami-accent);
  box-shadow: 2px 2px 0px var(--kami-accent);
}

html[data-kami-skin="manga"] .kami-root[data-kami-comp="panel"] input.kami-number[type="number"] {
  text-align: right;
}

html[data-kami-skin="manga"][data-kami-scheme="dark"] .kami-root[data-kami-comp="panel"] .kami-number,
html[data-kami-skin="manga"][data-kami-scheme="dark"] .kami-root[data-kami-comp="panel"] .kami-text,
html[data-kami-skin="manga"][data-kami-scheme="dark"] .kami-root[data-kami-comp="panel"] .kami-textarea,
html[data-kami-skin="manga"][data-kami-scheme="dark"] .kami-root[data-kami-comp="panel"] .kami-select {
  color-scheme: dark !important;
}

/* 控件通用排版 */
html[data-kami-skin="manga"] input.kami-text,
html[data-kami-skin="manga"] textarea.kami-textarea,
html[data-kami-skin="manga"] select.kami-select {
  min-height: var(--kami-row-h);
  padding: var(--kami-pad-y) var(--kami-pad-x);
  text-align: left;
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-sm);
  background-color: var(--kami-card);
  font-family: var(--kami-font);
  font-size: var(--kami-fs-sm);
  color: var(--kami-fg);
}

html[data-kami-skin="manga"] textarea.kami-textarea {
  resize: vertical;
}

/* 下拉选单自绘手绘三角箭头 */
html[data-kami-skin="manga"] select.kami-select {
  -webkit-appearance: none;
  appearance: none;
  padding-right: calc(var(--kami-pad-x) + 18px);
  background-image:
    linear-gradient(45deg, transparent 50%, var(--kami-fg) 50%),
    linear-gradient(135deg, var(--kami-fg) 50%, transparent 50%);
  background-size: 5px 5px, 5px 5px;
  background-position: calc(100% - 14px) calc(50% - 1px), calc(100% - 9px) calc(50% - 1px);
  background-repeat: no-repeat;
  cursor: pointer;
}

/* 禁用与锁死状态（契约 §4.2 & 用户友好性：必须一眼看出点不动） */
html[data-kami-skin="manga"] .kami-root .kami-btn[disabled],
html[data-kami-skin="manga"] .kami-root .kami-icon-btn[disabled] {
  opacity: var(--kami-dim-lock, .42);
  color: var(--kami-fg-mute);
  cursor: default;
  pointer-events: none;
  transform: none !important;
  box-shadow: none !important;
}

html[data-kami-skin="manga"] .kami-root[data-kami-comp="panel"] .kami-item[disabled],
html[data-kami-skin="manga"] .kami-root[data-kami-comp="panel"] .kami-item[disabled]:hover,
html[data-kami-skin="manga"] .kami-root[data-kami-comp="panel"] .kami-item[disabled]:active {
  background-color: var(--kami-card);
  background-image: none;
  border-color: var(--kami-fg-mute);
  box-shadow: none;
  transform: none;
  opacity: var(--kami-dim-lock, .42);
  color: var(--kami-fg-mute);
  cursor: default;
}

html[data-kami-skin="manga"] .kami-root[data-kami-comp="panel"] .kami-item[disabled]:hover::before,
html[data-kami-skin="manga"] .kami-root[data-kami-comp="panel"] .kami-item[disabled]:hover::after {
  transform: none;
  opacity: 0;
}

html[data-kami-skin="manga"] .kami-root[data-kami-comp="panel"] .kami-item[disabled]:hover > .kami-badge {
  transform: none;
}

/* ==========================================================================
 * 6 · 结构与等高约束（契约 §4.2 硬规则）
 * ======================================================================== */
html[data-kami-skin="manga"] .kami-root .kami-item-note {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

html[data-kami-skin="manga"] .kami-root .kami-item-note > .kami-card {
  flex: 1 1 auto;
}

html[data-kami-skin="manga"] .kami-root .kami-pv,
html[data-kami-skin="manga"] .kami-root .kami-pv-frame,
html[data-kami-skin="manga"] .kami-root .kami-guide-pv,
html[data-kami-skin="manga"] .kami-root .kami-guide-pv-frame {
  pointer-events: none;
}

html[data-kami-skin="manga"] .kami-root .kami-deco {
  display: none;
}

html[data-kami-skin="manga"] .kami-root .kami-d20 {
  pointer-events: auto;
}

html[data-kami-skin="manga"] .kami-d20-face {
  background: var(--kami-accent);
}

html[data-kami-skin="manga"] .kami-d20-face > i {
  background: var(--kami-bg);
  color: var(--kami-fg);
  font-family: var(--kami-font-title);
}

/* ==========================================================================
 * 7 · 外壳、漫画分镜面与通用头部
 * ======================================================================== */
html[data-kami-skin="manga"] .kami-shell {
  position: relative;
  display: block;
  background-color: var(--kami-bg);
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-lg);
  box-shadow: var(--kami-shadow);
  overflow: hidden;
  transition: border-color var(--kami-dur) var(--kami-ease), box-shadow var(--kami-dur) var(--kami-ease);
}

html[data-kami-skin="manga"] .kami-surface {
  background-image: var(--kami-texture);
  background-size: calc(var(--kami-mg-dot-size, 4px) * 2) calc(var(--kami-mg-dot-size, 4px) * 2);
}

html[data-kami-skin="manga"] .kami-head {
  position: relative;
  display: flex;
  align-items: center;
  gap: var(--kami-gap);
  min-height: var(--kami-row-h);
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
  background-color: var(--kami-card);
}

html[data-kami-skin="manga"] .kami-head:not(.kami-collapse-head) {
  border-bottom: var(--kami-border-w) solid var(--kami-line);
}

html[data-kami-skin="manga"] .kami-head[data-kami-drag] {
  cursor: move;
  user-select: none;
}

html[data-kami-skin="manga"] .kami-collapse-head {
  cursor: pointer;
  user-select: none;
}

/* 状态点（漫画墨点标记） */
html[data-kami-skin="manga"] .kami-dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: var(--kami-r-pill);
  background-color: var(--kami-fg);
  border: 1px solid var(--kami-line);
  flex-shrink: 0;
  transition: transform var(--kami-dur-fast) var(--kami-ease), background-color var(--kami-dur-fast) var(--kami-ease);
}

html[data-kami-skin="manga"] .kami-dot[data-kami-on="1"] {
  background-color: var(--kami-accent);
  border-color: var(--kami-accent);
  transform: scale(1.25);
  box-shadow: 0 0 0 2px var(--kami-accent-soft);
}

/* 标题与副文本 */
html[data-kami-skin="manga"] .kami-title {
  font-family: var(--kami-font-title);
  font-size: var(--kami-fs-lg);
  font-weight: var(--kami-fw-title);
  color: var(--kami-fg);
  letter-spacing: var(--kami-ls-title);
  text-transform: var(--kami-title-transform);
  line-height: 1.2;
}

html[data-kami-skin="manga"] .kami-sub {
  font-size: var(--kami-fs-xs);
  color: var(--kami-fg-mute);
  font-family: var(--kami-font-mono);
  line-height: 1;
}

html[data-kami-skin="manga"] .kami-actions {
  margin-left: auto;
  display: inline-flex;
  align-items: center;
  gap: var(--kami-gap);
  flex-shrink: 0;
}

html[data-kami-skin="manga"] .kami-body {
  position: relative;
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
}

html[data-kami-skin="manga"] .kami-foot {
  padding: var(--kami-pad-y) var(--kami-pad-lg-x);
  border-top: var(--kami-border-w) solid var(--kami-line);
  background-color: var(--kami-bg-soft);
  font-size: var(--kami-fs-xs);
  color: var(--kami-fg-dim);
}

/* ==========================================================================
 * 8 · 按钮、分段控件、徽章与开关
 * ======================================================================== */
/* 按钮基础 */
html[data-kami-skin="manga"] .kami-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: var(--kami-row-h);
  padding: var(--kami-pad-y) var(--kami-pad-x);
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-sm);
  background-color: var(--kami-card);
  color: var(--kami-fg);
  font-family: var(--kami-font-title);
  font-size: var(--kami-fs-sm);
  font-weight: var(--kami-fw-title);
  cursor: pointer;
  user-select: none;
  box-shadow: var(--kami-shadow-sm);
  transition: transform var(--kami-dur-fast) var(--kami-ease), box-shadow var(--kami-dur-fast) var(--kami-ease), background-color var(--kami-dur-fast) var(--kami-ease), color var(--kami-dur-fast) var(--kami-ease);
}

html[data-kami-skin="manga"] .kami-btn:hover {
  transform: translate(-1px, -1px);
  box-shadow: 3px 3px 0px var(--kami-line);
}

html[data-kami-skin="manga"] .kami-btn:active {
  transform: translate(1px, 1px);
  box-shadow: 1px 1px 0px var(--kami-line);
}

/* 主要按钮（原稿黑实底反白字） */
html[data-kami-skin="manga"] .kami-btn--primary {
  background-color: var(--kami-fg);
  color: var(--kami-bg);
  border-color: var(--kami-fg);
}

html[data-kami-skin="manga"] .kami-btn--primary:hover {
  background-color: var(--kami-accent);
  border-color: var(--kami-accent);
  color: var(--kami-accent-fg);
}

/* 次级幽灵按钮 */
html[data-kami-skin="manga"] .kami-btn--ghost {
  background-color: transparent;
  box-shadow: none;
}

html[data-kami-skin="manga"] .kami-btn--ghost:hover {
  background-color: var(--kami-card-2);
  box-shadow: 2px 2px 0px var(--kami-line);
}

/* 按钮选中态（成对反转字色，彻底杜绝 1:1 事故） */
html[data-kami-skin="manga"] .kami-btn.is-on {
  background-color: var(--kami-fg);
  color: var(--kami-bg);
  border-color: var(--kami-fg);
  box-shadow: 2px 2px 0px var(--kami-accent);
}

/* 图标按钮 */
html[data-kami-skin="manga"] .kami-icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--kami-row-h);
  height: var(--kami-row-h);
  padding: 0;
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-sm);
  background-color: var(--kami-card);
  color: var(--kami-fg);
  font-size: var(--kami-icon);
  cursor: pointer;
  user-select: none;
  box-shadow: var(--kami-shadow-sm);
  transition: transform var(--kami-dur-fast) var(--kami-ease), box-shadow var(--kami-dur-fast) var(--kami-ease);
}

html[data-kami-skin="manga"] .kami-icon-btn:hover {
  transform: translate(-1px, -1px);
  box-shadow: 3px 3px 0px var(--kami-line);
}

html[data-kami-skin="manga"] .kami-icon-btn:active {
  transform: translate(1px, 1px);
  box-shadow: 1px 1px 0px var(--kami-line);
}

html[data-kami-skin="manga"] .kami-icon-btn[aria-pressed="true"] {
  background-color: var(--kami-fg);
  color: var(--kami-bg);
  border-color: var(--kami-fg);
}

/* 分段切换控件 */
html[data-kami-skin="manga"] .kami-seg {
  display: inline-flex;
  align-items: center;
  padding: 2px;
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-sm);
  background-color: var(--kami-card-2);
  gap: 2px;
}

html[data-kami-skin="manga"] .kami-seg-item {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 4px 10px;
  border: 1px solid transparent;
  border-radius: var(--kami-r-xs);
  background: transparent;
  color: var(--kami-fg-dim);
  font-size: var(--kami-fs-xs);
  font-weight: var(--kami-fw-title);
  cursor: pointer;
  user-select: none;
  transition: background-color var(--kami-dur-fast) var(--kami-ease), color var(--kami-dur-fast) var(--kami-ease);
}

html[data-kami-skin="manga"] .kami-seg-item:hover {
  color: var(--kami-fg);
}

html[data-kami-skin="manga"] .kami-seg-item.is-on {
  background-color: var(--kami-fg);
  color: var(--kami-bg);
  border-color: var(--kami-fg);
  box-shadow: 1px 1px 0px var(--kami-accent);
}

/* 徽章与标签 */
html[data-kami-skin="manga"] .kami-chip,
html[data-kami-skin="manga"] .kami-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 2px 6px;
  border: 1px solid var(--kami-line);
  border-radius: var(--kami-r-xs);
  background-color: var(--kami-card);
  color: var(--kami-fg);
  font-size: var(--kami-fs-xs);
  font-weight: 700;
  line-height: 1.2;
}

html[data-kami-skin="manga"] .kami-badge {
  padding: 1px 5px;
  font-family: var(--kami-font-mono);
}

/* 开关组件 */
html[data-kami-skin="manga"] .kami-switch {
  position: relative;
  display: inline-block;
  width: 42px;
  height: 24px;
  flex-shrink: 0;
  cursor: pointer;
}

html[data-kami-skin="manga"] .kami-switch-input {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}

html[data-kami-skin="manga"] .kami-switch-track {
  position: absolute;
  inset: 0;
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-pill);
  background-color: var(--kami-card-2);
  transition: background-color var(--kami-dur) var(--kami-ease), border-color var(--kami-dur) var(--kami-ease);
}

html[data-kami-skin="manga"] .kami-switch-knob {
  position: absolute;
  top: 2px;
  left: 2px;
  width: 16px;
  height: 16px;
  border: 1px solid var(--kami-line);
  border-radius: var(--kami-r-pill);
  background-color: var(--kami-fg);
  transition: transform var(--kami-dur) var(--kami-ease), background-color var(--kami-dur) var(--kami-ease);
}

html[data-kami-skin="manga"] .kami-switch-input:checked + .kami-switch-track {
  background-color: var(--kami-accent);
  border-color: var(--kami-line);
}

html[data-kami-skin="manga"] .kami-switch-input:checked + .kami-switch-track .kami-switch-knob {
  transform: translateX(18px);
  background-color: #ffffff;
}

/* 滑杆 */
html[data-kami-skin="manga"] .kami-range {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 6px;
  border: 1px solid var(--kami-line);
  border-radius: var(--kami-r-pill);
  background: var(--kami-card-2);
  outline: none;
}

html[data-kami-skin="manga"] .kami-range::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 16px;
  height: 16px;
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-pill);
  background: var(--kami-accent);
  cursor: pointer;
  box-shadow: 1px 1px 0px var(--kami-line);
}

/* 折叠箭头 */
html[data-kami-skin="manga"] .kami-chev {
  display: inline-block;
  font-size: var(--kami-fs-sm);
  color: var(--kami-fg-dim);
  transition: transform var(--kami-dur) var(--kami-ease);
  transform-origin: center center;
}

html[data-kami-skin="manga"] .kami-collapse[data-kami-open="1"] > .kami-head .kami-chev,
html[data-kami-skin="manga"] .kami-collapse[data-kami-open="1"] > .kami-collapse-head .kami-chev {
  transform: rotate(90deg);
  color: var(--kami-accent);
}

/* ==========================================================================
 * 9 · 消息楼层前端（思维链 / 选项）
 * ======================================================================== */
html[data-kami-skin="manga"] .kami-root[data-kami-comp="think"],
html[data-kami-skin="manga"] .kami-root[data-kami-comp="options"] {
  max-width: var(--kami-maxw);
  margin: 0 auto;
}

/* 操作行 */
html[data-kami-skin="manga"] .kami-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--kami-gap);
  padding: 6px 0;
  margin-bottom: var(--kami-gap);
  border-bottom: 1px dashed var(--kami-line);
}

/* markdown 与原文
   ── 2026-09-25 补齐（此前只有 .kami-md / p / code 三条）──────────────────
   按老五套样板（grokbot/skin.css:1043-1159）把标题、列表、引用、表格、
   代码块、分隔线、链接、强调、图片全部补齐；造型走漫画草稿自己的语言：
   Impact 标题 + 全大写、3px 粗墨分镜线、朱笔修正竖条、硬边缘投影、
   网点纸底（--kami-card-2 自带 halftone 纹理）、墨块反白表头。 */
html[data-kami-skin="manga"] .kami-md {
  font-size: var(--kami-fs);
  line-height: var(--kami-lh);
  color: var(--kami-fg);
  overflow-wrap: anywhere;
}

html[data-kami-skin="manga"] .kami-md > :first-child { margin-top: 0; }
html[data-kami-skin="manga"] .kami-md > :last-child { margin-bottom: 0; }

html[data-kami-skin="manga"] .kami-md p {
  margin: 0 0 .6em 0;
}

html[data-kami-skin="manga"] .kami-md p:last-child {
  margin-bottom: 0;
}

/* 标题：Impact 分镜字 + 粗墨下边线（h1/h2）/ 朱笔修正竖条（h3） */
html[data-kami-skin="manga"] .kami-md h1,
html[data-kami-skin="manga"] .kami-md h2,
html[data-kami-skin="manga"] .kami-md h3,
html[data-kami-skin="manga"] .kami-md h4,
html[data-kami-skin="manga"] .kami-md h5,
html[data-kami-skin="manga"] .kami-md h6 {
  margin: 1em 0 .42em;
  font-family: var(--kami-font-title);
  font-weight: var(--kami-fw-title);
  font-size: var(--kami-fs);
  letter-spacing: var(--kami-ls-title);
  text-transform: var(--kami-title-transform);
  color: var(--kami-fg);
  line-height: 1.25;
}

html[data-kami-skin="manga"] .kami-md h1 {
  font-size: calc(var(--kami-fs) * 1.3);
}

html[data-kami-skin="manga"] .kami-md h2 {
  font-size: calc(var(--kami-fs) * 1.16);
  padding-bottom: .24em;
  border-bottom: var(--kami-border-w) solid var(--kami-fg);
}

html[data-kami-skin="manga"] .kami-md h3 {
  font-size: calc(var(--kami-fs) * 1.06);
  padding-left: .5em;
  border-left: var(--kami-accent-mark) solid var(--kami-accent);
}

html[data-kami-skin="manga"] .kami-md strong {
  font-weight: var(--kami-fw-title);
  color: var(--kami-fg);
}

html[data-kami-skin="manga"] .kami-md em {
  font-style: italic;
  color: var(--kami-fg-dim);
}

html[data-kami-skin="manga"] .kami-md del {
  opacity: .6;
  text-decoration-thickness: 1px;
}

html[data-kami-skin="manga"] .kami-md a {
  color: var(--kami-accent);
  text-decoration: underline;
  text-decoration-thickness: 1.5px;
  text-underline-offset: 3px;
}

/* 列表：缩进、行距、::marker 上色、嵌套层换形状 + 换色 */
html[data-kami-skin="manga"] .kami-md ul,
html[data-kami-skin="manga"] .kami-md ol {
  margin: .55em 0;
  padding-left: 1.45em;
}

html[data-kami-skin="manga"] .kami-md li {
  margin: .22em 0;
  line-height: var(--kami-lh);
}

html[data-kami-skin="manga"] .kami-md ul { list-style-type: disc; }
html[data-kami-skin="manga"] .kami-md ul ul { list-style-type: circle; }
html[data-kami-skin="manga"] .kami-md ul ul ul { list-style-type: square; }
html[data-kami-skin="manga"] .kami-md ol { list-style-type: decimal; }
html[data-kami-skin="manga"] .kami-md ol ol { list-style-type: lower-alpha; }

html[data-kami-skin="manga"] .kami-md li::marker {
  color: var(--kami-accent);
  font-weight: 700;
}

/* 嵌套层再淡一档：一眼看出是子级 */
html[data-kami-skin="manga"] .kami-md ul ul > li::marker,
html[data-kami-skin="manga"] .kami-md ul ul ul > li::marker,
html[data-kami-skin="manga"] .kami-md ol ol > li::marker,
html[data-kami-skin="manga"] .kami-md ol ol ol > li::marker {
  color: var(--kami-fg-mute);
  font-weight: 500;
}

html[data-kami-skin="manga"] .kami-md ul ul,
html[data-kami-skin="manga"] .kami-md ul ol,
html[data-kami-skin="manga"] .kami-md ol ul,
html[data-kami-skin="manga"] .kami-md ol ol {
  margin: .18em 0;
  padding-left: 1.2em;
}

/* 引用块：朱笔修正竖条 + 网点纸底 */
html[data-kami-skin="manga"] .kami-md blockquote {
  margin: .7em 0;
  padding: .45em .9em;
  border-left: var(--kami-accent-mark) solid var(--kami-accent);
  border-radius: 0 var(--kami-r-xs) var(--kami-r-xs) 0;
  background-color: var(--kami-card-2);
  color: var(--kami-fg-dim);
  font-style: italic;
}

html[data-kami-skin="manga"] .kami-md blockquote > :first-child { margin-top: 0; }
html[data-kami-skin="manga"] .kami-md blockquote > :last-child { margin-bottom: 0; }

/* 行内码：网点灰底 + 细墨线 */
html[data-kami-skin="manga"] .kami-md code {
  padding: 2px 5px;
  border: 1px solid var(--kami-line);
  border-radius: var(--kami-r-xs);
  background-color: var(--kami-card-2);
  font-family: var(--kami-font-mono);
  font-size: var(--kami-fs-sm);
  color: var(--kami-fg);
}

/* 代码块：分镜格 + 硬投影 */
html[data-kami-skin="manga"] .kami-md pre {
  margin: .7em 0;
  padding: var(--kami-pad-y) var(--kami-pad-x);
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-sm);
  background-color: var(--kami-card-2);
  box-shadow: var(--kami-shadow-sm);
  overflow-x: auto;
}

html[data-kami-skin="manga"] .kami-md pre code {
  padding: 0;
  border: 0;
  background: none;
  box-shadow: none;
  font-size: var(--kami-fs-sm);
}

/* 分隔线：漫画速度线（虚线段） */
html[data-kami-skin="manga"] .kami-md hr {
  height: 3px;
  margin: 1em 0;
  border: 0;
  background-image: linear-gradient(90deg, var(--kami-fg) 0 7px, transparent 7px 12px);
  background-size: 12px 3px;
  background-repeat: repeat-x;
  opacity: .55;
}

/* 表格：漫画分镜格，表头墨块反白 */
html[data-kami-skin="manga"] .kami-md table {
  width: 100%;
  border-collapse: collapse;
  margin: .7em 0;
  font-size: var(--kami-fs-sm);
  font-variant-numeric: tabular-nums;
}

html[data-kami-skin="manga"] .kami-md th,
html[data-kami-skin="manga"] .kami-md td {
  padding: 5px 9px;
  border: var(--kami-border-w) solid var(--kami-line);
  text-align: left;
}

html[data-kami-skin="manga"] .kami-md th {
  background-color: var(--kami-fg);
  color: var(--kami-bg);
  font-family: var(--kami-font-title);
  font-weight: var(--kami-fw-title);
  letter-spacing: var(--kami-ls-title);
}

html[data-kami-skin="manga"] .kami-md tbody tr:nth-child(even) td {
  background-color: var(--kami-t1);
}

/* 图片：贴一张分镜格 */
html[data-kami-skin="manga"] .kami-md img {
  max-width: 100%;
  height: auto;
  display: block;
  margin: .5em 0;
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-xs);
  box-shadow: var(--kami-shadow-sm);
}

html[data-kami-skin="manga"] .kami-raw {
  display: block;
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-sm);
  background-color: var(--kami-card-2);
  font-family: var(--kami-font-mono);
  font-size: var(--kami-fs-sm);
  line-height: 1.5;
  color: var(--kami-fg);
  white-space: pre-wrap;
  word-break: break-all;
}

/* 内联提示 */
html[data-kami-skin="manga"] .kami-toast {
  position: absolute;
  top: 8px;
  right: 8px;
  padding: 4px 10px;
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-sm);
  background-color: var(--kami-card);
  color: var(--kami-fg);
  font-size: var(--kami-fs-xs);
  font-weight: 700;
  box-shadow: 2px 2px 0px var(--kami-line);
  z-index: 10;
  animation: kami-mg-pop var(--kami-dur) var(--kami-ease);
}

html[data-kami-skin="manga"] .kami-toast.is-bad {
  background-color: var(--kami-warn);
  color: #ffffff;
  border-color: var(--kami-line);
}

/* 空态 */
html[data-kami-skin="manga"] .kami-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  color: var(--kami-fg-mute);
  font-size: var(--kami-fs-sm);
  font-style: italic;
}

/* 成功与忙碌钩子 */
html[data-kami-skin="manga"] .is-done {
  border-color: var(--kami-accent) !important;
  color: var(--kami-accent) !important;
}

html[data-kami-skin="manga"] [data-kami-busy="1"] {
  opacity: .6;
  pointer-events: none;
  cursor: wait;
}

/* ==========================================================================
 * 10 · 面板组件与卡片（契约 §4.4：绝不写死面板 id）
 * ======================================================================== */
/* 浮动面板本体 */
html[data-kami-skin="manga"] .kami-root[data-kami-comp="panel"] .kami-drop {
  position: absolute;
  left: var(--kami-panel-x, calc(50% - var(--kami-panel-w, 430px) / 2));
  top: var(--kami-panel-y, 72px);
  width: var(--kami-panel-w, 430px);
  height: var(--kami-panel-h, 570px);
  display: flex;
  flex-direction: column;
  background-color: var(--kami-bg);
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-lg);
  box-shadow: 6px 6px 0px var(--kami-line);
  overflow: hidden;
}

/* ⚠️ 面板滚动链路（2026-09-23 修「不能上下滑动」）：平台几何层只下发位置与尺寸，
   滚动区必须**被约束高度**才可能滚 —— 头/页签/脚不伸缩，中间页吃掉剩余高度。
   缺这条的表现：内容按自身高度撑开、没有溢出可滚，拖也拖不动（civdawn 真机报过同款）。 */
html[data-kami-skin="manga"] .kami-root[data-kami-comp="panel"] .kami-drop > .kami-head,
html[data-kami-skin="manga"] .kami-root[data-kami-comp="panel"] .kami-drop > .kami-tabs,
html[data-kami-skin="manga"] .kami-root[data-kami-comp="panel"] .kami-drop > .kami-foot {
  flex: 0 0 auto;
}
html[data-kami-skin="manga"] .kami-root[data-kami-comp="panel"] .kami-drop > .kami-body {
  flex: 1 1 auto;
  min-height: 0;
}

/* 贴底抽屉模式 */
html[data-kami-skin="manga"] .kami-root[data-kami-comp="panel"] .kami-drop[data-kami-layout="sheet"] {
  left: 0 !important;
  right: 0 !important;
  bottom: 0 !important;
  top: auto !important;
  width: 100% !important;
  max-height: 85% !important;
  border-radius: var(--kami-r-lg) var(--kami-r-lg) 0 0 !important;
  border-bottom: none !important;
  box-shadow: 0 -4px 0px var(--kami-line) !important;
}

/* 标签页导航 */
html[data-kami-skin="manga"] .kami-root[data-kami-comp="panel"] .kami-tabs {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 6px var(--kami-pad-lg-x);
  background-color: var(--kami-bg-soft);
  border-bottom: var(--kami-border-w) solid var(--kami-line);
  overflow-x: auto;
}

html[data-kami-skin="manga"] .kami-root[data-kami-comp="panel"] .kami-tab {
  display: inline-flex;
  align-items: center;
  padding: 6px 12px;
  border: var(--kami-border-w) solid transparent;
  border-radius: var(--kami-r-sm);
  background: transparent;
  color: var(--kami-fg-dim);
  font-family: var(--kami-font-title);
  font-size: var(--kami-fs-sm);
  font-weight: var(--kami-fw-title);
  cursor: pointer;
  user-select: none;
  white-space: nowrap;
  transition: all var(--kami-dur-fast) var(--kami-ease);
}

html[data-kami-skin="manga"] .kami-root[data-kami-comp="panel"] .kami-tab:hover {
  color: var(--kami-fg);
  background-color: var(--kami-card);
  border-color: var(--kami-line);
}

html[data-kami-skin="manga"] .kami-root[data-kami-comp="panel"] .kami-tab[aria-selected="true"] {
  background-color: var(--kami-fg);
  color: var(--kami-bg);
  border-color: var(--kami-fg);
  box-shadow: 2px 2px 0px var(--kami-accent);
}

/* 面板滚动体 */
html[data-kami-skin="manga"] .kami-root[data-kami-comp="panel"] .kami-scroll {
  flex: 1 1 auto;
  overflow-y: auto;
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
  scrollbar-width: thin;
  scrollbar-color: var(--kami-line) transparent;
}

html[data-kami-skin="manga"] .kami-root[data-kami-comp="panel"] .kami-scroll::-webkit-scrollbar {
  width: 6px;
}

html[data-kami-skin="manga"] .kami-root[data-kami-comp="panel"] .kami-scroll::-webkit-scrollbar-thumb {
  background-color: var(--kami-line);
  border-radius: var(--kami-r-pill);
}

/* 缩放把手 */
html[data-kami-skin="manga"] .kami-root[data-kami-comp="panel"] .kami-resize {
  position: absolute;
  right: 2px;
  bottom: 2px;
  width: 14px;
  height: 14px;
  cursor: nwse-resize;
  background-image:
    linear-gradient(135deg, transparent 6px, var(--kami-line) 6px, var(--kami-line) 8px, transparent 8px),
    linear-gradient(135deg, transparent 10px, var(--kami-line) 10px, var(--kami-line) 12px, transparent 12px);
}

/* 列表与分镜卡片 */
html[data-kami-skin="manga"] .kami-root .kami-list {
  display: flex;
  flex-direction: var(--kami-list-dir);
  gap: var(--kami-gap);
}

html[data-kami-skin="manga"] .kami-root .kami-card {
  position: relative;
  display: block;
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-md);
  background-color: var(--kami-card);
  box-shadow: 3px 3px 0px var(--kami-line);
  transition: transform var(--kami-dur-fast) var(--kami-ease), box-shadow var(--kami-dur-fast) var(--kami-ease), border-color var(--kami-dur-fast) var(--kami-ease);
}

html[data-kami-skin="manga"] .kami-root .kami-card:not(.kami-item) {
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
  margin-bottom: var(--kami-gap);
}

/* 卡片主体 */
html[data-kami-skin="manga"] .kami-card-body {
  display: block;
  font-size: var(--kami-fs-sm);
  color: var(--kami-fg-dim);
  line-height: var(--kami-lh);
}

/* 分组卡内部网格的边距控制：避免内边距叠两层挤扁条目名 */
html[data-kami-skin="manga"] .kami-drop .kami-card:has(> .kami-card-body > .kami-grid) {
  padding-left: 12px;
  padding-right: 12px;
}

html[data-kami-skin="manga"] .kami-drop .kami-card:not(.kami-item):has(> .kami-card-body > .kami-grid) > .kami-card-head,
html[data-kami-skin="manga"] .kami-drop .kami-card:not(.kami-item):has(> .kami-card-body > .kami-grid) > .kami-card-title,
html[data-kami-skin="manga"] .kami-drop .kami-card:not(.kami-item):has(> .kami-card-body > .kami-grid) > .kami-card-note {
  padding-left: 0;
  padding-right: 0;
}

/* 面板卡头：与卡同宽的矩形条，不做悬空胶囊 */
html[data-kami-skin="manga"] .kami-root[data-kami-comp="panel"] button.kami-card-head.kami-btn {
  width: 100%;
  min-height: 0;
  border-radius: var(--kami-r-xs);
  justify-content: flex-start;
  padding: 6px 8px;
  background: transparent;
  border: none;
}

/* 面板里的条目卡片 */
html[data-kami-skin="manga"] .kami-root[data-kami-comp="panel"] .kami-item {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  text-align: left;
  width: 100%;
  padding: var(--kami-pad-y) var(--kami-pad-x);
  cursor: pointer;
  user-select: none;
}

html[data-kami-skin="manga"] .kami-root[data-kami-comp="panel"] .kami-item:hover {
  transform: translate(-1px, -1px);
  box-shadow: 4px 4px 0px var(--kami-line);
  border-color: var(--kami-line);
}

html[data-kami-skin="manga"] .kami-root[data-kami-comp="panel"] .kami-item:active {
  transform: translate(1px, 1px);
  box-shadow: 2px 2px 0px var(--kami-line);
}

/* 激活选中态（开关开着）：必须有可视差别，翻转字色 */
html[data-kami-skin="manga"] .kami-root[data-kami-comp="panel"] .kami-item.is-on,
html[data-kami-skin="manga"] .kami-root[data-kami-comp="panel"] .kami-card-head.is-on {
  border-color: var(--kami-accent);
  box-shadow: 3px 3px 0px var(--kami-accent);
  background-color: var(--kami-card);
}

html[data-kami-skin="manga"] .kami-root[data-kami-comp="panel"] .kami-item.is-on::after {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  bottom: 0;
  width: 4px;
  background-color: var(--kami-accent);
  border-radius: var(--kami-r-xs) 0 0 var(--kami-r-xs);
}

html[data-kami-skin="manga"] .kami-root .kami-item-main {
  font-weight: 700;
  font-size: var(--kami-fs-sm);
  color: var(--kami-fg);
  line-height: 1.3;
}

html[data-kami-skin="manga"] .kami-root .kami-item-side {
  font-size: var(--kami-fs-xs);
  color: var(--kami-fg-dim);
  margin-top: 4px;
