"},{"id":"mileng","name":"军事工程","button":"军工","scheme":"dark","tagline":"军事工程装备面板：军绿沙色底、模板喷字大标题、编号刻度带与警示斜纹边条。","effects":[{"id":"ticks","label":"刻度带","desc":"组件头部下缘铺一道刻度尺细线，像装备标牌上的量程刻度。","default":true},{"id":"hazard","label":"警示斜纹","desc":"脚条上缘与提示框边缘铺 45 度沙黄黑警示斜纹边条，永不铺满整屏。","default":false},{"id":"grain","label":"喷漆颗粒","desc":"表面叠一层极淡的磨砂颗粒，像军械涂层掉漆后的底纹。","default":false},{"id":"beacon","label":"信号灯","desc":"状态点像值班信号灯一样缓慢收放辉光，纯 CSS 循环小动画。","default":false}],"params":[{"id":"hatch","label":"斜纹浓度","group":"警示","token":"--kami-mil-hatch","unit":"","min":0,"max":100,"step":5,"value":60},{"id":"grain","label":"颗粒浓度","group":"材质","token":"--kami-mil-grain","unit":"","min":0,"max":100,"step":5,"value":40},{"id":"lamp","label":"辉光半径","group":"氛围","token":"--kami-glow-size","unit":"px","min":0,"max":14,"step":1,"value":6},{"id":"tickgap","label":"刻度间距","group":"刻度","token":"--kami-mil-tick","unit":"px","min":4,"max":14,"step":1,"value":7}],"css":"/* ============================================================================
 * 卡密预设 · 皮肤：军事工程（mileng）
 * ----------------------------------------------------------------------------
 * 设计语言：一张军用装备面板标识板 —— 军绿压仓底、沙色模板喷字标题
 * （全大写、字距拉开的 stencil 字）、编号刻度带做骨架记号，
 * 警示 45 度斜纹只出现在边条与提示上。设计简报见 design/proposals/mileng.md。
 *
 * 身份符号只有一个：「模板喷字的编号刻度」—— 大写拉距标题 + 头部刻度尺
 * + 条目卡头的 01/02 式编号，是同一个记号系统的三件套。
 *
 * 配色：军绿沙色一族占约 85%，沙色前景承担全部正文，沙黄强调只做「点」。
 * 语义色七种按「色相 + 明度」区分（钢蓝 / 沙玫瑰 / 灰绿 / 青灰 / 布黄 / 锈红 / 装备灰）。
 *
 * 对比度（WCAG 2.1 相对亮度公式逐对实算，见设计简报 §三）：
 *   暗档 正文最差 12.7:1 ｜ 次要 8.9:1 ｜ 最弱 5.2:1 ｜ 强调底上的字 7.1:1
 *   亮档 正文最差 13.0:1 ｜ 次要 7.0:1 ｜ 最弱 4.6:1 ｜ 强调底上的字 6.9:1
 *   强描边对卡底：暗档 3.2:1、亮档 3.4:1，均 >= 3:1。
 *
 * 纯 CSS：零外部请求、无 JS、无 @import、无 @font-face、无 vh、
 * 无 position:fixed 铺满、--kami-blur: 0px（不做玻璃）。契约：docs/皮肤契约.md。
 * ========================================================================== */

/* ==========================================================================
 * 1 · 令牌全集（默认暗档：军绿仓底 + 沙色前景 + 沙黄强调）
 * ======================================================================== */
html[data-kami-skin="mileng"] .kami-root {
  /* —— 风格性文案槽位（契约 §3.7） —— */
  --kami-label-think-title: 战况推演;
  --kami-label-think-title-open: 推演全文;
  --kami-label-options-title: 行动命令;

  /* —— 色彩：军绿底三层阶梯 + 沙色前景 + 沙黄强调 —— */
  --kami-fg: #e9e1c8;            /* 主文字：沙白，对仓底 14.2:1 */
  --kami-fg-dim: #b9ae8d;        /* 次要文字：对正文块底 8.9:1 */
  --kami-fg-mute: #968f70;       /* 最弱文字：对卡底 5.2:1 */
  --kami-accent: #d8a93c;        /* 强调色：警示沙黄，只做「点」 */
  --kami-accent-fg: #1c1302;     /* 强调底上的文字：近黑，7.1:1 */
  --kami-accent-soft: rgba(216, 169, 60, 0.14);
  --kami-accent-line: rgba(216, 169, 60, 0.50);

  --kami-bg: #1a1e10;            /* 容器背景：军绿仓底 */
  --kami-bg-soft: #212612;       /* 次级容器背景 */
  --kami-card: #2a3017;          /* 卡片背景（比仓底亮一档） */
  --kami-card-2: #12150a;        /* 卡片内正文块背景（更暗，正文最清） */
  --kami-card-hover: #384120;    /* 卡片悬停：不透明 */
  --kami-line: rgba(233, 225, 200, 0.13);
  --kami-line-strong: rgba(216, 169, 60, 0.45); /* 对卡底 3.2:1 */
  --kami-t1: rgba(233, 225, 200, 0.05);
  --kami-t2: rgba(233, 225, 200, 0.09);
  --kami-t3: rgba(233, 225, 200, 0.16);
  --kami-warn: #ff9266;          /* 警示：对仓底 7.6:1 */
  --kami-shadow: 0 10px 30px rgba(0, 0, 0, 0.52);
  --kami-shadow-sm: 0 2px 8px rgba(0, 0, 0, 0.42);
  --kami-blur: 0px;              /* 工业面板不做玻璃：零模糊 */

  /* —— 布局与尺寸：小圆角是标牌骨架 —— */
  --kami-r-xs: 2px;
  --kami-r-sm: 3px;
  --kami-r-md: 4px;
  --kami-r-lg: 6px;
  --kami-r-pill: 999px;
  --kami-border-w: 1px;
  --kami-pad-x: 11px;
  --kami-pad-y: 7px;
  --kami-pad-lg-x: 15px;
  --kami-pad-lg-y: 12px;
  --kami-gap: 8px;
  --kami-gap-lg: 12px;
  --kami-row-h: 36px;
  --kami-icon: 15px;
  --kami-maxw: none;
  --kami-items-min: 15.5rem;
  --kami-panel-w: 430px;
  --kami-panel-h: 570px;
  --kami-list-dir: column;
  --kami-justify: stretch;

  /* —— 文本与排版：模板喷字 = 大写 + 拉距 —— */
  --kami-fs-scale: 1;
  --kami-fs: calc(14.5px * var(--kami-fs-scale));
  --kami-fs-xs: calc(var(--kami-fs) * .76);
  --kami-fs-sm: calc(var(--kami-fs) * .88);
  --kami-fs-lg: calc(var(--kami-fs) * 1.14);
  --kami-lh: 1.6;
  --kami-ls: .015em;
  --kami-ls-title: .18em;
  --kami-font: system-ui, -apple-system, "Segoe UI", "Microsoft YaHei", "PingFang SC", "Noto Sans SC", sans-serif;
  --kami-font-title: var(--kami-font);
  --kami-font-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, "Cascadia Mono", "Liberation Mono", monospace;
  --kami-fw: 400;
  --kami-fw-title: 700;
  --kami-title-transform: uppercase;

  /* —— 装饰与特效 —— */
  --kami-texture: radial-gradient(120% 100% at 50% 0%, rgba(216, 169, 60, 0.04), transparent 60%);
  --kami-glow: rgba(216, 169, 60, 0.5);
  --kami-glow-size: 6px;
  --kami-surface-clip: none;
  --kami-accent-mark: 3px;

  /* —— 动效 —— */
  --kami-dur-fast: .12s;
  --kami-dur: .2s;
  --kami-dur-slow: .3s;
  --kami-ease: cubic-bezier(.22, .61, .36, 1);
  --kami-ease-out: cubic-bezier(.16, 1, .3, 1);
  --kami-enter-y: 4px;
  --kami-enter-scale: 1;
  --kami-stagger: 22ms;

  /* —— 压淡令牌（契约 §3.10 可选，本皮肤给全） —— */
  --kami-dim-soft: .62;
  --kami-dim-lock: .42;

  /* —— 皮肤私有参数默认值（面板滑杆写的是这四个令牌） —— */
  --kami-mil-hatch: 60;          /* 警示斜纹浓度，无单位 */
  --kami-mil-grain: 40;          /* 喷漆颗粒浓度，无单位 */
  --kami-mil-tick: 7;            /* 刻度间距，px */

  box-sizing: border-box;
  color: var(--kami-fg);
  font-family: var(--kami-font);
  font-size: var(--kami-fs);
  font-weight: var(--kami-fw);
  line-height: var(--kami-lh);
  letter-spacing: var(--kami-ls);
  font-variant-numeric: tabular-nums;
  text-align: left;
  word-break: break-word;
  -webkit-tap-highlight-color: transparent;
}

/* 辉光半径参数接进标准令牌；刻度间距转成 px 长度 */
html[data-kami-skin="mileng"] .kami-root {
  --kami-mil-tick-l: calc(var(--kami-mil-tick) * 1px);
}

/* ==========================================================================
 * 2 · 明暗方案（亮档：沙纸文件底 + 墨绿字，两套全都在预览台测过）
 * ======================================================================== */
html[data-kami-skin="mileng"][data-kami-scheme="light"] .kami-root {
  --kami-fg: #262b15;            /* 主文字：墨绿，对沙纸底 13.0:1 */
  --kami-fg-dim: #4c5236;        /* 次要：7.0:1 */
  --kami-fg-mute: #666b4c;       /* 最弱：4.6:1 */
  --kami-accent: #97731a;        /* 强调压深：白字在其上 4.9:1 */
  --kami-accent-fg: #faf6e8;
  --kami-accent-soft: rgba(151, 115, 26, 0.13);
  --kami-accent-line: rgba(151, 115, 26, 0.52);

  --kami-bg: #e7e0cc;
  --kami-bg-soft: #ded6bd;
  --kami-card: #efe9d6;
  --kami-card-2: #ddd5bb;
  --kami-card-hover: #f7f2e0;
  --kami-line: rgba(38, 43, 21, 0.16);
  --kami-line-strong: rgba(38, 43, 21, 0.50); /* 对卡底 3.4:1 */
  --kami-t1: rgba(38, 43, 21, 0.045);
  --kami-t2: rgba(38, 43, 21, 0.075);
  --kami-t3: rgba(38, 43, 21, 0.14);
  --kami-warn: #b3401c;
  --kami-shadow: 0 10px 26px rgba(30, 26, 10, 0.18);
  --kami-shadow-sm: 0 2px 8px rgba(30, 26, 10, 0.12);

  --kami-texture: radial-gradient(120% 100% at 50% 0%, rgba(151, 115, 26, 0.05), transparent 60%);
  --kami-glow: rgba(151, 115, 26, 0.38);

  --kami-kind-action: #2b5a7e;   /* 行动 · 钢蓝 */
  --kami-kind-persona: #9c4a60;  /* 性格 · 沙玫瑰 */
  --kami-kind-plot: #47702d;     /* 推进 · 灰绿 */
  --kami-kind-info: #20727b;     /* 信息 · 青灰 */
  --kami-kind-fun: #8a6d10;      /* 搞笑 · 布黄 */
  --kami-kind-nsfw: #a53f2a;     /* nsfw · 锈红 */
  --kami-kind-other: #585c43;    /* 其他 · 装备灰 */
}

/* ==========================================================================
 * 3 · 档位响应：密度 / 动效 / 减少动态
 * ======================================================================== */
html[data-kami-skin="mileng"][data-kami-density="compact"] .kami-root {
  --kami-pad-x: 9px;
  --kami-pad-y: 5px;
  --kami-pad-lg-x: 12px;
  --kami-pad-lg-y: 9px;
  --kami-gap: 6px;
  --kami-gap-lg: 9px;
  --kami-row-h: 30px;
}

html[data-kami-skin="mileng"][data-kami-density="cozy"] .kami-root {
  --kami-pad-x: 11px;
  --kami-pad-y: 7px;
  --kami-pad-lg-x: 15px;
  --kami-pad-lg-y: 12px;
  --kami-gap: 8px;
  --kami-gap-lg: 12px;
  --kami-row-h: 36px;
}

html[data-kami-skin="mileng"][data-kami-density="roomy"] .kami-root {
  --kami-pad-x: 14px;
  --kami-pad-y: 10px;
  --kami-pad-lg-x: 19px;
  --kami-pad-lg-y: 17px;
  --kami-gap: 10px;
  --kami-gap-lg: 15px;
  --kami-row-h: 42px;
}

/* calm：时长降一档 + 去掉循环动画 */
html[data-kami-skin="mileng"][data-kami-motion="calm"] .kami-root {
  --kami-dur-fast: .07s;
  --kami-dur: .11s;
  --kami-dur-slow: .16s;
  --kami-enter-y: 1px;
  --kami-stagger: 8ms;
}

/* off：全部压到 1ms 且无位移；循环动画直接 animation:none（契约 §3.6） */
html[data-kami-skin="mileng"][data-kami-motion="off"] .kami-root {
  --kami-dur-fast: 1ms;
  --kami-dur: 1ms;
  --kami-dur-slow: 1ms;
  --kami-enter-y: 0px;
  --kami-enter-scale: 1;
  --kami-stagger: 0ms;
}

@media (prefers-reduced-motion: reduce) {
  html[data-kami-skin="mileng"] .kami-root {
    --kami-dur-fast: 1ms;
    --kami-dur: 1ms;
    --kami-dur-slow: 1ms;
    --kami-enter-y: 0px;
    --kami-enter-scale: 1;
    --kami-stagger: 0ms;
  }
  /* 循环动画一律直接停：压到 1ms 仍然是无限循环，reduce 下不许跑 */
  html[data-kami-skin="mileng"] .kami-root *,
  html[data-kami-skin="mileng"] .kami-root *::before,
  html[data-kami-skin="mileng"] .kami-root *::after {
    animation: none !important;
    transition-duration: 1ms !important;
  }
}

/* ==========================================================================
 * 4 · 关键帧（信号灯收放 / 斜纹爬行 / 入场）
 * ======================================================================== */
@keyframes kami-mil-in {
  from { opacity: 0; transform: translateY(calc(var(--kami-enter-y) * -1)); }
  to { opacity: 1; transform: none; }
}

@keyframes kami-mil-beacon {
  0%, 100% { box-shadow: 0 0 2px var(--kami-glow); }
  50% { box-shadow: 0 0 var(--kami-glow-size) var(--kami-glow); }
}

@keyframes kami-mil-hatch {
  from { background-position-x: 0px; }
  to { background-position-x: 16px; }
}

/* ==========================================================================
 * 5 · 焦点与可访问性
 * ======================================================================== */
html[data-kami-skin="mileng"] .kami-root :focus-visible {
  outline: 2px solid var(--kami-accent);
