}

html[data-kami-skin="mileng"] .kami-root .kami-switch-input:focus-visible + .kami-switch-track {
  outline: 2px solid var(--kami-accent);
  outline-offset: 2px;
}

/* ==========================================================================
 * 6 · 控件对比度四件套（panel 作用域 + 三项 !important）
 *    阻击两层抢色：① 酒馆「自定义 CSS」给四类控件上的 !important 深漆；
 *    ② 皮肤头部 input { color: inherit } 把文字压成 fg-dim。
 *    background-color 必须长写：简写会把 .kami-select 自绘箭头一起重置掉。
 * ======================================================================== */
html[data-kami-skin="mileng"] .kami-root[data-kami-comp="panel"] input.kami-number,
html[data-kami-skin="mileng"] .kami-root[data-kami-comp="panel"] select.kami-number,
html[data-kami-skin="mileng"] .kami-root[data-kami-comp="panel"] textarea.kami-number,
html[data-kami-skin="mileng"] .kami-root[data-kami-comp="panel"] input.kami-text,
html[data-kami-skin="mileng"] .kami-root[data-kami-comp="panel"] textarea.kami-textarea,
html[data-kami-skin="mileng"] .kami-root[data-kami-comp="panel"] select.kami-select {
  color: var(--kami-fg) !important;
  background-color: var(--kami-bg-soft) !important;
  border-color: var(--kami-line-strong) !important;
  color-scheme: dark !important;
}

html[data-kami-skin="mileng"][data-kami-scheme="light"] .kami-root[data-kami-comp="panel"] input.kami-number,
html[data-kami-skin="mileng"][data-kami-scheme="light"] .kami-root[data-kami-comp="panel"] select.kami-number,
html[data-kami-skin="mileng"][data-kami-scheme="light"] .kami-root[data-kami-comp="panel"] textarea.kami-number,
html[data-kami-skin="mileng"][data-kami-scheme="light"] .kami-root[data-kami-comp="panel"] input.kami-text,
html[data-kami-skin="mileng"][data-kami-scheme="light"] .kami-root[data-kami-comp="panel"] textarea.kami-textarea,
html[data-kami-skin="mileng"][data-kami-scheme="light"] .kami-root[data-kami-comp="panel"] select.kami-select {
  color-scheme: light !important;
}

/* 右对齐只属于数字框（契约 §4.2：不许挂在裸类名上） */
html[data-kami-skin="mileng"] .kami-root input.kami-number[type="number"] {
  text-align: right;
}

/* ==========================================================================
 * 7 · 结构与等高约束
 * ======================================================================== */
html[data-kami-skin="mileng"] .kami-root .kami-item-note {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

html[data-kami-skin="mileng"] .kami-root .kami-item-note > .kami-card {
  flex: 1 1 auto;
}

/* 预览窗必须 pointer-events:none：少一处就是「预览卡点不动」（iframe 吃点击） */
html[data-kami-skin="mileng"] .kami-root .kami-pv,
html[data-kami-skin="mileng"] .kami-root .kami-pv-frame,
html[data-kami-skin="mileng"] .kami-root .kami-guide-pv,
html[data-kami-skin="mileng"] .kami-root .kami-guide-pv-frame {
  pointer-events: none;
}

/* ==========================================================================
 * 8 · 基础重置
 * ======================================================================== */
html[data-kami-skin="mileng"] .kami-root *,
html[data-kami-skin="mileng"] .kami-root *::before,
html[data-kami-skin="mileng"] .kami-root *::after {
  box-sizing: border-box;
}

html[data-kami-skin="mileng"] .kami-root button,
html[data-kami-skin="mileng"] .kami-root input,
html[data-kami-skin="mileng"] .kami-root select,
html[data-kami-skin="mileng"] .kami-root textarea {
  font: inherit;
  color: inherit;
  letter-spacing: inherit;
  margin: 0;
}

html[data-kami-skin="mileng"] .kami-root button {
  -webkit-appearance: none;
  appearance: none;
}

html[data-kami-skin="mileng"] .kami-root [hidden] {
  display: none !important;
}

html[data-kami-skin="mileng"] .kami-root img {
  max-width: 100%;
}

/* 装饰槽：本皮肤不声明 decor，槽位一律收起 */
html[data-kami-skin="mileng"] .kami-root .kami-deco {
  display: none;
}
/* 若平台升级出 d20，也不给它让皮肤样式（本皮肤未声明 decor） */
html[data-kami-skin="mileng"] .kami-root .kami-deco.kami-d20 {
  display: none;
}

/* 结构兜底（与脚本注入的 STRUCT_CSS 一致，皮肤自己再写一遍，双保险） */
html[data-kami-skin="mileng"] .kami-root .kami-collapse[data-kami-open="0"] > .kami-collapse-body {
  display: none;
}
html[data-kami-skin="mileng"] .kami-root .kami-collapse[data-kami-open="1"] > .kami-collapse-body {
  display: block;
}
html[data-kami-skin="mileng"] .kami-root[data-kami-view="raw"] [data-kami-view="render"] {
  display: none;
}
html[data-kami-skin="mileng"] .kami-root[data-kami-view="render"] [data-kami-view="raw"] {
  display: none;
}

/* ==========================================================================
 * 9 · 外壳 / 表面 / 三段结构
 *     ⚠️ .kami-shell 与 .kami-surface 常是同一个元素：只写
 *     background-color / background-image 长写属性，绝不写 background 简写。
 * ======================================================================== */
html[data-kami-skin="mileng"] .kami-shell {
  position: relative;
  display: block;
  background-color: var(--kami-bg);
  border: var(--kami-border-w) solid var(--kami-line-strong);
  border-radius: var(--kami-r-lg);
  box-shadow: var(--kami-shadow);
  overflow: hidden;
  container-type: inline-size;
  transition: border-color var(--kami-dur) var(--kami-ease), box-shadow var(--kami-dur) var(--kami-ease);
}

html[data-kami-skin="mileng"] .kami-surface {
  background-image: var(--kami-texture);
}

html[data-kami-skin="mileng"] .kami-head {
  position: relative;
  display: flex;
  align-items: center;
  gap: var(--kami-gap);
  min-height: var(--kami-row-h);
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
}

html[data-kami-skin="mileng"] .kami-head:not(.kami-collapse-head) {
  border-bottom: var(--kami-border-w) solid var(--kami-line-strong);
}

html[data-kami-skin="mileng"] .kami-collapse-head {
  cursor: pointer;
  user-select: none;
}

/* 模板喷字标题：大写 + 拉距 + 字重；不加 text-stroke（小字会糊） */
html[data-kami-skin="mileng"] .kami-title {
  font-family: var(--kami-font-title);
  font-weight: var(--kami-fw-title);
  font-size: var(--kami-fs);
  letter-spacing: var(--kami-ls-title);
  text-transform: var(--kami-title-transform);
  color: var(--kami-fg);
  white-space: nowrap;
  text-shadow: 0 1px 0 rgba(0, 0, 0, 0.25);
}

html[data-kami-skin="mileng"] .kami-sub {
  font-family: var(--kami-font-mono);
  font-size: var(--kami-fs-xs);
  letter-spacing: var(--kami-ls);
  color: var(--kami-fg-mute);
  white-space: nowrap;
}

html[data-kami-skin="mileng"] .kami-actions {
  display: flex;
  align-items: center;
  gap: var(--kami-gap);
  margin-left: auto;
  flex: none;
}

html[data-kami-skin="mileng"] .kami-body {
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
}

html[data-kami-skin="mileng"] .kami-foot {
  display: flex;
  align-items: center;
  gap: var(--kami-gap);
  padding: var(--kami-pad-y) var(--kami-pad-lg-x) var(--kami-pad-lg-y);
  border-top: var(--kami-border-w) solid var(--kami-line-strong);
  font-family: var(--kami-font-mono);
  font-size: var(--kami-fs-xs);
  color: var(--kami-fg-mute);
  position: relative;
}

/* —— 状态点 = 信号灯：关态空心方框，开态沙黄实心方块（形状占一样） —— */
html[data-kami-skin="mileng"] .kami-dot {
  flex: none;
  width: 8px;
  height: 8px;
  border: var(--kami-border-w) solid var(--kami-fg-mute);
  border-radius: var(--kami-r-xs);
  background-color: transparent;
  transition: background-color var(--kami-dur) var(--kami-ease), border-color var(--kami-dur) var(--kami-ease);
}

html[data-kami-skin="mileng"] .kami-dot[data-kami-on="1"] {
  background-color: var(--kami-accent);
  border-color: var(--kami-accent);
  box-shadow: 0 0 var(--kami-glow-size) var(--kami-glow);
}

/* 引导向导的进度点复用 .kami-dot：回小方点，不跟信号灯闪 */
html[data-kami-skin="mileng"] .kami-dots .kami-dot {
  width: 6px;
  height: 6px;
  border-color: var(--kami-fg-mute);
  opacity: 0.38;
}

html[data-kami-skin="mileng"] .kami-dots .kami-dot[data-kami-on="1"] {
  background-color: var(--kami-accent);
  border-color: var(--kami-accent);
  opacity: 1;
}

/* —— 折叠箭头 —— */
html[data-kami-skin="mileng"] .kami-chev {
  flex: none;
  font-size: calc(var(--kami-icon) * 0.8);
  color: var(--kami-fg-mute);
  transition: transform var(--kami-dur) var(--kami-ease), color var(--kami-dur) var(--kami-ease);
}

html[data-kami-skin="mileng"] .kami-collapse[data-kami-open="1"] > .kami-head .kami-chev {
  transform: rotate(90deg);
  color: var(--kami-accent);
}

/* —— 正文头部的横向操作行 —— */
html[data-kami-skin="mileng"] .kami-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--kami-gap);
  padding: var(--kami-pad-y) var(--kami-pad-lg-x);
  border-bottom: var(--kami-border-w) solid var(--kami-line);
  background-color: var(--kami-bg-soft);
}

/* ==========================================================================
 * 10 · 按钮
 * ======================================================================== */
html[data-kami-skin="mileng"] .kami-btn,
html[data-kami-skin="mileng"] .kami-icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: var(--kami-row-h);
  padding: var(--kami-pad-y) var(--kami-pad-x);
  border: var(--kami-border-w) solid var(--kami-line-strong);
  border-radius: var(--kami-r-sm);
  background-color: var(--kami-card);
  color: var(--kami-fg);
  font-family: var(--kami-font);
  font-size: var(--kami-fs-sm);
  line-height: 1.2;
  cursor: pointer;
  user-select: none;
  transition: background-color var(--kami-dur-fast) var(--kami-ease),
              border-color var(--kami-dur-fast) var(--kami-ease),
              color var(--kami-dur-fast) var(--kami-ease);
}

html[data-kami-skin="mileng"] .kami-icon-btn {
  min-width: var(--kami-row-h);
  padding: 0;
  font-size: var(--kami-icon);
}

@media (hover: hover) {
  html[data-kami-skin="mileng"] .kami-btn:hover,
  html[data-kami-skin="mileng"] .kami-icon-btn:hover {
    background-color: var(--kami-card-hover);
    border-color: var(--kami-accent);
  }
}

html[data-kami-skin="mileng"] .kami-btn:active,
html[data-kami-skin="mileng"] .kami-icon-btn:active {
  transform: translateY(1px);
}

html[data-kami-skin="mileng"] .kami-btn--ghost {
  background-color: transparent;
}

/* 主按钮：整块强调底 → 文字一族成对翻过去（同型事故三次的教训） */
html[data-kami-skin="mileng"] .kami-root .kami-btn--primary {
  --kami-fg: var(--kami-accent-fg);
  --kami-fg-dim: var(--kami-accent-fg);
  --kami-fg-mute: var(--kami-accent-fg);
  --kami-line: var(--kami-accent-fg);
  --kami-line-strong: var(--kami-accent-fg);
  background-color: var(--kami-accent);
  border-color: var(--kami-accent);
  color: var(--kami-accent-fg);
  font-weight: var(--kami-fw-title);
}

@media (hover: hover) {
  html[data-kami-skin="mileng"] .kami-btn--primary:hover {
    filter: brightness(1.08);
    color: var(--kami-accent-fg);
  }
}

/* 选中态：淡染底 + 内环 + 加粗，三条里三条不是颜色（不改 border-width） */
html[data-kami-skin="mileng"] .kami-root .kami-btn.is-on {
  background-color: var(--kami-accent-soft);
  border-color: var(--kami-accent);
  color: var(--kami-fg);
  font-weight: var(--kami-fw-title);
  box-shadow: inset 0 0 0 1px var(--kami-accent);
}

/* 锁死的主按钮 / 图标按钮：一眼看出点不动 */
html[data-kami-skin="mileng"] .kami-root .kami-btn[disabled],
html[data-kami-skin="mileng"] .kami-root .kami-icon-btn[disabled] {
  opacity: var(--kami-dim-lock, .42);
  color: var(--kami-fg-mute);
  cursor: default;
  box-shadow: none;
  filter: none;
  transform: none;
}

html[data-kami-skin="mileng"] .kami-root .kami-btn[disabled]:hover,
html[data-kami-skin="mileng"] .kami-root .kami-icon-btn[disabled]:hover {
  background-color: var(--kami-card);
  border-color: var(--kami-line-strong);
  color: var(--kami-fg-mute);
}

html[data-kami-skin="mileng"] .kami-root .kami-btn--ghost[disabled],
html[data-kami-skin="mileng"] .kami-btn--primary[disabled] {
  background-color: var(--kami-card);
  border-color: var(--kami-line-strong);
  color: var(--kami-fg-mute);
}

/* ==========================================================================
 * 11 · 分段切换（渲染 / 原文、填入 / 发送）
 * ======================================================================== */
html[data-kami-skin="mileng"] .kami-seg {
  display: inline-flex;
  gap: 2px;
  padding: 2px;
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-sm);
  background-color: var(--kami-t1);
}

html[data-kami-skin="mileng"] .kami-seg-item {
  border: 0;
  border-radius: var(--kami-r-xs);
  background-color: transparent;
  color: var(--kami-fg-dim);
  font-family: var(--kami-font);
  font-size: var(--kami-fs-xs);
  letter-spacing: var(--kami-ls);
  padding: 5px 9px;
  cursor: pointer;
  transition: background-color var(--kami-dur-fast) var(--kami-ease), color var(--kami-dur-fast) var(--kami-ease);
}

/* 选中换整块强调底 → 文字一族翻过去 */
html[data-kami-skin="mileng"] .kami-root .kami-seg-item.is-on {
  --kami-fg: var(--kami-accent-fg);
  --kami-fg-dim: var(--kami-accent-fg);
  --kami-fg-mute: var(--kami-accent-fg);
  --kami-line: var(--kami-accent-fg);
  --kami-line-strong: var(--kami-accent-fg);
  background-color: var(--kami-accent);
  color: var(--kami-accent-fg);
  font-weight: var(--kami-fw-title);
}

/* ==========================================================================
 * 12 · 消息楼层组件（思维链 think / 行动选项 options）
 * ======================================================================== */
html[data-kami-skin="mileng"] .kami-root:not([data-kami-comp="panel"]) {
  margin: 10px 0 8px;
  max-width: var(--kami-maxw);
}

/* —— markdown 正文 —— */
html[data-kami-skin="mileng"] .kami-md {
  font-size: var(--kami-fs-sm);
  line-height: var(--kami-lh);
  color: var(--kami-fg);
}

html[data-kami-skin="mileng"] .kami-md > :first-child {
  margin-top: 0;
}

html[data-kami-skin="mileng"] .kami-md > :last-child {
  margin-bottom: 0;
}

html[data-kami-skin="mileng"] .kami-md p {
  margin: 0.5em 0;
}

html[data-kami-skin="mileng"] .kami-md h1,
html[data-kami-skin="mileng"] .kami-md h2,
html[data-kami-skin="mileng"] .kami-md h3 {
  margin: 0.9em 0 0.4em;
  font-family: var(--kami-font-title);
  font-weight: var(--kami-fw-title);
  font-size: var(--kami-fs);
  letter-spacing: var(--kami-ls-title);
  text-transform: var(--kami-title-transform);
  color: var(--kami-fg);
}

/* 引用块 = 战报里引用前一条命令的输出 */
html[data-kami-skin="mileng"] .kami-md blockquote {
  margin: 0.6em 0;
  padding: 2px 0 2px 10px;
  border-left: var(--kami-accent-mark) solid var(--kami-accent-line);
  color: var(--kami-fg-mute);
}

html[data-kami-skin="mileng"] .kami-md blockquote::before {
  content: "» ";
  color: var(--kami-accent);
}

html[data-kami-skin="mileng"] .kami-md code {
  font-family: var(--kami-font-mono);
  font-size: 0.88em;
  padding: 1px 5px;
  border-radius: var(--kami-r-xs);
  background-color: var(--kami-accent-soft);
  color: var(--kami-fg);
}

html[data-kami-skin="mileng"] .kami-md pre {
  margin: 0.6em 0;
  padding: var(--kami-pad-y) var(--kami-pad-x);
  border-radius: var(--kami-r-sm);
  background-color: var(--kami-card-2);
  border: var(--kami-border-w) solid var(--kami-line);
  overflow-x: auto;
}

html[data-kami-skin="mileng"] .kami-md pre code {
  background: none;
  padding: 0;
  color: inherit;
}

html[data-kami-skin="mileng"] .kami-md ul,
html[data-kami-skin="mileng"] .kami-md ol {
  margin: 0.5em 0;
  padding-left: 1.3em;
}

html[data-kami-skin="mileng"] .kami-md li {
  margin: 0.18em 0;
}

html[data-kami-skin="mileng"] .kami-md strong {
  color: var(--kami-fg);
  font-weight: 700;
}

html[data-kami-skin="mileng"] .kami-md a {
  color: var(--kami-accent);
  text-underline-offset: 2px;
}

html[data-kami-skin="mileng"] .kami-md hr {
  border: 0;
  border-top: var(--kami-border-w) solid var(--kami-line);
  margin: 0.8em 0;
}

/* markdown 表头：沙黄下划线，像栏位表的表头 */
html[data-kami-skin="mileng"] .kami-md table {
  border-collapse: collapse;
  width: 100%;
  font-size: var(--kami-fs-xs);
}

html[data-kami-skin="mileng"] .kami-md th {
  border: var(--kami-border-w) solid var(--kami-line-strong);
  padding: 4px 7px;
  background-color: var(--kami-accent-soft);
  color: var(--kami-fg);
}

html[data-kami-skin="mileng"] .kami-md td {
  border: var(--kami-border-w) solid var(--kami-line);
  padding: 4px 7px;
}

/* —— 原文（等宽）块：装备日志的原文档 —— */
html[data-kami-skin="mileng"] .kami-raw {
  margin: 0;
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
  border-radius: var(--kami-r-md);
  background-color: var(--kami-card-2);
  border: var(--kami-border-w) solid var(--kami-line);
  font-family: var(--kami-font-mono);
  font-size: var(--kami-fs-xs);
  line-height: 1.5;
  color: var(--kami-fg-dim);
  white-space: pre-wrap;
  overflow-x: auto;
}

/* —— 列表 / 网格 —— */
html[data-kami-skin="mileng"] .kami-list {
  display: flex;
  flex-direction: var(--kami-list-dir);
  justify-content: var(--kami-justify);
  gap: var(--kami-gap);
}

html[data-kami-skin="mileng"] .kami-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, var(--kami-items-min)), 1fr));
  gap: var(--kami-gap);
  align-items: stretch;
}

/* 编号刻度：每个直系条目一支计数器；卡头左侧盖一枚 01 式钢印编号 */
html[data-kami-skin="mileng"] .kami-root .kami-grid {
  counter-reset: kami-n 0;
}

html[data-kami-skin="mileng"] .kami-root .kami-grid > .kami-item {
  counter-increment: kami-n;
}

html[data-kami-skin="mileng"] .kami-root .kami-grid > .kami-item > .kami-card-head::before {
  content: counter(kami-n, decimal-leading-zero);
  flex: none;
  font-family: var(--kami-font-mono);
  font-size: var(--kami-fs-xs);
  letter-spacing: var(--kami-ls);
  color: var(--kami-accent);
}

/* —— 卡片 / 条目 —— */
html[data-kami-skin="mileng"] .kami-card {
  position: relative;
  background-color: var(--kami-card);
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-md);
}

html[data-kami-skin="mileng"] .kami-item {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 4px;
  width: 100%;
  text-align: left;
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-md);
  background-color: var(--kami-card);
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
  cursor: pointer;
  transition: background-color var(--kami-dur) var(--kami-ease),
              border-color var(--kami-dur) var(--kami-ease);
}

@media (hover: hover) {
  html[data-kami-skin="mileng"] .kami-item:hover {
    background-color: var(--kami-card-hover);
    border-color: var(--kami-accent);
  }
}

/* 选中态：淡染底 + 内环 + 加粗，形状/边线/字重三样占齐 */
html[data-kami-skin="mileng"] .kami-root .kami-item.is-on,
html[data-kami-skin="mileng"] .kami-root .kami-item[aria-pressed="true"] {
  border-color: var(--kami-accent);
  background-color: var(--kami-accent-soft);
  color: var(--kami-fg);
  font-weight: var(--kami-fw-title);
  box-shadow: inset 0 0 0 1px var(--kami-accent);
}

html[data-kami-skin="mileng"] .kami-item.is-done {
  border-color: var(--kami-accent);
  background-color: var(--kami-accent-soft);
}

html[data-kami-skin="mileng"] .kami-item[data-kami-busy="1"] {
  opacity: 0.7;
  pointer-events: none;
}

html[data-kami-skin="mileng"] .kami-item.is-demo {
  opacity: 0.62;
  cursor: default;
}

html[data-kami-skin="mileng"] .kami-item-main {
  flex: 1 1 auto;
  min-width: 0;
}

html[data-kami-skin="mileng"] .kami-item-side {
  flex: none;
  margin-left: auto;
  color: var(--kami-fg-mute);
  font-family: var(--kami-font-mono);
  font-size: var(--kami-fs-sm);
}

html[data-kami-skin="mileng"] .kami-card-head {
  display: flex;
  align-items: center;
  gap: var(--kami-gap);
  width: 100%;
  margin-bottom: 6px;
}

html[data-kami-skin="mileng"] .kami-card-title {
  font-weight: var(--kami-fw-title);
  font-size: var(--kami-fs-sm);
  letter-spacing: var(--kami-ls);
  color: var(--kami-fg);
}

html[data-kami-skin="mileng"] .kami-card-note {
  font-size: var(--kami-fs-xs);
  color: var(--kami-fg-mute);
}

html[data-kami-skin="mileng"] .kami-card-body {
  display: block;
  font-size: var(--kami-fs-sm);
  color: var(--kami-fg-dim);
}

/* —— 面板里的卡头别做成胶囊：与卡同宽的矩形标题条 —— */
html[data-kami-skin="mileng"] .kami-root[data-kami-comp="panel"] button.kami-card-head.kami-btn {
  width: 100%;
  min-height: 0;
  border-radius: var(--kami-r-xs);
  justify-content: flex-start;
  padding: 6px 8px;
  background-color: transparent;
  border: 0;
}

/* —— chip / badge：军械标牌（消息楼层里的 badge 才做钢印样式） —— */
html[data-kami-skin="mileng"] .kami-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex: none;
  padding: 1px 7px;
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-xs);
  background-color: var(--kami-t1);
  color: var(--kami-fg-dim);
  font-family: var(--kami-font-mono);
  font-size: var(--kami-fs-xs);
  line-height: 1.5;
  white-space: nowrap;
}

/* 语义色：chip / badge / 卡片左缘一条同色标线 */
html[data-kami-skin="mileng"] .kami-root [data-kami-kind="action"]  { --kami-kind-curr: var(--kami-kind-action); }
html[data-kami-skin="mileng"] .kami-root [data-kami-kind="persona"] { --kami-kind-curr: var(--kami-kind-persona); }
html[data-kami-skin="mileng"] .kami-root [data-kami-kind="plot"]    { --kami-kind-curr: var(--kami-kind-plot); }
html[data-kami-skin="mileng"] .kami-root [data-kami-kind="info"]    { --kami-kind-curr: var(--kami-kind-info); }
html[data-kami-skin="mileng"] .kami-root [data-kami-kind="fun"]     { --kami-kind-curr: var(--kami-kind-fun); }
html[data-kami-skin="mileng"] .kami-root [data-kami-kind="nsfw"]    { --kami-kind-curr: var(--kami-kind-nsfw); }
html[data-kami-skin="mileng"] .kami-root [data-kami-kind="other"]   { --kami-kind-curr: var(--kami-kind-other); }

html[data-kami-skin="mileng"] .kami-chip[data-kami-kind] {
  color: var(--kami-kind-curr, var(--kami-accent));
  border-color: var(--kami-kind-curr, var(--kami-accent));
}

/* 消息楼层（options）里的徽记 = 军械标牌：按类型摆钢印色 */
html[data-kami-skin="mileng"] .kami-root:not([data-kami-comp="panel"]) .kami-badge {
  flex: none;
  padding: 1px 7px;
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-xs);
  background-color: var(--kami-t1);
  color: var(--kami-fg-dim);
  font-family: var(--kami-font-mono);
  font-size: var(--kami-fs-xs);
  line-height: 1.5;
  white-space: nowrap;
}

html[data-kami-skin="mileng"] .kami-root:not([data-kami-comp="panel"]) .kami-badge[data-kami-kind="action"] {
  color: var(--kami-kind-action);
  border-color: var(--kami-kind-action);
}

html[data-kami-skin="mileng"] .kami-root:not([data-kami-comp="panel"]) .kami-badge[data-kami-kind="persona"] {
  color: var(--kami-kind-persona);
  border-color: var(--kami-kind-persona);
}

html[data-kami-skin="mileng"] .kami-root:not([data-kami-comp="panel"]) .kami-badge[data-kami-kind="plot"] {
  color: var(--kami-kind-plot);
  border-color: var(--kami-kind-plot);
}

html[data-kami-skin="mileng"] .kami-root:not([data-kami-comp="panel"]) .kami-badge[data-kami-kind="info"] {
  color: var(--kami-kind-info);
  border-color: var(--kami-kind-info);
}

html[data-kami-skin="mileng"] .kami-root:not([data-kami-comp="panel"]) .kami-badge[data-kami-kind="fun"] {
  color: var(--kami-kind-fun);
  border-color: var(--kami-kind-fun);
}

html[data-kami-skin="mileng"] .kami-root:not([data-kami-comp="panel"]) .kami-badge[data-kami-kind="nsfw"] {
  color: var(--kami-kind-nsfw);
  border-color: var(--kami-kind-nsfw);
}

html[data-kami-skin="mileng"] .kami-root:not([data-kami-comp="panel"]) .kami-badge[data-kami-kind="other"] {
  color: var(--kami-kind-other);
  border-color: var(--kami-kind-other);
}

html[data-kami-skin="mileng"] .kami-root .kami-card[data-kami-kind],
html[data-kami-skin="mileng"] .kami-root .kami-item[data-kami-kind] {
  border-left: var(--kami-accent-mark) solid var(--kami-kind-curr, var(--kami-accent-line));
}

/* —— 空态：一枚编号钢印记号 —— */
html[data-kami-skin="mileng"] .kami-empty {
  padding: var(--kami-pad-lg-y) 0;
  color: var(--kami-fg-mute);
  font-size: var(--kami-fs-sm);
}

html[data-kami-skin="mileng"] .kami-empty::before {
  content: "◇ ";
  color: var(--kami-accent);
}

/* —— 内联提示 Toast：左缘一道警示条 —— */
html[data-kami-skin="mileng"] .kami-toast {
  margin-top: var(--kami-gap);
  padding: var(--kami-pad-y) var(--kami-pad-x);
  border: var(--kami-border-w) solid var(--kami-line-strong);
  border-left: var(--kami-accent-mark) solid var(--kami-accent);
  border-radius: var(--kami-r-xs);
  background-color: var(--kami-bg-soft);
  color: var(--kami-fg);
  font-size: var(--kami-fs-xs);
  animation: kami-mil-in var(--kami-dur) var(--kami-ease-out) backwards;
}

html[data-kami-skin="mileng"] .kami-toast.is-bad {
  color: var(--kami-warn);
  border-color: var(--kami-warn);
  border-left-color: var(--kami-warn);
  background-color: var(--kami-card-2);
}

/* ==========================================================================
 * 13 · 面板专用（契约 §4.4：一律 .kami-root[data-kami-comp="panel"] 后代
 *      选择器，绝不挂任何面板 id；组件在四块面板里是同一副样子。）
 * ======================================================================== */
/* 舞台后面压一层暗夜幕，让浮窗从页面里浮出来 */
html[data-kami-skin="mileng"] .kami-root[data-kami-comp="panel"] {
  background-color: rgba(8, 10, 4, 0.55);
}

html[data-kami-skin="mileng"][data-kami-scheme="light"] .kami-root[data-kami-comp="panel"] {
  background-color: rgba(40, 36, 18, 0.28);
}

/* 面板本体：位置与尺寸来自脚本下发的四个几何令牌 */
html[data-kami-skin="mileng"] .kami-root .kami-drop.kami-drop {
  position: absolute;
  left: var(--kami-panel-x, 50%);
  top: var(--kami-panel-y, 72px);
  width: var(--kami-panel-w, min(430px, calc(100% - 24px)));
  height: var(--kami-panel-h, 570px);
  max-height: calc(100% - 24px);
  pointer-events: auto;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background-color: var(--kami-bg);
  background-image: var(--kami-texture);
  border: var(--kami-border-w) solid var(--kami-line-strong);
  border-radius: var(--kami-r-lg);
  box-shadow: var(--kami-shadow);
  container-type: inline-size;
}

html[data-kami-skin="mileng"] .kami-drop > .kami-head,
html[data-kami-skin="mileng"] .kami-drop > .kami-tabs,
html[data-kami-skin="mileng"] .kami-drop > .kami-foot { flex: 0 0 auto; }

html[data-kami-skin="mileng"] .kami-drop > .kami-body { flex: 1 1 auto; min-height: 0; }

/* 拖动把手的视觉反馈 */
html[data-kami-skin="mileng"] .kami-drop > .kami-head[data-kami-drag] { cursor: grab; }
html[data-kami-skin="mileng"] .kami-drop > .kami-head[data-kami-drag]:active { cursor: grabbing; }

/* —— 标签页行：选中的 tab 是「沙黄粗底线 + 加粗」 —— */
html[data-kami-skin="mileng"] .kami-tabs {
  display: flex;
  gap: 2px;
  padding: 0 var(--kami-pad-lg-x);
  border-bottom: var(--kami-border-w) solid var(--kami-line-strong);
  overflow-x: auto;
  scrollbar-width: none;
  -webkit-mask-image: linear-gradient(90deg, #000 calc(100% - 20px), transparent 100%);
  mask-image: linear-gradient(90deg, #000 calc(100% - 20px), transparent 100%);
}

html[data-kami-skin="mileng"] .kami-tabs::-webkit-scrollbar { display: none; }

html[data-kami-skin="mileng"] .kami-tab {
  flex: none;
  border: 0;
  border-bottom: var(--kami-accent-mark) solid transparent;
  background-color: transparent;
  color: var(--kami-fg-mute);
  font-family: var(--kami-font);
  font-size: var(--kami-fs-sm);
  letter-spacing: var(--kami-ls);
  padding: 9px var(--kami-pad-x);
  cursor: pointer;
  white-space: nowrap;
  transition: color var(--kami-dur-fast) var(--kami-ease), border-color var(--kami-dur-fast) var(--kami-ease);
}

@media (hover: hover) {
  html[data-kami-skin="mileng"] .kami-tab:hover {
    color: var(--kami-fg);
    border-bottom-color: var(--kami-fg-mute);
  }
}

html[data-kami-skin="mileng"] .kami-tab[aria-selected="true"] {
  color: var(--kami-accent);
  font-weight: var(--kami-fw-title);
  border-bottom-color: var(--kami-accent);
}

/* —— 面板网格：密集判据必须把 .kami-item-note 一并列进去 —— */
html[data-kami-skin="mileng"] .kami-root[data-kami-comp="panel"] .kami-grid:has(> .kami-item, > .kami-item-note) {
  --kami-items-min: 100px;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, var(--kami-items-min)), 1fr));
  gap: var(--kami-gap);
}

/* —— 面板内卡片：未选中不能和容器同色（换一档明度 + 看得见的边） —— */
html[data-kami-skin="mileng"] .kami-root[data-kami-comp="panel"] .kami-card {
  border: var(--kami-border-w) solid var(--kami-line-strong);
  background-color: var(--kami-card);
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
}

html[data-kami-skin="mileng"] .kami-root[data-kami-comp="panel"] .kami-card .kami-card:not(.is-on):not([aria-pressed="true"]) {
  background-color: var(--kami-card-2);
  border-color: var(--kami-line);
}

html[data-kami-skin="mileng"] .kami-root[data-kami-comp="panel"] .kami-card.is-on,
html[data-kami-skin="mileng"] .kami-root[data-kami-comp="panel"] .kami-card[aria-pressed="true"] {
  border-color: var(--kami-accent);
  background-color: var(--kami-accent-soft);
  color: var(--kami-fg);
  box-shadow: inset 0 0 0 1px var(--kami-accent);
}

/* 分组卡内部网格：别把内边距叠两层（条目卡自己已有内边距） */
html[data-kami-skin="mileng"] .kami-drop .kami-card:not(.kami-item):has(> .kami-card-body > .kami-grid) {
  padding-left: 12px;
  padding-right: 12px;
}

html[data-kami-skin="mileng"] .kami-drop .kami-card:not(.kami-item):has(> .kami-card-body > .kami-grid) > .kami-card-head,
html[data-kami-skin="mileng"] .kami-drop .kami-card:not(.kami-item):has(> .kami-card-body > .kami-grid) > .kami-card-title,
html[data-kami-skin="mileng"] .kami-drop .kami-card:not(.kami-item):has(> .kami-card-body > .kami-grid) > .kami-card-note {
  padding-left: 0;
  padding-right: 0;
}

/* —— 面板里的条目卡 —— */
html[data-kami-skin="mileng"] .kami-root[data-kami-comp="panel"] .kami-item {
  position: relative;
  padding: 10px 12px;
  min-height: 42px;
}

/* ⓘ 注释标记：右上角角标，只占高度不占宽度；必须能点。
   margin:0 —— .kami-card-note 的 margin-top 会把角标整体推低，压到条目名。 */
html[data-kami-skin="mileng"] .kami-root[data-kami-comp="panel"] .kami-item > .kami-card-note[data-kami-note-mark][data-kami-corner] {
  position: absolute;
  top: 5px;
  right: 5px;
  left: auto;
  z-index: 2;
  margin: 0;
  pointer-events: auto;
}

/* 上/下角标的内边距补偿：条目卡里有角标或 ⓘ 时各让出一格。
   1.4em 取的是**卡片**的字号（--kami-fs-sm），ⓘ 的 1.4em 取的是它自己的 --kami-fs-xs；
   fs-sm > fs-xs，所以这一项必然盖过角标本体的高，再加 --kami-pad-y 盖过 top 偏移。
   旧值 calc(var(--kami-pad-lg-y) + 0.4em) 只给到 17.1px，而 ⓘ 从 top:5px 起占 15.4px
   （底边 20.4px），实测还剩 8.4 × 3.3 = 28px² 压在条目名上（2026-09-25 修）。 */
html[data-kami-skin="mileng"] .kami-root[data-kami-comp="panel"] .kami-item:has(> .kami-badge[data-kami-corner="tl"], > .kami-badge[data-kami-corner="tr"], > .kami-card-note[data-kami-corner="tr"]) {
  padding-top: calc(var(--kami-pad-y) + 1.4em);
}

html[data-kami-skin="mileng"] .kami-root[data-kami-comp="panel"] .kami-item:has(> .kami-badge[data-kami-corner="bl"], > .kami-badge[data-kami-corner="br"]) {
  padding-bottom: calc(var(--kami-pad-y) + 1.4em);
}

/* emoji 角标（条目名里摘出来的那枚）：不占宽度、不抢点击 */
html[data-kami-skin="mileng"] .kami-root[data-kami-comp="panel"] .kami-item > .kami-badge {
  position: absolute;
  top: 5px;
  right: 5px;
  left: auto;
  z-index: 2;
  padding: 0;
  border: 0;
  background: none;
  font-size: var(--kami-fs-xs);
  line-height: 1.2;
  color: var(--kami-fg-mute);
  pointer-events: none;
}

html[data-kami-skin="mileng"] .kami-root[data-kami-comp="panel"] .kami-item > .kami-badge[data-kami-corner="tl"],
html[data-kami-skin="mileng"] .kami-root[data-kami-comp="panel"] .kami-item > .kami-badge[data-kami-corner="bl"] {
  right: auto;
  left: 5px;
}

html[data-kami-skin="mileng"] .kami-root[data-kami-comp="panel"] .kami-item > .kami-badge[data-kami-corner="br"],
html[data-kami-skin="mileng"] .kami-root[data-kami-comp="panel"] .kami-item > .kami-badge[data-kami-corner="bl"] {
  top: auto;
  bottom: 5px;
}

/* —— 非当前模型的条目：锁死（脚本写原生 disabled）必须一眼看出点不动 —— */
html[data-kami-skin="mileng"] .kami-root[data-kami-comp="panel"] .kami-item[disabled],
html[data-kami-skin="mileng"] .kami-root[data-kami-comp="panel"] .kami-item[disabled]:hover,
html[data-kami-skin="mileng"] .kami-root[data-kami-comp="panel"] .kami-item[disabled]:active {
  background-color: var(--kami-card);
  background-image: none;
  border-color: var(--kami-line);
  box-shadow: none;
  transform: none;
  opacity: var(--kami-dim-lock, .42);
  color: var(--kami-fg-mute);
  font-weight: var(--kami-fw);
  cursor: default;
}

/* 悬停才冒出来的装饰（编号、角标转正、左缘标线）在锁死时一律不许动 */
html[data-kami-skin="mileng"] .kami-root[data-kami-comp="panel"] .kami-item[disabled]:hover::before,
html[data-kami-skin="mileng"] .kami-root[data-kami-comp="panel"] .kami-item[disabled]:hover::after {
  transform: none;
  opacity: 0;
}

html[data-kami-skin="mileng"] .kami-root[data-kami-comp="panel"] .kami-item[disabled]:hover > .kami-badge {
  transform: none;
}

/* —— 注释标记（行内那枚）与注释正文 —— */
html[data-kami-skin="mileng"] .kami-root[data-kami-comp="panel"] .kami-card-note[data-kami-note-mark] {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.4em;
  height: 1.4em;
  margin-left: 5px;
  border: var(--kami-border-w) solid var(--kami-accent);
  border-radius: var(--kami-r-xs);
  background-color: var(--kami-accent-soft);
  color: var(--kami-fg);
  font-size: var(--kami-fs-xs);
  line-height: 1;
  cursor: pointer;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}

html[data-kami-skin="mileng"] .kami-root[data-kami-comp="panel"] .kami-card-note[data-kami-note-mark]:hover,
html[data-kami-skin="mileng"] .kami-root[data-kami-comp="panel"] .kami-card-note[data-kami-note-mark]:focus-visible {
  background-color: var(--kami-accent);
  color: var(--kami-accent-fg);
}

html[data-kami-skin="mileng"] .kami-root[data-kami-comp="panel"] .kami-card-note[data-kami-note] {
  display: block;
  margin: 5px 0 0;
  padding: 5px 7px;
  border-left: var(--kami-accent-mark) solid var(--kami-accent);
  border-radius: var(--kami-r-xs);
  background-color: var(--kami-t2);
  color: var(--kami-fg-dim);
  font-size: var(--kami-fs-xs);
  line-height: 1.55;
  white-space: pre-wrap;
  word-break: break-word;
  text-align: left;
}

html[data-kami-skin="mileng"] .kami-root[data-kami-comp="panel"] .kami-card-note[data-kami-note][hidden] {
  display: none;
}

/* —— 设置项一行 —— */
html[data-kami-skin="mileng"] .kami-field {
  display: flex;
  align-items: center;
  gap: var(--kami-gap);
  padding: var(--kami-pad-y) 0;
  border-bottom: var(--kami-border-w) solid var(--kami-line);
}

html[data-kami-skin="mileng"] .kami-field:last-child { border-bottom: none; }

html[data-kami-skin="mileng"] .kami-field-label {
  flex: 1 1 auto;
  min-width: 0;
  font-size: var(--kami-fs-sm);
  color: var(--kami-fg);
}

html[data-kami-skin="mileng"] .kami-field-value {
  flex: none;
  display: flex;
  align-items: center;
  gap: 6px;
}

/* —— 数字框 / 文本 / 多行 / 下拉（非 panel 作用域的那份外观） —— */
html[data-kami-skin="mileng"] .kami-root .kami-text,
html[data-kami-skin="mileng"] .kami-root .kami-textarea {
  min-height: var(--kami-row-h);
  padding: var(--kami-pad-y) var(--kami-pad-x);
  border: var(--kami-border-w) solid var(--kami-line-strong);
  border-radius: var(--kami-r-xs);
  background-color: var(--kami-bg-soft);
  color: var(--kami-fg);
  font-family: var(--kami-font);
  font-size: var(--kami-fs-sm);
  text-align: left;
}

html[data-kami-skin="mileng"] .kami-root textarea.kami-textarea {
  resize: vertical;
}

html[data-kami-skin="mileng"] .kami-root input.kami-number {
  width: 62px;
  min-height: 28px;
  padding: 2px 6px;
  border: var(--kami-border-w) solid var(--kami-line-strong);
  border-radius: var(--kami-r-xs);
  background-color: var(--kami-bg-soft);
  color: var(--kami-fg);
  font-family: var(--kami-font-mono);
  font-size: var(--kami-fs-xs);
  text-align: left;
}

/* 下拉：抹掉原生外观，用两层 linear-gradient 拼一个 V 形箭头。
   底必须写 background-color 长写属性 —— 写 background 简写会把箭头一起重置。 */
html[data-kami-skin="mileng"] .kami-root .kami-select {
  -webkit-appearance: none;
  appearance: none;
  min-height: var(--kami-row-h);
  padding: var(--kami-pad-y) calc(var(--kami-pad-x) + 16px) var(--kami-pad-y) var(--kami-pad-x);
  border: var(--kami-border-w) solid var(--kami-line-strong);
  border-radius: var(--kami-r-xs);
  background-color: var(--kami-bg-soft);
  background-image:
    linear-gradient(45deg, transparent 50%, var(--kami-fg-mute) 50%),
    linear-gradient(135deg, var(--kami-fg-mute) 50%, transparent 50%);
  background-size: 4px 4px, 4px 4px;
  background-position: calc(100% - 13px) calc(50% + 1px), calc(100% - 9px) calc(50% + 1px);
  background-repeat: no-repeat;
  color: var(--kami-fg);
  font-family: var(--kami-font);
  font-size: var(--kami-fs-sm);
  text-align: left;
  cursor: pointer;
}

/* —— 开关：方角轨道 + 方形旋钮（装备面板的拨动开关是方的） —— */
html[data-kami-skin="mileng"] .kami-switch {
  position: relative;
  display: inline-flex;
  align-items: center;
  cursor: pointer;
  user-select: none;
}

html[data-kami-skin="mileng"] .kami-switch-input {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}

html[data-kami-skin="mileng"] .kami-switch-track {
  position: relative;
  width: 40px;
  height: 22px;
  border: var(--kami-border-w) solid var(--kami-line-strong);
  border-radius: var(--kami-r-xs);
  background-color: var(--kami-t3);
  transition: background-color var(--kami-dur) var(--kami-ease), border-color var(--kami-dur) var(--kami-ease);
}

html[data-kami-skin="mileng"] .kami-switch-knob {
  position: absolute;
  top: 2px;
  left: 2px;
  width: 16px;
  height: 16px;
  border-radius: var(--kami-r-xs);
  background-color: var(--kami-fg-dim);
  transition: transform var(--kami-dur) var(--kami-ease), background-color var(--kami-dur) var(--kami-ease);
}

html[data-kami-skin="mileng"] .kami-switch-input:checked + .kami-switch-track {
  background-color: var(--kami-accent-soft);
  border-color: var(--kami-accent);
}

html[data-kami-skin="mileng"] .kami-switch-input:checked + .kami-switch-track .kami-switch-knob {
  transform: translateX(18px);
  background-color: var(--kami-accent);
}

/* —— 滑杆：方型拨钮 —— */
html[data-kami-skin="mileng"] .kami-range {
  -webkit-appearance: none;
  appearance: none;
  width: 96px;
  height: 4px;
  border-radius: var(--kami-r-pill);
  background-color: var(--kami-t3);
  cursor: pointer;
}

html[data-kami-skin="mileng"] .kami-range::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 14px;
  height: 14px;
  border-radius: var(--kami-r-xs);
  background-color: var(--kami-accent);
  border: 2px solid var(--kami-bg);
  box-shadow: var(--kami-shadow-sm);
  cursor: pointer;
}

html[data-kami-skin="mileng"] .kami-range::-moz-range-thumb {
  width: 12px;
  height: 12px;
  border-radius: var(--kami-r-xs);
  background-color: var(--kami-accent);
  border: 2px solid var(--kami-bg);
  cursor: pointer;
}

/* —— 滚动区 —— */
html[data-kami-skin="mileng"] .kami-scroll {
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: var(--kami-line-strong) transparent;
}

html[data-kami-skin="mileng"] .kami-scroll::-webkit-scrollbar { width: 8px; height: 8px; }

html[data-kami-skin="mileng"] .kami-scroll::-webkit-scrollbar-track { background: transparent; }

html[data-kami-skin="mileng"] .kami-scroll::-webkit-scrollbar-thumb {
  background-color: var(--kami-line-strong);
  border-radius: var(--kami-r-xs);
}

/* —— 尺寸把手 —— */
html[data-kami-skin="mileng"] .kami-resize {
  position: absolute;
  right: 0;
  bottom: 0;
  width: 16px;
  height: 16px;
  cursor: nwse-resize;
  background-image: linear-gradient(135deg, transparent 46%, var(--kami-line-strong) 46%, var(--kami-line-strong) 54%, transparent 54%);
}

/* —— 皮肤预览缩略 —— */
html[data-kami-skin="mileng"] .kami-preview {
  position: relative;
  border-radius: var(--kami-r-md);
  border: var(--kami-border-w) solid var(--kami-line);
  background-color: var(--kami-card);
  padding: 8px;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

html[data-kami-skin="mileng"] .kami-preview i {
  display: block;
  height: 6px;
  border-radius: var(--kami-r-xs);
  background-color: var(--kami-t3);
}

html[data-kami-skin="mileng"] .kami-preview i:first-child {
  width: 58%;
  background-color: var(--kami-accent);
}

/* —— 贴底抽屉（脚本下发的 data-kami-layout="sheet"） —— */
html[data-kami-skin="mileng"] .kami-root .kami-drop.kami-drop[data-kami-layout="sheet"] {
  left: 0;
  right: 0;
  top: auto;
  bottom: 0;
  width: auto;
  height: 78%;
  max-height: 78%;
  border-radius: var(--kami-r-lg) var(--kami-r-lg) 0 0;
}

/* 兜底：面板脚本还没跑起来（元素上还没有 data-kami-layout）时按 768px 贴底 */
@media (max-width: 768px) {
  html[data-kami-skin="mileng"] .kami-root .kami-drop.kami-drop:not([data-kami-layout]) {
    left: 0;
    right: 0;
    top: auto;
    bottom: 0;
    width: auto;
    height: 78%;
    max-height: 78%;
    border-radius: var(--kami-r-lg) var(--kami-r-lg) 0 0;
  }
}

/* ==========================================================================
 * 13 · 容器查询与窄屏（320px 必须成立；手机档选择器必须与
 *      基准规则逐字相同，否则 .kami-root 祖先声明会吃掉元素自己的值）
 * ======================================================================== */
@container (max-width: 360px) {
  html[data-kami-skin="mileng"] .kami-root .kami-title {
    letter-spacing: calc(var(--kami-ls-title) * 0.5);
  }
}

@media (max-width: 560px) {
  html[data-kami-skin="mileng"] .kami-root[data-kami-comp="panel"] .kami-grid:has(> .kami-item, > .kami-item-note) {
    --kami-items-min: 152px;
  }
}

@media (max-width: 380px) {
  html[data-kami-skin="mileng"] .kami-root[data-kami-comp="panel"] .kami-grid:has(> .kami-item, > .kami-item-note) {
    --kami-items-min: 108px;
  }
  html[data-kami-skin="mileng"] .kami-root[data-kami-comp="panel"] {
    --kami-row-h: 44px;
  }
  html[data-kami-skin="mileng"] .kami-root .kami-bar {
    flex-wrap: wrap;
  }
}

/* ==========================================================================
 * 14 · 特效实现（每个 id 都有 data-kami-effects~= 规则）
 * ========================================================================== */

/* 1. 刻度带（ticks）：头部下缘一道量程刻度尺；浓度静态、零动画 */
html[data-kami-skin="mileng"][data-kami-effects~="ticks"] .kami-head::after {
  content: "";
  position: absolute;
  left: var(--kami-pad-lg-x);
  right: var(--kami-pad-lg-x);
  bottom: 0;
  height: 5px;
  pointer-events: none;
  background-image:
    repeating-linear-gradient(90deg,
      var(--kami-accent-line) 0 1px,
      transparent 1px var(--kami-mil-tick-l)),
    linear-gradient(180deg, var(--kami-line) 0 1px, transparent 1px);
  background-size: auto 3px, auto 1px;
  background-position: 0 100%, 0 0;
  background-repeat: repeat-x, no-repeat;
  opacity: 0.8;
}

/* markdown 栏目级标题也带一小段刻度，把身份符号延到正文 */
html[data-kami-skin="mileng"][data-kami-effects~="ticks"] .kami-md h1::after,
html[data-kami-skin="mileng"][data-kami-effects~="ticks"] .kami-md h2::after {
  content: "";
  display: block;
  height: 4px;
  margin-top: 4px;
  background-image: repeating-linear-gradient(90deg,
    var(--kami-accent-line) 0 1px,
    transparent 1px calc(var(--kami-mil-tick) * 1px));
  background-repeat: repeat-x;
}

/* 2. 警示斜纹（hazard）：只画边条 —— 脚条上缘一道、警示提示左缘一段；
      浓度走无单位参数（crt80s 的教训：unit 写 % 会让 alpha 失真） */
html[data-kami-skin="mileng"][data-kami-effects~="hazard"] .kami-root .kami-foot::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: -3px;
  height: 3px;
  pointer-events: none;
  background-image: repeating-linear-gradient(45deg,
    rgba(216, 169, 60, calc(0.85 * var(--kami-mil-hatch) / 100)) 0 6px,
    transparent 6px 12px);
}

html[data-kami-skin="mileng"][data-kami-effects~="hazard"] .kami-root .kami-toast {
  border-image: none;
}

html[data-kami-skin="mileng"][data-kami-effects~="hazard"] .kami-root .kami-toast.is-bad {
  box-shadow: inset 4px 0 0 var(--kami-warn);
}

html[data-kami-skin="mileng"][data-kami-effects~="hazard"] .kami-root .kami-item.is-on {
  background-image: repeating-linear-gradient(90deg,
    rgba(216, 169, 60, calc(0.28 * var(--kami-mil-hatch) / 100)) 0 2px,
    transparent 2px 14px);
}

/* 3. 喷漆颗粒（grain）：静态、零动画；浓度走无单位参数 */
html[data-kami-skin="mileng"][data-kami-effects~="grain"] .kami-surface::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image:
    repeating-linear-gradient(0deg,
      rgba(233, 225, 200, calc(0.05 * var(--kami-mil-grain) / 100)) 0 1px,
      transparent 1px 3px),
    repeating-linear-gradient(90deg,
      rgba(233, 225, 200, calc(0.05 * var(--kami-mil-grain) / 100)) 0 1px,
      transparent 1px 3px);
}

/* 4. 信号灯（beacon）：状态点的循环辉光；是本皮肤唯一的循环动画 */
html[data-kami-skin="mileng"][data-kami-effects~="beacon"] .kami-root .kami-dot[data-kami-on="1"] {
  animation: kami-mil-beacon 1.8s var(--kami-ease) infinite;
}

/* 循环动画在 calm / off 与 prefers-reduced-motion 下必须直接停（契约 §3.6）；
   off 档是全场打包压到 1ms，这里对循环动画补一刀 animation:none */
html[data-kami-skin="mileng"][data-kami-motion="calm"] .kami-root .kami-dot[data-kami-on="1"],
html[data-kami-skin="mileng"][data-kami-motion="off"] .kami-root .kami-dot[data-kami-on="1"] {
  animation: none !important;
}

/* markdown：强调与插图（2026-09-24 补齐 —— 覆盖矩阵原本缺这两项） */
html[data-kami-skin="mileng"] .kami-md em { font-style: italic; color: var(--kami-accent); letter-spacing: .02em; }
html[data-kami-skin="mileng"] .kami-md del { color: var(--kami-fg-mute); text-decoration-thickness: 1px; }
html[data-kami-skin="mileng"] .kami-md img {
  display: block;
  max-width: 100%;
  margin: .6em 0;
  border: var(--kami-border-w) solid var(--kami-line-strong);
  box-shadow: 0 4px 0 var(--kami-line);
}


/* 列表符号：显式声明，不依赖环境继承（酒馆楼层的列表样式可能被整链重置成 none，
   皮肤只给 ::marker 上色是不够的，符号必须自己声明、自己真的画出来）。
   无序：一级 disc / 二级 circle / 三级起 square；有序：decimal → lower-alpha → lower-roman */
html[data-kami-skin="mileng"] .kami-md ul { list-style-type: disc; }
html[data-kami-skin="mileng"] .kami-md ul ul { list-style-type: circle; }
html[data-kami-skin="mileng"] .kami-md ul ul ul { list-style-type: square; }
html[data-kami-skin="mileng"] .kami-md ol { list-style-type: decimal; }
html[data-kami-skin="mileng"] .kami-md ol ol { list-style-type: lower-alpha; }
html[data-kami-skin="mileng"] .kami-md ol ol ol { list-style-type: lower-roman; }
html[data-kami-skin="mileng"] .kami-md li::marker { color: var(--kami-accent); }
html[data-kami-skin="mileng"] .kami-md li li::marker { color: var(--kami-fg-mute); }

/* 特效页说明（.kami-field 里的那枚 .kami-sub）：375px 窄屏必须能换行读全。
   结构层的 .kami-sub 是 white-space:nowrap（标题栏计数确实要单行），
   这里只对「字段标签里的说明」这一处放开，不碰标题栏 / 页脚的。 */
html[data-kami-skin="mileng"] .kami-root[data-kami-comp="panel"] .kami-field .kami-field-label .kami-sub {
  white-space: normal;
  overflow: visible;
  text-overflow: clip;
  min-width: 0;
}

/* ============================================================
 * · 正文美化包裹层 [data-kami-comp="body"]（已退役，2026-09-26）
 *   本节原样保留到 2026-09-26：给「只美化 <content> 标签内正文」包出来的
 *   div.kami-root[data-kami-comp="body"] 上皮（容器底 / 描边 / 圆角 / 字色）。
 *   那套功能已按用户裁定整体退役（改为直接在酒馆的消息楼层上做皮肤排版，
 *   见 src/skin/tavern.css 第 ⑤ 段与契约 §9.8），包裹层不再产生，故本节删除。
 *   消息楼层的容器（.mes）与正文排版都由全局层负责，皮肤包这边零维护。
 * ============================================================ */

/* ==== 全局层令牌上提（build/sync-tavern.mjs 生成，勿手改；把 --kami-* 令牌同时定义到 <html>，契约 §3）==== */
html[data-kami-skin="mileng"] {
  --kami-label-think-title: 战况推演;
  --kami-label-think-title-open: 推演全文;
  --kami-label-options-title: 行动命令;
  --kami-fg: #e9e1c8;
  --kami-fg-dim: #b9ae8d;
  --kami-fg-mute: #968f70;
  --kami-accent: #d8a93c;
  --kami-accent-fg: #1c1302;
  --kami-accent-soft: rgba(216, 169, 60, 0.14);
  --kami-accent-line: rgba(216, 169, 60, 0.50);
  --kami-bg: #1a1e10;
  --kami-bg-soft: #212612;
  --kami-card: #2a3017;
  --kami-card-2: #12150a;
  --kami-card-hover: #384120;
  --kami-line: rgba(233, 225, 200, 0.13);
  --kami-line-strong: rgba(216, 169, 60, 0.45);
  --kami-t1: rgba(233, 225, 200, 0.05);
  --kami-t2: rgba(233, 225, 200, 0.09);
  --kami-t3: rgba(233, 225, 200, 0.16);
  --kami-warn: #ff9266;
  --kami-shadow: 0 10px 30px rgba(0, 0, 0, 0.52);
  --kami-shadow-sm: 0 2px 8px rgba(0, 0, 0, 0.42);
  --kami-blur: 0px;
  --kami-r-xs: 2px;
  --kami-r-sm: 3px;
  --kami-r-md: 4px;
  --kami-r-lg: 6px;
  --kami-r-pill: 999px;
  --kami-border-w: 1px;
  --kami-pad-x: 11px;
  --kami-pad-y: 7px;
  --kami-pad-lg-x: 15px;
  --kami-pad-lg-y: 12px;
  --kami-gap: 8px;
  --kami-gap-lg: 12px;
  --kami-row-h: 36px;
  --kami-icon: 15px;
  --kami-maxw: none;
  --kami-items-min: 15.5rem;
  --kami-panel-w: 430px;
  --kami-panel-h: 570px;
  --kami-list-dir: column;
  --kami-justify: stretch;
  --kami-fs-scale: 1;
  --kami-fs: calc(14.5px * var(--kami-fs-scale));
  --kami-fs-xs: calc(var(--kami-fs) * .76);
  --kami-fs-sm: calc(var(--kami-fs) * .88);
  --kami-fs-lg: calc(var(--kami-fs) * 1.14);
  --kami-lh: 1.6;
  --kami-ls: .015em;
  --kami-ls-title: .18em;
  --kami-font: system-ui, -apple-system, "Segoe UI", "Microsoft YaHei", "PingFang SC", "Noto Sans SC", sans-serif;
  --kami-font-title: var(--kami-font);
  --kami-font-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, "Cascadia Mono", "Liberation Mono", monospace;
  --kami-fw: 400;
  --kami-fw-title: 700;
  --kami-title-transform: uppercase;
  --kami-texture: radial-gradient(120% 100% at 50% 0%, rgba(216, 169, 60, 0.04), transparent 60%);
  --kami-glow: rgba(216, 169, 60, 0.5);
  --kami-glow-size: 6px;
  --kami-surface-clip: none;
  --kami-accent-mark: 3px;
  --kami-dur-fast: .12s;
  --kami-dur: .2s;
  --kami-dur-slow: .3s;
  --kami-ease: cubic-bezier(.22, .61, .36, 1);
  --kami-ease-out: cubic-bezier(.16, 1, .3, 1);
  --kami-enter-y: 4px;
  --kami-enter-scale: 1;
