  --kami-dim-lock: .42;
  --kami-mil-hatch: 60;
  --kami-mil-grain: 40;
  --kami-mil-tick: 7;
}
html[data-kami-skin="mileng"] {
  --kami-mil-tick-l: calc(var(--kami-mil-tick) * 1px);
}
html[data-kami-skin="mileng"][data-kami-scheme="light"] {
  --kami-fg: #262b15;
