  --kami-line-strong: rgba(38, 43, 21, 0.50);
  --kami-t1: rgba(38, 43, 21, 0.045);
  --kami-t2: rgba(38, 43, 21, 0.075);
  --kami-t3: rgba(38, 43, 21, 0.14);
  --kami-warn: #b3401c;
  --kami-shadow: 0 10px 26px rgba(30, 26, 10, 0.18);
  --kami-shadow-sm: 0 2px 8px rgba(30, 26, 10, 0.12);
