  --kami-kind-persona: #9c4a60;
  --kami-kind-plot: #47702d;
  --kami-kind-info: #20727b;
  --kami-kind-fun: #8a6d10;
  --kami-kind-nsfw: #a53f2a;
  --kami-kind-other: #585c43;
}
html[data-kami-skin="mileng"][data-kami-density="compact"] {
  --kami-pad-x: 9px;
  --kami-pad-y: 5px;
  --kami-pad-lg-x: 12px;
