html[data-kami-skin="nixie"] .kami-root *,
html[data-kami-skin="nixie"] .kami-root *::before,
html[data-kami-skin="nixie"] .kami-root *::after { box-sizing: border-box; }
html[data-kami-skin="nixie"] .kami-root button,
