/* ==========================================================================
 * 10 · 表单：直线电位器 / 读数输入 / 刀闸
 * ======================================================================== */
html[data-kami-skin="nixie"] .kami-field {
  display: flex;
  align-items: center;
  gap: var(--kami-gap);
  padding: var(--kami-pad-y) 0;
}
html[data-kami-skin="nixie"] .kami-field + .kami-field { border-top: var(--kami-border-w) solid var(--kami-t1); }
html[data-kami-skin="nixie"] .kami-field-label {
  flex: 1 1 auto;
  min-width: 0;
  font-size: var(--kami-fs-sm);
  color: var(--kami-fg);
}
html[data-kami-skin="nixie"] .kami-field:has(.kami-sub) { align-items: flex-start; }
html[data-kami-skin="nixie"] .kami-field:has(.kami-sub) > .kami-field-label { flex: 1 1 55%; }
html[data-kami-skin="nixie"] .kami-field:has(.kami-sub) > .kami-field-value { margin-left: auto; padding-top: 2px; }
html[data-kami-skin="nixie"] .kami-field-label > .kami-sub { display: block; margin-top: 3px; line-height: 1.5; }
html[data-kami-skin="nixie"] .kami-field-value { flex: none; display: flex; align-items: center; gap: 6px; }
html[data-kami-skin="nixie"] .kami-range {
  -webkit-appearance: none;
