  border: 0;
  background-color: transparent;
  background-image:
    linear-gradient(90deg, rgba(255, 170, 90, .9) 0, rgba(255, 138, 32, .65) 100%),
    repeating-linear-gradient(90deg, var(--kami-t3) 0 1px, rgba(0, 0, 0, 0) 1px 8px),
    linear-gradient(180deg, rgba(0, 0, 0, .7) 0, rgba(0, 0, 0, .32) 100%);
  background-repeat: no-repeat, repeat-x, no-repeat;
  background-position: 7px 50%, 0 50%, 0 50%;
  background-size: calc(var(--kami-value, 0) * (100% - 14px)) 2px, 100% 10px, 100% 4px;
  cursor: pointer;
}
html[data-kami-skin="nixie"] .kami-range::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 14px;
  height: 22px;
  border: 0;
  border-radius: var(--kami-r-xs);
  background-color: #2b241c;
  background-image:
    repeating-linear-gradient(90deg, rgba(255, 236, 214, .12) 0 1px, rgba(0, 0, 0, 0) 1px 3px),
    linear-gradient(180deg, rgba(255, 236, 214, .18) 0, rgba(0, 0, 0, .38) 100%);
  box-shadow: inset 0 1px 0 rgba(255, 236, 214, .2), inset 0 0 0 1px rgba(0, 0, 0, .55), 0 1px 2px rgba(0, 0, 0, .7);
}
html[data-kami-skin="nixie"] .kami-range::-moz-range-track { height: 4px; background: transparent; border: 0; }
html[data-kami-skin="nixie"] .kami-range::-moz-range-progress { height: 2px; background: linear-gradient(90deg, rgba(255, 170, 90, .9), rgba(255, 138, 32, .65)); }
html[data-kami-skin="nixie"] .kami-range::-moz-range-thumb {
  width: 14px;
  height: 22px;
  border: 0;
  border-radius: var(--kami-r-xs);
  background-color: #2b241c;
  box-shadow: inset 0 1px 0 rgba(255, 236, 214, .2), inset 0 0 0 1px rgba(0, 0, 0, .55), 0 1px 2px rgba(0, 0, 0, .7);
}
html[data-kami-skin="nixie"] .kami-range:focus-visible { outline-offset: 4px; }
html[data-kami-skin="nixie"] .kami-number {
  width: 62px;
  min-height: 30px;
  padding: 2px 6px;
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-xs);
  background-color: var(--kami-bg-soft);
  color: var(--kami-accent);
  font-family: var(--kami-font-mono);
  font-size: var(--kami-fs-xs);
  box-shadow: inset 0 1px 2px rgba(0, 0, 0, .6), inset 0 0 0 1px rgba(0, 0, 0, .35);
  text-shadow: 0 0 1px rgba(255, 170, 90, .45);
}
/* 右对齐是数字框的专属：以前这条写在裸 .kami-number 上，把摘要提示词的正文与角色下拉一起带偏了 */
html[data-kami-skin="nixie"] input.kami-number[type="number"] { text-align: right; }
html[data-kami-skin="nixie"] .kami-number::-webkit-outer-spin-button,
html[data-kami-skin="nixie"] .kami-number::-webkit-inner-spin-button { opacity: .4; }
html[data-kami-skin="nixie"] .kami-number:focus-visible { border-color: var(--kami-accent-line); }

/* 面板里的数字输入框：琥珀字压在仪器暗面上（--kami-bg-soft），描边提到 line-strong 让凹陷看得见
   （必须点名 input.kami-number：.kami-root input 的 color:inherit 特异性更高，
    会把原来的 --kami-accent 压成继承来的 --kami-fg-dim。两块面板共用，panel 限定即可）
   底必须显式写、并且带 !important：酒馆「用户设置 → 自定义 CSS」里那条
    input[type="number"] { background-color: var(--ui-color-sec) !important } 会盖掉
    这里的暗底（真机实测）。color-scheme 写死，别让浏览器替我们决定控件底色。
    底只能写 background-color：写成 background 简写会把 .kami-select 那枚自绘箭头
    的 background-image 一起重置掉。 */
html[data-kami-skin="nixie"] .kami-root[data-kami-comp="panel"] input.kami-number,
html[data-kami-skin="nixie"] .kami-root[data-kami-comp="panel"] input.kami-text,
html[data-kami-skin="nixie"] .kami-root[data-kami-comp="panel"] textarea.kami-textarea,
html[data-kami-skin="nixie"] .kami-root[data-kami-comp="panel"] select.kami-select {
  color: var(--kami-accent) !important;
  background-color: var(--kami-bg-soft) !important;
  border-color: var(--kami-line-strong) !important;
  color-scheme: dark !important;
}

/* 文本 / 多行 / 下拉（契约 §4.2 新登记的三类）：同一个仪器凹槽（--kami-bg-soft 比卡片再暗一档），
   一律左对齐。选择器点名到元素：.kami-root input / select / textarea 的 color:inherit 与它同为
   (0,2,2)，只有源码顺序在后才压得住，否则字会被 .kami-field 的 --kami-fg-dim 接管。 */
html[data-kami-skin="nixie"] input.kami-text,
html[data-kami-skin="nixie"] textarea.kami-textarea,
html[data-kami-skin="nixie"] select.kami-select {
  min-height: var(--kami-row-h);
  padding: var(--kami-pad-y) var(--kami-pad-x);
  text-align: left;
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-xs);
  background-color: var(--kami-bg-soft);
  box-shadow: inset 0 1px 2px rgba(0, 0, 0, .6), inset 0 0 0 1px rgba(0, 0, 0, .35);
  font-family: var(--kami-font-mono);
  font-size: var(--kami-fs-sm);
  color: var(--kami-fg);
}
html[data-kami-skin="nixie"] textarea.kami-textarea { resize: vertical; }
/* 下拉框：抹掉浏览器默认外观，用两层渐变拼一枚 V 形箭头；右内边距给箭头留位 */
html[data-kami-skin="nixie"] select.kami-select {
  -webkit-appearance: none;
  appearance: none;
  padding-right: calc(var(--kami-pad-x) + 16px);
  background-image:
    linear-gradient(45deg, transparent 50%, var(--kami-fg-mute) 50%),
    linear-gradient(135deg, var(--kami-fg-mute) 50%, transparent 50%);
  background-size: 4px 4px, 4px 4px;
  background-position: calc(100% - 13px) calc(50% + 1px), calc(100% - 9px) calc(50% + 1px);
  background-repeat: no-repeat;
  cursor: pointer;
}
html[data-kami-skin="nixie"] .kami-switch { position: relative; display: inline-flex; align-items: center; cursor: pointer; }
html[data-kami-skin="nixie"] .kami-switch-input {
  position: absolute;
  left: 0;
  top: 0;
  width: 100%;
  height: 100%;
  opacity: 0;
  pointer-events: none;
}
html[data-kami-skin="nixie"] .kami-switch-track {
  position: relative;
  display: block;
  width: 46px;
  height: 24px;
  border-radius: var(--kami-r-xs);
  background-color: var(--kami-bg-soft);
  background-image: linear-gradient(180deg, rgba(0, 0, 0, .65) 0, rgba(0, 0, 0, .25) 100%);
  box-shadow: inset 0 1px 2px rgba(0, 0, 0, .7), inset 0 0 0 1px rgba(0, 0, 0, .5), 0 1px 0 rgba(255, 236, 214, .05);
  transition: background-color var(--kami-dur) var(--kami-ease), box-shadow var(--kami-dur) var(--kami-ease);
}
html[data-kami-skin="nixie"] .kami-switch-track::after {
  content: "";
  position: absolute;
  right: 4px;
  top: 50%;
  width: 5px;
  height: 5px;
  margin-top: -2.5px;
  border-radius: 50%;
  background-image: radial-gradient(circle at 50% 42%, #46331f, #17120e 72%);
  box-shadow: inset 0 0 0 1px rgba(0, 0, 0, .6);
  transition: background-image var(--kami-dur) var(--kami-ease), box-shadow var(--kami-dur) var(--kami-ease);
}
html[data-kami-skin="nixie"] .kami-switch-knob {
  position: absolute;
  left: 3px;
  top: 3px;
  width: 20px;
  height: 18px;
  border-radius: 1px;
  background-color: #2b241c;
  background-image:
    repeating-linear-gradient(90deg, rgba(255, 236, 214, .12) 0 1px, rgba(0, 0, 0, 0) 1px 3px),
    linear-gradient(180deg, rgba(255, 236, 214, .18) 0, rgba(0, 0, 0, .38) 100%);
  box-shadow: inset 0 1px 0 rgba(255, 236, 214, .2), 0 1px 2px rgba(0, 0, 0, .75);
  transition: transform var(--kami-dur) cubic-bezier(.34, 1.56, .64, 1), background-color var(--kami-dur) var(--kami-ease);
}
html[data-kami-skin="nixie"] .kami-switch-input:checked + .kami-switch-track {
  background-color: #241a10;
  box-shadow: inset 0 1px 2px rgba(0, 0, 0, .7), inset 0 0 0 1px var(--kami-accent-line), inset 0 -1px 0 rgba(255, 138, 32, .4);
}
html[data-kami-skin="nixie"] .kami-switch-input:checked + .kami-switch-track .kami-switch-knob { transform: translateX(20px); }
html[data-kami-skin="nixie"] .kami-switch-input:checked + .kami-switch-track::after {
  background-image: radial-gradient(circle at 50% 45%, #ffe6bc, #ff8a20 55%, rgba(255, 138, 32, .25) 100%);
  box-shadow: 0 0 4px rgba(255, 138, 32, .7), inset 0 0 0 1px rgba(255, 190, 130, .45);
}
html[data-kami-skin="nixie"] .kami-switch-input:focus-visible + .kami-switch-track {
  outline: 2px solid var(--kami-accent);
  outline-offset: 2px;
}

/* ==========================================================================
 * 11 · 标签页：沉轨上的机械琴键
 * ======================================================================== */
html[data-kami-skin="nixie"] .kami-tabs {
  display: flex;
  flex: 0 0 auto;
  min-height: 36px;
  gap: 3px;
  padding: 0 var(--kami-pad-lg-x);
  border-bottom: var(--kami-border-w) solid var(--kami-line);
  background-image: linear-gradient(180deg, rgba(0, 0, 0, .34), rgba(0, 0, 0, 0));
  overflow-x: auto;
  scrollbar-width: none;
}
html[data-kami-skin="nixie"] .kami-tabs::-webkit-scrollbar { display: none; }
/* tab 行放不下时（7 个 tab / 420px 面板、或手机抽屉）要**看得出来还能往右滑**：
   给滚动容器右缘一道 20px 的渐隐遮罩。遮罩挂在滚动容器自己的边框盒上，内容在它下面滚，
   被裁掉的那半个 tab 会淡出成「还有」的暗示；tab 行排得下时渐隐落在右侧内边距与底线上。 */
html[data-kami-skin="nixie"] .kami-tabs {
  -webkit-mask-image: linear-gradient(90deg, #000 calc(100% - 20px), transparent 100%);
  mask-image: linear-gradient(90deg, #000 calc(100% - 20px), transparent 100%);
}
html[data-kami-skin="nixie"] .kami-tab {
  flex: none;
  position: relative;
  margin-bottom: -1px;
  padding: 8px 12px;
  border: var(--kami-border-w) solid transparent;
  border-bottom: 0;
  border-radius: var(--kami-r-xs) var(--kami-r-xs) 0 0;
  background-color: transparent;
  background-image: linear-gradient(180deg, rgba(255, 236, 214, .05) 0, rgba(0, 0, 0, 0) 70%);
  color: var(--kami-fg-mute);
  font-size: var(--kami-fs-sm);
  letter-spacing: var(--kami-ls);
  cursor: pointer;
  box-shadow: inset 0 1px 0 rgba(255, 236, 214, .05);
  transition: color var(--kami-dur-fast) var(--kami-ease), background-color var(--kami-dur) var(--kami-ease), box-shadow var(--kami-dur) var(--kami-ease);
}
@media (hover: hover) {
  html[data-kami-skin="nixie"] .kami-tab:hover { color: var(--kami-fg); }
}
html[data-kami-skin="nixie"] .kami-tab[aria-selected="true"] {
  background-color: var(--kami-bg-soft);
  background-image: none;
  border-color: var(--kami-line);
  color: var(--kami-fg);
  text-shadow: 0 0 1px rgba(255, 170, 90, .5);
  box-shadow: inset 0 -2px 0 var(--kami-accent), 0 2px 8px -6px rgba(255, 138, 32, .8);
}

/* ==========================================================================
 * 12 · 面板与抽屉：仪器机箱
 * ======================================================================== */
html[data-kami-skin="nixie"] .kami-drop {
  position: absolute;
  left: var(--kami-panel-x, 50%);
  top: var(--kami-panel-y, 72px);
  width: var(--kami-panel-w, min(420px, calc(100% - 24px)));
  height: var(--kami-panel-h, 560px);
  max-height: calc(100% - 32px);
  display: flex;
  flex-direction: column;
  pointer-events: auto;
  border-radius: var(--kami-r-lg);
  border-color: var(--kami-line-strong);
  background-image:
    radial-gradient(circle at 7px 7px, rgba(255, 236, 214, .10) 0 1px, rgba(0, 0, 0, 0) 1.7px),
    radial-gradient(circle at calc(100% - 7px) 7px, rgba(255, 236, 214, .10) 0 1px, rgba(0, 0, 0, 0) 1.7px),
    radial-gradient(circle at 7px calc(100% - 7px), rgba(255, 236, 214, .07) 0 1px, rgba(0, 0, 0, 0) 1.7px),
    radial-gradient(circle at calc(100% - 7px) calc(100% - 7px), rgba(255, 236, 214, .07) 0 1px, rgba(0, 0, 0, 0) 1.7px),
    linear-gradient(225deg, rgba(0, 0, 0, .55) 0 14px, rgba(0, 0, 0, 0) 14px),
    var(--kami-texture);
  box-shadow: var(--kami-shadow), inset 0 1px 0 rgba(255, 236, 214, .07);
  overflow: hidden;
}
html[data-kami-skin="nixie"][data-kami-effects~="halo"] .kami-root .kami-drop {
  box-shadow:
    var(--kami-shadow),
    inset 0 1px 0 rgba(255, 236, 214, .08),
    0 calc(var(--kami-nixie-halo-r) * 1.4) calc(var(--kami-nixie-halo-r) * 3.4) -8px rgba(255, 138, 32, .38);
}
html[data-kami-skin="nixie"] .kami-drop > .kami-body { flex: 1 1 auto; min-height: 0; }
/* 面板是 flex 列：头 / 标签轨 / 底栏绝不参与收缩，否则内容一长它们会被压扁
   （375px 抽屉下表现为标签被切成半行——已实测） */
html[data-kami-skin="nixie"] .kami-drop > .kami-head,
html[data-kami-skin="nixie"] .kami-drop > .kami-tabs,
html[data-kami-skin="nixie"] .kami-drop > .kami-foot { flex: 0 0 auto; }
html[data-kami-skin="nixie"] .kami-drop > .kami-head { padding-right: calc(var(--kami-pad-lg-x) - 4px); }
html[data-kami-skin="nixie"] .kami-drop > .kami-foot { background-image: linear-gradient(90deg, var(--kami-line) 0, var(--kami-line) 62%, rgba(255, 228, 196, 0) 100%); background-repeat: no-repeat; background-position: 0 0; background-size: 100% 1px; }
html[data-kami-skin="nixie"] .kami-drop > .kami-foot .kami-sub { margin-left: 0; }
html[data-kami-skin="nixie"] .kami-drop .kami-card .kami-card-head { margin-bottom: 4px; }
html[data-kami-skin="nixie"] .kami-drop .kami-grid { grid-template-columns: repeat(auto-fill, minmax(min(100%, 11.5rem), 1fr)); }
html[data-kami-skin="nixie"] .kami-drop .kami-card + .kami-card { margin-top: 0; }
html[data-kami-skin="nixie"] .kami-drop .kami-scroll > .kami-card { margin-bottom: var(--kami-gap); }
html[data-kami-skin="nixie"] .kami-drop .kami-card-body > .kami-field:first-child { padding-top: 2px; }
html[data-kami-skin="nixie"] .kami-drop .kami-collapse-head { gap: var(--kami-gap); margin-bottom: 2px; }
html[data-kami-skin="nixie"] .kami-drop .kami-collapse-head .kami-card-title { letter-spacing: .1em; color: var(--kami-fg-dim); }
html[data-kami-skin="nixie"] .kami-drop .kami-card-note + .kami-card-note { margin-top: 2px; }
html[data-kami-skin="nixie"] .kami-resize {
  position: absolute;
  right: 0;
  bottom: 0;
  width: 20px;
  height: 20px;
  cursor: nwse-resize;
  background-image: repeating-linear-gradient(135deg, var(--kami-t3) 0 1px, rgba(0, 0, 0, 0) 1px 4px);
  background-repeat: no-repeat;
  background-position: 100% 100%;
  background-size: 14px 14px;
  transition: background-image var(--kami-dur-fast) var(--kami-ease);
}
html[data-kami-skin="nixie"] .kami-resize::before {
  content: "";
  position: absolute;
  right: 2px;
  bottom: 2px;
  width: 12px;
  height: 12px;
  border-right: var(--kami-border-w) solid var(--kami-line);
  border-bottom: var(--kami-border-w) solid var(--kami-line);
  transition: border-color var(--kami-dur-fast) var(--kami-ease);
}
@media (hover: hover) {
  html[data-kami-skin="nixie"] .kami-resize:hover::before { border-color: var(--kami-accent-line); }
}
/* 贴底抽屉：模式由脚本按**酒馆自己的单栏状态**下发（data-kami-layout="sheet"），
   不再用写死的 768px 媒体查询（酒馆自己是在 1000px 切单栏的）。 */
html[data-kami-skin="nixie"] .kami-drop[data-kami-layout="sheet"] {
  left: 0;
  right: 0;
  top: auto;
  bottom: 0;
  width: auto;
  height: 78%;
  max-height: 78%;
  border-radius: var(--kami-r-lg) var(--kami-r-lg) 0 0;
  border-bottom: 0;
}
html[data-kami-skin="nixie"] .kami-drop[data-kami-layout="sheet"] > .kami-head { padding-top: calc(var(--kami-pad-lg-y) + 8px); }
html[data-kami-skin="nixie"] .kami-drop[data-kami-layout="sheet"] > .kami-head::before {
  content: "";
  position: absolute;
  left: 50%;
  top: 6px;
  width: 46px;
  height: 3px;
  margin-left: -23px;
  border-radius: 2px;
  background-image: repeating-linear-gradient(90deg, rgba(255, 236, 214, .18) 0 1px, rgba(0, 0, 0, 0) 1px 4px);
}
html[data-kami-skin="nixie"] .kami-drop[data-kami-layout="sheet"] .kami-resize { display: none; }
/* 滚动条：又一根电位器 */
html[data-kami-skin="nixie"] .kami-scroll {
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: var(--kami-t3) transparent;
}
html[data-kami-skin="nixie"] .kami-scroll::-webkit-scrollbar { width: 9px; height: 9px; }
html[data-kami-skin="nixie"] .kami-scroll::-webkit-scrollbar-track { background-color: var(--kami-bg-soft); box-shadow: inset 1px 0 0 rgba(0, 0, 0, .5); }
html[data-kami-skin="nixie"] .kami-scroll::-webkit-scrollbar-thumb {
  border: 3px solid rgba(0, 0, 0, 0);
  border-radius: var(--kami-r-xs);
  background-color: var(--kami-t3);
  background-clip: content-box;
}
html[data-kami-skin="nixie"] .kami-scroll::-webkit-scrollbar-thumb:hover {
  background-color: var(--kami-accent-line);
  box-shadow: 0 0 6px rgba(255, 138, 32, .45);
}

/* ==========================================================================
 * 13 · 空态 / 内联提示 / 皮肤预览缩略
 * ======================================================================== */
html[data-kami-skin="nixie"] .kami-empty {
  position: relative;
  margin: var(--kami-gap) 0;
  padding: calc(var(--kami-pad-lg-y) * 1.4) var(--kami-pad-lg-x) calc(var(--kami-pad-lg-y) * 1.4) calc(var(--kami-pad-lg-x) + 14px);
  border: var(--kami-border-w) dashed rgba(138, 129, 117, .4);
  border-radius: var(--kami-r-sm);
  background-color: var(--kami-bg-soft);
  color: var(--kami-fg-mute);
  font-size: var(--kami-fs-sm);
  box-shadow: inset 0 1px 3px rgba(0, 0, 0, .5);
}
html[data-kami-skin="nixie"] .kami-empty::before {
  content: "";
  position: absolute;
  left: var(--kami-pad-lg-x);
  top: 50%;
  width: 5px;
  height: 5px;
  margin-top: -2.5px;
  border-radius: 50%;
  background-color: rgba(255, 138, 32, .35);
  box-shadow: 0 0 4px rgba(255, 138, 32, .3), inset 0 0 0 1px rgba(255, 190, 130, .25);
}
html[data-kami-skin="nixie"][data-kami-effects~="idle"] .kami-root .kami-empty::before {
  animation: kami-nixie-mains 4.7s var(--kami-ease) infinite;
}
html[data-kami-skin="nixie"] .kami-toast {
  position: relative;
  margin: 0 var(--kami-pad-lg-x) var(--kami-pad-lg-y);
  padding: var(--kami-pad-y) var(--kami-pad-x) var(--kami-pad-y) calc(var(--kami-pad-x) + 8px);
  border: var(--kami-border-w) solid var(--kami-line-strong);
  border-radius: var(--kami-r-xs);
  background-color: var(--kami-bg);
  color: var(--kami-fg);
  font-family: var(--kami-font-mono);
  font-size: var(--kami-fs-xs);
  letter-spacing: .03em;
  box-shadow: var(--kami-shadow-sm), inset 0 -1px 0 var(--kami-accent), 0 calc(var(--kami-nixie-halo-r) * .35) var(--kami-nixie-halo-r) -4px rgba(255, 138, 32, .5);
  animation: kami-nixie-sweep var(--kami-dur) var(--kami-ease-out) both;
}
html[data-kami-skin="nixie"] .kami-toast::before {
  content: "";
  position: absolute;
  left: 4px;
  top: 50%;
  width: 4px;
  height: 4px;
  margin-top: -2px;
  border-radius: 50%;
  background-color: var(--kami-accent);
  box-shadow: 0 0 4px rgba(255, 138, 32, .7);
}
html[data-kami-skin="nixie"] .kami-toast.is-bad {
  color: var(--kami-warn);
  border-color: var(--kami-warn);
  box-shadow: var(--kami-shadow-sm), inset 0 -1px 0 var(--kami-warn);
  animation: kami-nixie-badflash calc(var(--kami-dur-slow) * 1.4) steps(1, end) both;
}
html[data-kami-skin="nixie"] .kami-toast.is-bad::before { background-color: var(--kami-warn); box-shadow: 0 0 4px currentColor; }
html[data-kami-skin="nixie"] .kami-root[data-kami-comp="panel"] .kami-toast { margin: 0 0 var(--kami-gap-lg); }
@supports (backdrop-filter: blur(2px)) {
  html[data-kami-skin="nixie"] .kami-root[data-kami-comp="panel"] .kami-toast {
    backdrop-filter: blur(var(--kami-blur));
  }
}
html[data-kami-skin="nixie"] .kami-preview {
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  gap: 4px;
  aspect-ratio: 16 / 7;
  margin-top: var(--kami-gap);
  padding: 7px;
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-xs);
  background-color: var(--kami-bg-soft);
  background-image: repeating-linear-gradient(90deg, rgba(255, 232, 204, .05) 0 1px, rgba(0, 0, 0, 0) 1px 4px);
  box-shadow: inset 0 1px 3px rgba(0, 0, 0, .6);
  overflow: hidden;
}
html[data-kami-skin="nixie"] .kami-preview i {
  display: block;
  height: 4px;
  border-radius: 1px;
  background-color: var(--kami-t2);
}
html[data-kami-skin="nixie"] .kami-preview i:first-child {
  width: 58%;
