}
html[data-kami-skin="nixie"] .kami-preview i:nth-child(2) { width: 76%; }
html[data-kami-skin="nixie"] .kami-preview i:nth-child(3) { width: 64%; }
html[data-kami-skin="nixie"] .kami-preview i:nth-child(4) { width: 40%; }
html[data-kami-skin="nixie"] .kami-card.is-on .kami-preview i:first-child,
html[data-kami-skin="nixie"] .kami-card[aria-pressed="true"] .kami-preview i:first-child {
  background-color: var(--kami-accent);
  box-shadow: 0 0 8px rgba(255, 138, 32, .6);
}
html[data-kami-skin="nixie"] .kami-card.is-on { border-color: var(--kami-accent-line); }
html[data-kami-skin="nixie"] .kami-card.is-on .kami-card-head .kami-dot { box-shadow: 0 0 6px rgba(255, 138, 32, .5), inset 0 0 0 1px rgba(255, 190, 130, .4); }

/* ==========================================================================
 * 14 · 高级特效
 * ======================================================================== */

/* —— idle · 市电呼吸：唯一的循环动画，只动 opacity 的合成层 —— */
html[data-kami-skin="nixie"][data-kami-effects~="idle"] .kami-root .kami-surface::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 3;
  border-radius: inherit;
  pointer-events: none;
  mix-blend-mode: screen;
  background-image: radial-gradient(140% 100% at 50% -8%, rgba(255, 138, 32, calc(.075 * var(--kami-nixie-halo) / 100 * var(--kami-nixie-halo-cap))), rgba(0, 0, 0, 0) 62%);
  opacity: .9;
  animation: kami-nixie-mains 9.3s var(--kami-ease) infinite;
}

/* —— strike · 起辉：一道 1px 琥珀前缘从上往下扫过（纯 transform） —— */
html[data-kami-skin="nixie"][data-kami-effects~="strike"] .kami-root .kami-surface::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 4;
  border-radius: inherit;
  pointer-events: none;
  opacity: 0;
  background-image: linear-gradient(180deg, rgba(255, 214, 160, .9) 0, rgba(255, 170, 90, .45) 1px, rgba(255, 138, 32, .18) 3px, rgba(255, 138, 32, .05) 5px, rgba(0, 0, 0, 0) 7px);
}
html[data-kami-skin="nixie"][data-kami-effects~="strike"] .kami-root .kami-collapse[data-kami-open="1"].kami-surface::before,
html[data-kami-skin="nixie"][data-kami-effects~="strike"] .kami-root .kami-drop[data-kami-open="1"].kami-surface::before {
  animation: kami-nixie-front var(--kami-dur-slow) var(--kami-ease-out) both;
}
@keyframes kami-nixie-front {
  0% { opacity: .95; transform: translateY(0); }
  62% { opacity: .55; }
  100% { opacity: 0; transform: translateY(100%); }
}
html[data-kami-skin="nixie"][data-kami-effects~="strike"] .kami-root .kami-collapse[data-kami-open="1"].kami-shell {
  animation: kami-nixie-flash var(--kami-dur-slow) var(--kami-ease-out);
}
@keyframes kami-nixie-flash {
  0% { box-shadow: inset 0 1px 0 rgba(255, 236, 214, .055), inset 0 -1px 0 rgba(0, 0, 0, .5), var(--kami-shadow-sm); }
  16% { box-shadow: inset 0 1px 0 rgba(255, 236, 214, .16), inset 0 -1px 0 rgba(0, 0, 0, .5), var(--kami-shadow-sm), 0 0 calc(var(--kami-nixie-halo-r) * 2.2) -4px rgba(255, 138, 32, .55); }
  100% { box-shadow: inset 0 1px 0 rgba(255, 236, 214, .055), inset 0 -1px 0 rgba(0, 0, 0, .5), var(--kami-shadow-sm); }
}

/* —— halo · 过载溢光：加大电流，只在大屏上有意义 —— */
html[data-kami-skin="nixie"][data-kami-effects~="halo"] .kami-root .kami-shell {
  box-shadow:
    inset 0 1px 0 rgba(255, 236, 214, .07),
    inset 0 -1px 0 rgba(0, 0, 0, .5),
    var(--kami-shadow-sm),
    0 calc(var(--kami-nixie-halo-r) * 1.2) calc(var(--kami-nixie-halo-r) * 3) -10px rgba(255, 138, 32, .45);
}
html[data-kami-skin="nixie"][data-kami-effects~="halo"] .kami-root .kami-head .kami-sub {
  text-shadow: 0 0 1px rgba(255, 180, 110, .7), 0 1px calc(var(--kami-nixie-halo-r) * .7) rgba(255, 138, 32, .55), 0 0 calc(var(--kami-nixie-halo-r) * 2) rgba(255, 138, 32, .35);
}

/* ==========================================================================
 * 15 · 关键帧
 * ======================================================================== */
@keyframes kami-nixie-mains {
  0% { opacity: .92; }
  7% { opacity: .85; }
  13% { opacity: .96; }
  28% { opacity: .9; }
  41% { opacity: .95; }
  57% { opacity: .88; }
  63% { opacity: .97; }
  79% { opacity: .89; }
  93% { opacity: .94; }
  96% { opacity: .58; }
  97% { opacity: .97; }
  100% { opacity: .92; }
}
@keyframes kami-nixie-unseal {
  from { clip-path: inset(0 0 100% 0); }
  to { clip-path: inset(0 0 0 0); }
}
@keyframes kami-nixie-sweep {
  from { opacity: .9; transform: scaleX(0); }
  to { opacity: 1; transform: scaleX(1); }
}
@keyframes kami-nixie-strike {
  0% { box-shadow: inset 0 1px 2px rgba(0, 0, 0, .75), inset 0 -1px 0 var(--kami-accent), 0 0 calc(var(--kami-nixie-halo-r) * 1.6) -2px rgba(255, 170, 90, .85); }
  100% { box-shadow: inset 0 1px 2px rgba(0, 0, 0, .75), inset 0 -1px 0 var(--kami-accent), 0 calc(var(--kami-nixie-halo-r) * .3) calc(var(--kami-nixie-halo-r) * .7) -3px rgba(255, 138, 32, .6); }
}
@keyframes kami-nixie-badflash {
  0% { opacity: .35; }
  18% { opacity: 1; }
  34% { opacity: .4; }
  52% { opacity: 1; }
  100% { opacity: 1; }
}

/* ==========================================================================
 * 16 · 密度档位（换仪器，不是缩放）
 * ======================================================================== */
html[data-kami-skin="nixie"][data-kami-density="compact"] .kami-root {
  --kami-pad-x: 8px;
  --kami-pad-y: 5px;
  --kami-pad-lg-x: 10px;
  --kami-pad-lg-y: 8px;
  --kami-gap: 6px;
  --kami-gap-lg: 9px;
  --kami-row-h: 36px;
  --kami-ls-title: .12em;
  --kami-items-min: 13.5rem;
}
html[data-kami-skin="nixie"][data-kami-density="roomy"] .kami-root {
  --kami-pad-x: 13px;
  --kami-pad-y: 9px;
  --kami-pad-lg-x: 17px;
  --kami-pad-lg-y: 15px;
  --kami-gap: 11px;
  --kami-gap-lg: 16px;
  --kami-row-h: 44px;
  --kami-ls-title: .22em;
  --kami-items-min: 18rem;
}

/* ==========================================================================
 * 17 · 亮色：同一台仪器在日光下（通电 = 实心琥珀底 + 深色字）
 * ======================================================================== */
html[data-kami-skin="nixie"][data-kami-scheme="light"] .kami-root {
  --kami-fg: #2b261d;
