  --kami-bg-soft: #ded7c8;
  --kami-card: #f0ebe0;
  --kami-card-2: #e2dbcc;
  --kami-card-hover: #f7f2e8;
  --kami-line: rgba(60, 48, 30, .16);
  --kami-line-strong: rgba(60, 48, 30, .62);
  --kami-t1: rgba(60, 48, 30, .045);
  --kami-t2: rgba(60, 48, 30, .075);
  --kami-t3: rgba(60, 48, 30, .14);
