  --kami-shadow: 0 12px 28px -18px rgba(60, 40, 20, .45), 0 2px 5px -2px rgba(60, 40, 20, .25);
  --kami-shadow-sm: 0 3px 8px -4px rgba(60, 40, 20, .30);
  --kami-glow: #b8531a;
  --kami-nixie-glow-cap: .22;
  --kami-nixie-halo-cap: .42;
  --kami-texture:
    repeating-linear-gradient(0deg, rgba(90, 70, 40, calc(.028 * var(--kami-nixie-mesh) / 100)) 0 1px, transparent 1px 3px),
    repeating-linear-gradient(90deg, rgba(90, 70, 40, calc(.030 * var(--kami-nixie-mesh) / 100)) 0 1px, transparent 1px 4px),
    repeating-linear-gradient(0deg, rgba(90, 70, 40, calc(.040 * var(--kami-nixie-mesh) / 100)) 0 1px, transparent 1px 24px),
    radial-gradient(140% 100% at 50% -10%, rgba(184, 83, 26, calc(.05 * var(--kami-nixie-halo) / 100 * var(--kami-nixie-halo-cap))), transparent 62%);
  --kami-kind-action: #9b4210;
  --kami-kind-persona: #6b4a9c;
  --kami-kind-plot: #2f7a52;
  --kami-kind-info: #26687a;
  --kami-kind-fun: #8a6410;
  --kami-kind-nsfw: #9c3355;
  --kami-kind-other: #6a6353;
}
html[data-kami-skin="nixie"][data-kami-scheme="light"] .kami-root .kami-surface {
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .55), inset 0 -1px 0 rgba(60, 40, 20, .22), var(--kami-shadow-sm);
}
html[data-kami-skin="nixie"][data-kami-scheme="light"] .kami-root .kami-title { text-shadow: 0 -1px 0 rgba(255, 255, 255, .6), 0 1px 0 rgba(60, 40, 20, .18); }
html[data-kami-skin="nixie"][data-kami-scheme="light"] .kami-root .kami-head .kami-sub {
  background-color: var(--kami-accent);
  background-image: linear-gradient(180deg, rgba(255, 255, 255, .18), rgba(0, 0, 0, .12));
