  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .3), inset 0 -1px 0 rgba(0, 0, 0, .25);
}
html[data-kami-skin="nixie"][data-kami-scheme="light"] .kami-root .kami-seg-item.is-on {
  background-color: var(--kami-accent);
  color: var(--kami-accent-fg);
