}
html[data-kami-skin="nixie"][data-kami-scheme="light"] .kami-root .kami-card-note,
html[data-kami-skin="nixie"][data-kami-scheme="light"] .kami-root .kami-foot .kami-sub { text-shadow: 0 1px 0 rgba(255, 255, 255, .5); }
html[data-kami-skin="nixie"][data-kami-scheme="light"] .kami-root .kami-item::after { background-image: linear-gradient(90deg, rgba(155, 66, 16, 0) 0, var(--kami-accent) 45%, rgba(155, 66, 16, 0) 100%); }

/* ==========================================================================
 * 18 · 动效档位与降级
 * ======================================================================== */
html[data-kami-skin="nixie"][data-kami-motion="calm"] .kami-root {
  --kami-dur-fast: .15s;
  --kami-dur: .28s;
  --kami-dur-slow: .52s;
  --kami-enter-y: 0px;
  --kami-stagger: 0ms;
}
html[data-kami-skin="nixie"][data-kami-motion="calm"] .kami-root .kami-surface::after,
html[data-kami-skin="nixie"][data-kami-motion="calm"] .kami-root .kami-empty::before {
  animation: none;
}
html[data-kami-skin="nixie"][data-kami-motion="calm"] .kami-root .kami-surface::after { opacity: .92; }
html[data-kami-skin="nixie"][data-kami-motion="off"] .kami-root,
html[data-kami-skin="nixie"] .kami-root[data-kami-motion="off"] {
  --kami-dur-fast: 1ms;
  --kami-dur: 1ms;
  --kami-dur-slow: 1ms;
  --kami-enter-y: 0px;
  --kami-enter-scale: 1;
  --kami-stagger: 0ms;
}
html[data-kami-skin="nixie"][data-kami-motion="off"] .kami-root *,
html[data-kami-skin="nixie"][data-kami-motion="off"] .kami-root *::before,
html[data-kami-skin="nixie"][data-kami-motion="off"] .kami-root *::after,
html[data-kami-skin="nixie"] .kami-root[data-kami-motion="off"] *,
html[data-kami-skin="nixie"] .kami-root[data-kami-motion="off"] *::before,
html[data-kami-skin="nixie"] .kami-root[data-kami-motion="off"] *::after {
  animation-duration: 1ms !important;
  animation-delay: 0ms !important;
  animation-iteration-count: 1 !important;
  transition-duration: 1ms !important;
}
@media (prefers-reduced-motion: reduce) {
  html[data-kami-skin="nixie"] .kami-root *,
  html[data-kami-skin="nixie"] .kami-root *::before,
  html[data-kami-skin="nixie"] .kami-root *::after {
    animation-duration: 1ms !important;
    animation-delay: 0ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 1ms !important;
  }
}

/* ==========================================================================
 * 19 · 窄屏：320px 必须成立
 * ======================================================================== */
html[data-kami-skin="nixie"] .kami-shell { container-type: inline-size; container-name: kami-shell; }
@container kami-shell (max-width: 21rem) {
  html[data-kami-skin="nixie"] .kami-root .kami-list > .kami-item { grid-template-columns: 1fr; column-gap: 0; }
  html[data-kami-skin="nixie"] .kami-root .kami-list > .kami-item::before { display: none; }
  html[data-kami-skin="nixie"] .kami-root .kami-item { padding: var(--kami-pad-lg-y) 11px; }
  html[data-kami-skin="nixie"] .kami-root .kami-title { --kami-ls-title: .08em; }
}
@container kami-shell (max-width: 19rem) {
  html[data-kami-skin="nixie"] .kami-root .kami-seg-item { padding: 4px 7px; }
  html[data-kami-skin="nixie"] .kami-root .kami-head { gap: 6px; padding-left: var(--kami-pad-x); padding-right: var(--kami-pad-x); }
  html[data-kami-skin="nixie"] .kami-root .kami-body,
  html[data-kami-skin="nixie"] .kami-root .kami-foot,
  html[data-kami-skin="nixie"] .kami-root .kami-grid.kami-list { padding-left: var(--kami-pad-x); padding-right: var(--kami-pad-x); }
}
@container kami-shell (max-width: 15rem) {
  html[data-kami-skin="nixie"] .kami-root .kami-actions { flex-wrap: wrap; justify-content: flex-end; }
  html[data-kami-skin="nixie"] .kami-root .kami-head { flex-wrap: wrap; }
  html[data-kami-skin="nixie"] .kami-root .kami-head .kami-sub { min-width: 0; }
}
/* 窄屏下的面板：底部抽屉已由 ≤768px 的媒体查询接管 */
@media (max-width: 380px) {
  html[data-kami-skin="nixie"] .kami-root .kami-field-value { flex-wrap: wrap; justify-content: flex-end; }
  html[data-kami-skin="nixie"] .kami-root .kami-range { flex: 1 1 100%; width: auto; }
}

/* ============================================================
 * 20 · 设置面板里的条目网格：紧凑多列（手机底部抽屉排 3 列）
 * ------------------------------------------------------------
 * 面板里的网格只有 349~352px 宽，皮肤默认的 --kami-items-min（15.5rem ≈ 248px）
 * 永远只排得下 1 列。所以面板作用域内把令牌压到 96px：
 * 390px 宽的底部抽屉正好 3 列，桌面 420px 面板 3~4 列。
 *
 * 本皮肤还在上面把面板网格的列宽**写死**成 min(100%, 11.5rem)，根本不读那个令牌，
 * 所以这里必须把列宽改回读令牌 —— 不然光改令牌一点用都没有。
 *
 * 三重限定，缺一不可：
 *   · html[data-kami-skin="nixie"] —— 皮肤契约要求的皮肤前缀；
 *   · [data-kami-comp="panel"]     —— 消息 iframe 里只有 think / options 两种组件，
 *                                     没有 panel。带上它，紧凑化就绝不会渗进聊天前端；
 *  · **不再用面板 id 限定**（契约 §4.4）：组件规则对所有面板生效，以后加面板零维护。
 * ============================================================ */
html[data-kami-skin="nixie"] .kami-root[data-kami-comp="panel"]#kami-preset-panel {
  --kami-items-min: 96px;
}
html[data-kami-skin="nixie"] .kami-root[data-kami-comp="panel"]#kami-preset-panel .kami-grid {
  grid-template-columns: repeat(auto-fill, minmax(min(100%, var(--kami-items-min)), 1fr));
}

/* 窄屏（手机底部抽屉）下的列宽：96px 会让 375px 的抽屉排出 3 列、卡只有 ~110px，
   「DS/GLM底部破限」这种名字被拦腰断成 DS/GLM 断行。窄屏把列宽调大，宁可两列：
   375px 抽屉 → 2 列（卡 ~166px），320px → 2 列（卡 ~110px）。
   只改令牌，不动脚本结构；桌面 420px 面板不受影响（视口 > 560px 时照旧 3~4 列）。 */
@media (max-width: 560px) {
  html[data-kami-skin="nixie"] .kami-root[data-kami-comp="panel"]#kami-preset-panel {
    --kami-items-min: 152px;
  }
}
@media (max-width: 380px) {
  html[data-kami-skin="nixie"] .kami-root[data-kami-comp="panel"]#kami-preset-panel {
    --kami-items-min: 108px;
  }
}


/* ============================================================
 * 21 · 预设设置面板：条目卡「通电」的样子（开着 = 亮了）
 * ------------------------------------------------------------
 * 面板里一个条目 = 一张小卡（button.kami-item.kami-card），开着时脚本加 .is-on。
 * 上面第 6 节给 .kami-card.is-on 的只有一行边框换色，在 96px 的紧凑小卡上太弱：
 * 一眼扫过去分不清哪几条是通电的（用户真机实测）。这里用**本皮肤自己的暖橙令牌**
 * 强化成「老式仪器通电发光」：琥珀描边 + 内壁透光 + 底边电流 + 标题字发光。
 *
 * 三重限定（与上面的紧凑网格同一套理由，缺一不可）：
 *   · html[data-kami-skin="nixie"] —— 皮肤契约要求的皮肤前缀；
 *   · [data-kami-comp="panel"]     —— 消息 iframe 里只有 think / options，没有 panel；
 *  · **不再用面板 id 限定**（契约 §4.4）：组件规则对所有面板生效，以后加面板零维护。
 * 全部只用已有令牌，不新造颜色；光晕半径一律乘 --kami-nixie-halo-r，
 * 这样「特效关闭 / 亮色方案」下自动跟着衰减（亮色方案里 halo-cap 已被压到 .42）。
 * ============================================================ */
html[data-kami-skin="nixie"] .kami-root[data-kami-comp="panel"] .kami-item.is-on,
html[data-kami-skin="nixie"] .kami-root[data-kami-comp="panel"] .kami-item[aria-pressed="true"] {
  border-color: var(--kami-accent-line);
  background-color: var(--kami-accent-soft);
  background-image:
    linear-gradient(180deg, rgba(255, 138, 32, .10), rgba(255, 232, 204, 0) 46%),
    linear-gradient(180deg, rgba(255, 236, 214, .04), transparent 42%);
  box-shadow:
    inset 0 0 0 1px rgba(232, 134, 44, .22),
    inset 0 -2px 0 var(--kami-accent),
    0 calc(var(--kami-nixie-halo-r) * .55) calc(var(--kami-nixie-halo-r) * 1.4) -6px rgba(255, 138, 32, .62);
  color: var(--kami-fg);
}
/* 底边那道电流常亮（第 6 节的 ::after 只在 :active 时扫过） */
html[data-kami-skin="nixie"] .kami-root[data-kami-comp="panel"] .kami-item.is-on::after,
html[data-kami-skin="nixie"] .kami-root[data-kami-comp="panel"] .kami-item[aria-pressed="true"]::after {
  opacity: .85;
  transform: scaleX(1);
  box-shadow: 0 0 calc(var(--kami-nixie-halo-r) * .8) rgba(255, 138, 32, .55);
}
/* 条目名也跟着亮：辉光管「数字亮起来」的那一下 */
html[data-kami-skin="nixie"] .kami-root[data-kami-comp="panel"] .kami-item.is-on .kami-item-main,
html[data-kami-skin="nixie"] .kami-root[data-kami-comp="panel"] .kami-item[aria-pressed="true"] .kami-item-main {
  color: var(--kami-accent);
  text-shadow:
    0 0 1px rgba(255, 190, 130, .55),
    0 1px calc(var(--kami-nixie-halo-r) * .5) rgba(255, 138, 32, .48);
}
/* 未通电：沉下去一点，让「亮 / 不亮」的对比在紧凑网格里也一眼看得出 */
html[data-kami-skin="nixie"] .kami-root[data-kami-comp="panel"] .kami-item[aria-pressed="false"] .kami-item-main {
  color: var(--kami-fg-mute);
}
html[data-kami-skin="nixie"] .kami-root[data-kami-comp="panel"] .kami-item[aria-pressed="false"] {
  background-color: transparent;
  box-shadow: inset 0 1px 0 rgba(255, 236, 214, .03);
}
html[data-kami-skin="nixie"] .kami-root[data-kami-comp="panel"] .kami-item.is-on:hover,
html[data-kami-skin="nixie"] .kami-root[data-kami-comp="panel"] .kami-item[aria-pressed="true"]:hover {
  border-color: var(--kami-accent);
  box-shadow:
    inset 0 0 0 1px rgba(232, 134, 44, .34),
    inset 0 -2px 0 var(--kami-accent),
    0 calc(var(--kami-nixie-halo-r) * .8) calc(var(--kami-nixie-halo-r) * 1.9) -6px rgba(255, 138, 32, .75);
}

/* ============================================================
 * 22 · 条目名角标：emoji 摘下来，像管壳角上一枚常亮的小灯
 * ------------------------------------------------------------
 * 条目名绝大多数是四个汉字，前面那枚 emoji + 空格会把 110px 的紧凑小卡顶成两行。
 * 把 emoji 绝对定位到卡片角上，文字那一行**整行**腾出来，卡片高度不因此变高。
 * 脚本只摘显示，预设里条目名一个字没动。
 *
 * 三重限定，缺一不可（理由同上节）：
 *   · html[data-kami-skin="nixie"] —— 皮肤前缀；
 *   · [data-kami-comp="panel"]     —— 消息 iframe 里只有 think / options，没有 panel；
 *  · **不再用面板 id 限定**（契约 §4.4）：组件规则对所有面板生效，以后加面板零维护。
 * 颜色只用本皮肤已有的暖橙令牌，光晕半径照样乘 --kami-nixie-halo-r，
 * 这样特效关闭 / 亮色方案下自动跟着衰减。
 * ============================================================ */
html[data-kami-skin="nixie"] .kami-root[data-kami-comp="panel"] .kami-item.kami-card {
  position: relative;
}
html[data-kami-skin="nixie"] .kami-root[data-kami-comp="panel"] .kami-item > .kami-badge {
  position: absolute;
  top: 1px;
  right: 4px;
  left: auto;
  z-index: 2;
  padding: 0;
  border: 0;
  border-radius: 0;
  background-color: transparent;
  font-size: var(--kami-fs-xs);
  line-height: 1.2;
  letter-spacing: 0;
  color: var(--kami-accent);
  text-shadow: 0 1px calc(var(--kami-nixie-halo-r) * .5) rgba(255, 138, 32, .5);
  pointer-events: none;
}
html[data-kami-skin="nixie"] .kami-root[data-kami-comp="panel"] .kami-item > .kami-badge[data-kami-corner="tl"],
html[data-kami-skin="nixie"] .kami-root[data-kami-comp="panel"] .kami-item > .kami-badge[data-kami-corner="bl"] {
  right: auto;
  left: 4px;
}
html[data-kami-skin="nixie"] .kami-root[data-kami-comp="panel"] .kami-item > .kami-badge[data-kami-corner="br"],
html[data-kami-skin="nixie"] .kami-root[data-kami-comp="panel"] .kami-item > .kami-badge[data-kami-corner="bl"] {
  top: auto;
  bottom: 1px;
}
/* 角标**不占宽度**：文字始终拿整张卡的宽度；只在上下方向让出角标的高度。
   有上角标（tl/tr）就加上边距，有下角标（bl/br）就加下边距 —— 卡片略高一点点，
   文字那一行永远是整宽的（用户裁定：角标可以占高度，不能占宽度）。
   1.4em 取的是**卡片**的字号（--kami-fs-sm），ⓘ 的 1.4em 取的是它自己的 --kami-fs-xs；
   fs-sm > fs-xs，所以这一项必然盖过角标本体的高，再加 --kami-pad-y 盖过 top 偏移。
   旧值 calc(var(--kami-pad-lg-y) + 0.4em) 只给到 16.3px，而 ⓘ 从 top:1px 起占 16.4px
   （底边 17.4px），实测还剩 7.4 × 1.1 = 8.1px² 压在条目名上（2026-09-25 修）。 */
html[data-kami-skin="nixie"] .kami-root[data-kami-comp="panel"] .kami-item:has(> .kami-badge[data-kami-corner="tl"], > .kami-badge[data-kami-corner="tr"], > .kami-card-note[data-kami-corner="tr"]) {
  padding-top: calc(var(--kami-pad-y) + 1.4em);
}
html[data-kami-skin="nixie"] .kami-root[data-kami-comp="panel"] .kami-item:has(> .kami-badge[data-kami-corner="bl"], > .kami-badge[data-kami-corner="br"]) {
  padding-bottom: calc(var(--kami-pad-y) + 1.4em);
}

/* ============================================================
 * 24 · 非当前模型的模型专属条目：锁死
 * ------------------------------------------------------------
 * 面板「🤖 模型」tab 里，不属于「当前模型」的模型专属条目一律禁用（脚本写 HTML 原生的
 * disabled，条目卡本来就是 button）。外观也要给出「锁死」的样子：变暗 + 去掉悬停反馈
 * + 鼠标禁止符号。颜色只用本文件已有的「最弱文字色」令牌 --kami-fg-mute，不引入新颜色。
 *
 * 三重限定，缺一不可（理由同上面 22 节）：
 *   · html[data-kami-skin="nixie"] —— nixie 的作用域前缀；
 *   · [data-kami-comp="panel"]    —— 消息 iframe 里只有 think / options，没有 panel；
 *  · **不再用面板 id 限定**（契约 §4.4）：组件规则对所有面板生效，以后加面板零维护。
 * ============================================================ */
html[data-kami-skin="nixie"] .kami-root[data-kami-comp="panel"] .kami-item[disabled],
html[data-kami-skin="nixie"] .kami-root[data-kami-comp="panel"] .kami-item[disabled]:hover,
html[data-kami-skin="nixie"] .kami-root[data-kami-comp="panel"] .kami-item[disabled]:active {
  background-color: var(--kami-card);
  background-image: none;
  border-color: var(--kami-line);
  box-shadow: none;
  transform: none;
  opacity: .42;
  color: var(--kami-fg-mute);
  cursor: not-allowed;
}
/* 悬停才会冒出来的装饰（角标转正 / 左缘竖条 / 湿痕横线）在锁死时一律不许动 */
html[data-kami-skin="nixie"] .kami-root[data-kami-comp="panel"] .kami-item[disabled]:hover::before,
html[data-kami-skin="nixie"] .kami-root[data-kami-comp="panel"] .kami-item[disabled]:hover::after {
  transform: scale(0);
  opacity: 0;
}
html[data-kami-skin="nixie"] .kami-root[data-kami-comp="panel"] .kami-item[disabled]:hover > .kami-badge { transform: none; }

/* 注释标记 + 展开出来的注释正文：**不得用面板 id 限定**（契约 §4.4 硬规则），
   否则后加的面板（如引导 ）一条都匹配不上。
   标记元素 = span.kami-card-note[data-kami-note-mark]，与 🌟 预设面板同构。 */
html[data-kami-skin="nixie"] .kami-root[data-kami-comp="panel"] .kami-card-note[data-kami-note-mark] {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.4em;
  height: 1.4em;
  margin-left: 5px;
  border: var(--kami-border-w) solid var(--kami-accent);
  border-radius: var(--kami-r-pill);
  background: var(--kami-accent-soft);
  color: var(--kami-fg);
  font-size: var(--kami-fs-xs);
  line-height: 1;
  cursor: pointer;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}
html[data-kami-skin="nixie"] .kami-root[data-kami-comp="panel"] .kami-card-note[data-kami-note-mark]:hover,
html[data-kami-skin="nixie"] .kami-root[data-kami-comp="panel"] .kami-card-note[data-kami-note-mark]:focus-visible {
  background: var(--kami-accent);
  color: var(--kami-bg);
  border-color: var(--kami-accent);
}
html[data-kami-skin="nixie"] .kami-root[data-kami-comp="panel"] .kami-card-note[data-kami-note] {
  display: block;
  margin: 5px 0 0;
  padding: 5px 7px;
  border-left: var(--kami-accent-mark) solid var(--kami-accent);
  border-radius: var(--kami-r-xs);
  background: var(--kami-t2);
  color: var(--kami-fg-dim);
  font-size: var(--kami-fs-xs);
  line-height: 1.55;
  white-space: pre-wrap;
  word-break: break-word;
  text-align: left;
}
html[data-kami-skin="nixie"] .kami-root[data-kami-comp="panel"] .kami-card-note[data-kami-note][hidden] { display: none; }

/* ============================================================
 * · 面板里的控件边界：描边抬到「看得见」那一档
 * ------------------------------------------------------------
 * 面板里的条目卡底与外面那层卡片底是同一个色，唯一的边界就是那 1px 描边；
 * 原来的 --kami-line 实测只有 1.3~1.6:1，卡片会连成一片、看不出是一张一张的按钮。
 * 面板内的控件描边统一提到 --kami-line-strong（同一个色，只是更实），卡片边界实测 >= 3:1。
 * 只用本皮肤已有令牌，没有新颜色；不开 --kami-line 本身：聊天前端的细线该细还是细。
 * 不带面板 id（契约 §4.4）：三块面板与以后的新面板共用这一条。
 * ============================================================ */
html[data-kami-skin="nixie"] .kami-root[data-kami-comp="panel"] .kami-item:not(.is-on):not([aria-pressed="true"]),
html[data-kami-skin="nixie"] .kami-root[data-kami-comp="panel"] .kami-card:not(.kami-item),
html[data-kami-skin="nixie"] .kami-root[data-kami-comp="panel"] .kami-btn:not(.is-on):not(.kami-btn--primary) {
  border-color: var(--kami-line-strong);
}

/* ============================================================
 * 注释标记 ⓘ 做成右上角角标 + 注释外包层的等高拉伸（2026-09-21 用户裁定）
 * ------------------------------------------------------------
 * 1) 条目卡里的 ⓘ 现在是**右上角角标**：构建器给它 data-kami-corner="tr"
 *    （契约 §4.4 已登记的角标机制，与 emoji 角标同一套定位）。它不再占名字那一行的
 *    宽度 —— 行内记号会把约 100px 宽的条目卡里的名字挤到换行，同一行卡片因此被撑高。
 *    卡片头里的 ⓘ（卡片组标题、变量卡）没有这个属性，仍是行内记号，不受影响。
 *    角标位置与本皮肤 emoji 角标同值；pointer-events 必须是 auto（emoji 角标是 none，
 *    ⓘ 要能点）。上角标的内边距补偿在上面的 .kami-item:has(...) 里一起算了。
 * 2) .kami-item-note 是网格项、会被同行最高的卡拉伸；里面的卡片不跟着伸的话，
 *    带注释的卡就比同行其它卡矮一截（网格 stretch 只拉外包层，不拉它的子元素）。
 *    flex:1 1 auto 让卡片撑满外包层；注释展开时外包层被内容撑高，卡片照旧拿自然高度。
 * ============================================================ */
html[data-kami-skin="nixie"] .kami-root[data-kami-comp="panel"] .kami-item > .kami-card-note[data-kami-note-mark][data-kami-corner] {
  position: absolute;
  top: 1px;
  right: 4px;
  left: auto;
  z-index: 2;
  margin: 0;   /* .kami-card-note 的 margin-top 会把角标整体推低，压到条目名 */
  pointer-events: auto;
}
html[data-kami-skin="nixie"] .kami-root .kami-item-note {
  display: flex;
  flex-direction: column;
  min-width: 0;
}
html[data-kami-skin="nixie"] .kami-root .kami-item-note > .kami-card {
  flex: 1 1 auto;
}


/* ============================================================
 * · 正文美化包裹层 [data-kami-comp="body"]（已退役，2026-09-26）
 *   本节原样保留到 2026-09-26：给「只美化 <content> 标签内正文」包出来的
 *   div.kami-root[data-kami-comp="body"] 上皮（容器底 / 描边 / 圆角 / 字色）。
 *   那套功能已按用户裁定整体退役（改为直接在酒馆的消息楼层上做皮肤排版，
 *   见 src/skin/tavern.css 第 ⑤ 段与契约 §9.8），包裹层不再产生，故本节删除。
 *   消息楼层的容器（.mes）与正文排版都由全局层负责，皮肤包这边零维护。
 * ============================================================ */

/* ==== 全局层令牌上提（build/sync-tavern.mjs 生成，勿手改；把 --kami-* 令牌同时定义到 <html>，契约 §3）==== */
html[data-kami-skin="nixie"] {
  --kami-label-think-title: 演算;
  --kami-label-think-title-open: 演算明细;
  --kami-label-options-title: 指令;
  --kami-fg: #d9d2c4;
  --kami-fg-dim: #a49c8e;
  --kami-fg-mute: #9c9384;
  --kami-accent: #e8862c;
  --kami-accent-fg: #1b1105;
  --kami-accent-soft: rgba(232, 134, 44, .13);
  --kami-accent-line: rgba(232, 134, 44, .42);
  --kami-bg: #191612;
  --kami-bg-soft: #120f0c;
  --kami-card: #1f1b15;
  --kami-card-2: #13100d;
  --kami-card-hover: #272119;
  --kami-line: rgba(255, 228, 196, .10);
  --kami-line-strong: rgba(255, 186, 112, .46);
