"},{"id":"rain","name":"恋雨","button":"恋雨","scheme":"dark","tagline":"一块从内侧看的窗玻璃：雨在外面，恋在里面；玻璃上蒙着薄雾与滑落的水痕。","effects":[{"id":"fog","label":"玻璃起雾","desc":"组件表面覆盖半透明水雾，展开时雾气淡去，收起后重新蒙上。","default":true},{"id":"beading","label":"水珠凝结","desc":"玻璃表面附着细密微小凝结水珠，增加湿润反光质感。","default":true},{"id":"impact","label":"雨滴敲击","desc":"组件背景交替闪现雨滴撞击玻璃的扩散光斑与水晕。","default":true},{"id":"runnel","label":"雨痕滑落","desc":"多道水痕沿玻璃表面自上而下缓慢流淌滑落。","default":false},{"id":"longexposure","label":"车灯光斑","desc":"玻璃背景右上侧有一团静止的暖橙色车灯散焦光晕。","default":false}],"params":[{"id":"fog","label":"水雾浓度","group":"水汽","token":"--kami-fog","unit":"%","min":0,"max":100,"step":5,"value":45},{"id":"mark","label":"标线宽度","group":"面板","token":"--kami-accent-mark","unit":"px","min":0,"max":8,"step":1,"value":3},{"id":"ground","label":"底部暗影","group":"光照","token":"--kami-ground","unit":"%","min":0,"max":100,"step":5,"value":90}],"css":"/* ============================================================
 * 恋雨 · rain   —— 一块从内侧看的窗玻璃
 * ------------------------------------------------------------
 * 湿 = 模型的内心（外侧的雨）：边缘化开的玻璃、会起雾、被擦开
 * 干 = 你的抉择（内侧的你）：闭合的纸边、哑光、裁得利落
 * 重力是唯一方向：圆角上大下小 · 阴影下方重 · 悬停向下沉 · 水位线向下长
 *
 * 纯 CSS：无 JS、无外链、无 vh、无 SVG 外链（全部用渐变画）
 * 消息楼层里不使用 filter / backdrop-filter —— 模糊只留给唯一的悬浮面板
 * ============================================================ */

/* ============================================================
 * 1. 令牌 · 夜雨（dark，默认）
 * ============================================================ */
html[data-kami-skin="rain"] .kami-root {
  /* 色彩：湿灰绿 + 骨白 + 全屏唯一的一枚朱橙（钠灯 / 体温） */
  --kami-fg: #e9e4da;
  --kami-fg-dim: #aeb3ab;
  --kami-fg-mute: #858c85;
  --kami-accent: #ec7c4a;
  --kami-accent-fg: #14100c;
  --kami-accent-soft: rgba(236, 124, 74, .15);
  --kami-accent-line: rgba(236, 124, 74, .46);
  /* 「恋」那一半：暖晕。只出现在"被碰过/被选过"的地方，不参与大面积着色 */
  --kami-warm: rgba(240, 164, 132, .55);

  --kami-bg: rgba(16, 20, 21, .88);
  --kami-bg-soft: rgba(22, 27, 28, .93);
  /* 温度差：玻璃是冷的（--kami-bg），递到你手上的纸是暖的（--kami-card*） */
  --kami-card: #20201b;
  --kami-card-2: #16150f;
  --kami-card-hover: #2b2a23;
  --kami-line: rgba(233, 228, 218, .13);
  --kami-line-strong: rgba(233, 228, 218, .42);
  --kami-t1: rgba(233, 228, 218, .055);
  --kami-t2: rgba(233, 228, 218, .10);
  --kami-t3: rgba(233, 228, 218, .17);
  --kami-warn: #ef6a6c;
  /* 「投影重量」参数直接驱动投影的不透明度（--kami-ground 为百分比） */
  --kami-shadow: 0 1px 0 var(--kami-rain-sink), 0 16px 32px -20px rgba(0, 0, 0, var(--kami-ground));
  --kami-shadow-sm: 0 1px 0 var(--kami-rain-sink), 0 6px 14px -10px rgba(0, 0, 0, var(--kami-ground));

  /* 玻璃模糊量：只有唯一的悬浮面板用它（楼层里一律不模糊） */
  --kami-blur: 7px;

  /* 布局与尺寸 */
  --kami-r-xs: 4px;
  --kami-r-sm: 7px;
  --kami-r-md: 10px;
  --kami-r-lg: 14px;
  --kami-r-pill: 999px;
  --kami-border-w: 1px;
  --kami-pad-x: 11px;
  --kami-pad-y: 8px;
  --kami-pad-lg-x: 14px;
  --kami-pad-lg-y: 12px;
  --kami-gap: 7px;
  --kami-gap-lg: 12px;
  --kami-row-h: 42px;
  --kami-icon: 15px;
  --kami-maxw: none;
  --kami-items-min: 260px;
  --kami-panel-w: 420px;
  --kami-panel-h: 560px;
  --kami-list-dir: column;
  --kami-justify: stretch;

  /* 排版：界面用无衬线（器物），"话"用衬线（见 --kami-font-title） */
  --kami-fs-scale: 1;
  --kami-fs: calc(15px * var(--kami-fs-scale));
  --kami-fs-xs: calc(var(--kami-fs) * .74);
  --kami-fs-sm: calc(var(--kami-fs) * .88);
  --kami-fs-lg: calc(var(--kami-fs) * 1.14);
  --kami-lh: 1.72;
  --kami-ls: .015em;
  --kami-ls-title: .08em;
  --kami-font: system-ui, -apple-system, "Segoe UI", "PingFang SC", "HarmonyOS Sans SC", "Source Han Sans SC", "Noto Sans SC", "Microsoft YaHei", sans-serif;
  --kami-font-title: Georgia, "Songti SC", "Source Han Serif SC", "Noto Serif SC", "STSong", SimSun, serif;
  --kami-font-mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, "Liberation Mono", monospace;
  --kami-fw: 400;
  --kami-fw-title: 600;
  --kami-title-transform: full-width;

  /* 材质：单层斜向雨丝（透过玻璃看纸的那层雨） */
  --kami-texture: repeating-linear-gradient(78deg, rgba(233, 228, 218, .012) 0 1px, transparent 1px 7px);

  /* 水痕环：只用于 :focus-visible 外侧那一圈洇散 */
  --kami-glow: rgba(242, 150, 112, .32);
  --kami-glow-size: 6px;
  --kami-surface-clip: none;
  --kami-accent-mark: 3px;

  /* 动效：水被推着走，没有回弹 */
  --kami-dur-fast: .14s;
  --kami-dur: .2s;
  --kami-dur-slow: .3s;
  --kami-ease: cubic-bezier(.32, .72, .28, 1);
  --kami-ease-out: cubic-bezier(.16, .84, .28, 1);
  --kami-enter-y: -5px;
  --kami-enter-scale: .994;
  --kami-stagger: 45ms;

  /* 语义色：同一种湿灰绿在 7 个气温下的样子（识别主力是徽章的色条） */
  /* 「近处」的两类走暖（性格 / nsfw），其余四类保持雨里的冷 —— 温度本身就是分类信息 */
  --kami-kind-action: #ec7c4a;
  --kami-kind-persona: #e0998e;
  --kami-kind-plot: #8fbfa6;
  --kami-kind-info: #8fa9c0;
  --kami-kind-fun: #c3bc63;
  --kami-kind-nsfw: #cc6a6f;
  --kami-kind-other: #93a09b;

  /* 皮肤自定义参数（面板可覆盖）：起雾浓度 / 投影重量 */
  --kami-fog: 45%;
  --kami-ground: 90%;

  /* 掌印：手心贴在雾玻璃上留下的那一小块（静态，零成本） */
  --kami-palm:
    radial-gradient(30% 24% at 23% 64%, rgba(240, 164, 132, .085), transparent 72%),
    radial-gradient(33% 27% at 23% 64%, transparent 56%, rgba(240, 164, 132, .06) 62%, transparent 70%),
    radial-gradient(6% 5% at 36% 70%, rgba(240, 164, 132, .055), transparent 72%);

  /* 内部量：不属于契约令牌 */
  --kami-rain-dry: rgba(255, 255, 255, .05);
  --kami-rain-sink: rgba(0, 0, 0, .42);
  --kami-fog-k: .5;
  --kami-fx-b: none;
  --kami-fx-c: none;

  /* 风格性文案：只剩三个令牌（契约 §3.7），值先放中性占位，措辞由文案 Agent 统一处理 */
  --kami-label-think-title: 心事;
  --kami-label-think-title-open: 心事独白;
  --kami-label-options-title: 回应;
}

/* ---------- 令牌 · 雾白（light）—— 不是反相：阴天的乳白玻璃、被雨浸过的纸 ---------- */
html[data-kami-skin="rain"][data-kami-scheme="light"] .kami-surface {
  background-blend-mode: screen, overlay, multiply, normal;
}
html[data-kami-skin="rain"][data-kami-scheme="light"] .kami-root {
  --kami-fg: #1f2526;
  --kami-fg-dim: #4a5254;
  --kami-fg-mute: #57605e;
