  /* 雾白：玻璃偏中性冷，纸偏暖 —— 和暗色方案一样保留"外面冷、手里暖"的温度差 */
  --kami-bg: rgba(230, 231, 227, .92);
  --kami-bg-soft: rgba(237, 237, 232, .96);
  --kami-card: #f5f1e6;
