  letter-spacing: inherit;
}
html[data-kami-skin="rain"] .kami-root button { -webkit-appearance: none; appearance: none; }

/* 焦点：一枚落下的水滴——细环 + 一圈向外洇散的水痕（--kami-glow 的唯一用途） */
html[data-kami-skin="rain"] .kami-root :focus-visible {
  outline: 2px solid var(--kami-accent);
