"},{"id":"senren","name":"千恋万花","button":"千恋","scheme":"light","tagline":"和风古韵与落樱飞花：温润的米白和纸、薄红樱瓣，与细腻的描金短册。","effects":[{"id":"sakura","label":"落樱花瓣","desc":"卡片边缘点缀飘落的薄粉樱花花瓣与柔和花晕。","default":true},{"id":"washi","label":"和纸云纹","desc":"米白纸面上铺展细密的和纸纤维与微光云纹肌理。","default":true},{"id":"goldleaf","label":"洒金描边","desc":"标题与卡片边缘勾勒细腻的金箔微光与细描金线。","default":true},{"id":"tanzaku","label":"短册笺条","desc":"选项与卡片左侧装饰和风短册竖标与朱砂印记。","default":true},{"id":"softglow","label":"神木柔光","desc":"组件周围漫射温润的淡樱暖色环境光晕。","default":false}],"params":[{"id":"glow","label":"柔光半径","group":"光效","token":"--kami-glow-size","unit":"px","min":0,"max":20,"step":1,"value":6},{"id":"washi","label":"和纸浓度","group":"材质","token":"--kami-sr-washi","unit":"","min":0,"max":100,"step":5,"value":50},{"id":"sakura","label":"落樱浓度","group":"氛围","token":"--kami-sr-sakura","unit":"","min":0,"max":100,"step":5,"value":60},{"id":"gold","label":"描金亮度","group":"材质","token":"--kami-sr-gold","unit":"","min":0,"max":100,"step":5,"value":40},{"id":"drift","label":"飘樱周期","group":"动效","token":"--kami-sr-drift","unit":"s","min":2,"max":8,"step":0.5,"value":4}],"css":"/* ============================================================================
 * 卡密预设 · 皮肤：千恋万花（senren）
 * ----------------------------------------------------------------------------
 * 灵感源自和风古韵与落樱飞花：
 * 漫天飘落的淡粉樱花、温润素雅的米白和纸、典雅的朱红印泥与细腻的洒金描边。
 * 设计简报：design/proposals/senren.md
 *
 * 设计语言一句话：
 *   和风古韵与落樱飞花：温润的米白和纸、薄红樱瓣，与细腻的描金短册。
 *
 * 核心审美要素：
 *   · 纸律（和纸云纹）：素雅米白底色（#fcfaf6），细密和纸纤维与微光云纹肌理。
 *   · 樱律（落樱薄红）：以薄红樱色（#c94b6d）为主强调色，点缀花瓣剪影与落樱微晕。
 *   · 金律（描金细线）：以古雅金箔（#b88a44）为控件边线与高光，层次分明而温润细腻。
 *   · 印律（短册朱印）：状态指示与选中态化用和风短册竖签与朱砂钤印，字重与边框联动。
 *
 * 纯 CSS 实现：零外部请求、无 JS、无 @import、无 @font-face、无 vh、无 position:fixed 铺满。
 * 契约：docs/皮肤契约.md（作用域前缀 / 令牌全集 / 风格性文案槽 / 对比度防线）。
 * ========================================================================== */

/* ==========================================================================
 * 1 · 令牌全集（默认亮色：温润和纸配薄红樱色）
 * ======================================================================== */
html[data-kami-skin="senren"] .kami-root {
  /* —— 风格性文案槽位（契约 §3.7） —— */
  --kami-label-think-title: 绘卷;
  --kami-label-think-title-open: 绘卷全览;
  --kami-label-options-title: 纸笺;

  /* —— 色彩：米白和纸 + 浓墨 + 薄红樱色 + 描金 —— */
  --kami-fg: #2c2225;            /* 主文字：深沉温润的古墨色，对米白底 14.83:1，对白卡 15.65:1 */
  --kami-fg-dim: #5c4e54;        /* 次要文字：暖调墨灰，对米白底 7.52:1 */
  --kami-fg-mute: #7d6d74;       /* 最弱文字：淡墨，对米白底 5.11:1，对卡内 4.56:1 */
  --kami-accent: #c94b6d;        /* 强调色：薄红樱粉，白字在其上 5.40:1 */
  --kami-accent-fg: #ffffff;     /* 强调底上的文字：纯白 */
  --kami-accent-soft: rgba(201, 75, 109, 0.12); /* 浅樱粉高亮底 */
  --kami-accent-line: rgba(201, 75, 109, 0.52); /* 樱红描边/短册竖标 */

  --kami-bg: #fcfaf6;            /* 容器背景：米白温润和纸底 */
  --kami-bg-soft: #f5ede4;       /* 次级容器背景：浅暖米和纸底 */
  --kami-card: #ffffff;          /* 卡片背景：洁白素笺卡面 */
  --kami-card-2: #fbf5ee;        /* 卡片内正文/引用块背景 */
  --kami-card-hover: #fff3f6;    /* 卡片悬停：微透樱粉白（不透明色） */
  --kami-line: rgba(92, 78, 84, 0.16);          /* 常规分隔线 */
  --kami-line-strong: rgba(184, 138, 68, 0.55); /* 强调描边：细腻描金线，对和纸底 3.25:1 */
  --kami-t1: rgba(44, 34, 37, 0.04);
  --kami-t2: rgba(44, 34, 37, 0.08);
  --kami-t3: rgba(44, 34, 37, 0.16);
  --kami-warn: #ba3348;          /* 警示色：朱砂绯红，对卡底 5.82:1 */
  --kami-shadow: 0 8px 24px -8px rgba(90, 54, 62, 0.18), 0 2px 6px rgba(90, 54, 62, 0.06);
  --kami-shadow-sm: 0 2px 8px -2px rgba(90, 54, 62, 0.12);
  --kami-blur: 0px;

  /* —— 布局与尺寸 —— */
  --kami-r-xs: 3px;
  --kami-r-sm: 5px;
  --kami-r-md: 8px;
  --kami-r-lg: 12px;
  --kami-r-pill: 999px;
  --kami-border-w: 1px;
  --kami-pad-x: 12px;
  --kami-pad-y: 8px;
  --kami-pad-lg-x: 16px;
  --kami-pad-lg-y: 14px;
  --kami-gap: 8px;
  --kami-gap-lg: 12px;
  --kami-row-h: 38px;
  --kami-icon: 15px;
  --kami-maxw: none;
  --kami-items-min: 15.5rem;
  --kami-panel-w: 430px;
  --kami-panel-h: 570px;
  --kami-list-dir: column;
  --kami-justify: stretch;

  /* —— 文本与排版 —— */
  --kami-fs-scale: 1;
  --kami-fs: calc(15px * var(--kami-fs-scale));
  --kami-fs-xs: calc(var(--kami-fs) * 0.76);
  --kami-fs-sm: calc(var(--kami-fs) * 0.88);
  --kami-fs-lg: calc(var(--kami-fs) * 1.16);
  --kami-lh: 1.72;
  --kami-ls: 0.015em;
  --kami-ls-title: 0.08em;
  --kami-font: "Songti SC", "STSong", "宋体", "Noto Serif CJK SC", "Source Han Serif SC", Georgia, "Times New Roman", serif;
  --kami-font-title: "Kaiti SC", "STKaiti", "KaiTi", "Kaiti TC", "Hiragino Mincho ProN", "Songti SC", "STSong", serif;
  --kami-font-mono: ui-monospace, SFMono-Regular, "Cascadia Mono", Consolas, "Liberation Mono", monospace;
  --kami-fw: 400;
  --kami-fw-title: 700;
  --kami-title-transform: none;

  /* —— 装饰与特效 —— */
  --kami-texture: radial-gradient(circle at 18% 22%, rgba(201, 75, 109, 0.04) 0%, transparent 60%),
                  radial-gradient(circle at 82% 78%, rgba(184, 138, 68, 0.04) 0%, transparent 60%);
  --kami-glow: rgba(201, 75, 109, 0.35);
  --kami-glow-size: 6px;
  --kami-surface-clip: none;
  --kami-accent-mark: 3px;
  --kami-dim-lock: 0.42;

  /* —— 动效与过渡 —— */
  --kami-dur-fast: 0.12s;
  --kami-dur: 0.2s;
  --kami-dur-slow: 0.32s;
  --kami-ease: cubic-bezier(0.22, 0.72, 0.3, 1);
  --kami-ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --kami-enter-y: 4px;
  --kami-enter-scale: 0.985;
  --kami-stagger: 25ms;

  /* —— 语义色（和风传统七色，对亮底对比度均 >= 4.8:1） —— */
  --kami-kind-action: #2568a8;   /* 行动 · 蓝葵 */
  --kami-kind-persona: #b33a78;  /* 性格 · 樱紫 */
  --kami-kind-plot: #267d53;     /* 推进 · 松绿 */
  --kami-kind-info: #22788c;     /* 信息 · 浅葱 */
  --kami-kind-fun: #a86915;      /* 搞笑 · 琥珀 */
  --kami-kind-nsfw: #ba3348;     /* nsfw · 绯红 */
  --kami-kind-other: #6e6268;    /* 其他 · 灰樱 */

  /* —— 皮肤私有参数默认值 —— */
  --kami-sr-washi: 50;
  --kami-sr-sakura: 60;
  --kami-sr-gold: 40;
  --kami-sr-drift: 4s;

  box-sizing: border-box;
  color: var(--kami-fg);
  font-family: var(--kami-font);
  font-size: var(--kami-fs);
  font-weight: var(--kami-fw);
  line-height: var(--kami-lh);
  letter-spacing: var(--kami-ls);
  font-variant-numeric: tabular-nums;
  text-align: left;
  text-rendering: optimizeLegibility;
  word-break: break-word;
  -webkit-tap-highlight-color: transparent;
}

/* ==========================================================================
 * 2 · 基础重置与无干扰约束
 * ======================================================================== */
html[data-kami-skin="senren"] .kami-root *,
html[data-kami-skin="senren"] .kami-root *::before,
html[data-kami-skin="senren"] .kami-root *::after {
  box-sizing: border-box;
}

