}

html[data-kami-skin="senren"] .kami-switch-input:checked + .kami-switch-track .kami-switch-knob {
  transform: translateX(16px);
}

/* 滑杆 Range */
html[data-kami-skin="senren"] .kami-range {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 6px;
  border-radius: var(--kami-r-pill);
  background-color: var(--kami-bg-soft);
  border: var(--kami-border-w) solid var(--kami-line);
  outline: none;
}

html[data-kami-skin="senren"] .kami-range::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background-color: var(--kami-accent);
  border: 2px solid #ffffff;
  box-shadow: 0 1px 4px rgba(90, 54, 62, 0.3);
  cursor: pointer;
  transition: transform var(--kami-dur-fast) var(--kami-ease);
}

html[data-kami-skin="senren"] .kami-range::-moz-range-thumb {
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background-color: var(--kami-accent);
  border: 2px solid #ffffff;
