  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: var(--kami-line-strong) transparent;
}

html[data-kami-skin="senren"] .kami-scroll::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}

html[data-kami-skin="senren"] .kami-scroll::-webkit-scrollbar-track {
  background: transparent;
}

html[data-kami-skin="senren"] .kami-scroll::-webkit-scrollbar-thumb {
  background-color: var(--kami-line-strong);
  border-radius: var(--kami-r-pill);
}

/* 缩放手柄（描金短册折角） */
html[data-kami-skin="senren"] .kami-resize {
  position: absolute;
  right: 0;
  bottom: 0;
  width: 16px;
  height: 16px;
  cursor: nwse-resize;
  background-image: linear-gradient(135deg, transparent 46%, var(--kami-line-strong) 46%, var(--kami-line-strong) 54%, transparent 54%);
}

/* ==========================================================================
 * 20 · 移动端抽屉与两端适配（320px 必须成立）
 * ======================================================================== */
/* 兜底：面板脚本未挂 layout 时按 768px 贴底 */
@media (max-width: 768px) {
  html[data-kami-skin="senren"] .kami-root .kami-drop.kami-drop:not([data-kami-layout]) {
    left: 0;
    right: 0;
    top: auto;
    bottom: 0;
    width: auto;
    height: 78%;
    max-height: 78%;
    border-radius: var(--kami-r-lg) var(--kami-r-lg) 0 0;
  }
}

/* 移动端贴底抽屉 Sheet */
html[data-kami-skin="senren"] .kami-drop[data-kami-layout="sheet"] {
  border-bottom-left-radius: 0;
  border-bottom-right-radius: 0;
  border-bottom: none;
}

html[data-kami-skin="senren"] .kami-drop[data-kami-layout="sheet"] > .kami-head {
  padding-top: calc(var(--kami-pad-lg-y) + 8px);
}

html[data-kami-skin="senren"] .kami-drop[data-kami-layout="sheet"] > .kami-head::before {
  content: "";
  position: absolute;
  left: 50%;
  top: 6px;
  width: 36px;
  height: 4px;
  border-radius: var(--kami-r-pill);
  background-color: var(--kami-line-strong);
  transform: translateX(-50%);
}

/* 手机档媒体查询（选择器必须与密集网格基准规则逐字相同） */
@media (max-width: 560px) {
  html[data-kami-skin="senren"] .kami-root {
    --kami-row-h: 44px;
  }
  html[data-kami-skin="senren"] .kami-root[data-kami-comp="panel"] .kami-grid:has(> .kami-item, > .kami-item-note) {
    --kami-items-min: 152px;
  }
}

@media (max-width: 380px) {
  html[data-kami-skin="senren"] .kami-root {
    --kami-row-h: 44px;
  }
  html[data-kami-skin="senren"] .kami-root[data-kami-comp="panel"] .kami-grid:has(> .kami-item, > .kami-item-note) {
    --kami-items-min: 108px;
  }
  html[data-kami-skin="senren"] .kami-root .kami-bar {
    flex-wrap: wrap;
  }
}

/* 容器查询自适应收敛 */
@container kami-shell (max-width: 21rem) {
  html[data-kami-skin="senren"] .kami-root .kami-title { --kami-ls-title: 0.04em; }
  html[data-kami-skin="senren"] .kami-root .kami-bar { flex-wrap: wrap; }
}

@container kami-shell (max-width: 18rem) {
  html[data-kami-skin="senren"] .kami-root .kami-head { flex-wrap: wrap; }
  html[data-kami-skin="senren"] .kami-root .kami-actions { flex-wrap: wrap; }
}

/* ==========================================================================
 * 21 · 引导向导排版层（GUIDE_CSS 只排不染，外观归皮肤）
 * ======================================================================== */
