/* ==========================================================================
 * 22 · 特效实现（五大特效体系）
 * ======================================================================== */
/* 1. 落樱花瓣（sakura）：边缘飘落樱花花晕与花瓣剪影，带轻微飘舞动效 */
html[data-kami-skin="senren"][data-kami-effects~="sakura"] .kami-shell::before,
html[data-kami-skin="senren"][data-kami-effects~="sakura"] .kami-drop::before {
  content: "";
  position: absolute;
  top: 0;
  right: 0;
  width: 140px;
  height: 140px;
  pointer-events: none;
  background-image:
    radial-gradient(circle at 80% 20%, rgba(201, 75, 109, calc(0.18 * var(--kami-sr-sakura) / 100)) 0%, transparent 65%),
    radial-gradient(ellipse at 90% 10%, rgba(240, 160, 180, calc(0.25 * var(--kami-sr-sakura) / 100)) 0%, transparent 40%);
  z-index: 0;
  animation: kami-senren-drift var(--kami-sr-drift) ease-in-out infinite;
}

/* 2. 和纸云纹（washi）：米白纸面纤维纹理与云纹 */
html[data-kami-skin="senren"][data-kami-effects~="washi"] .kami-surface {
  background-image:
    repeating-linear-gradient(45deg, rgba(184, 138, 68, calc(0.025 * var(--kami-sr-washi) / 100)) 0 1px, transparent 1px 6px),
    repeating-linear-gradient(-45deg, rgba(201, 75, 109, calc(0.02 * var(--kami-sr-washi) / 100)) 0 1px, transparent 1px 8px),
    var(--kami-texture);
}

/* 3. 洒金描边（goldleaf）：细描金边与标题微光 */
html[data-kami-skin="senren"][data-kami-effects~="goldleaf"] .kami-card {
  box-shadow: 0 0 0 1px rgba(184, 138, 68, calc(0.35 * var(--kami-sr-gold) / 100)), var(--kami-shadow-sm);
}

html[data-kami-skin="senren"][data-kami-effects~="goldleaf"] .kami-title {
  text-shadow: 0 0 calc(var(--kami-glow-size) * 0.8) rgba(184, 138, 68, calc(0.3 * var(--kami-sr-gold) / 100));
}

/* 4. 短册笺条（tanzaku）：选项与卡片左侧和风短册竖标与朱砂钤印 */
html[data-kami-skin="senren"][data-kami-effects~="tanzaku"] .kami-item {
  border-left-width: 4px;
}

html[data-kami-skin="senren"][data-kami-effects~="tanzaku"] .kami-item.is-on::after {
  content: "";
  position: absolute;
  right: 8px;
  top: 8px;
  width: 8px;
  height: 8px;
  border-radius: 50% 0 50% 50%;
  background-color: var(--kami-accent);
  opacity: 0.85;
  transform: rotate(-30deg);
}

/* 5. 神木柔光（softglow）：温润樱红环境光晕 */
html[data-kami-skin="senren"][data-kami-effects~="softglow"] .kami-shell,
html[data-kami-skin="senren"][data-kami-effects~="softglow"] .kami-drop {
  box-shadow: 0 10px 30px -5px rgba(201, 75, 109, 0.28), 0 2px 10px rgba(90, 54, 62, 0.08);
}

