 * 卡密预设 · 皮肤：终端（terminal）
 * ----------------------------------------------------------------------------
 * 设计语言：一块深色终端窗口 —— 等宽字体、零圆角方框、双线外框、方括号标签，
 * 以及一个一直在闪的方块光标。设计简报见 design/proposals/terminal.md。
 *
 * 身份符号只有一个：「方括号标签 [ ] ＋ 闪烁方块光标 ▌」这套命令行标记语言。
 * ASCII 边框落成「1px 外框 + 内缩 3px 的 1px 内细线」双线框（特效 frame），
 * 不用盒画字符拼四角（字体回退与四角对齐在真机上不稳，且会跟标签抢注意力）。
 *
 * 配色两层就够：一层中性前景（--kami-fg 一族，承担全部正文）+ 一层亮绿强调
 * （--kami-accent，只做「点」：状态光标、选中描边、主按钮底、行内码）。
 * 琥珀只出现在 --kami-kind-fun 上，不参与主调。
 *
 * 对比度（WCAG 2.1 相对亮度公式实算，见 design/proposals/terminal.md §四）：
 *   暗档 正文最差 12.81:1 ｜ 次要 7.95:1 ｜ 最弱 5.91:1 ｜ 强调底上的字 9.62:1
 *   亮档 正文最差 13.69:1 ｜ 次要 6.91:1 ｜ 最弱 4.80:1 ｜ 强调底上的字 5.41:1
 *   强描边（--kami-line-strong）对卡底：暗档 3.75:1、亮档 3.69:1，均 >= 3:1。
 *
 * 纯 CSS 实现：零外部请求、无 JS、无 @import、无 @font-face、无 vh、
 * 无 position:fixed 铺满。契约：docs/皮肤契约.md。
 * ========================================================================== */

/* ==========================================================================
 * 1 · 令牌全集（默认暗档：近黑绿灰底 + 中性灰绿前景 + 亮绿强调）
 * ======================================================================== */
html[data-kami-skin="terminal"] .kami-root {
  /* —— 风格性文案槽位（契约 §3.7） —— */
  --kami-label-think-title: 思维日志;
  --kami-label-think-title-open: 日志全文;
  --kami-label-options-title: 行动指令;

  /* —— 色彩：中性前景一层 + 亮绿强调一层 —— */
  --kami-fg: #d3e6d8;            /* 主文字：中性浅灰绿（不是荧光绿），对卡底 12.81:1 */
  --kami-fg-dim: #a3b8a8;        /* 次要文字：对卡底 7.95:1 */
  --kami-fg-mute: #86a08d;       /* 最弱文字：对卡底 5.91:1 */
  --kami-accent: #3ee07f;        /* 强调色：终端亮绿，只做「点」 */
  --kami-accent-fg: #05240f;     /* 强调底上的文字：深墨绿，9.62:1 */
  --kami-accent-soft: rgba(62, 224, 127, 0.14);
  --kami-accent-line: rgba(62, 224, 127, 0.50);

  --kami-bg: #0c110d;            /* 容器背景：近黑绿灰 */
  --kami-bg-soft: #111811;       /* 次级容器背景 */
  --kami-card: #16201a;          /* 卡片背景（比容器亮一档，套卡时分得开） */
  --kami-card-2: #0f1512;        /* 卡片内正文块背景 */
  --kami-card-hover: #1c2a20;    /* 卡片悬停：不 opaque */
  --kami-line: rgba(211, 230, 216, 0.14);
  --kami-line-strong: rgba(127, 230, 166, 0.50); /* 对卡底 3.75:1 */
  --kami-t1: rgba(211, 230, 216, 0.05);
  --kami-t2: rgba(211, 230, 216, 0.09);
  --kami-t3: rgba(211, 230, 216, 0.16);
  --kami-warn: #ff7a6b;          /* 警示：对卡底 6.57:1 */
  --kami-shadow: 0 10px 30px rgba(0, 0, 0, 0.55);
  --kami-shadow-sm: 0 2px 8px rgba(0, 0, 0, 0.40);
  --kami-blur: 0px;              /* 终端不玻璃：零模糊，省每一层的 backdrop-filter */

  /* —— 布局与尺寸：零圆角是这套皮肤的骨架 —— */
  --kami-r-xs: 0px;
  --kami-r-sm: 0px;
  --kami-r-md: 0px;
  --kami-r-lg: 0px;
  --kami-r-pill: 0px;
  --kami-border-w: 1px;
  --kami-pad-x: 12px;
  --kami-pad-y: 7px;
  --kami-pad-lg-x: 16px;
  --kami-pad-lg-y: 13px;
  --kami-gap: 8px;
  --kami-gap-lg: 12px;
  --kami-row-h: 36px;
  --kami-icon: 15px;
  --kami-maxw: none;
  --kami-items-min: 15.5rem;
  --kami-panel-w: 430px;
  --kami-panel-h: 570px;
  --kami-list-dir: column;
  --kami-justify: stretch;

  /* —— 文本与排版：等宽三连，行高字距按等宽字单独调 —— */
  --kami-fs-scale: 1;
  --kami-fs: calc(14px * var(--kami-fs-scale));
  --kami-fs-xs: calc(var(--kami-fs) * .78);
  --kami-fs-sm: calc(var(--kami-fs) * .88);
  --kami-fs-lg: calc(var(--kami-fs) * 1.12);
  --kami-lh: 1.55;               /* 等宽字不套 serif 的行高 */
  --kami-ls: 0em;
  --kami-ls-title: 0.08em;
  --kami-font: ui-monospace, "SFMono-Regular", Menlo, Consolas, "Cascadia Mono", "Liberation Mono", "DejaVu Sans Mono", "Noto Sans Mono CJK SC", "Microsoft YaHei", monospace;
  --kami-font-title: var(--kami-font);
  --kami-font-mono: var(--kami-font);
  --kami-fw: 400;
  --kami-fw-title: 700;
  --kami-title-transform: none;

  /* —— 装饰与特效 —— */
  --kami-texture: radial-gradient(130% 100% at 50% 0%, rgba(62, 224, 127, 0.05), transparent 62%);
  --kami-glow: rgba(62, 224, 127, 0.45);
  --kami-glow-size: 6px;
  --kami-surface-clip: none;
  --kami-accent-mark: 2px;

  /* —— 动效 —— */
  --kami-dur-fast: 0.11s;
  --kami-dur: 0.18s;
  --kami-dur-slow: 0.28s;
  --kami-ease: cubic-bezier(0.22, 0.72, 0.3, 1);
  --kami-ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --kami-enter-y: 3px;
  --kami-enter-scale: 1;
  --kami-stagger: 22ms;

  /* —— 语义色（七个色相，同一档明度；暗档对卡底 >= 6.99:1） —— */
  --kami-kind-action: #6fb7ff;   /* 行动 · 蓝 */
  --kami-kind-persona: #ff9ec4;  /* 性格 · 粉 */
  --kami-kind-plot: #5fd48a;     /* 推进 · 绿 */
  --kami-kind-info: #5fc8d4;     /* 信息 · 青 */
  --kami-kind-fun: #e8b34a;      /* 搞笑 · 琥珀 */
  --kami-kind-nsfw: #ff8095;     /* nsfw · 绯 */
  --kami-kind-other: #a9b8ae;    /* 其他 · 灰绿 */

  /* —— 皮肤私有参数默认值（面板滑杆写的是这三个令牌） —— */
  --kami-term-glow: 6;           /* 辉光半径，px */
  --kami-term-scan: 30;          /* 扫描线浓度，% */
  --kami-term-blink: 1.06s;      /* 光标闪烁间隔 */

  box-sizing: border-box;
  color: var(--kami-fg);
  font-family: var(--kami-font);
  font-size: var(--kami-fs);
  font-weight: var(--kami-fw);
  line-height: var(--kami-lh);
  letter-spacing: var(--kami-ls);
  font-variant-numeric: tabular-nums;
  text-align: left;
  word-break: break-word;
  -webkit-tap-highlight-color: transparent;
}

/* 辉光半径参数接进标准令牌：--kami-glow-size 是无单位数字，参数给的是裸数 */
html[data-kami-skin="terminal"] .kami-root {
  --kami-glow-size: calc(var(--kami-term-glow) * 1px);
}

/* ==========================================================================
 * 2 · 明暗方案（亮档：纸白 + 墨绿，不做「只推算不实测」的那一档）
 * ======================================================================== */
html[data-kami-skin="terminal"][data-kami-scheme="light"] .kami-root {
  --kami-fg: #16241b;            /* 主文字：对纸白卡底 16.13:1 */
  --kami-fg-dim: #3f5546;        /* 次要：6.91:1 */
  --kami-fg-mute: #566d5e;       /* 最弱：4.80:1 */
  --kami-accent: #0b7a45;        /* 强调色压深：白字在其上 5.41:1 */
  --kami-accent-fg: #ffffff;
  --kami-accent-soft: rgba(11, 122, 69, 0.12);
  --kami-accent-line: rgba(11, 122, 69, 0.50);

  --kami-bg: #f2f6f1;
  --kami-bg-soft: #e9efe7;
  --kami-card: #ffffff;
  --kami-card-2: #eef3ec;
  --kami-card-hover: #e6efe4;
  --kami-line: rgba(22, 36, 27, 0.16);
  --kami-line-strong: rgba(22, 36, 27, 0.55); /* 对白卡底 3.69:1 */
  --kami-t1: rgba(22, 36, 27, 0.045);
  --kami-t2: rgba(22, 36, 27, 0.075);
  --kami-t3: rgba(22, 36, 27, 0.14);
  --kami-warn: #b3261e;
  --kami-shadow: 0 10px 26px rgba(12, 30, 18, 0.16);
  --kami-shadow-sm: 0 2px 8px rgba(12, 30, 18, 0.12);

  --kami-texture: radial-gradient(130% 100% at 50% 0%, rgba(11, 122, 69, 0.06), transparent 62%);
  --kami-glow: rgba(11, 122, 69, 0.35);

  --kami-kind-action: #1a5fa8;
  --kami-kind-persona: #a8386a;
  --kami-kind-plot: #1a7a45;
  --kami-kind-info: #136b76;
  --kami-kind-fun: #8a5e0a;
  --kami-kind-nsfw: #b02a4a;
  --kami-kind-other: #4d5c52;
}

/* ==========================================================================
 * 3 · 档位响应：密度 / 动效 / 减少动态
 * ======================================================================== */
html[data-kami-skin="terminal"][data-kami-density="compact"] .kami-root {
  --kami-pad-x: 9px;
  --kami-pad-y: 5px;
  --kami-pad-lg-x: 12px;
  --kami-pad-lg-y: 9px;
  --kami-gap: 6px;
  --kami-gap-lg: 9px;
  --kami-row-h: 30px;
}

html[data-kami-skin="terminal"][data-kami-density="cozy"] .kami-root {
  --kami-pad-x: 12px;
  --kami-pad-y: 7px;
  --kami-pad-lg-x: 16px;
  --kami-pad-lg-y: 13px;
  --kami-gap: 8px;
  --kami-gap-lg: 12px;
  --kami-row-h: 36px;
}

html[data-kami-skin="terminal"][data-kami-density="roomy"] .kami-root {
  --kami-pad-x: 15px;
  --kami-pad-y: 10px;
  --kami-pad-lg-x: 20px;
  --kami-pad-lg-y: 18px;
  --kami-gap: 10px;
  --kami-gap-lg: 15px;
  --kami-row-h: 42px;
}

/* calm：时长降一档 + 去掉循环动画 */
html[data-kami-skin="terminal"][data-kami-motion="calm"] .kami-root {
  --kami-dur-fast: 0.07s;
  --kami-dur: 0.11s;
  --kami-dur-slow: 0.16s;
  --kami-enter-y: 1px;
  --kami-stagger: 8ms;
}

/* off：全部压到 1ms 且无位移；循环动画直接停（不是压到 1ms，契约 §3.6） */
html[data-kami-skin="terminal"][data-kami-motion="off"] .kami-root {
  --kami-dur-fast: 1ms;
  --kami-dur: 1ms;
  --kami-dur-slow: 1ms;
  --kami-enter-y: 0px;
  --kami-enter-scale: 1;
  --kami-stagger: 0ms;
}

@media (prefers-reduced-motion: reduce) {
  html[data-kami-skin="terminal"] .kami-root {
    --kami-dur-fast: 1ms;
    --kami-dur: 1ms;
    --kami-dur-slow: 1ms;
    --kami-enter-y: 0px;
    --kami-enter-scale: 1;
    --kami-stagger: 0ms;
  }
  /* 循环动画一律直接停：压到 1ms 仍然是无限循环，reduce 下不许跑 */
  html[data-kami-skin="terminal"] .kami-root *,
  html[data-kami-skin="terminal"] .kami-root *::before,
  html[data-kami-skin="terminal"] .kami-root *::after {
    animation: none !important;
    transition-duration: 1ms !important;
  }
}

/* ==========================================================================
 * 4 · 光标闪烁关键帧（硬切换，不做渐变——终端光标是瞬跳的）
 * ======================================================================== */
@keyframes kami-term-blink {
  0%, 45% { opacity: 1; }
  55%, 100% { opacity: 0; }
}

/* ==========================================================================
 * 5 · 焦点与可访问性
 * ======================================================================== */
html[data-kami-skin="terminal"] .kami-root :focus-visible {
  outline: 2px solid var(--kami-accent);
  outline-offset: 2px;
}

html[data-kami-skin="terminal"] .kami-root .kami-switch-input:focus-visible + .kami-switch-track {
  outline: 2px solid var(--kami-accent);
  outline-offset: 2px;
}

/* ==========================================================================
 * 6 · 控件对比度四件套（panel 作用域 + 三项 !important）
 *    阻击两层抢色：① 用户酒馆「自定义 CSS」给四类控件上的 !important 深漆；
 *    ② 皮肤头部 .kami-root input { color: inherit } 把文字压成 fg-dim。
 *    background-color 必须长写：简写会把 .kami-select 自绘箭头的
 *    background-image 一起重置掉。
 * ======================================================================== */
html[data-kami-skin="terminal"] .kami-root[data-kami-comp="panel"] input.kami-number,
html[data-kami-skin="terminal"] .kami-root[data-kami-comp="panel"] select.kami-number,
html[data-kami-skin="terminal"] .kami-root[data-kami-comp="panel"] textarea.kami-number,
html[data-kami-skin="terminal"] .kami-root[data-kami-comp="panel"] input.kami-text,
html[data-kami-skin="terminal"] .kami-root[data-kami-comp="panel"] textarea.kami-textarea,
html[data-kami-skin="terminal"] .kami-root[data-kami-comp="panel"] select.kami-select {
  color: var(--kami-fg) !important;
  background-color: var(--kami-bg-soft) !important;
  border-color: var(--kami-line-strong) !important;
  color-scheme: dark !important;
}

html[data-kami-skin="terminal"][data-kami-scheme="light"] .kami-root[data-kami-comp="panel"] input.kami-number,
html[data-kami-skin="terminal"][data-kami-scheme="light"] .kami-root[data-kami-comp="panel"] select.kami-number,
html[data-kami-skin="terminal"][data-kami-scheme="light"] .kami-root[data-kami-comp="panel"] textarea.kami-number,
html[data-kami-skin="terminal"][data-kami-scheme="light"] .kami-root[data-kami-comp="panel"] input.kami-text,
html[data-kami-skin="terminal"][data-kami-scheme="light"] .kami-root[data-kami-comp="panel"] textarea.kami-textarea,
html[data-kami-skin="terminal"][data-kami-scheme="light"] .kami-root[data-kami-comp="panel"] select.kami-select {
  color-scheme: light !important;
}

/* 右对齐只属于数字框（契约 §4.2：不许挂在裸类名上，会被 select/textarea 一起吃） */
html[data-kami-skin="terminal"] .kami-root input.kami-number[type="number"] {
  text-align: right;
}

/* ==========================================================================
 * 7 · 结构与等高约束
 * ======================================================================== */
html[data-kami-skin="terminal"] .kami-root .kami-item-note {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

html[data-kami-skin="terminal"] .kami-root .kami-item-note > .kami-card {
  flex: 1 1 auto;
}

/* 预览窗必须 pointer-events:none：少一处就是「预览卡点不动」（iframe 吃点击） */
html[data-kami-skin="terminal"] .kami-root .kami-pv,
html[data-kami-skin="terminal"] .kami-root .kami-pv-frame,
html[data-kami-skin="terminal"] .kami-root .kami-guide-pv,
html[data-kami-skin="terminal"] .kami-root .kami-guide-pv-frame {
  pointer-events: none;
}

/* ==========================================================================
 * 8 · 基础重置
 * ======================================================================== */
html[data-kami-skin="terminal"] .kami-root *,
html[data-kami-skin="terminal"] .kami-root *::before,
html[data-kami-skin="terminal"] .kami-root *::after {
  box-sizing: border-box;
}

html[data-kami-skin="terminal"] .kami-root button,
html[data-kami-skin="terminal"] .kami-root input,
html[data-kami-skin="terminal"] .kami-root select,
html[data-kami-skin="terminal"] .kami-root textarea {
  font: inherit;
  color: inherit;
  letter-spacing: inherit;
  margin: 0;
}

html[data-kami-skin="terminal"] .kami-root button {
  -webkit-appearance: none;
  appearance: none;
}

html[data-kami-skin="terminal"] .kami-root [hidden] {
  display: none !important;
}

html[data-kami-skin="terminal"] .kami-root img {
  max-width: 100%;
}

/* 装饰槽：本皮肤不声明 decor，槽位一律收起 */
html[data-kami-skin="terminal"] .kami-root .kami-deco {
  display: none;
}

/* 结构兜底（与脚本注入的 STRUCT_CSS 一致，皮肤自己再写一遍，双保险） */
html[data-kami-skin="terminal"] .kami-root .kami-collapse[data-kami-open="0"] > .kami-collapse-body {
  display: none;
}
html[data-kami-skin="terminal"] .kami-root .kami-collapse[data-kami-open="1"] > .kami-collapse-body {
  display: block;
}
html[data-kami-skin="terminal"] .kami-root[data-kami-view="raw"] [data-kami-view="render"] {
  display: none;
}
html[data-kami-skin="terminal"] .kami-root[data-kami-view="render"] [data-kami-view="raw"] {
  display: none;
}

/* ==========================================================================
 * 9 · 外壳 / 表面 / 三段结构
 *    ⚠️ .kami-shell 与 .kami-surface 常常是同一个元素：这里只写
 *    background-color / background-image 长写属性，绝不写 background 简写
 *    （简写会把 .kami-surface 上叠的纹理整个重置掉）。
 * ======================================================================== */
html[data-kami-skin="terminal"] .kami-shell {
  position: relative;
  display: block;
  background-color: var(--kami-bg);
  border: var(--kami-border-w) solid var(--kami-line-strong);
  border-radius: var(--kami-r-lg);
  box-shadow: var(--kami-shadow);
  overflow: hidden;
  transition: border-color var(--kami-dur) var(--kami-ease), box-shadow var(--kami-dur) var(--kami-ease);
}

html[data-kami-skin="terminal"] .kami-surface {
  background-image: var(--kami-texture);
}

html[data-kami-skin="terminal"] .kami-head {
  position: relative;
  display: flex;
  align-items: center;
  gap: var(--kami-gap);
  min-height: var(--kami-row-h);
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
}

html[data-kami-skin="terminal"] .kami-head:not(.kami-collapse-head) {
  border-bottom: var(--kami-border-w) solid var(--kami-line);
}

html[data-kami-skin="terminal"] .kami-collapse-head {
  cursor: pointer;
  user-select: none;
}

html[data-kami-skin="terminal"] .kami-title {
  font-family: var(--kami-font-title);
  font-weight: var(--kami-fw-title);
  font-size: var(--kami-fs);
  letter-spacing: var(--kami-ls-title);
  color: var(--kami-fg);
  white-space: nowrap;
}

html[data-kami-skin="terminal"] .kami-sub {
  font-size: var(--kami-fs-xs);
  color: var(--kami-fg-mute);
  white-space: nowrap;
}

html[data-kami-skin="terminal"] .kami-actions {
  display: flex;
  align-items: center;
  gap: var(--kami-gap);
  margin-left: auto;
  flex: none;
}

html[data-kami-skin="terminal"] .kami-body {
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
}

html[data-kami-skin="terminal"] .kami-foot {
  display: flex;
  align-items: center;
  gap: var(--kami-gap);
  padding: var(--kami-pad-y) var(--kami-pad-lg-x) var(--kami-pad-lg-y);
  border-top: var(--kami-border-w) solid var(--kami-line);
  font-size: var(--kami-fs-xs);
  color: var(--kami-fg-mute);
}

/* —— 状态点 = 方块光标：关态空心框，开态实心块（形状占一样，不只靠颜色） —— */
html[data-kami-skin="terminal"] .kami-dot {
  flex: none;
  width: 0.55em;
  height: 1em;
  border: var(--kami-border-w) solid var(--kami-fg-mute);
  border-radius: var(--kami-r-xs);
  background-color: transparent;
  transition: background-color var(--kami-dur) var(--kami-ease), border-color var(--kami-dur) var(--kami-ease);
}

html[data-kami-skin="terminal"] .kami-dot[data-kami-on="1"] {
  background-color: var(--kami-accent);
  border-color: var(--kami-accent);
  box-shadow: 0 0 var(--kami-glow-size) var(--kami-glow);
}

/* 引导向导的进度点复用 .kami-dot：不许跟着闪，退回小方点 */
html[data-kami-skin="terminal"] .kami-dots .kami-dot {
  width: 6px;
  height: 6px;
  border-color: var(--kami-fg-mute);
  opacity: 0.38;
}

html[data-kami-skin="terminal"] .kami-dots .kami-dot[data-kami-on="1"] {
  background-color: var(--kami-accent);
  border-color: var(--kami-accent);
  opacity: 1;
}

/* —— 折叠箭头 —— */
html[data-kami-skin="terminal"] .kami-chev {
  flex: none;
  font-size: calc(var(--kami-icon) * 0.8);
  color: var(--kami-accent);
  transition: transform var(--kami-dur) var(--kami-ease);
}

html[data-kami-skin="terminal"] .kami-collapse[data-kami-open="1"] > .kami-head .kami-chev {
  transform: rotate(90deg);
}

/* —— 正文头部的横向操作行 —— */
html[data-kami-skin="terminal"] .kami-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--kami-gap);
  padding: var(--kami-pad-y) var(--kami-pad-lg-x);
  border-bottom: var(--kami-border-w) solid var(--kami-line);
  background-color: var(--kami-bg-soft);
}

/* ==========================================================================
 * 10 · 按钮
 * ======================================================================== */
html[data-kami-skin="terminal"] .kami-btn,
html[data-kami-skin="terminal"] .kami-icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: var(--kami-row-h);
  padding: var(--kami-pad-y) var(--kami-pad-x);
  border: var(--kami-border-w) solid var(--kami-line-strong);
  border-radius: var(--kami-r-sm);
  background-color: var(--kami-card);
  color: var(--kami-fg);
  font-family: var(--kami-font);
  font-size: var(--kami-fs-sm);
  line-height: 1.2;
  cursor: pointer;
  user-select: none;
  transition: background-color var(--kami-dur-fast) var(--kami-ease),
              border-color var(--kami-dur-fast) var(--kami-ease),
              color var(--kami-dur-fast) var(--kami-ease);
}

html[data-kami-skin="terminal"] .kami-icon-btn {
  min-width: var(--kami-row-h);
  padding: 0;
  font-size: var(--kami-icon);
}

@media (hover: hover) {
  html[data-kami-skin="terminal"] .kami-btn:hover,
  html[data-kami-skin="terminal"] .kami-icon-btn:hover {
    background-color: var(--kami-card-hover);
    border-color: var(--kami-accent);
    color: var(--kami-accent);
  }
}

html[data-kami-skin="terminal"] .kami-btn:active,
html[data-kami-skin="terminal"] .kami-icon-btn:active {
  transform: translateY(1px);
}

html[data-kami-skin="terminal"] .kami-btn[disabled],
html[data-kami-skin="terminal"] .kami-icon-btn[disabled] {
  opacity: 0.45;
  cursor: default;
}

html[data-kami-skin="terminal"] .kami-btn--ghost {
  background-color: transparent;
}

/* 主按钮：整块强调底 → 文字令牌一族成对翻过去（历史上同型事故三次） */
html[data-kami-skin="terminal"] .kami-root .kami-btn--primary {
  --kami-fg: var(--kami-accent-fg);
  --kami-fg-dim: var(--kami-accent-fg);
  --kami-fg-mute: var(--kami-accent-fg);
  --kami-line: var(--kami-accent-fg);
  --kami-line-strong: var(--kami-accent-fg);
  background-color: var(--kami-accent);
  border-color: var(--kami-accent);
  color: var(--kami-accent-fg);
  font-weight: var(--kami-fw-title);
}

@media (hover: hover) {
  html[data-kami-skin="terminal"] .kami-btn--primary:hover {
    filter: brightness(1.08);
    color: var(--kami-accent-fg);
  }
}

/* 选中态：淡染底 + 内环 + 加粗，四条里三条不是颜色。
   ⚠️ 不加 border-width:2px —— 那会让卡片点一下跳高 3px（实测引导页 45 vs 42）。 */
html[data-kami-skin="terminal"] .kami-root .kami-btn.is-on {
  background-color: var(--kami-accent-soft);
  border-color: var(--kami-accent);
  color: var(--kami-fg);
  font-weight: var(--kami-fw-title);
  box-shadow: inset 0 0 0 1px var(--kami-accent);
}

/* ==========================================================================
 * 11 · 分段切换（渲染 / 原文、填入 / 发送）
 * ======================================================================== */
html[data-kami-skin="terminal"] .kami-seg {
  display: inline-flex;
  gap: 2px;
  padding: 2px;
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-sm);
  background-color: var(--kami-t1);
}

html[data-kami-skin="terminal"] .kami-seg-item {
  border: 0;
  border-radius: var(--kami-r-xs);
  background-color: transparent;
  color: var(--kami-fg-dim);
  font-family: var(--kami-font);
  font-size: var(--kami-fs-xs);
  letter-spacing: var(--kami-ls);
  padding: 5px 9px;
  cursor: pointer;
  transition: background-color var(--kami-dur-fast) var(--kami-ease), color var(--kami-dur-fast) var(--kami-ease);
}

/* 选中换底（整块强调色）→ 文字一族翻过去 */
html[data-kami-skin="terminal"] .kami-root .kami-seg-item.is-on {
  --kami-fg: var(--kami-accent-fg);
  --kami-fg-dim: var(--kami-accent-fg);
  --kami-fg-mute: var(--kami-accent-fg);
  --kami-line: var(--kami-accent-fg);
  --kami-line-strong: var(--kami-accent-fg);
  background-color: var(--kami-accent);
  color: var(--kami-accent-fg);
  font-weight: var(--kami-fw-title);
}

/* ==========================================================================
 * 12 · 消息楼层组件（思维链 think / 行动选项 options）
 * ======================================================================== */
html[data-kami-skin="terminal"] .kami-root:not([data-kami-comp="panel"]) {
  margin: 10px 0 8px;
  max-width: var(--kami-maxw);
}

/* —— markdown 正文 —— */
html[data-kami-skin="terminal"] .kami-md {
  font-size: var(--kami-fs);
  line-height: var(--kami-lh);
  color: var(--kami-fg);
}

html[data-kami-skin="terminal"] .kami-md > :first-child {
  margin-top: 0;
}

html[data-kami-skin="terminal"] .kami-md > :last-child {
  margin-bottom: 0;
}

html[data-kami-skin="terminal"] .kami-md p {
  margin: 0.5em 0;
}

html[data-kami-skin="terminal"] .kami-md h1,
html[data-kami-skin="terminal"] .kami-md h2,
html[data-kami-skin="terminal"] .kami-md h3 {
  margin: 0.9em 0 0.4em;
  font-family: var(--kami-font-title);
  font-weight: var(--kami-fw-title);
  font-size: var(--kami-fs);
  letter-spacing: var(--kami-ls-title);
  color: var(--kami-fg);
}

/* 引用块 = 终端里引用别人的输出 */
html[data-kami-skin="terminal"] .kami-md blockquote {
  margin: 0.6em 0;
  padding: 2px 0 2px 10px;
  border-left: var(--kami-accent-mark) solid var(--kami-accent-line);
  color: var(--kami-fg-mute);
}

html[data-kami-skin="terminal"] .kami-md blockquote::before {
  content: "> ";
  color: var(--kami-accent);
}

html[data-kami-skin="terminal"] .kami-md code {
  font-family: var(--kami-font-mono);
  font-size: 0.88em;
  padding: 1px 5px;
  background-color: var(--kami-accent-soft);
  color: var(--kami-accent);
}

html[data-kami-skin="terminal"] .kami-md pre {
  margin: 0.6em 0;
  padding: var(--kami-pad-y) var(--kami-pad-x);
  background-color: var(--kami-card-2);
  border: var(--kami-border-w) solid var(--kami-line);
  overflow-x: auto;
}

html[data-kami-skin="terminal"] .kami-md pre code {
  background: none;
  padding: 0;
  color: inherit;
}

html[data-kami-skin="terminal"] .kami-md ul,
html[data-kami-skin="terminal"] .kami-md ol {
  margin: 0.5em 0;
  padding-left: 1.3em;
}

html[data-kami-skin="terminal"] .kami-md li {
  margin: 0.18em 0;
}

html[data-kami-skin="terminal"] .kami-md strong {
  color: var(--kami-fg);
  font-weight: 700;
}

html[data-kami-skin="terminal"] .kami-md a {
  color: var(--kami-accent);
  text-underline-offset: 2px;
}

html[data-kami-skin="terminal"] .kami-md hr {
  border: 0;
  border-top: var(--kami-border-w) solid var(--kami-line);
  margin: 0.8em 0;
}

html[data-kami-skin="terminal"] .kami-md table {
  border-collapse: collapse;
  width: 100%;
  font-size: var(--kami-fs-xs);
}

html[data-kami-skin="terminal"] .kami-md th,
html[data-kami-skin="terminal"] .kami-md td {
  border: var(--kami-border-w) solid var(--kami-line);
  padding: 4px 7px;
}

/* —— 原文（等宽）块：终端控制台的样子 —— */
html[data-kami-skin="terminal"] .kami-raw {
  margin: 0;
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
  background-color: var(--kami-card-2);
  border: var(--kami-border-w) solid var(--kami-line);
  font-family: var(--kami-font-mono);
  font-size: var(--kami-fs-xs);
  line-height: 1.5;
  color: var(--kami-fg-dim);
  white-space: pre-wrap;
  overflow-x: auto;
}

/* —— 列表 / 网格 —— */
html[data-kami-skin="terminal"] .kami-list {
  display: flex;
  flex-direction: var(--kami-list-dir);
  justify-content: var(--kami-justify);
  gap: var(--kami-gap);
}

html[data-kami-skin="terminal"] .kami-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, var(--kami-items-min)), 1fr));
  gap: var(--kami-gap);
  align-items: stretch;
}

/* —— 卡片 / 条目 —— */
html[data-kami-skin="terminal"] .kami-card {
  position: relative;
  background-color: var(--kami-card);
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-md);
}

html[data-kami-skin="terminal"] .kami-item {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 4px;
  width: 100%;
  text-align: left;
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-md);
  background-color: var(--kami-card);
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
  cursor: pointer;
  transition: background-color var(--kami-dur) var(--kami-ease),
              border-color var(--kami-dur) var(--kami-ease);
}

@media (hover: hover) {
  html[data-kami-skin="terminal"] .kami-item:hover {
    background-color: var(--kami-card-hover);
    border-color: var(--kami-accent);
  }
}

/* 选中态：淡染底 + 内环 + 加粗，四条里三条不是颜色（不改 border-width，避免点一下跳高） */
html[data-kami-skin="terminal"] .kami-root .kami-item.is-on,
html[data-kami-skin="terminal"] .kami-root .kami-item[aria-pressed="true"] {
  border-color: var(--kami-accent);
  background-color: var(--kami-accent-soft);
  color: var(--kami-fg);
  font-weight: var(--kami-fw-title);
  box-shadow: inset 0 0 0 1px var(--kami-accent);
}

html[data-kami-skin="terminal"] .kami-item.is-done {
  border-color: var(--kami-accent);
  background-color: var(--kami-accent-soft);
}

html[data-kami-skin="terminal"] .kami-item[data-kami-busy="1"] {
  opacity: 0.7;
  pointer-events: none;
}

html[data-kami-skin="terminal"] .kami-item.is-demo {
  opacity: 0.62;
  cursor: default;
}

html[data-kami-skin="terminal"] .kami-item-main {
  flex: 1 1 auto;
  min-width: 0;
}

html[data-kami-skin="terminal"] .kami-item-side {
  flex: none;
  margin-left: auto;
  color: var(--kami-fg-mute);
  font-size: var(--kami-fs-sm);
}

html[data-kami-skin="terminal"] .kami-card-head {
  display: flex;
  align-items: center;
  gap: var(--kami-gap);
  width: 100%;
  margin-bottom: 6px;
}

html[data-kami-skin="terminal"] .kami-card-title {
  font-weight: var(--kami-fw-title);
  font-size: var(--kami-fs-sm);
  color: var(--kami-fg);
}

html[data-kami-skin="terminal"] .kami-card-note {
  font-size: var(--kami-fs-xs);
  color: var(--kami-fg-mute);
}

html[data-kami-skin="terminal"] .kami-card-body {
  display: block;
  font-size: var(--kami-fs-sm);
  color: var(--kami-fg-dim);
}

/* —— 方括号标签（身份符号）：chip 与消息楼层里的 badge —— */
html[data-kami-skin="terminal"] .kami-chip,
html[data-kami-skin="terminal"] .kami-root:not([data-kami-comp="panel"]) .kami-badge {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  flex: none;
  padding: 1px 6px;
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-xs);
  background-color: var(--kami-t1);
  color: var(--kami-fg-dim);
  font-size: var(--kami-fs-xs);
  line-height: 1.5;
  white-space: nowrap;
}

html[data-kami-skin="terminal"] .kami-chip::before,
html[data-kami-skin="terminal"] .kami-root:not([data-kami-comp="panel"]) .kami-badge::before {
  content: "[";
  color: var(--kami-accent);
}

html[data-kami-skin="terminal"] .kami-chip::after,
html[data-kami-skin="terminal"] .kami-root:not([data-kami-comp="panel"]) .kami-badge::after {
  content: "]";
  color: var(--kami-accent);
}

/* 语义色：chip / badge / 卡片左缘一条同色线 */
html[data-kami-skin="terminal"] .kami-root [data-kami-kind="action"]  { --kami-kind-curr: var(--kami-kind-action); }
html[data-kami-skin="terminal"] .kami-root [data-kami-kind="persona"] { --kami-kind-curr: var(--kami-kind-persona); }
html[data-kami-skin="terminal"] .kami-root [data-kami-kind="plot"]    { --kami-kind-curr: var(--kami-kind-plot); }
html[data-kami-skin="terminal"] .kami-root [data-kami-kind="info"]    { --kami-kind-curr: var(--kami-kind-info); }
html[data-kami-skin="terminal"] .kami-root [data-kami-kind="fun"]     { --kami-kind-curr: var(--kami-kind-fun); }
html[data-kami-skin="terminal"] .kami-root [data-kami-kind="nsfw"]    { --kami-kind-curr: var(--kami-kind-nsfw); }
html[data-kami-skin="terminal"] .kami-root [data-kami-kind="other"]   { --kami-kind-curr: var(--kami-kind-other); }

html[data-kami-skin="terminal"] .kami-chip[data-kami-kind],
html[data-kami-skin="terminal"] .kami-root:not([data-kami-comp="panel"]) .kami-badge[data-kami-kind] {
  color: var(--kami-kind-curr, var(--kami-accent));
  border-color: var(--kami-kind-curr, var(--kami-accent));
}

html[data-kami-skin="terminal"] .kami-root .kami-card[data-kami-kind],
html[data-kami-skin="terminal"] .kami-root .kami-item[data-kami-kind] {
  border-left: var(--kami-accent-mark) solid var(--kami-kind-curr, var(--kami-accent-line));
}

/* —— 空态：一枚 $ 提示符 + 一枚方块光标 —— */
html[data-kami-skin="terminal"] .kami-empty {
  padding: var(--kami-pad-lg-y) 0;
  color: var(--kami-fg-mute);
  font-size: var(--kami-fs-sm);
}

html[data-kami-skin="terminal"] .kami-empty::before {
  content: "$ ";
  color: var(--kami-accent);
}

html[data-kami-skin="terminal"] .kami-empty::after {
  content: "";
  display: inline-block;
  width: 0.5em;
  height: 1em;
  margin-left: 2px;
  vertical-align: -0.14em;
  background-color: var(--kami-accent);
}

/* —— 内联提示 Toast —— */
html[data-kami-skin="terminal"] .kami-toast {
  margin-top: var(--kami-gap);
  padding: var(--kami-pad-y) var(--kami-pad-x);
  border: var(--kami-border-w) solid var(--kami-accent);
  border-radius: var(--kami-r-xs);
  background-color: var(--kami-accent);
  color: var(--kami-accent-fg);
  font-size: var(--kami-fs-xs);
  font-weight: var(--kami-fw-title);
  animation: kami-term-in var(--kami-dur) var(--kami-ease-out) backwards;
}

html[data-kami-skin="terminal"] .kami-toast.is-bad {
  background-color: var(--kami-warn);
  border-color: var(--kami-warn);
  color: var(--kami-accent-fg);
}

@keyframes kami-term-in {
  from { opacity: 0; transform: translateY(calc(var(--kami-enter-y) * -1)); }
  to { opacity: 1; transform: none; }
}

/* ==========================================================================
 * 13 · 面板专用（契约 §4.4：一律 .kami-root[data-kami-comp="panel"] 后代选择器，
 *     绝不挂 #kami-preset-panel / #kami-guide-panel / #kami-skin-panel /
 *     #kami-compress-panel。同一枚组件在四块面板里必须是同一副样子。）
 * ======================================================================== */
/* 舞台后面压一层暗幕，让浮窗从页面里浮出来（舞台本身 pointer-events:none 由脚本保证） */
html[data-kami-skin="terminal"] .kami-root[data-kami-comp="panel"] {
  background-color: rgba(4, 9, 6, 0.55);
}

html[data-kami-skin="terminal"][data-kami-scheme="light"] .kami-root[data-kami-comp="panel"] {
  background-color: rgba(16, 30, 22, 0.28);
}

/* 面板本体：位置与尺寸来自脚本下发的四个几何令牌，皮肤只决定它长什么样 */
html[data-kami-skin="terminal"] .kami-root .kami-drop.kami-drop {
  position: absolute;
  left: var(--kami-panel-x, 50%);
  top: var(--kami-panel-y, 72px);
  width: var(--kami-panel-w, min(430px, calc(100% - 24px)));
  height: var(--kami-panel-h, 570px);
  max-height: calc(100% - 24px);
  pointer-events: auto;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background-color: var(--kami-bg);
  background-image: var(--kami-texture);
  border: var(--kami-border-w) solid var(--kami-line-strong);
  border-radius: var(--kami-r-lg);
  box-shadow: var(--kami-shadow);
}

html[data-kami-skin="terminal"] .kami-drop > .kami-head,
html[data-kami-skin="terminal"] .kami-drop > .kami-tabs,
html[data-kami-skin="terminal"] .kami-drop > .kami-foot { flex: 0 0 auto; }

html[data-kami-skin="terminal"] .kami-drop > .kami-body { flex: 1 1 auto; min-height: 0; }

/* 拖动把手的视觉反馈（data-kami-drag 由面板脚本下发） */
html[data-kami-skin="terminal"] .kami-drop > .kami-head[data-kami-drag] { cursor: grab; }
html[data-kami-skin="terminal"] .kami-drop > .kami-head[data-kami-drag]:active { cursor: grabbing; }

/* —— 标签页行：方括号标签 + 底部实线 —— */
html[data-kami-skin="terminal"] .kami-tabs {
  display: flex;
  gap: 2px;
  padding: 0 var(--kami-pad-lg-x);
  border-bottom: var(--kami-border-w) solid var(--kami-line);
  overflow-x: auto;
  scrollbar-width: none;
  -webkit-mask-image: linear-gradient(90deg, #000 calc(100% - 20px), transparent 100%);
  mask-image: linear-gradient(90deg, #000 calc(100% - 20px), transparent 100%);
}

html[data-kami-skin="terminal"] .kami-tabs::-webkit-scrollbar { display: none; }

html[data-kami-skin="terminal"] .kami-tab {
  flex: none;
  border: 0;
  border-bottom: var(--kami-accent-mark) solid transparent;
  background-color: transparent;
  color: var(--kami-fg-mute);
  font-family: var(--kami-font);
  font-size: var(--kami-fs-sm);
  letter-spacing: var(--kami-ls);
  padding: 9px var(--kami-pad-x);
  cursor: pointer;
  white-space: nowrap;
  transition: color var(--kami-dur-fast) var(--kami-ease), border-color var(--kami-dur-fast) var(--kami-ease);
}

html[data-kami-skin="terminal"] .kami-tab::before { content: "["; color: var(--kami-fg-mute); }
html[data-kami-skin="terminal"] .kami-tab::after { content: "]"; color: var(--kami-fg-mute); }

@media (hover: hover) {
  html[data-kami-skin="terminal"] .kami-tab:hover { color: var(--kami-accent); }
  html[data-kami-skin="terminal"] .kami-tab:hover::before,
  html[data-kami-skin="terminal"] .kami-tab:hover::after { color: var(--kami-accent); }
}

/* 选中 tab：换底（淡染）+ 粗底线 + 字重，三条里两条不是颜色 */
html[data-kami-skin="terminal"] .kami-tab[aria-selected="true"] {
  color: var(--kami-accent);
  font-weight: var(--kami-fw-title);
  border-bottom-color: var(--kami-accent);
  background-color: var(--kami-accent-soft);
}

html[data-kami-skin="terminal"] .kami-tab[aria-selected="true"]::before,
html[data-kami-skin="terminal"] .kami-tab[aria-selected="true"]::after { color: var(--kami-accent); }

/* —— 面板网格：密集判据必须把 .kami-item-note 一并列进去 —— */
html[data-kami-skin="terminal"] .kami-root[data-kami-comp="panel"] .kami-grid:has(> .kami-item, > .kami-item-note) {
  --kami-items-min: 100px;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, var(--kami-items-min)), 1fr));
  gap: var(--kami-gap);
}

/* —— 面板内卡片：未选中不能和容器同色（换一档明度 + 一条看得见的边） —— */
html[data-kami-skin="terminal"] .kami-root[data-kami-comp="panel"] .kami-card {
  border: var(--kami-border-w) solid var(--kami-line-strong);
  background-color: var(--kami-card);
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
}

html[data-kami-skin="terminal"] .kami-root[data-kami-comp="panel"] .kami-card .kami-card:not(.is-on):not([aria-pressed="true"]) {
  background-color: var(--kami-card-2);
  border-color: var(--kami-line);
}

html[data-kami-skin="terminal"] .kami-root[data-kami-comp="panel"] .kami-card.is-on,
html[data-kami-skin="terminal"] .kami-root[data-kami-comp="panel"] .kami-card[aria-pressed="true"] {
  border-color: var(--kami-accent);
  background-color: var(--kami-accent-soft);
  color: var(--kami-fg);
  box-shadow: inset 0 0 0 1px var(--kami-accent);
}

/* 分组卡内部网格：别把内边距叠两层（条目卡自己已有内边距） */
html[data-kami-skin="terminal"] .kami-drop .kami-card:not(.kami-item):has(> .kami-card-body > .kami-grid) {
  padding-left: 12px;
  padding-right: 12px;
}

html[data-kami-skin="terminal"] .kami-drop .kami-card:not(.kami-item):has(> .kami-card-body > .kami-grid) > .kami-card-head,
html[data-kami-skin="terminal"] .kami-drop .kami-card:not(.kami-item):has(> .kami-card-body > .kami-grid) > .kami-card-title,
html[data-kami-skin="terminal"] .kami-drop .kami-card:not(.kami-item):has(> .kami-card-body > .kami-grid) > .kami-card-note {
  padding-left: 0;
  padding-right: 0;
}

/* 卡头做成与卡同宽的矩形标题条，不是悬在卡里的小药丸 */
html[data-kami-skin="terminal"] .kami-root[data-kami-comp="panel"] button.kami-card-head.kami-btn {
  width: 100%;
  min-height: 0;
  border-radius: var(--kami-r-xs);
  justify-content: flex-start;
  padding: 6px 8px;
  background-color: transparent;
  border: 0;
}

/* —— 面板里的条目卡 —— */
html[data-kami-skin="terminal"] .kami-root[data-kami-comp="panel"] .kami-item {
  position: relative;
  padding: 10px 12px;
  min-height: 42px;
}

/* ⓘ 注释标记：右上角角标，只占高度不占宽度；必须能点。
   margin:0 —— .kami-card-note 的 margin-top 会把角标整体推低，压到条目名。 */
html[data-kami-skin="terminal"] .kami-root[data-kami-comp="panel"] .kami-item > .kami-card-note[data-kami-note-mark][data-kami-corner] {
  position: absolute;
  top: 5px;
  right: 5px;
  left: auto;
  z-index: 2;
  margin: 0;
  pointer-events: auto;
}

/* 上角标的内边距补偿：条目卡里有 tl/tr 角标或 ⓘ 时，顶上让出一格。
   1.4em 取的是**卡片**的字号（--kami-fs-sm），ⓘ 的 1.4em 取的是它自己的 --kami-fs-xs；
   fs-sm > fs-xs，所以这一项必然盖过角标本体的高，再加 --kami-pad-y 盖过 top 偏移。
   旧值 calc(var(--kami-pad-lg-y) + 0.4em) 只给到 17.9px，而 ⓘ 从 top:5px 起占 15.3px
   （底边 20.3px），实测还剩 8.3 × 2.4 = 19.6px² 压在条目名上（2026-09-25 修）。 */
html[data-kami-skin="terminal"] .kami-root[data-kami-comp="panel"] .kami-item:has(> .kami-badge[data-kami-corner="tl"], > .kami-badge[data-kami-corner="tr"], > .kami-card-note[data-kami-corner="tr"]) {
  padding-top: calc(var(--kami-pad-y) + 1.4em);
}

html[data-kami-skin="terminal"] .kami-root[data-kami-comp="panel"] .kami-item:has(> .kami-badge[data-kami-corner="bl"], > .kami-badge[data-kami-corner="br"]) {
  padding-bottom: calc(var(--kami-pad-y) + 1.4em);
}

/* emoji 角标（条目名里摘出来的那枚）：不占宽度、不抢点击 */
html[data-kami-skin="terminal"] .kami-root[data-kami-comp="panel"] .kami-item > .kami-badge {
  position: absolute;
  top: 5px;
  right: 5px;
  left: auto;
  z-index: 2;
  padding: 0;
  border: 0;
  background: none;
  font-size: var(--kami-fs-xs);
  line-height: 1.2;
  color: var(--kami-fg-mute);
  pointer-events: none;
}

html[data-kami-skin="terminal"] .kami-root[data-kami-comp="panel"] .kami-item > .kami-badge[data-kami-corner="tl"],
html[data-kami-skin="terminal"] .kami-root[data-kami-comp="panel"] .kami-item > .kami-badge[data-kami-corner="bl"] {
  right: auto;
  left: 5px;
}

html[data-kami-skin="terminal"] .kami-root[data-kami-comp="panel"] .kami-item > .kami-badge[data-kami-corner="br"],
html[data-kami-skin="terminal"] .kami-root[data-kami-comp="panel"] .kami-item > .kami-badge[data-kami-corner="bl"] {
  top: auto;
  bottom: 5px;
}

/* 锁死的模型专属条目 */
html[data-kami-skin="terminal"] .kami-root[data-kami-comp="panel"] .kami-item[disabled],
html[data-kami-skin="terminal"] .kami-root[data-kami-comp="panel"] .kami-item[disabled]:hover,
html[data-kami-skin="terminal"] .kami-root[data-kami-comp="panel"] .kami-item[disabled]:active {
  background-color: var(--kami-card);
  border-color: var(--kami-line);
  box-shadow: none;
  opacity: 0.42;
  color: var(--kami-fg-mute);
  cursor: not-allowed;
}

/* 注释标记（行内那枚）与注释正文 */
html[data-kami-skin="terminal"] .kami-root[data-kami-comp="panel"] .kami-card-note[data-kami-note-mark] {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.4em;
  height: 1.4em;
  margin-left: 5px;
  border: var(--kami-border-w) solid var(--kami-accent);
  border-radius: var(--kami-r-xs);
  background-color: var(--kami-accent-soft);
  color: var(--kami-fg);
  font-size: var(--kami-fs-xs);
  line-height: 1;
  cursor: pointer;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}

html[data-kami-skin="terminal"] .kami-root[data-kami-comp="panel"] .kami-card-note[data-kami-note-mark]:hover,
html[data-kami-skin="terminal"] .kami-root[data-kami-comp="panel"] .kami-card-note[data-kami-note-mark]:focus-visible {
  background-color: var(--kami-accent);
  color: var(--kami-accent-fg);
}

html[data-kami-skin="terminal"] .kami-root[data-kami-comp="panel"] .kami-card-note[data-kami-note] {
  display: block;
  margin: 5px 0 0;
  padding: 5px 7px;
  border-left: var(--kami-accent-mark) solid var(--kami-accent);
  border-radius: var(--kami-r-xs);
  background-color: var(--kami-t2);
  color: var(--kami-fg-dim);
  font-size: var(--kami-fs-xs);
  line-height: 1.55;
  white-space: pre-wrap;
  word-break: break-word;
  text-align: left;
}

html[data-kami-skin="terminal"] .kami-root[data-kami-comp="panel"] .kami-card-note[data-kami-note][hidden] {
  display: none;
}

/* —— 设置项一行 —— */
html[data-kami-skin="terminal"] .kami-field {
  display: flex;
  align-items: center;
  gap: var(--kami-gap);
  padding: var(--kami-pad-y) 0;
  border-bottom: var(--kami-border-w) solid var(--kami-line);
}

html[data-kami-skin="terminal"] .kami-field:last-child { border-bottom: none; }

html[data-kami-skin="terminal"] .kami-field-label {
  flex: 1 1 auto;
  min-width: 0;
  font-size: var(--kami-fs-sm);
  color: var(--kami-fg);
}

html[data-kami-skin="terminal"] .kami-field-value {
  flex: none;
  display: flex;
  align-items: center;
  gap: 6px;
}

/* —— 数字框 / 文本 / 多行 / 下拉（非 panel 作用域的那份外观） —— */
html[data-kami-skin="terminal"] .kami-root .kami-number,
html[data-kami-skin="terminal"] .kami-root .kami-text,
html[data-kami-skin="terminal"] .kami-root .kami-textarea {
  min-height: var(--kami-row-h);
  padding: var(--kami-pad-y) var(--kami-pad-x);
  border: var(--kami-border-w) solid var(--kami-line-strong);
  border-radius: var(--kami-r-xs);
  background-color: var(--kami-bg-soft);
  color: var(--kami-fg);
  font-family: var(--kami-font-mono);
  font-size: var(--kami-fs-sm);
  text-align: left;
}

html[data-kami-skin="terminal"] .kami-root .kami-number {
  width: 62px;
  min-height: 28px;
  padding: 2px 6px;
  font-size: var(--kami-fs-xs);
}

html[data-kami-skin="terminal"] .kami-root .kami-textarea { resize: vertical; }

/* 下拉：抹掉原生外观，用两层 linear-gradient 拼一个 V 形箭头。
    底必须写 background-color 长写属性 —— 写 background 简写会把箭头一起重置。 */
html[data-kami-skin="terminal"] .kami-root .kami-select {
  -webkit-appearance: none;
  appearance: none;
  min-height: var(--kami-row-h);
  padding: var(--kami-pad-y) calc(var(--kami-pad-x) + 16px) var(--kami-pad-y) var(--kami-pad-x);
  border: var(--kami-border-w) solid var(--kami-line-strong);
  border-radius: var(--kami-r-xs);
  background-color: var(--kami-bg-soft);
  background-image:
    linear-gradient(45deg, transparent 50%, var(--kami-fg-mute) 50%),
    linear-gradient(135deg, var(--kami-fg-mute) 50%, transparent 50%);
  background-size: 4px 4px, 4px 4px;
  background-position: calc(100% - 13px) calc(50% + 1px), calc(100% - 9px) calc(50% + 1px);
  background-repeat: no-repeat;
  color: var(--kami-fg);
  font-family: var(--kami-font);
  font-size: var(--kami-fs-sm);
  text-align: left;
  cursor: pointer;
}

/* —— 开关：方角轨道 + 方块旋钮（终端开关是方的，不是胶囊） —— */
html[data-kami-skin="terminal"] .kami-switch {
  position: relative;
  display: inline-flex;
  align-items: center;
  cursor: pointer;
  user-select: none;
}

html[data-kami-skin="terminal"] .kami-switch-input {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}

html[data-kami-skin="terminal"] .kami-switch-track {
  position: relative;
  width: 40px;
  height: 22px;
  border: var(--kami-border-w) solid var(--kami-line-strong);
  border-radius: var(--kami-r-xs);
  background-color: var(--kami-t3);
  transition: background-color var(--kami-dur) var(--kami-ease), border-color var(--kami-dur) var(--kami-ease);
}

html[data-kami-skin="terminal"] .kami-switch-knob {
  position: absolute;
  top: 2px;
  left: 2px;
  width: 16px;
  height: 16px;
  border-radius: var(--kami-r-xs);
  background-color: var(--kami-fg-dim);
  transition: transform var(--kami-dur) var(--kami-ease), background-color var(--kami-dur) var(--kami-ease);
}

html[data-kami-skin="terminal"] .kami-switch-input:checked + .kami-switch-track {
  background-color: var(--kami-accent-soft);
  border-color: var(--kami-accent);
}

html[data-kami-skin="terminal"] .kami-switch-input:checked + .kami-switch-track .kami-switch-knob {
  transform: translateX(18px);
  background-color: var(--kami-accent);
}

/* —— 滑杆 —— */
html[data-kami-skin="terminal"] .kami-range {
  -webkit-appearance: none;
  appearance: none;
  width: 96px;
  height: 4px;
  border-radius: var(--kami-r-pill);
  background-color: var(--kami-t3);
  cursor: pointer;
}

html[data-kami-skin="terminal"] .kami-range::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 14px;
  height: 14px;
  border-radius: var(--kami-r-xs);
  background-color: var(--kami-accent);
  border: 2px solid var(--kami-bg);
  box-shadow: var(--kami-shadow-sm);
  cursor: pointer;
}

html[data-kami-skin="terminal"] .kami-range::-moz-range-thumb {
  width: 12px;
  height: 12px;
  border-radius: var(--kami-r-xs);
  background-color: var(--kami-accent);
  border: 2px solid var(--kami-bg);
  cursor: pointer;
}

/* —— 滚动区 —— */
html[data-kami-skin="terminal"] .kami-scroll {
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: var(--kami-line-strong) transparent;
}

html[data-kami-skin="terminal"] .kami-scroll::-webkit-scrollbar { width: 8px; height: 8px; }

html[data-kami-skin="terminal"] .kami-scroll::-webkit-scrollbar-track { background: transparent; }

html[data-kami-skin="terminal"] .kami-scroll::-webkit-scrollbar-thumb {
  background-color: var(--kami-line-strong);
  border-radius: var(--kami-r-xs);
}

/* —— 尺寸把手 —— */
html[data-kami-skin="terminal"] .kami-resize {
  position: absolute;
  right: 0;
  bottom: 0;
  width: 16px;
  height: 16px;
  cursor: nwse-resize;
  background-image: linear-gradient(135deg, transparent 46%, var(--kami-line-strong) 46%, var(--kami-line-strong) 54%, transparent 54%);
}

/* —— 皮肤预览缩略 —— */
html[data-kami-skin="terminal"] .kami-preview {
  position: relative;
  border-radius: var(--kami-r-md);
  border: var(--kami-border-w) solid var(--kami-line);
  background-color: var(--kami-card);
  padding: 8px;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

html[data-kami-skin="terminal"] .kami-preview i {
  display: block;
  height: 6px;
  border-radius: var(--kami-r-xs);
  background-color: var(--kami-t3);
}

html[data-kami-skin="terminal"] .kami-preview i:first-child {
  width: 58%;
  background-color: var(--kami-accent);
}

/* —— 贴底抽屉（脚本下发的 data-kami-layout="sheet"） —— */
html[data-kami-skin="terminal"] .kami-root .kami-drop.kami-drop[data-kami-layout="sheet"] {
  left: 0;
  right: 0;
  top: auto;
  bottom: 0;
  width: auto;
  height: 78%;
  max-height: 78%;
  border-radius: var(--kami-r-lg) var(--kami-r-lg) 0 0;
}

/* 兜底：面板脚本还没跑起来（元素上还没有 data-kami-layout）时按 768px 贴底 */
@media (max-width: 768px) {
  html[data-kami-skin="terminal"] .kami-root .kami-drop.kami-drop:not([data-kami-layout]) {
    left: 0;
    right: 0;
    top: auto;
    bottom: 0;
    width: auto;
    height: 78%;
    max-height: 78%;
    border-radius: var(--kami-r-lg) var(--kami-r-lg) 0 0;
  }
}

/* ==========================================================================
 * 14 · 特效实现
 * ======================================================================== */
/* 1. 双线外框（frame）：外框内侧 3px 再补一道 1px 细线。
      用 ::before 而不是 background 简写 —— .kami-shell 与 .kami-surface 常是同一个元素，
      写 background 会把 .kami-surface 上的纹理重置掉。 */
html[data-kami-skin="terminal"][data-kami-effects~="frame"] .kami-shell::before,
html[data-kami-skin="terminal"][data-kami-effects~="frame"] .kami-drop::before {
  content: "";
  position: absolute;
  inset: 3px;
  border: var(--kami-border-w) solid var(--kami-line);
  pointer-events: none;
}

/* 2. 方块光标（cursor）：硬切换闪烁，steps(1) 不做渐变 */
html[data-kami-skin="terminal"][data-kami-effects~="cursor"] .kami-dot[data-kami-on="1"],
html[data-kami-skin="terminal"][data-kami-effects~="cursor"] .kami-empty::after {
  animation: kami-term-blink var(--kami-term-blink) steps(1, end) infinite;
}

/* 3. 荧光辉光（glow）：只在小面积强调色上做，radius 走参数 */
html[data-kami-skin="terminal"][data-kami-effects~="glow"] .kami-title {
  text-shadow: 0 0 var(--kami-glow-size) var(--kami-glow);
}

html[data-kami-skin="terminal"][data-kami-effects~="glow"] .kami-btn--primary {
  box-shadow: 0 0 var(--kami-glow-size) var(--kami-glow);
}

html[data-kami-skin="terminal"][data-kami-effects~="glow"] .kami-root .kami-item.is-on,
html[data-kami-skin="terminal"][data-kami-effects~="glow"] .kami-root .kami-item[aria-pressed="true"],
html[data-kami-skin="terminal"][data-kami-effects~="glow"] .kami-root[data-kami-comp="panel"] .kami-card.is-on {
  box-shadow: inset 0 0 0 1px var(--kami-accent), 0 0 var(--kami-glow-size) var(--kami-glow);
}

html[data-kami-skin="terminal"][data-kami-effects~="glow"] .kami-md code {
  box-shadow: 0 0 var(--kami-glow-size) var(--kami-glow);
}

/* 4. 扫描横纹（scanline）：静态、不上动画；浓度走参数 */
html[data-kami-skin="terminal"][data-kami-effects~="scanline"] .kami-surface::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image: repeating-linear-gradient(
    180deg,
    rgba(127, 230, 166, calc(0.05 * var(--kami-term-scan) / 100)) 0 1px,
    transparent 1px 3px
  );
}

/* 循环动画在 calm / off 与 prefers-reduced-motion 下必须直接停（契约 §3.6） */
html[data-kami-skin="terminal"][data-kami-motion="calm"] .kami-dot[data-kami-on="1"],
html[data-kami-skin="terminal"][data-kami-motion="calm"] .kami-empty::after,
html[data-kami-skin="terminal"][data-kami-motion="off"] .kami-dot[data-kami-on="1"],
html[data-kami-skin="terminal"][data-kami-motion="off"] .kami-empty::after {
  animation: none !important;
}

/* ==========================================================================
 * 15 · 窄屏（320px 必须成立）
 * ======================================================================== */
@media (max-width: 560px) {
  html[data-kami-skin="terminal"] .kami-root[data-kami-comp="panel"] .kami-grid:has(> .kami-item, > .kami-item-note) {
    --kami-items-min: 152px;
  }
}

@media (max-width: 380px) {
  html[data-kami-skin="terminal"] .kami-root[data-kami-comp="panel"] .kami-grid:has(> .kami-item, > .kami-item-note) {
    --kami-items-min: 108px;
  }
  html[data-kami-skin="terminal"] .kami-root .kami-bar {
    flex-wrap: wrap;
  }
}


/* markdown：强调与插图（2026-09-24 补齐 —— 覆盖矩阵原本缺这两项） */
html[data-kami-skin="terminal"] .kami-md em { font-style: italic; color: var(--kami-accent); }
html[data-kami-skin="terminal"] .kami-md del { color: var(--kami-fg-mute); text-decoration-thickness: 1px; }
html[data-kami-skin="terminal"] .kami-md img {
  display: block;
  max-width: 100%;
  margin: .6em 0;
  border: var(--kami-border-w) solid var(--kami-line-strong);
  border-radius: var(--kami-r-xs);
}


/* 列表符号：显式声明，不依赖环境继承（酒馆楼层的列表样式可能被整链重置成 none，
   皮肤只给 ::marker 上色是不够的，符号必须自己声明、自己真的画出来）。
   无序：一级 disc / 二级 circle / 三级起 square；有序：decimal → lower-alpha → lower-roman */
html[data-kami-skin="terminal"] .kami-md ul { list-style-type: disc; }
html[data-kami-skin="terminal"] .kami-md ul ul { list-style-type: circle; }
html[data-kami-skin="terminal"] .kami-md ul ul ul { list-style-type: square; }
html[data-kami-skin="terminal"] .kami-md ol { list-style-type: decimal; }
html[data-kami-skin="terminal"] .kami-md ol ol { list-style-type: lower-alpha; }
html[data-kami-skin="terminal"] .kami-md ol ol ol { list-style-type: lower-roman; }
html[data-kami-skin="terminal"] .kami-md li::marker { color: var(--kami-accent); }
html[data-kami-skin="terminal"] .kami-md li li::marker { color: var(--kami-fg-mute); }

/* 特效页说明（.kami-field 里的那枚 .kami-sub）：375px 窄屏必须能换行读全。
   结构层的 .kami-sub 是 white-space:nowrap（标题栏计数确实要单行），
   这里只对「字段标签里的说明」这一处放开，不碰标题栏 / 页脚的。 */
html[data-kami-skin="terminal"] .kami-root[data-kami-comp="panel"] .kami-field .kami-field-label .kami-sub {
  white-space: normal;
  overflow: visible;
  text-overflow: clip;
  min-width: 0;
}

