"},{"id":"wod","name":"黑暗世界","button":"WOD","scheme":"dark","tagline":"一册封尘的血族密契：黑羊皮书脊、骨白衬线手记与暗红封蜡。","decor":["d10"],"effects":[{"id":"blood","label":"血契红光","desc":"状态点、主按钮与选中项透出深红封蜡光晕，选中卡泛起血契光泽。","default":true},{"id":"rose","label":"玫瑰花窗","desc":"外壳与卡片底层隐约透出哥特尖拱与玫瑰花窗的几何暗纹。","default":true},{"id":"mist","label":"夜雾流转","desc":"底板四周沉下一圈夜雾暗角，圣器般把面板托出页面。","default":true},{"id":"parchment","label":"羊皮纸痕","desc":"表面叠加褪色古籍的微细噪点与泛黄斑驳质感。","default":true},{"id":"candle","label":"烛影摇曳","desc":"状态点与标题描边带烛火般的明暗起伏，是循环动画。","default":true},{"id":"seal","label":"封蜡印痕","desc":"选中的卡片右下角盖下一枚深红封蜡血印并落章。","default":false}],"params":[{"id":"blood","label":"血光强度","group":"氛围","token":"--kami-wod-blood","unit":"","min":0,"max":100,"step":5,"value":60},{"id":"mist","label":"夜雾浓淡","group":"氛围","token":"--kami-wod-mist","unit":"","min":0,"max":100,"step":5,"value":45},{"id":"rose","label":"花窗明度","group":"纹样","token":"--kami-wod-rose","unit":"","min":0,"max":100,"step":5,"value":35},{"id":"aging","label":"做旧程度","group":"纸面","token":"--kami-wod-aging","unit":"","min":0,"max":100,"step":5,"value":50},{"id":"candle","label":"烛影起伏","group":"氛围","token":"--kami-wod-candle","unit":"","min":0,"max":100,"step":5,"value":55}],"css":"/* ============================================================================
 * 卡密预设 · 皮肤：黑暗世界（wod / World of Darkness）· 2026 重制版
 * ----------------------------------------------------------------------------
 * 概念：一册封存在隐秘结社禁忌图书馆深处的血族羊皮卷密契。
 *   · 材质律：黑羊皮书脊、做旧泛黄羊皮纸、哥特式尖拱与玫瑰花窗暗纹。
 *   · 配色律：暗夜黑曜底（#141019） × 骨白衬线字（#ece4d8） × 封蜡暗红血光（#c0263a）。
 *   · 符号律：封蜡血印、哥特尖拱、暗金骨线、中世纪手抄本花体与古典衬线体。
 *   · 排版律：系统衬线字体栈（不引外部字体）、15px 基准字号、1.66 行高、
 *     标题与正文两级拉开、字距 .02em —— 暗底白字不许糊成一片。
 *   · 纯 CSS：无 JS、无外部资源、无 @import、无 vh、无 position:fixed 铺满。
 *
 * 对比度（WCAG 2.1 实算，见 §1 注释）：
 *   暗档：正文 #ece4d8 / #141019 = 13.1:1 ｜ 次要 #c3b6a4 = 8.3:1 ｜ 最弱 #93857a = 5.2:1
 *   亮档：正文 #241a16 / #f2ead8 = 13.6:1 ｜ 次要 #5c4c42 = 7.2:1 ｜ 最弱 #7d6c60 = 4.9:1
 *   七个语义色在两档底色上做的是「色相 + 明度」双维度拉开（见 §6 注释）。
 * ========================================================================== */

/* ==========================================================================
 * 1 · 令牌（默认 = 暗夜古卷）
 * ======================================================================== */
html[data-kami-skin="wod"] .kami-root {
  /* —— 风格性文案令牌（契约 §3.7，只此三处） —— */
