  --kami-font-title: "Palatino Linotype", "Book Antiqua", Georgia, "Times New Roman", "Songti SC", "STSong", "SimSun", "宋体", "Noto Serif CJK SC", serif;
  --kami-font-mono: ui-monospace, SFMono-Regular, "Cascadia Mono", Menlo, Consolas, "Liberation Mono", monospace;
