  html[data-kami-skin="wod"] .kami-root[data-kami-comp="panel"] .kami-card .kami-card .kami-grid:has(> .kami-item, > .kami-item-note) {
    --kami-items-min: 150px;
  }
  html[data-kami-skin="wod"] .kami-root .kami-bar { flex-wrap: wrap; }
}
@media (max-width: 380px) {
  html[data-kami-skin="wod"] .kami-root {
    --kami-row-h: 44px;
    --kami-pad-lg-x: 12px;
    --kami-pad-lg-y: 11px;
  }
  html[data-kami-skin="wod"] .kami-root[data-kami-comp="panel"] .kami-grid:has(> .kami-item, > .kami-item-note) {
    --kami-items-min: 108px;
  }
  html[data-kami-skin="wod"] .kami-root[data-kami-comp="panel"] .kami-card .kami-card .kami-grid:has(> .kami-item, > .kami-item-note) {
    --kami-items-min: 108px;
  }
  html[data-kami-skin="wod"] .kami-root .kami-head { flex-wrap: wrap; }
  html[data-kami-skin="wod"] .kami-root .kami-bar { flex-wrap: wrap; }
  html[data-kami-skin="wod"] .kami-root .kami-actions { flex-wrap: wrap; justify-content: flex-end; }
}


/* 列表符号：显式声明，不依赖环境继承（酒馆楼层的列表样式可能被整链重置成 none，
   皮肤只给 ::marker 上色是不够的，符号必须自己声明、自己真的画出来）。
   无序：一级 disc / 二级 circle / 三级起 square；有序：decimal → lower-alpha → lower-roman */
html[data-kami-skin="wod"] .kami-md ul { list-style-type: disc; }
html[data-kami-skin="wod"] .kami-md ul ul { list-style-type: circle; }
html[data-kami-skin="wod"] .kami-md ul ul ul { list-style-type: square; }
