"},{"id":"xianyun","name":"闲云野鹤","button":"闲云","scheme":"light","tagline":"水墨留白与闲云仙鹤：素雅宣纸、层叠水墨晕染，点缀一抹古雅朱砂印。","effects":[{"id":"inkwash","label":"水墨晕染","desc":"卡片边缘与容器透出层叠晕开的淡墨微痕与水墨韵味。","default":true},{"id":"xuanzhi","label":"宣纸帘纹","desc":"纸面铺展细腻温润的生宣纸纤维与微光帘纹肌理。","default":true},{"id":"seal","label":"朱砂印章","desc":"关键标题与选中标记呈现古雅朱砂钤印与方印红框。","default":true},{"id":"mist","label":"云烟飘渺","desc":"外壳与浮层底部隐约透出道家闲云与淡雅云雾意象。","default":true}],"params":[{"id":"ink","label":"墨晕浓度","group":"水墨","token":"--kami-xy-ink","unit":"%","min":0,"max":100,"step":5,"value":50},{"id":"xuan","label":"宣纸质感","group":"材质","token":"--kami-xy-xuan","unit":"%","min":0,"max":100,"step":5,"value":40},{"id":"seal","label":"朱砂鲜明","group":"印章","token":"--kami-xy-seal","unit":"%","min":0,"max":100,"step":5,"value":70},{"id":"glow","label":"印光半径","group":"光效","token":"--kami-glow-size","unit":"px","min":0,"max":20,"step":1,"value":6}],"css":"/* ============================================================================
 * 卡密预设 · 皮肤：闲云野鹤（xianyun）
 * ----------------------------------------------------------------------------
 * 主题：水墨 + 修仙 —— 黑白为主 + 一点朱砂红，墨迹晕染、大片留白、书法字体。
 *
 * 设计语言四律：
 *   · 纸律（素宣留白）：以素雅生宣（#f7f5f0 / #fdfcf9）为底，大片留白，气韵生动。
 *   · 墨律（水墨晕染）：以沉稳浓墨（#1a1a1c）与淡墨焦墨为阶，层叠水墨晕染，干湿浓淡相宜。
 *   · 印律（朱砂钤印）：唯一身份符号为「朱砂方印」（#b82424），面积 ≤5%，点水墨之睛。
 *   · 书律（楷宋碑帖）：标题采用楷书/隶书书法栈，正文采用典雅宋体栈，纯本地字体零外链。
 *
 * 对比度：
 *   宣纸底（#f7f5f0）上的浓墨字（#1a1a1c）= 15.2:1 ｜ 卡片净白底上 = 16.6:1
 *   次要文字（#4a4a4d）= 8.4:1 ｜ 最弱文字（#76767b）= 4.5:1
 *   朱砂红底（#b82424）上的纯白字（#ffffff）= 5.6:1
 *   深墨线（rgba(28,28,30,0.45)）对宣纸底 = 3.3:1
 *   选中态具有「字重加粗 + 朱砂方印边线 + 纯白反字/淡印底色」多重可视差别，不只靠颜色。
 *
 * 纯 CSS 实现：零外部网络请求、无 JS、无 @import、无 @font-face、无 vh、无 position:fixed 铺满。
 * 契约规范：docs/皮肤契约.md（作用域前缀 / 令牌全集 / 风格性文案槽 / 对比度防线）。
 * ========================================================================== */

/* ==========================================================================
 * 1 · 令牌全集（默认亮色：素宣温润配浓墨朱砂）
 * ======================================================================== */
html[data-kami-skin="xianyun"] .kami-root {
  /* —— 风格性文案槽位（契约 §3.7） —— */
  --kami-label-think-title: 仙卷;
  --kami-label-think-title-open: 仙卷全览;
  --kami-label-options-title: 问道;

  /* —— 色彩：宣纸白 + 浓墨黑 + 朱砂红 —— */
  --kami-fg: #1a1a1c;            /* 主文字：沉稳浓墨黑，对纸白底 > 15:1 */
  --kami-fg-dim: #464649;        /* 次要文字：焦墨灰，对纸白底 > 8.4:1 */
  --kami-fg-mute: #737378;       /* 最弱文字：淡墨灰，对纸白底 >= 4.5:1 */
  --kami-accent: #b82424;        /* 强调色：纯正朱砂红，白字在其上 5.6:1 */
  --kami-accent-fg: #ffffff;     /* 强调底上的文字：纯白印文 */
  --kami-accent-soft: rgba(184, 36, 36, 0.09); /* 朱砂淡印晕 */
  --kami-accent-line: rgba(184, 36, 36, 0.65); /* 朱砂印章边线 */

  --kami-bg: #f7f5f0;            /* 容器背景：温润熟宣米白底 */
  --kami-bg-soft: #eeeae1;       /* 次级容器背景：浅灰宣纸底 */
  --kami-card: #ffffff;          /* 卡片背景：洁净宣纸白 */
  --kami-card-2: #f4f0e6;        /* 卡片内正文/引用块背景 */
  --kami-card-hover: #f0ebe0;    /* 卡片悬停：微润淡墨底（不透明色） */
  --kami-line: rgba(28, 28, 30, 0.14);          /* 常规分隔线：淡墨细线 */
  --kami-line-strong: rgba(28, 28, 30, 0.45);   /* 强调描边：焦墨实线 >= 3.2:1 */
  --kami-t1: rgba(28, 28, 30, 0.04);
  --kami-t2: rgba(28, 28, 30, 0.08);
  --kami-t3: rgba(28, 28, 30, 0.16);
  --kami-warn: #c23531;          /* 警示色：朱砂赤红 */
  --kami-shadow: 0 10px 30px -8px rgba(28, 28, 30, 0.16), 0 2px 8px rgba(28, 28, 30, 0.06);
  --kami-shadow-sm: 0 2px 8px -2px rgba(28, 28, 30, 0.10);
  --kami-blur: 0px;

  /* —— 布局与尺寸 —— */
  --kami-r-xs: 3px;
  --kami-r-sm: 5px;
  --kami-r-md: 8px;
  --kami-r-lg: 12px;
  --kami-r-pill: 999px;
  --kami-border-w: 1px;
  --kami-pad-x: 12px;
  --kami-pad-y: 8px;
  --kami-pad-lg-x: 16px;
  --kami-pad-lg-y: 14px;
  --kami-gap: 8px;
  --kami-gap-lg: 12px;
  --kami-row-h: 40px;            /* 控件行高移动端基准 >= 40px */
  --kami-icon: 15px;
  --kami-maxw: none;
  --kami-items-min: 15.5rem;
  --kami-panel-w: 430px;
  --kami-panel-h: 570px;
  --kami-list-dir: column;
  --kami-justify: stretch;

  /* —— 文本与排版（本地书法字体栈） —— */
  --kami-fs-scale: 1;
  --kami-fs: calc(15px * var(--kami-fs-scale));
  --kami-fs-xs: calc(var(--kami-fs) * .78);
  --kami-fs-sm: calc(var(--kami-fs) * .88);
  --kami-fs-lg: calc(var(--kami-fs) * 1.14);
  --kami-lh: 1.68;
  --kami-ls: .015em;
  --kami-ls-title: .06em;
  --kami-font: "Songti SC", "STSong", "宋体", "Noto Serif CJK SC", "Source Han Serif SC", serif;
  --kami-font-title: "KaiTi", "STKaiti", "楷体", "Kaiti SC", "KaiTi_GB2312", "LiSu", "隶书", "STSong", "宋体", "Songti SC", serif;
  --kami-font-mono: ui-monospace, SFMono-Regular, "Cascadia Mono", Consolas, "Liberation Mono", "Courier New", monospace;
  --kami-fw: 400;
  --kami-fw-title: 700;
  --kami-title-transform: none;

  /* —— 装饰与特效 —— */
  --kami-texture: radial-gradient(circle at 15% 18%, rgba(28, 28, 30, 0.035) 0%, transparent 65%),
                  radial-gradient(circle at 85% 82%, rgba(28, 28, 30, 0.025) 0%, transparent 60%);
  --kami-glow: rgba(184, 36, 36, 0.35);
  --kami-glow-size: 6px;
  --kami-surface-clip: none;
  --kami-accent-mark: 3px;

  /* —— 动效 —— */
  --kami-dur-fast: .12s;
  --kami-dur: .22s;
  --kami-dur-slow: .35s;
  --kami-ease: cubic-bezier(.22, .72, .3, 1);
  --kami-ease-out: cubic-bezier(.16, 1, .3, 1);
  --kami-enter-y: 4px;
  --kami-enter-scale: .98;
  --kami-stagger: 24ms;

  /* —— 语义色（国画水墨七色，对宣纸亮底对比度均 >= 4.8:1） —— */
  --kami-kind-action: #225577;   /* 行动 · 石青 */
  --kami-kind-persona: #8c2d52;  /* 性格 · 胭脂 */
  --kami-kind-plot: #286b45;     /* 推进 · 松柏 */
  --kami-kind-info: #246a78;     /* 信息 · 浅黛 */
  --kami-kind-fun: #915e12;      /* 搞笑 · 雄黄 */
  --kami-kind-nsfw: #b82424;     /* nsfw · 朱砂 */
  --kami-kind-other: #555861;    /* 其他 · 墨灰 */

  /* —— 皮肤私有参数默认值 —— */
  --kami-xy-ink: 50;
  --kami-xy-xuan: 40;
  --kami-xy-seal: 70;

  box-sizing: border-box;
  color: var(--kami-fg);
  font-family: var(--kami-font);
  font-size: var(--kami-fs);
  font-weight: var(--kami-fw);
  line-height: var(--kami-lh);
  letter-spacing: var(--kami-ls);
  font-variant-numeric: tabular-nums;
  text-align: left;
  text-rendering: optimizeLegibility;
  word-break: break-word;
  -webkit-tap-highlight-color: transparent;
}

/* ==========================================================================
 * 2 · 基础样式与重置
 * ======================================================================== */
html[data-kami-skin="xianyun"] .kami-root *,
html[data-kami-skin="xianyun"] .kami-root *::before,
html[data-kami-skin="xianyun"] .kami-root *::after {
  box-sizing: border-box;
}

html[data-kami-skin="xianyun"] .kami-root button,
html[data-kami-skin="xianyun"] .kami-root input,
html[data-kami-skin="xianyun"] .kami-root select,
html[data-kami-skin="xianyun"] .kami-root textarea {
  font: inherit;
  color: inherit;
  letter-spacing: inherit;
  margin: 0;
}

html[data-kami-skin="xianyun"] .kami-root button {
  -webkit-appearance: none;
  appearance: none;
}

html[data-kami-skin="xianyun"] .kami-root [hidden] {
  display: none !important;
}

html[data-kami-skin="xianyun"] .kami-root img {
  max-width: 100%;
}

html[data-kami-skin="xianyun"] .kami-root .kami-deco {
  display: none;
}

html[data-kami-skin="xianyun"] .kami-root .kami-d20::before,
html[data-kami-skin="xianyun"] .kami-root .kami-d20::after {
  content: none;
}

/* ==========================================================================
 * 3 · 档位响应：明暗 / 密度 / 动效
 * ======================================================================== */
/* 明暗方案：暗色（墨夜寒潭） */
html[data-kami-skin="xianyun"][data-kami-scheme="dark"] .kami-root {
  --kami-fg: #ede8df;            /* 宣白墨字 */
  --kami-fg-dim: #b5b0a7;        /* 淡墨白 */
  --kami-fg-mute: #858077;       /* 灰墨 */
  --kami-accent: #d94141;        /* 夜色朱砂红 */
  --kami-accent-fg: #14171a;     /* 暗底朱砂上的墨黑字 */
  --kami-accent-soft: rgba(217, 65, 65, 0.18);
  --kami-accent-line: rgba(217, 65, 65, 0.60);

  --kami-bg: #121417;            /* 深墨夜色底 */
  --kami-bg-soft: #191c21;       /* 次级暗墨底 */
  --kami-card: #1c1f24;          /* 砚台墨石卡面 */
  --kami-card-2: #15181c;        /* 内嵌深潭底 */
  --kami-card-hover: #262b33;    /* 卡片悬停底 */
  --kami-line: rgba(237, 232, 223, 0.14);
  --kami-line-strong: rgba(237, 232, 223, 0.40);
  --kami-t1: rgba(237, 232, 223, 0.05);
  --kami-t2: rgba(237, 232, 223, 0.09);
  --kami-t3: rgba(237, 232, 223, 0.18);
  --kami-warn: #ff6b6b;
  --kami-shadow: 0 10px 30px -8px rgba(0, 0, 0, 0.70), 0 2px 8px rgba(0, 0, 0, 0.45);
  --kami-shadow-sm: 0 2px 8px rgba(0, 0, 0, 0.35);

  --kami-texture: radial-gradient(circle at 15% 18%, rgba(237, 232, 223, 0.03) 0%, transparent 65%),
                  radial-gradient(circle at 85% 82%, rgba(237, 232, 223, 0.02) 0%, transparent 60%);

  --kami-kind-action: #5c9fd8;
  --kami-kind-persona: #e0689b;
  --kami-kind-plot: #48b885;
  --kami-kind-info: #4eb3cb;
  --kami-kind-fun: #db9a42;
  --kami-kind-nsfw: #e85555;
  --kami-kind-other: #9ea1a8;
}

/* 密度档位 */
html[data-kami-skin="xianyun"][data-kami-density="compact"] .kami-root {
  --kami-pad-x: 9px;
  --kami-pad-y: 5px;
  --kami-pad-lg-x: 12px;
  --kami-pad-lg-y: 10px;
  --kami-gap: 6px;
  --kami-gap-lg: 9px;
  --kami-row-h: 36px;
}

html[data-kami-skin="xianyun"][data-kami-density="roomy"] .kami-root {
  --kami-pad-x: 15px;
  --kami-pad-y: 10px;
  --kami-pad-lg-x: 20px;
  --kami-pad-lg-y: 18px;
  --kami-gap: 10px;
  --kami-gap-lg: 15px;
  --kami-row-h: 46px;
}

/* 动效档位 */
html[data-kami-skin="xianyun"][data-kami-motion="calm"] .kami-root {
  --kami-dur-fast: .08s;
  --kami-dur: .14s;
  --kami-dur-slow: .20s;
  --kami-enter-y: 1px;
  --kami-stagger: 10ms;
}

html[data-kami-skin="xianyun"][data-kami-motion="off"] .kami-root {
  --kami-dur-fast: 1ms;
  --kami-dur: 1ms;
  --kami-dur-slow: 1ms;
  --kami-enter-y: 0px;
  --kami-enter-scale: 1;
  --kami-stagger: 0ms;
}

@media (prefers-reduced-motion: reduce) {
  html[data-kami-skin="xianyun"] .kami-root {
    --kami-dur-fast: 1ms;
    --kami-dur: 1ms;
    --kami-dur-slow: 1ms;
    --kami-enter-y: 0px;
    --kami-enter-scale: 1;
    --kami-stagger: 0ms;
  }
}

/* ==========================================================================
 * 4 · 焦点与可访问性
 * ======================================================================== */
html[data-kami-skin="xianyun"] .kami-root :focus-visible {
  outline: 2px solid var(--kami-accent);
  outline-offset: 2px;
}

/* ==========================================================================
 * 5 · 控件对比度四件套（硬性三项 !important：阻击宿主与用户自定义深色 CSS 污染）
 * ======================================================================== */
html[data-kami-skin="xianyun"] .kami-root[data-kami-comp="panel"] .kami-number,
html[data-kami-skin="xianyun"] .kami-root[data-kami-comp="panel"] .kami-text,
html[data-kami-skin="xianyun"] .kami-root[data-kami-comp="panel"] .kami-textarea,
html[data-kami-skin="xianyun"] .kami-root[data-kami-comp="panel"] .kami-select {
  background-color: var(--kami-card) !important;
  color: var(--kami-fg) !important;
  color-scheme: light !important;
  border: var(--kami-border-w) solid var(--kami-line-strong);
  border-radius: var(--kami-r-sm);
  padding: 6px 10px;
  transition: border-color var(--kami-dur-fast) var(--kami-ease), box-shadow var(--kami-dur-fast) var(--kami-ease);
}

html[data-kami-skin="xianyun"] .kami-root[data-kami-comp="panel"] .kami-number:focus,
html[data-kami-skin="xianyun"] .kami-root[data-kami-comp="panel"] .kami-text:focus,
html[data-kami-skin="xianyun"] .kami-root[data-kami-comp="panel"] .kami-textarea:focus,
html[data-kami-skin="xianyun"] .kami-root[data-kami-comp="panel"] .kami-select:focus {
  border-color: var(--kami-accent);
  box-shadow: 0 0 0 2px var(--kami-accent-soft);
}

html[data-kami-skin="xianyun"] .kami-root[data-kami-comp="panel"] input.kami-number[type="number"] {
  text-align: right;
}

html[data-kami-skin="xianyun"][data-kami-scheme="dark"] .kami-root[data-kami-comp="panel"] .kami-number,
html[data-kami-skin="xianyun"][data-kami-scheme="dark"] .kami-root[data-kami-comp="panel"] .kami-text,
html[data-kami-skin="xianyun"][data-kami-scheme="dark"] .kami-root[data-kami-comp="panel"] .kami-textarea,
html[data-kami-skin="xianyun"][data-kami-scheme="dark"] .kami-root[data-kami-comp="panel"] .kami-select {
  color-scheme: dark !important;
}

/* 控件通用排版 */
html[data-kami-skin="xianyun"] input.kami-text,
html[data-kami-skin="xianyun"] textarea.kami-textarea,
html[data-kami-skin="xianyun"] select.kami-select {
  min-height: var(--kami-row-h);
  padding: var(--kami-pad-y) var(--kami-pad-x);
  text-align: left;
  border: var(--kami-border-w) solid var(--kami-line-strong);
  border-radius: var(--kami-r-sm);
  background-color: var(--kami-card);
  font-family: var(--kami-font);
  font-size: var(--kami-fs-sm);
  color: var(--kami-fg);
}

html[data-kami-skin="xianyun"] textarea.kami-textarea {
  resize: vertical;
}

/* 下拉选单自绘箭头 */
html[data-kami-skin="xianyun"] select.kami-select {
  -webkit-appearance: none;
  appearance: none;
  padding-right: calc(var(--kami-pad-x) + 18px);
  background-image:
    linear-gradient(45deg, transparent 50%, var(--kami-fg-mute) 50%),
    linear-gradient(135deg, var(--kami-fg-mute) 50%, transparent 50%);
  background-size: 4px 4px, 4px 4px;
  background-position: calc(100% - 14px) calc(50% + 1px), calc(100% - 10px) calc(50% + 1px);
  background-repeat: no-repeat;
  cursor: pointer;
}

/* 禁用与锁死状态（契约 §4.2 & 用户友好性） */
html[data-kami-skin="xianyun"] .kami-root .kami-btn[disabled],
html[data-kami-skin="xianyun"] .kami-root .kami-icon-btn[disabled] {
  opacity: .42;
  cursor: default;
  pointer-events: none;
  transform: none !important;
  box-shadow: none !important;
}

html[data-kami-skin="xianyun"] .kami-root[data-kami-comp="panel"] .kami-item[disabled],
html[data-kami-skin="xianyun"] .kami-root[data-kami-comp="panel"] .kami-item[disabled]:hover,
html[data-kami-skin="xianyun"] .kami-root[data-kami-comp="panel"] .kami-item[disabled]:active {
  background-color: var(--kami-card);
  background-image: none;
  border-color: var(--kami-line);
  box-shadow: none;
  transform: none;
  opacity: .42;
  color: var(--kami-fg-mute);
  cursor: default;
}

html[data-kami-skin="xianyun"] .kami-root[data-kami-comp="panel"] .kami-item[disabled]:hover::before,
html[data-kami-skin="xianyun"] .kami-root[data-kami-comp="panel"] .kami-item[disabled]:hover::after {
  transform: scale(0);
  opacity: 0;
}

html[data-kami-skin="xianyun"] .kami-root[data-kami-comp="panel"] .kami-item[disabled]:hover > .kami-badge {
  transform: none;
}

/* ==========================================================================
 * 6 · 结构与等高约束（契约 §4.2 硬规则）
 * ======================================================================== */
html[data-kami-skin="xianyun"] .kami-root .kami-item-note {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

html[data-kami-skin="xianyun"] .kami-root .kami-item-note > .kami-card {
  flex: 1 1 auto;
}

html[data-kami-skin="xianyun"] .kami-root .kami-pv,
html[data-kami-skin="xianyun"] .kami-root .kami-pv-frame,
html[data-kami-skin="xianyun"] .kami-root .kami-guide-pv,
html[data-kami-skin="xianyun"] .kami-root .kami-guide-pv-frame {
  pointer-events: none;
}

html[data-kami-skin="xianyun"] .kami-root .kami-d20 {
  pointer-events: auto;
}

html[data-kami-skin="xianyun"] .kami-d20-face {
  background: var(--kami-accent);
}

html[data-kami-skin="xianyun"] .kami-d20-face > i {
  background: var(--kami-bg);
  color: var(--kami-fg);
  font-family: var(--kami-font-title);
}

/* ==========================================================================
 * 7 · 外壳、宣纸面与通用头部
 * ======================================================================== */
html[data-kami-skin="xianyun"] .kami-shell {
  position: relative;
  display: block;
  background-color: var(--kami-bg);
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-lg);
  box-shadow: var(--kami-shadow);
  overflow: hidden;
  transition: border-color var(--kami-dur) var(--kami-ease), box-shadow var(--kami-dur) var(--kami-ease);
}

html[data-kami-skin="xianyun"] .kami-surface {
  background-image: var(--kami-texture);
}

html[data-kami-skin="xianyun"] .kami-head {
  position: relative;
  display: flex;
  align-items: center;
  gap: var(--kami-gap);
  min-height: var(--kami-row-h);
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
}

html[data-kami-skin="xianyun"] .kami-head:not(.kami-collapse-head) {
  border-bottom: var(--kami-border-w) solid var(--kami-line);
}

html[data-kami-skin="xianyun"] .kami-head[data-kami-drag] {
  cursor: move;
  user-select: none;
}

html[data-kami-skin="xianyun"] .kami-collapse-head {
  cursor: pointer;
  user-select: none;
}

html[data-kami-skin="xianyun"] .kami-title {
  font-family: var(--kami-font-title);
  font-weight: var(--kami-fw-title);
  font-size: var(--kami-fs);
  letter-spacing: var(--kami-ls-title);
  color: var(--kami-fg);
}

html[data-kami-skin="xianyun"] .kami-sub {
  font-size: var(--kami-fs-xs);
  color: var(--kami-fg-mute);
  margin-left: 4px;
}

html[data-kami-skin="xianyun"] .kami-actions {
  display: flex;
  align-items: center;
  gap: var(--kami-gap);
  margin-left: auto;
}

/* —— 状态点：朱砂古印小方印 —— */
html[data-kami-skin="xianyun"] .kami-dot {
  flex: none;
  width: 9px;
  height: 9px;
  border-radius: var(--kami-r-xs);
  background-color: var(--kami-fg-mute);
  opacity: .5;
  transition: all var(--kami-dur) var(--kami-ease);
}

html[data-kami-skin="xianyun"] .kami-dot[data-kami-on="1"] {
  background-color: var(--kami-accent);
  opacity: 1;
  box-shadow: 0 0 calc(var(--kami-glow-size) * .8) var(--kami-glow);
  transform: scale(1.15);
}

/* —— 折叠指示箭头 —— */
html[data-kami-skin="xianyun"] .kami-chev {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: var(--kami-fs-sm);
  color: var(--kami-accent);
  transition: transform var(--kami-dur) var(--kami-ease);
}

html[data-kami-skin="xianyun"] .kami-collapse[data-kami-open="1"] > .kami-head .kami-chev {
  transform: rotate(90deg);
}

/* —— 按钮系 —— */
