/* 面板内选中态：朱砂方印边线与印晕 */
html[data-kami-skin="xianyun"] .kami-root[data-kami-comp="panel"] .kami-card.is-on,
html[data-kami-skin="xianyun"] .kami-root[data-kami-comp="panel"] .kami-item.is-on,
