/* 分组卡内部网格的边距控制：避免内边距叠两层挤扁条目名 */
html[data-kami-skin="xianyun"] .kami-drop .kami-card:has(> .kami-card-body > .kami-grid) {
  padding-left: 12px;
  padding-right: 12px;
