  --kami-accent-line: rgba(184, 36, 36, 0.65);
  --kami-bg: #f7f5f0;
  --kami-bg-soft: #eeeae1;
  --kami-card: #ffffff;
  --kami-card-2: #f4f0e6;
  --kami-card-hover: #f0ebe0;
  --kami-line: rgba(28, 28, 30, 0.14);
  --kami-line-strong: rgba(28, 28, 30, 0.45);
  --kami-t1: rgba(28, 28, 30, 0.04);
