    slot.timer = setTimeout(function () { if (!r.dispatched) { r.ok = false; r.error = '6 秒内没看到保存请求'; finish(); } }, 6000);
    return r;
  }

  /* watchSave 压上的 fetch 补丁栈（后进先出收回）。
