              border-color var(--kami-dur-fast) var(--kami-ease),
              color var(--kami-dur-fast) var(--kami-ease),
              transform var(--kami-dur-fast) var(--kami-ease);
}
html:not([data-kami-skin]) .kami-icon-btn {
  min-width: var(--kami-row-h);
  padding: 0;
  font-size: var(--kami-icon);
}
html:not([data-kami-skin]) .kami-btn--ghost { background: transparent; }
html:not([data-kami-skin]) .kami-root .kami-btn--primary {
  background: var(--kami-accent);
  border-color: var(--kami-accent);
  color: var(--kami-accent-fg);
}
html:not([data-kami-skin]) .kami-btn.is-on {
  background: var(--kami-accent-soft);
  border-color: var(--kami-accent-line);
  color: var(--kami-fg);
}
@media (hover: hover) {
  html:not([data-kami-skin]) .kami-btn:hover,
  html:not([data-kami-skin]) .kami-icon-btn:hover { background: var(--kami-t2); border-color: var(--kami-line-strong); }
  html:not([data-kami-skin]) .kami-btn--primary:hover { filter: brightness(1.06); }
}
html:not([data-kami-skin]) .kami-btn:active,
html:not([data-kami-skin]) .kami-icon-btn:active { transform: translateY(1px); }
html:not([data-kami-skin]) .kami-btn[disabled],
html:not([data-kami-skin]) .kami-icon-btn[disabled] { opacity: .45; cursor: default; }

/* ---------- 分段切换 ---------- */
html:not([data-kami-skin]) .kami-seg {
  display: inline-flex;
  gap: 2px;
  padding: 2px;
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-sm);
  background: var(--kami-t1);
}
html:not([data-kami-skin]) .kami-seg-item {
  border: 0;
  border-radius: calc(var(--kami-r-sm) - 3px);
  background: transparent;
  color: var(--kami-fg-dim);
  font-size: var(--kami-fs-xs);
  letter-spacing: var(--kami-ls);
  padding: 5px 9px;
  cursor: pointer;
  transition: background var(--kami-dur-fast) var(--kami-ease), color var(--kami-dur-fast) var(--kami-ease);
}
html:not([data-kami-skin]) .kami-seg-item.is-on {
  background: var(--kami-accent-soft);
  color: var(--kami-fg);
  box-shadow: inset 0 0 0 1px var(--kami-accent-line);
}

/* ---------- 卡片 / 列表 / 徽章 ---------- */
html:not([data-kami-skin]) .kami-card {
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-md);
  background: var(--kami-card);
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
}
html:not([data-kami-skin]) .kami-card-head {
  display: flex;
  align-items: center;
  gap: var(--kami-gap);
  margin-bottom: 6px;
}
html:not([data-kami-skin]) .kami-card-title {
  font-weight: var(--kami-fw-title);
  font-size: var(--kami-fs-sm);
}
html:not([data-kami-skin]) .kami-card-note { font-size: var(--kami-fs-xs); color: var(--kami-fg-mute); }
html:not([data-kami-skin]) .kami-card-body { display: block; font-size: var(--kami-fs-sm); color: var(--kami-fg-dim); }

html:not([data-kami-skin]) .kami-list {
  display: flex;
  flex-direction: var(--kami-list-dir);
  justify-content: var(--kami-justify);
  gap: var(--kami-gap);
}
html:not([data-kami-skin]) .kami-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, var(--kami-items-min)), 1fr));
  gap: var(--kami-gap);
}
html:not([data-kami-skin]) .kami-item {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 4px;
  width: 100%;
  text-align: left;
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-md);
  background: var(--kami-card);
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
  cursor: pointer;
  transition: background var(--kami-dur) var(--kami-ease),
              border-color var(--kami-dur) var(--kami-ease),
              transform var(--kami-dur) var(--kami-ease);
}
@media (hover: hover) {
  html:not([data-kami-skin]) .kami-item:hover {
    background: var(--kami-card-hover);
    border-color: var(--kami-accent-line);
    transform: translateY(-1px);
  }
}
html:not([data-kami-skin]) .kami-item.is-demo { opacity: .62; cursor: default; }
html:not([data-kami-skin]) .kami-item-main { min-width: 0; }
html:not([data-kami-skin]) .kami-item-side { flex: none; margin-left: auto; color: var(--kami-fg-mute); font-size: var(--kami-fs-sm); }

html:not([data-kami-skin]) .kami-badge,
html:not([data-kami-skin]) .kami-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex: none;
  padding: 1px 7px;
  border-radius: var(--kami-r-pill);
  border: var(--kami-border-w) solid currentColor;
  font-size: var(--kami-fs-xs);
  line-height: 1.5;
  color: var(--kami-kind-other);
  white-space: nowrap;
}
html:not([data-kami-skin]) .kami-chip { border-color: var(--kami-line); color: var(--kami-fg-dim); background: var(--kami-t1); }
html:not([data-kami-skin]) .kami-root [data-kami-kind="action"]  { color: var(--kami-kind-action); }
html:not([data-kami-skin]) .kami-root [data-kami-kind="persona"] { color: var(--kami-kind-persona); }
html:not([data-kami-skin]) .kami-root [data-kami-kind="plot"]    { color: var(--kami-kind-plot); }
html:not([data-kami-skin]) .kami-root [data-kami-kind="info"]    { color: var(--kami-kind-info); }
html:not([data-kami-skin]) .kami-root [data-kami-kind="fun"]     { color: var(--kami-kind-fun); }
html:not([data-kami-skin]) .kami-root [data-kami-kind="nsfw"]    { color: var(--kami-kind-nsfw); }
html:not([data-kami-skin]) .kami-root [data-kami-kind="other"]   { color: var(--kami-kind-other); }

/* ---------- 折叠 ---------- */
html:not([data-kami-skin]) .kami-collapse-head { cursor: pointer; user-select: none; }
html:not([data-kami-skin]) .kami-chev {
  flex: none;
  font-size: calc(var(--kami-icon) * .8);
  color: var(--kami-fg-mute);
  transition: transform var(--kami-dur) var(--kami-ease), color var(--kami-dur) var(--kami-ease);
}
html:not([data-kami-skin]) .kami-collapse[data-kami-open="1"] > .kami-head .kami-chev { transform: rotate(90deg); color: var(--kami-accent); }
html:not([data-kami-skin]) .kami-collapse > .kami-body { display: none; }
html:not([data-kami-skin]) .kami-collapse[data-kami-open="1"] > .kami-body {
  display: block;
  animation: kami-base-in var(--kami-dur-slow) var(--kami-ease-out) backwards;
}
@keyframes kami-base-in {
  from { opacity: 0; transform: translateY(calc(var(--kami-enter-y) * -1)) scale(var(--kami-enter-scale)); }
  to { opacity: 1; transform: none; }
}

/* ============================================================
 * 30 · 消息楼层正文排版（全局层，契约 §9.8 第五类，2026-09-26）
 * ------------------------------------------------------------
 * 旧版（2026-09-25 ~ 09-26）这里是「正文美化包裹层」的结构规则：由 30-皮肤管理.js
 * 把 <content> 标签内的正文包进 div.kami-root[data-kami-comp="body"]，本节负责
 * 去掉 .kami-root 通用外边距、把 .kami-body 的内边距归零。
 * **那套已整体退役**（用户裁定：改成直接美化酒馆的消息楼层），包裹层不再产生，
 * 所以本节删除。新的消息楼层排版在 src/skin/tavern.css 的第 ⑤ 段（全局层，
 * 只读令牌，15 套皮肤自动跟随），兜底皮肤那份见下面 31 节。
 * ⚠️ 紧跟着的 .kami-md 规则（下方「正文 / markdown / 原文」一节）**不能删**：
 * 它同时在服务面板预览骨架（30-皮肤管理.js 的 previewSkeleton）与两个正则前端
 * （frontend-think.html 的 <div class="kami-md">，皮肤管理没跑时靠这份兜底）。
 * ============================================================ */

/* ---------- 正文 / markdown / 原文 ---------- */
html:not([data-kami-skin]) .kami-md {
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
  border-radius: var(--kami-r-md);
  background: var(--kami-card-2);
  border: var(--kami-border-w) solid var(--kami-line);
  font-size: var(--kami-fs-sm);
  color: var(--kami-fg-dim);
}
html:not([data-kami-skin]) .kami-md > :first-child { margin-top: 0; }
html:not([data-kami-skin]) .kami-md > :last-child { margin-bottom: 0; }
html:not([data-kami-skin]) .kami-md p { margin: .5em 0; }
html:not([data-kami-skin]) .kami-md h1,
html:not([data-kami-skin]) .kami-md h2,
html:not([data-kami-skin]) .kami-md h3 {
  margin: .9em 0 .4em;
  font-family: var(--kami-font-title);
  font-weight: var(--kami-fw-title);
  font-size: var(--kami-fs);
  color: var(--kami-fg);
}
html:not([data-kami-skin]) .kami-md code {
  font-family: var(--kami-font-mono);
  font-size: .88em;
  padding: 1px 5px;
  border-radius: var(--kami-r-xs);
  background: var(--kami-t2);
}
html:not([data-kami-skin]) .kami-md pre {
  margin: .6em 0;
  padding: var(--kami-pad-y) var(--kami-pad-x);
  border-radius: var(--kami-r-sm);
  background: var(--kami-card-2);
  border: var(--kami-border-w) solid var(--kami-line);
  overflow-x: auto;
}
html:not([data-kami-skin]) .kami-md pre code { background: none; padding: 0; }
html:not([data-kami-skin]) .kami-md blockquote {
  margin: .6em 0;
  padding: 2px 0 2px 10px;
  border-left: var(--kami-accent-mark) solid var(--kami-accent-line);
  color: var(--kami-fg-mute);
}
html:not([data-kami-skin]) .kami-md ul,
html:not([data-kami-skin]) .kami-md ol { margin: .5em 0; padding-left: 1.3em; }
html:not([data-kami-skin]) .kami-md li { margin: .18em 0; }
html:not([data-kami-skin]) .kami-md strong { color: var(--kami-fg); font-weight: 700; }
html:not([data-kami-skin]) .kami-md a { color: var(--kami-accent); text-underline-offset: 2px; }
html:not([data-kami-skin]) .kami-md hr { border: 0; border-top: var(--kami-border-w) solid var(--kami-line); margin: .8em 0; }
html:not([data-kami-skin]) .kami-md img { max-width: 100%; border-radius: var(--kami-r-sm); }
html:not([data-kami-skin]) .kami-md table { border-collapse: collapse; width: 100%; font-size: var(--kami-fs-xs); }
html:not([data-kami-skin]) .kami-md th,
html:not([data-kami-skin]) .kami-md td { border: var(--kami-border-w) solid var(--kami-line); padding: 4px 7px; }
html:not([data-kami-skin]) .kami-raw {
  margin: 0;
  padding: var(--kami-pad-lg-y) var(--kami-pad-lg-x);
  border-radius: var(--kami-r-md);
  background: var(--kami-card-2);
  border: var(--kami-border-w) solid var(--kami-line);
  font-family: var(--kami-font-mono);
  font-size: var(--kami-fs-xs);
  line-height: 1.6;
  color: var(--kami-fg-dim);
  white-space: pre-wrap;
  overflow-x: auto;
}

/* ---------- 表单控件 ---------- */
html:not([data-kami-skin]) .kami-field {
  display: flex;
  align-items: center;
  gap: var(--kami-gap);
  padding: var(--kami-pad-y) 0;
}
html:not([data-kami-skin]) .kami-field-label { flex: 1 1 auto; min-width: 0; font-size: var(--kami-fs-sm); }
html:not([data-kami-skin]) .kami-field-value { flex: none; display: flex; align-items: center; gap: 6px; }
/* 面板字段里的「说明」文字（特效页 / 参数说明）是整段长文，375px 窄屏必须能换行显示完整。
   基础 .kami-sub 规则是 nowrap —— 那是给标题栏计数、页脚提示、参数单位这类「单行短文本」用的；
   「字段标签下的说明」挤一行会被截断（真机报过：特效说明过长时手机只显示一行）。
   这里只放开 .kami-field-label 下的这一处：标题栏 / 页脚 / 参数单位的 .kami-sub 仍保持单行，不受影响。
   带说明时开关顶到左上与标签首行对齐（长文换行后不被坠到行中间）。 */
html:not([data-kami-skin]) .kami-root[data-kami-comp="panel"] .kami-field:has(.kami-sub) { align-items: flex-start; }
html:not([data-kami-skin]) .kami-root[data-kami-comp="panel"] .kami-field .kami-field-label .kami-sub {
  display: block;
  margin-top: 3px;
  line-height: 1.5;
  white-space: normal;
  overflow-wrap: anywhere;
}
html:not([data-kami-skin]) .kami-range {
  -webkit-appearance: none;
  appearance: none;
  width: 96px;
  height: 4px;
  border-radius: var(--kami-r-pill);
  background: var(--kami-t3);
  cursor: pointer;
}
html:not([data-kami-skin]) .kami-range::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 14px; height: 14px;
  border-radius: 50%;
  background: var(--kami-accent);
  border: 2px solid var(--kami-bg);
  box-shadow: var(--kami-shadow-sm);
}
html:not([data-kami-skin]) .kami-range::-moz-range-thumb {
  width: 12px; height: 12px; border: 2px solid var(--kami-bg);
  border-radius: 50%; background: var(--kami-accent);
}
html:not([data-kami-skin]) .kami-number {
  width: 62px;
  min-height: 28px;
  padding: 2px 6px;
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-xs);
  background: var(--kami-t1);
  font-family: var(--kami-font-mono);
  font-size: var(--kami-fs-xs);
  color: var(--kami-fg);
}
/* 右对齐只属于数字框。以前挂在裸 .kami-number 上，被复用它的 select / textarea /
   input[type=text] 一起吃了 —— 摘要提示词正文与角色下拉全部右对齐（用户真机报的 bug）。
   契约 §4.2 要求收窄成 input.kami-number[type="number"]。 */
html:not([data-kami-skin]) .kami-root input.kami-number[type="number"] { text-align: right; }

/* 面板里的输入类控件（兜底皮肤）：底色原本是 6% 的叠加，跟卡片底几乎分不出边界；
   换成次级容器底并抬一道描边，字仍然用正文色。四类控件（数字 / 文本 / 多行 / 下拉）
   共用这一条 —— 契约 §3 的对比度条款要求每套皮肤同时写这四类，兜底皮肤也不例外；
   六块面板的输入类控件都走它，不带面板 id（契约 §4.4）。
   底必须显式写、并且带 !important：酒馆「用户设置 → 自定义 CSS」里那条
    input[type="number"] { background-color: var(--ui-color-sec) !important } 会盖掉这里的底
   （真机实测），select / textarea / text 各有同款 !important 深漆。
   必须写 background-color 而不是 background 简写：简写会把下面 .kami-select 自绘箭头的
   background-image 一起重置掉。
   color-scheme 写 light dark：兜底令牌本来就分「默认＝暗」与
   prefers-color-scheme: light 两套，交给浏览器按用户偏好选，别写死。
   select.kami-number / textarea.kami-number 是 2026-09-21 分工收口前的旧写法，压缩面板
   还在用（60-压缩.js:1526 / 1541 / 1559）；等那批脚本迁到 .kami-select / .kami-textarea 再删。 */
html:not([data-kami-skin]) .kami-root[data-kami-comp="panel"] input.kami-number,
html:not([data-kami-skin]) .kami-root[data-kami-comp="panel"] select.kami-number,
html:not([data-kami-skin]) .kami-root[data-kami-comp="panel"] textarea.kami-number,
html:not([data-kami-skin]) .kami-root[data-kami-comp="panel"] input.kami-text,
html:not([data-kami-skin]) .kami-root[data-kami-comp="panel"] textarea.kami-textarea,
html:not([data-kami-skin]) .kami-root[data-kami-comp="panel"] select.kami-select {
  color: var(--kami-fg) !important;
  background-color: var(--kami-bg-soft) !important;
  border-color: var(--kami-line-strong) !important;
  color-scheme: light dark;
}

/* ---------- 文本 / 多行 / 下拉（契约 §4.2，2026-09-21 登记的三个类名） ----------
   这三类此前一条样式都没有（全项目只有压缩面板在用 <select>），真机上就是浏览器默认外观。
   底 --kami-bg-soft（半透明玻璃，能透出后面的内容）、描边 --kami-line、字 --kami-fg，
   一律左对齐；字数与控件同高，和 .kami-btn 对齐成一行。
   font-family 必须写：.kami-root 那条 font: inherit 只给了 button 与 input，
   textarea / select 吃不到，不写就掉回浏览器默认字体。 */
html:not([data-kami-skin]) .kami-root .kami-text,
html:not([data-kami-skin]) .kami-root .kami-textarea {
  min-height: var(--kami-row-h);
  padding: var(--kami-pad-y) var(--kami-pad-x);
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-xs);
  background-color: var(--kami-bg-soft);
  color: var(--kami-fg);
  font-family: var(--kami-font);
  font-size: var(--kami-fs-sm);
  text-align: left;
}
html:not([data-kami-skin]) .kami-root .kami-textarea { resize: vertical; }
/* 下拉：抹掉原生外观，用两层 linear-gradient 拼一个 V 形箭头（箭头色 --kami-fg-mute）。
   右侧内边距多留 16px 给箭头；底必须写 background-color —— 写 background 简写会把
   上面那两层 background-image 一起重置掉，箭头就没了（面板那条对比度规则同理）。 */
html:not([data-kami-skin]) .kami-root .kami-select {
  -webkit-appearance: none;
  appearance: none;
  min-height: var(--kami-row-h);
  padding: var(--kami-pad-y) calc(var(--kami-pad-x) + 16px) var(--kami-pad-y) var(--kami-pad-x);
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-xs);
  background-color: var(--kami-bg-soft);
  background-image:
    linear-gradient(45deg, transparent 50%, var(--kami-fg-mute) 50%),
    linear-gradient(135deg, var(--kami-fg-mute) 50%, transparent 50%);
  background-size: 4px 4px, 4px 4px;
  background-position: calc(100% - 13px) calc(50% + 1px), calc(100% - 9px) calc(50% + 1px);
  background-repeat: no-repeat;
  color: var(--kami-fg);
  font-family: var(--kami-font);
  font-size: var(--kami-fs-sm);
  text-align: left;
  cursor: pointer;
}
html:not([data-kami-skin]) .kami-switch { display: inline-flex; align-items: center; cursor: pointer; }
html:not([data-kami-skin]) .kami-switch-input { position: absolute; opacity: 0; width: 0; height: 0; }
html:not([data-kami-skin]) .kami-switch-track {
  position: relative;
  width: 38px; height: 22px;
  border-radius: var(--kami-r-pill);
  background: var(--kami-t3);
  transition: background var(--kami-dur) var(--kami-ease);
}
html:not([data-kami-skin]) .kami-switch-knob {
  position: absolute; top: 2px; left: 2px;
  width: 18px; height: 18px;
  border-radius: 50%;
  background: var(--kami-fg-dim);
  transition: transform var(--kami-dur) var(--kami-ease), background var(--kami-dur) var(--kami-ease);
}
html:not([data-kami-skin]) .kami-switch-input:checked + .kami-switch-track { background: var(--kami-accent-soft); box-shadow: inset 0 0 0 1px var(--kami-accent-line); }
html:not([data-kami-skin]) .kami-switch-input:checked + .kami-switch-track .kami-switch-knob { transform: translateX(16px); background: var(--kami-accent); }
html:not([data-kami-skin]) .kami-switch-input:focus-visible + .kami-switch-track { outline: 2px solid var(--kami-accent); outline-offset: 2px; }

/* ---------- 标签页 ---------- */
html:not([data-kami-skin]) .kami-tabs {
  display: flex;
  gap: 2px;
  padding: 0 var(--kami-pad-lg-x);
  border-bottom: var(--kami-border-w) solid var(--kami-line);
  overflow-x: auto;
  scrollbar-width: none;
}
html:not([data-kami-skin]) .kami-tabs::-webkit-scrollbar { display: none; }
/* tab 行放不下时（7 个 tab / 420px 面板、或手机抽屉）要**看得出来还能往右滑**：
   给滚动容器右缘一道 20px 的渐隐遮罩。遮罩挂在滚动容器自己的边框盒上，内容在它下面滚，
   被裁掉的那半个 tab 会淡出成「还有」的暗示；tab 行排得下时渐隐落在右侧内边距与底线上。
   兜底皮肤也要给：皮肤管理没在跑时，面板用的就是这一份。 */
html:not([data-kami-skin]) .kami-tabs {
  -webkit-mask-image: linear-gradient(90deg, #000 calc(100% - 20px), transparent 100%);
  mask-image: linear-gradient(90deg, #000 calc(100% - 20px), transparent 100%);
}
/* ② tab 行放不下时：只允许横向手势（脚本另外把纵向滚轮转成横向滚动）。
   这一条是「结构」不是外观：皮肤切换后也必须成立，所以放开皮肤前缀。 */
.kami-tabs { touch-action: pan-x; overscroll-behavior-x: contain; }
html:not([data-kami-skin]) .kami-tab {
  flex: none;
  border: 0;
  border-bottom: var(--kami-accent-mark) solid transparent;
  background: transparent;
  color: var(--kami-fg-mute);
  font-size: var(--kami-fs-sm);
  padding: 9px var(--kami-pad-x);
  cursor: pointer;
  transition: color var(--kami-dur-fast) var(--kami-ease), border-color var(--kami-dur-fast) var(--kami-ease);
}
html:not([data-kami-skin]) .kami-tab[aria-selected="true"] { color: var(--kami-fg); border-bottom-color: var(--kami-accent); }

/* ---------- 滚动区 / 浮动层 / 其它 ---------- */
html:not([data-kami-skin]) .kami-scroll {
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: var(--kami-t3) transparent;
}
html:not([data-kami-skin]) .kami-scroll::-webkit-scrollbar { width: 8px; height: 8px; }
html:not([data-kami-skin]) .kami-scroll::-webkit-scrollbar-thumb {
  background: var(--kami-t3);
  border-radius: var(--kami-r-pill);
  border: 2px solid transparent;
  background-clip: content-box;
}
/* 面板几何：舞台铺满视口，面板位置/尺寸来自脚本下发的几何令牌 */
html:not([data-kami-skin]) .kami-root[data-kami-comp="panel"] {
  position: fixed;
  inset: 0;
  top: 0; right: 0; bottom: 0; left: 0;
  width: auto; height: auto; min-height: 0;
  margin: 0;
  z-index: 30000;
  pointer-events: none;
}
html:not([data-kami-skin]) .kami-root .kami-drop.kami-drop {
  position: absolute;
  left: var(--kami-panel-x, 50%);
  top: var(--kami-panel-y, 72px);
  width: var(--kami-panel-w, min(420px, calc(100% - 24px)));
  height: var(--kami-panel-h, 560px);
  max-height: calc(100% - 24px);
  pointer-events: auto;
  background: var(--kami-bg-soft);
  border: var(--kami-border-w) solid var(--kami-line);
  border-radius: var(--kami-r-lg);
  box-shadow: var(--kami-shadow);
  overflow: hidden;
  display: flex;
  flex-direction: column;
}
/* 浮动面板也要毛玻璃：底是半透明的 --kami-bg-soft（不写死不透明色），
   模糊由下面的 @supports 给，写法与 .kami-shell 那条一致（含 -webkit- 前缀那一条）。 */
@supports ((backdrop-filter: blur(2px)) or (-webkit-backdrop-filter: blur(2px))) {
  html:not([data-kami-skin]) .kami-root .kami-drop.kami-drop {
    -webkit-backdrop-filter: blur(var(--kami-blur));
    backdrop-filter: blur(var(--kami-blur));
  }
}
/* 毛玻璃的通用做法：1px 高光上边缘，光从上面打下来的错觉。只能引令牌，所以「高光」
   用 --kami-line-strong —— 它比其余三条的 --kami-line 实一档（暗档 34% 对 12% 的白，
   亮档 52% 对 12% 的黑），不能写死 rgba(255,255,255,.3) 那类颜色。
   写在 .kami-drop 基础规则之后：两条特异性都是 (0,4,1)，靠顺序取胜。 */
html:not([data-kami-skin]) .kami-root .kami-shell,
html:not([data-kami-skin]) .kami-root .kami-drop.kami-drop {
  border-top-color: var(--kami-line-strong);
}
html:not([data-kami-skin]) .kami-drop > .kami-body { flex: 1 1 auto; min-height: 0; }
/* 面板是 flex 列：头部 / 标签轨 / 底部不得被长内容压扁（窄屏抽屉下尤其明显） */
html:not([data-kami-skin]) .kami-drop > .kami-head,
html:not([data-kami-skin]) .kami-drop > .kami-tabs,
html:not([data-kami-skin]) .kami-drop > .kami-foot { flex: 0 0 auto; }
/* 贴底抽屉：由脚本下发的 data-kami-layout="sheet" 决定（皮肤管理没在跑时，面板脚本自己下发，
   见 40-预设设置.js 的 sheetMode；皮肤管理在跑时由它注入的几何层负责）。
   注意选择器必须把特异性抬到上面那条 `.kami-root .kami-drop.kami-drop`（0,4,1）之上：
   下面这条规则原来写成 `html:not([data-kami-skin]) .kami-drop`（0,2,1），**被上面那条整体压掉**，
   于是「皮肤管理没运行 + 窄屏」时面板会按 50%/420px 摆成一个挂在视口外的小窗
   （关闭按钮直接被裁掉，点不到）。这里补一个 [data-kami-layout="sheet"] 版本，特异性 (0,5,1)。 */
html:not([data-kami-skin]) .kami-root .kami-drop.kami-drop[data-kami-layout="sheet"] {
  left: 0; right: 0; top: auto; bottom: 0;
  width: auto; height: 78%; max-height: 78%;
  border-radius: var(--kami-r-lg) var(--kami-r-lg) 0 0;
}
/* 兜底：面板脚本还没跑起来（元素上还没有 data-kami-layout）时按 768px 贴底 */
@media (max-width: 768px) {
  html:not([data-kami-skin]) .kami-root .kami-drop.kami-drop:not([data-kami-layout]) {
    left: 0; right: 0; top: auto; bottom: 0;
    width: auto; height: 78%; max-height: 78%;
    border-radius: var(--kami-r-lg) var(--kami-r-lg) 0 0;
  }
}
html:not([data-kami-skin]) .kami-resize {
  position: absolute;
  right: 0; bottom: 0;
  width: 16px; height: 16px;
  cursor: nwse-resize;
  background: linear-gradient(135deg, transparent 46%, var(--kami-line-strong) 46%, var(--kami-line-strong) 54%, transparent 54%);
}
html:not([data-kami-skin]) .kami-empty { padding: var(--kami-pad-lg-y) 0; color: var(--kami-fg-mute); font-size: var(--kami-fs-sm); }
html:not([data-kami-skin]) .kami-toast {
  margin-top: var(--kami-gap);
  padding: var(--kami-pad-y) var(--kami-pad-x);
  border-radius: var(--kami-r-sm);
  border: var(--kami-border-w) solid var(--kami-line);
  background: var(--kami-t2);
  font-size: var(--kami-fs-xs);
  color: var(--kami-fg-dim);
  animation: kami-base-in var(--kami-dur) var(--kami-ease-out) backwards;
}
html:not([data-kami-skin]) .kami-toast.is-bad { color: var(--kami-warn); border-color: currentColor; }
html:not([data-kami-skin]) .kami-preview {
  position: relative;
  border-radius: var(--kami-r-md);
  border: var(--kami-border-w) solid var(--kami-line);
  background: var(--kami-card);
  padding: 8px;
  display: flex;
  flex-direction: column;
  gap: 5px;
}
html:not([data-kami-skin]) .kami-preview i {
  display: block;
  height: 6px;
  border-radius: var(--kami-r-pill);
  background: var(--kami-t3);
}
html:not([data-kami-skin]) .kami-preview i:first-child { width: 58%; background: var(--kami-accent); }

/* ---------- 动效降级 ---------- */
@media (prefers-reduced-motion: reduce) {
  html:not([data-kami-skin]) .kami-root *,
  html:not([data-kami-skin]) .kami-root *::before,
  html:not([data-kami-skin]) .kami-root *::after {
    animation-duration: 1ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 1ms !important;
  }
}
html:not([data-kami-skin]) .kami-root[data-kami-motion="off"] *,
html:not([data-kami-skin]) .kami-root[data-kami-motion="off"] *::before,
html:not([data-kami-skin]) .kami-root[data-kami-motion="off"] *::after {
  animation-duration: 1ms !important;
  transition-duration: 1ms !important;
}

/* ============================================================
 * 设置面板里的条目网格：紧凑多列（兜底皮肤）
 * ------------------------------------------------------------
 * 兜底皮肤的 --kami-items-min 是 240px（按 820px 宽的消息区调的），在设置面板里
 * 永远只排得下 1 列 —— 面板里的网格只有 350px 宽。面板作用域内压到 96px：
 * 390px 宽的底部抽屉正好 3 列，桌面 420px 面板 3~4 列。
 *
 * 三重限定，缺一不可：
 *   · html:not([data-kami-skin]) 是兜底皮肤的作用域前缀；
 *   · [data-kami-comp="panel"] 是面板限定：消息 iframe 里只有 think 与 options
 *     两种组件，没有 panel。带上它，紧凑化就绝不会渗进聊天前端
 *     （两个正则前端内联的就是本文件）；
 *  · **不再用面板 id 限定**（契约 §4.4）：组件规则对所有面板生效，以后加面板零维护。
 *     它那张网格装的是带预览 iframe 的大卡，不能一起压。
 * ============================================================ */
html:not([data-kami-skin]) .kami-root[data-kami-comp="panel"]#kami-preset-panel {
  --kami-items-min: 96px;
}

/* 窄屏（手机底部抽屉）下的列宽：96px 会让 375px 的抽屉排出 3 列、卡只有 ~110px，
   「DS/GLM底部破限」这种名字被拦腰断成 DS/GLM 断行。窄屏把列宽调大，宁可两列：
   375px 抽屉 → 2 列（卡 ~166px），320px → 2 列（卡 ~110px）。
   只改令牌，不动脚本结构；桌面 420px 面板不受影响（视口 > 560px 时照旧 3~4 列）。 */
@media (max-width: 560px) {
  html:not([data-kami-skin]) .kami-root[data-kami-comp="panel"]#kami-preset-panel {
    --kami-items-min: 152px;
  }
}
@media (max-width: 380px) {
  html:not([data-kami-skin]) .kami-root[data-kami-comp="panel"]#kami-preset-panel {
    --kami-items-min: 108px;
  }
}


/* ============================================================
 * 面板内的「条目名角标」：emoji 从条目名里摘出来钉在卡片角上（兜底皮肤）
 * ------------------------------------------------------------
 * 为什么：条目名绝大多数是四个汉字，前面那枚 emoji + 空格会把 110px 的紧凑小卡顶成两行。
 * 把 emoji 绝对定位到卡片角上，文字那一行就**整行**腾出来了；卡片高度不因此变高。
 * 脚本只摘**显示**，预设里条目名的一个字都没动（40-预设设置.js 的 splitLeadingEmoji）。
 *
 * 三重限定，缺一不可（与上面那节同一套理由）：
 *   · html:not([data-kami-skin]) 是兜底皮肤的作用域前缀；
 *   · [data-kami-comp="panel"] 是面板限定：消息 iframe 里只有 think / options，没有 panel；
 *  · **不再用面板 id 限定**（契约 §4.4）：组件规则对所有面板生效，以后加面板零维护。
 *     装的是带预览 iframe 的大卡，不能一起改。
 *
 * 类名只用契约 §4.2 已登记的 .kami-badge（小标签），左右上角靠 data-kami-corner 区分，
 * 不新增类名；颜色/字号全部取本文件已有令牌，没有新颜色。
 * ============================================================ */
html:not([data-kami-skin]) .kami-root[data-kami-comp="panel"] .kami-item.kami-card {
  position: relative;   /* 角标的定位基准 */
}
html:not([data-kami-skin]) .kami-root[data-kami-comp="panel"] .kami-item > .kami-badge {
  position: absolute;
  top: 1px;
  right: 3px;
  left: auto;
  z-index: 2;
  padding: 0;
  border: 0;
  background: none;
  font-size: var(--kami-fs-xs);
  line-height: 1.2;
  color: var(--kami-fg-mute);
  pointer-events: none;
}
html:not([data-kami-skin]) .kami-root[data-kami-comp="panel"] .kami-item > .kami-badge[data-kami-corner="tl"],
html:not([data-kami-skin]) .kami-root[data-kami-comp="panel"] .kami-item > .kami-badge[data-kami-corner="bl"] {
  right: auto;
  left: 3px;
}
html:not([data-kami-skin]) .kami-root[data-kami-comp="panel"] .kami-item > .kami-badge[data-kami-corner="br"],
html:not([data-kami-skin]) .kami-root[data-kami-comp="panel"] .kami-item > .kami-badge[data-kami-corner="bl"] {
  top: auto;
  bottom: 1px;
}
/* 角标**不占宽度**：文字始终拿整张卡的宽度；只在上下方向让出角标的高度。
   有上角标（tl/tr）就加上边距，有下角标（bl/br）就加下边距 —— 卡片会略高一点点，
   但文字那一行永远是整宽的（用户裁定：角标可以占高度，不能占宽度）。 */
html:not([data-kami-skin]) .kami-root[data-kami-comp="panel"] .kami-item:has(> .kami-badge[data-kami-corner="tl"], > .kami-badge[data-kami-corner="tr"], > .kami-card-note[data-kami-corner="tr"]) {
  padding-top: calc(var(--kami-pad-lg-y) + 0.4em);
}
html:not([data-kami-skin]) .kami-root[data-kami-comp="panel"] .kami-item:has(> .kami-badge[data-kami-corner="bl"], > .kami-badge[data-kami-corner="br"]) {
  padding-bottom: calc(var(--kami-pad-lg-y) + 0.4em);
}

/* ============================================================
 * 24 · 非当前模型的模型专属条目：锁死
 * ------------------------------------------------------------
 * 面板「🤖 模型」tab 里，不属于「当前模型」的模型专属条目一律禁用（脚本写 HTML 原生的
 * disabled，条目卡本来就是 button）。外观也要给出「锁死」的样子：变暗 + 去掉悬停反馈
 * + 鼠标禁止符号。颜色只用本文件已有的「最弱文字色」令牌 --kami-fg-mute，不引入新颜色。
 *
 * 三重限定，缺一不可（理由同上面 22 节）：
 *   · html:not([data-kami-skin]) —— 兜底皮肤（无皮肤时生效） 的作用域前缀；
 *   · [data-kami-comp="panel"]    —— 消息 iframe 里只有 think / options，没有 panel；
 *  · **不再用面板 id 限定**（契约 §4.4）：组件规则对所有面板生效，以后加面板零维护。
 * ============================================================ */
html:not([data-kami-skin]) .kami-root[data-kami-comp="panel"] .kami-item[disabled],
html:not([data-kami-skin]) .kami-root[data-kami-comp="panel"] .kami-item[disabled]:hover,
html:not([data-kami-skin]) .kami-root[data-kami-comp="panel"] .kami-item[disabled]:active {
  background-color: var(--kami-card);
  background-image: none;
  border-color: var(--kami-line);
  box-shadow: none;
  transform: none;
  opacity: .42;
  color: var(--kami-fg-mute);
  cursor: not-allowed;
}
/* 悬停才会冒出来的装饰（角标转正 / 左缘竖条 / 湿痕横线）在锁死时一律不许动 */
html:not([data-kami-skin]) .kami-root[data-kami-comp="panel"] .kami-item[disabled]:hover::before,
html:not([data-kami-skin]) .kami-root[data-kami-comp="panel"] .kami-item[disabled]:hover::after {
  transform: scale(0);
  opacity: 0;
}
html:not([data-kami-skin]) .kami-root[data-kami-comp="panel"] .kami-item[disabled]:hover > .kami-badge { transform: none; }

/* ============================================================
 * 26 · 面板里的「注释查看」与「设置变量」
 * ------------------------------------------------------------
 * 用户裁定：注释入口**不是角标**，就挂在名字后面（条目卡挂在条目名后面，
 * 卡片头挂在卡片名后面），占一格宽度、带高亮，让人一眼看出可以点；
 * 点它就地展开注释正文（.kami-card-note[data-kami-note]），再点收起。
 * **没有注释的条目/卡片一枚记号都不加**（不显示灰色不可点，免得用户困惑）。
 *
 * 三重限定，缺一不可（理由同 22 节）：
 *   · 皮肤作用域前缀（本套皮肤 / 兜底皮肤）；
 *   · [data-kami-comp="panel"] —— 消息 iframe 里只有 think / options，没有 panel；
 *   · **不得再用面板 id 限定**（契约 §4.4 硬规则）—— 面板不止 #kami-preset-panel 一块，
 *     引导面板 #kami-guide-panel 的 ⓘ 用的是同一套 DOM，加了 id 就会漏。
 * 类名只用契约 §4.2 已登记的 .kami-card-note / .kami-number，不新增类名；
 * 标记与正文靠 data-kami-note-mark / data-kami-note 两个属性区分。
 * ============================================================ */
/* 兜底皮肤：注释标记 + 展开出来的注释正文 */
html:not([data-kami-skin]) .kami-root[data-kami-comp="panel"] .kami-card-note[data-kami-note-mark] {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.4em;
  height: 1.4em;
  margin-left: 5px;
  border: var(--kami-border-w) solid var(--kami-accent);
  border-radius: var(--kami-r-pill);
  background: var(--kami-accent-soft);
  color: var(--kami-fg);
  font-size: var(--kami-fs-xs);
  line-height: 1;
  cursor: pointer;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}
html:not([data-kami-skin]) .kami-root[data-kami-comp="panel"] .kami-card-note[data-kami-note-mark]:hover,
html:not([data-kami-skin]) .kami-root[data-kami-comp="panel"] .kami-card-note[data-kami-note-mark]:focus-visible {
  background: var(--kami-accent);
  color: var(--kami-bg);
  border-color: var(--kami-accent);
}
html:not([data-kami-skin]) .kami-root[data-kami-comp="panel"] .kami-card-note[data-kami-note] {
  display: block;
  margin: 5px 0 0;
  padding: 5px 7px;
  border-left: var(--kami-accent-mark) solid var(--kami-accent);
  border-radius: var(--kami-r-xs);
  background: var(--kami-t2);
  color: var(--kami-fg-dim);
  font-size: var(--kami-fs-xs);
  line-height: 1.55;
  white-space: pre-wrap;
  word-break: break-word;
  text-align: left;
}
html:not([data-kami-skin]) .kami-root[data-kami-comp="panel"] .kami-card-note[data-kami-note][hidden] { display: none; }

/* ============================================================
 * · 面板里的控件边界：描边抬到「看得见」那一档
 * ------------------------------------------------------------
 * 面板里的条目卡底与外面那层卡片底是同一个色，唯一的边界就是那 1px 描边；
 * 原来的 --kami-line 实测只有 1.3~1.6:1，卡片会连成一片、看不出是一张一张的按钮。
 * 面板内的控件描边统一提到 --kami-line-strong（同一个色，只是更实），卡片边界实测 >= 3:1。
 * 只用本皮肤已有令牌，没有新颜色；不开 --kami-line 本身：聊天前端的细线该细还是细。
 * 不带面板 id（契约 §4.4）：三块面板与以后的新面板共用这一条。
 * ============================================================ */
html:not([data-kami-skin]) .kami-root[data-kami-comp="panel"] .kami-item:not(.is-on):not([aria-pressed="true"]),
html:not([data-kami-skin]) .kami-root[data-kami-comp="panel"] .kami-card:not(.kami-item),
html:not([data-kami-skin]) .kami-root[data-kami-comp="panel"] .kami-btn:not(.is-on):not(.kami-btn--primary) {
  border-color: var(--kami-line-strong);
}

/* ============================================================
 * · 兜底皮肤的面板条目卡「开着」高亮（原来缺这一条）
 * ------------------------------------------------------------
 * 没有皮肤管理脚本时，所有面板（皮肤管理 / 预设设置 / 引导 / 压缩）都用这一份兜底皮肤。
 * 原来只有 .kami-btn.is-on，条目卡开着与关着长得一模一样 —— 补上：
 * 强调色描边 + 淡染强调底色 + 名字回到正文色，与 .kami-btn.is-on 同一套令牌。
 * 不带面板 id（契约 §4.4）：以后加面板零维护。
 * ============================================================ */
html:not([data-kami-skin]) .kami-root[data-kami-comp="panel"] .kami-item.is-on,
html:not([data-kami-skin]) .kami-root[data-kami-comp="panel"] .kami-item[aria-pressed="true"] {
  border-color: var(--kami-accent-line);
  background: var(--kami-accent-soft);
  color: var(--kami-fg);
}
html:not([data-kami-skin]) .kami-root[data-kami-comp="panel"] .kami-item.is-on .kami-item-main,
html:not([data-kami-skin]) .kami-root[data-kami-comp="panel"] .kami-item[aria-pressed="true"] .kami-item-main {
  color: var(--kami-fg);
}

/* ============================================================
 * 注释标记 ⓘ 做成右上角角标 + 注释外包层的等高拉伸（2026-09-21 用户裁定）
 * ------------------------------------------------------------
 * 1) 条目卡里的 ⓘ 现在是**右上角角标**：构建器给它 data-kami-corner="tr"
 *    （契约 §4.4 已登记的角标机制，与 emoji 角标同一套定位）。它不再占名字那一行的
 *    宽度 —— 行内记号会把约 100px 宽的条目卡里的名字挤到换行，同一行卡片因此被撑高。
 *    卡片头里的 ⓘ（卡片组标题、变量卡）没有这个属性，仍是行内记号，不受影响。
 *    角标位置与本皮肤 emoji 角标同值；pointer-events 必须是 auto（emoji 角标是 none，
 *    ⓘ 要能点）。上角标的内边距补偿在上面的 .kami-item:has(...) 里一起算了。
 * 2) .kami-item-note 是网格项、会被同行最高的卡拉伸；里面的卡片不跟着伸的话，
 *    带注释的卡就比同行其它卡矮一截（网格 stretch 只拉外包层，不拉它的子元素）。
 *    flex:1 1 auto 让卡片撑满外包层；注释展开时外包层被内容撑高，卡片照旧拿自然高度。
 * ============================================================ */
html:not([data-kami-skin]) .kami-root[data-kami-comp="panel"] .kami-item > .kami-card-note[data-kami-note-mark][data-kami-corner] {
  position: absolute;
  top: 1px;
  right: 3px;
  left: auto;
  z-index: 2;
  margin-left: 0;
  pointer-events: auto;
}
html:not([data-kami-skin]) .kami-root .kami-item-note {
  display: flex;
  flex-direction: column;
  min-width: 0;
}
html:not([data-kami-skin]) .kami-root .kami-item-note > .kami-card {
  flex: 1 1 auto;
}
";

  /* ── 预设结构解析器（规则真相：test/harness/preset-parse.mjs，构建期内联） ── */
  // preset-parse.mjs —— 「卡密预设」结构解析器（纯函数版）
//
// 设计约束（本工作区约定）：
//   1) 不使用正则表达式，一律 indexOf / startsWith / endsWith / 按行切分
//   2) 脚本内不出现反斜杠字面量与美元号字面量（换行用 String.fromCharCode(10)）
//   3) 本文件零 import，可直接被浏览器面板脚本复用
//
// 输入：迁移后的预设对象（内存态）
// 输出：结构树（tab -> 卡片 -> 条目）
//
// 编号约定（别混）：
//   - 本文件注释里的 1) 2) 3) … 是**代码步骤**编号
//   - 报告（design/proposals/预设结构解析表.md）里的「规则 N」是**需求规则**编号
//   - 步骤 6.5 实现的是**规则 15**（模型专属卡片降级，规则 4 的补充）
//     规则 15 的实际适用条件是**收窄过的**：一张卡片必须是它所在层级里**唯一的卡片**
//     （层级的卡片列表里只有它一张），且名下条目全是模型专属条目，才降级。
//     收窄的理由：原版（不看"唯一卡片"）会把 `🧠 推理选项` 里的 `🤔 [推理格式]` 也判掉，
//     用户实测后指出那是误伤（[推理格式] 本来就该是卡片层级）。收窄后
//     `🪓 神秘咒语`（层级里只有 `🤖 [模型类型]` 一张卡片）照旧不出 tab，
//     `🧠 推理选项`（5 张卡片）里的 `🤔 [推理格式]` 恢复成正常卡片。

const ARROW_OPEN = String.fromCodePoint(0x1f53b); // 🔻
const ARROW_CLOSE = String.fromCodePoint(0x1f53a); // 🔺
const NL = String.fromCharCode(10);
const VAR_SUFFIX = ' | var';
const MODEL_SUFFIX = ' | model';
const CARD_ONCE = ' 选一';
const CARD_ANY = ' 任选';
const FULL_COLON = '：';

// ---------- 基础工具（无正则） ----------

function countOccurrences(text, sub) {
  if (typeof text !== 'string' || typeof sub !== 'string' || sub.length === 0) return 0;
  let count = 0;
  let i = 0;
  for (;;) {
    i = text.indexOf(sub, i);
    if (i < 0) return count;
    count++;
    i += sub.length;
  }
}

function isPureDigits(text) {
  if (typeof text !== 'string' || text.length === 0) return false;
  for (let i = 0; i < text.length; i++) {
    const c = text.charCodeAt(i);
    if (c < 48 || c > 57) return false;
  }
  return true;
}

// 去掉首尾的 🔻 / 🔺，再 trim。用于包裹区与层级的内名比对。
// 注意：🔻/🔺 是代理对（2 个 UTF-16 码元），必须按 2 个码元切，不能用 slice(1)。
function stripArrowEnds(text) {
  let s = String(text);
  let changed = true;
  while (changed) {
    changed = false;
    while (s.startsWith(ARROW_OPEN) || s.startsWith(ARROW_CLOSE)) {
      s = s.slice(2);
      changed = true;
    }
    while (s.endsWith(ARROW_OPEN) || s.endsWith(ARROW_CLOSE)) {
      s = s.slice(0, s.length - 2);
      changed = true;
    }
  }
  return s.trim();
}

// 第一个 {{// ... }} 的内部文本（去掉包裹符），没有则为 null
function firstComment(content) {
  if (typeof content !== 'string') return null;
  const start = content.indexOf('{{//');
  if (start < 0) return null;
  const end = content.indexOf('}}', start);
  if (end < 0) return null;
  return content.slice(start + 4, end);
}

// 抽 content 里所有 setvar::名字::值 片段
function parseSetvars(content) {
  const out = [];
  if (typeof content !== 'string') return out;
  let i = 0;
  for (;;) {
    i = content.indexOf('setvar::', i);
    if (i < 0) return out;
    const rest = content.slice(i + 8);
    let end = rest.indexOf('}}');
    if (end < 0) end = rest.length;
    const body = rest.slice(0, end);
    const sep = body.indexOf('::');
    if (sep >= 0) {
      const name = body.slice(0, sep).trim();
      const value = body.slice(sep + 2).trim();
      out.push({ name: name, value: value, numeric: isPureDigits(value), raw: body });
    }
    i += 8;
  }
}

// 从模型登记表 content 里解析 emoji 表：每个 {{// ... }} 块按行切
function parseModelTable(content) {
  const models = [];
  if (typeof content !== 'string') return models;
  let i = 0;
  for (;;) {
    const start = content.indexOf('{{//', i);
    if (start < 0) return models;
    const end = content.indexOf('}}', start);
    if (end < 0) return models;
    const inner = content.slice(start + 4, end);
    const lines = inner.split(NL);
    for (const lineRaw of lines) {
      const line = lineRaw.trim();
      if (line.length === 0) continue;
      const c = line.indexOf(FULL_COLON);
      if (c <= 0) continue;
      const emoji = line.slice(0, c).trim();
      const label = line.slice(c + 1).trim();
      if (emoji.length > 0 && label.length > 0) {
        models.push({ emoji: emoji, label: label, line: lineRaw, source: end });
      }
    }
    i = end + 2;
  }
}

// 变量条目 -> 卡片（范围卡 / 数字卡）
function buildVarCards(entry) {
  const numeric = parseSetvars(entry.content).filter((s) => s.numeric);
  const used = [];
  const cards = [];
  const consumedNames = [];
  for (const v of numeric) {
    if (consumedNames.indexOf(v.name) >= 0) continue;
    let base = null;
    if (v.name.endsWith('_min')) base = v.name.slice(0, v.name.length - 4);
    else if (v.name.endsWith('_max')) base = v.name.slice(0, v.name.length - 4);
    if (base !== null && base.length > 0) {
      const minName = base + '_min';
      const maxName = base + '_max';
      const minVar = numeric.find((x) => x.name === minName);
      const maxVar = numeric.find((x) => x.name === maxName);
      if (minVar && maxVar) {
        consumedNames.push(minName, maxName);
        cards.push({
          type: 'range',
          identifier: entry.identifier,
          entryName: entry.name,
          base: base,
          min: { name: minName, value: minVar.value, number: Number(minVar.value) },
          max: { name: maxName, value: maxVar.value, number: Number(maxVar.value) },
          swapped: Number(minVar.value) > Number(maxVar.value),
        });
        continue;
      }
    }
    consumedNames.push(v.name);
    cards.push({
      type: 'number',
      identifier: entry.identifier,
      entryName: entry.name,
      name: v.name,
      value: v.value,
      number: Number(v.value),
    });
  }
  for (const v of numeric) used.push(v.name);
  return { cards: cards, numericVars: numeric, allVars: parseSetvars(entry.content), usedNames: used };
}

// ---------- 主解析 ----------

function parsePreset(preset) {
  const issues = [];
  const orders = preset && preset.prompt_order ? preset.prompt_order : [];
  if (orders.length === 0) throw new Error('prompt_order 为空，无法解析');
  const orderArr = orders[0].order || [];
  const prompts = preset.prompts || [];
  const byId = new Map();
  for (const p of prompts) byId.set(p.identifier, p);

  // 1) 按 order 展开，主键用完整 identifier，短号取后 6 位
  const entries = [];
  orderArr.forEach((o, index) => {
    const p = byId.get(o.identifier);
    if (!p) {
      issues.push({ level: 'error', kind: 'prompt-not-found', identifier: o.identifier, index: index });
      return;
    }
    const nameRaw = typeof p.name === 'string' ? p.name : '';
    const name = nameRaw.trim();
    const content = typeof p.content === 'string' ? p.content : '';
    const openCount = countOccurrences(name, ARROW_OPEN);
    const closeCount = countOccurrences(name, ARROW_CLOSE);
    let kind = 'plain';
    if (name.endsWith(ARROW_OPEN) && openCount === 2) kind = 'wrapper-open';
    else if (name.endsWith(ARROW_CLOSE) && closeCount === 2) kind = 'wrapper-close';
    else if (name.endsWith(ARROW_OPEN) && openCount === 1) kind = 'layer-open';
    else if (name.endsWith(ARROW_CLOSE) && closeCount === 1) kind = 'layer-close';
    else if (openCount > 0 || closeCount > 0) {
      issues.push({ level: 'warn', kind: 'arrow-name-not-matching-any-pattern', identifier: p.identifier, name: name });
    }
    entries.push({
      index: index,
      identifier: p.identifier,
      shortId: p.identifier.slice(Math.max(0, p.identifier.length - 6)),
      nameRaw: nameRaw,
      name: name,
      enabled: o.enabled === undefined ? p.enabled : o.enabled,
      promptEnabled: p.enabled,
      marker: p.marker === true,
      role: p.role,
      systemPrompt: p.system_prompt,
      injectionDepth: p.injection_depth,
      injectionOrder: p.injection_order,
      injectionPosition: p.injection_position,
      forbidOverrides: p.forbid_overrides,
      content: content,
      contentLength: content.length,
      kind: kind,
      orderEnabled: o.enabled,
      comment: firstComment(content),
      commentFlat: null,
      region: null,
      card: null,
      models: [],
      modelLabels: [],
      modelExclusive: false,
      lockedOpen: false,
      note: null,
    });
  });
  for (const e of entries) e.commentFlat = e.comment === null ? null : e.comment.trim();

  // 2) 区间识别：栈式配对（层级 / 包裹区）
  const regions = [];
  const stack = [];
  const closeRegion = (region, node) => {
    region.closeIndex = node.index;
    region.closeEntry = node;
    regions.push(region);
  };
  for (const e of entries) {
    if (e.kind === 'layer-open' || e.kind === 'wrapper-open') {
      stack.push({
        kind: e.kind === 'layer-open' ? 'layer' : 'wrapper',
        name: stripArrowEnds(e.name),
        openIndex: e.index,
        openEntry: e,
        closeIndex: -1,
        closeEntry: null,
        children: [],
        cards: [],
        activeCards: [],
        segments: [],
        ownItems: [],
      });
      continue;
    }
    if (e.kind === 'layer-close' || e.kind === 'wrapper-close') {
      const want = e.kind === 'layer-close' ? 'layer' : 'wrapper';
      const wantName = stripArrowEnds(e.name);
      let found = -1;
      for (let s = stack.length - 1; s >= 0; s--) {
        if (stack[s].kind === want && stack[s].name === wantName) {
          found = s;
          break;
        }
      }
      if (found < 0) {
        issues.push({ level: 'error', kind: 'region-close-without-open', identifier: e.identifier, name: e.name, index: e.index });
        e.role = 'region-orphan';
        continue;
      }
      for (let s = stack.length - 1; s > found; s--) {
        issues.push({
          level: 'error',
          kind: 'region-not-closed',
          name: stack[s].name,
          kindOfRegion: stack[s].kind,
          openIndex: stack[s].openIndex,
          closedBy: e.name,
        });
        closeRegion(stack[s], e);
      }
      stack.length = found + 1;
      const region = stack.pop();
      closeRegion(region, e);
      continue;
    }
    if (stack.length > 0) stack[stack.length - 1].children.push(e);
  }
  for (let s = stack.length - 1; s >= 0; s--) {
    issues.push({ level: 'error', kind: 'region-never-closed', name: stack[s].name, kindOfRegion: stack[s].kind, openIndex: stack[s].openIndex });
    const stub = entries[entries.length - 1];
    closeRegion(stack[s], { index: stub ? stub.index : -1, name: '<<EOF>>' });
  }
  regions.sort((a, b) => a.openIndex - b.openIndex);

  const innermostRegion = (index) => {
    let best = null;
    for (const r of regions) {
      if (r.openIndex < index && (r.closeIndex < 0 || index < r.closeIndex)) {
        if (!best || r.openIndex > best.openIndex) best = r;
      }
    }
    return best;
  };
  for (const e of entries) e.region = innermostRegion(e.index);

  // 3) 角色判定
  for (const e of entries) {
    if (e.kind === 'layer-open' || e.kind === 'layer-close') {
      e.role2 = 'layer-locked';
      e.lockedOpen = true;
      continue;
    }
    if (e.region && e.region.kind === 'wrapper') {
      e.role2 = 'wrapper-part';
      continue;
    }
    if (e.region && e.region.kind === 'layer') {
      if (e.name.endsWith(VAR_SUFFIX)) e.role2 = 'var';
      else if (e.name.endsWith(MODEL_SUFFIX)) e.role2 = 'model-registry';
      else if (e.name.endsWith(CARD_ONCE) || e.name.endsWith(CARD_ANY)) e.role2 = 'card-head';
      else e.role2 = 'item';
      continue;
    }
    if (e.kind === 'wrapper-close' || e.kind === 'wrapper-open') {
      e.role2 = 'wrapper-part';
      continue;
    }
    if (e.name.endsWith(VAR_SUFFIX)) {
      e.role2 = 'var';
      issues.push({ level: 'warn', kind: 'var-entry-outside-any-layer', identifier: e.identifier, name: e.name });
      continue;
    }
    if (e.name.endsWith(MODEL_SUFFIX)) {
      e.role2 = 'model-registry';
      issues.push({ level: 'info', kind: 'model-registry-outside-any-layer', identifier: e.identifier, name: e.name });
      continue;
    }
    if (e.marker) {
      e.role2 = 'marker';
      continue;
    }
    e.role2 = 'structure';
  }

  // 4) 层级内部：卡片组装 + 零条目卡片降级
  const layerRegions = regions.filter((r) => r.kind === 'layer');
  const wrapperRegions = regions.filter((r) => r.kind === 'wrapper');
  for (const r of layerRegions) {
    r.entryList = r.children.filter((c) => c.role2 !== 'layer-locked');
    const segs = [];
    let cur = null;
    for (const c of r.entryList) {
      if (c.role2 === 'card-head') {
        const suffix = c.name.endsWith(CARD_ONCE) ? CARD_ONCE : CARD_ANY;
        cur = {
          name: c.name.slice(0, c.name.length - suffix.length).trim(),
          rawName: c.name,
          mode: suffix === CARD_ONCE ? '单选' : '多选',
          suffix: suffix,
          head: c,
          items: [],
        };
        c.cardName = cur.name;
        segs.push({ type: 'card', card: cur });
      } else if (cur) {
        cur.items.push(c);
        c.card = cur;
      } else {
        segs.push({ type: 'item', entry: c });
      }
    }
    const cards = [];
    const blocks = [];
    r.ownItems = [];
    for (const seg of segs) {
      if (seg.type === 'item') {
        blocks.push(seg);
        r.ownItems.push(seg.entry);
        continue;
      }
      if (seg.card.items.length === 0) {
        seg.card.head.role2 = 'item';
        seg.card.head.cardDemoted = true;
        seg.card.head.cardDemoteReason = 'empty';
        seg.card.head.cardName = null;
        r.ownItems.push(seg.card.head);
        blocks.push({ type: 'item', entry: seg.card.head });
      } else {
        cards.push(seg.card);
        blocks.push(seg);
      }
    }
    r.cards = cards;
    r.segments = blocks;
    r.vars = r.entryList.filter((c) => c.role2 === 'var');
    r.registries = r.entryList.filter((c) => c.role2 === 'model-registry');
    r.items = r.entryList.filter((c) => c.role2 === 'item');
    r.hasTab = cards.length > 0 || r.vars.length > 0;
    r.skipReason = r.hasTab ? null : '无卡片且无变量条目';
    for (const c of cards) {
      for (const it of c.items) it.inCard = c.name;
    }
    for (const it of r.ownItems) it.inCard = null;
  }

  // 5) 模型登记表
  const registryEntries = entries.filter((e) => e.role2 === 'model-registry');
  const table = [];
  for (const reg of registryEntries) {
    const rows = parseModelTable(reg.content);
    for (const row of rows) table.push({ emoji: row.emoji, label: row.label, from: reg.identifier, fromName: reg.name });
  }

  // 6) 模型归属
  const modelMembers = [];
  for (const e of entries) {
    if (e.role2 === 'layer-locked' || e.role2 === 'wrapper-part' || e.role2 === 'structure' || e.role2 === 'marker' || e.role2 === 'model-registry') continue;
    const hit = table.filter((m) => e.name.indexOf(m.emoji) >= 0);
    if (hit.length === 0) continue;
    e.models = hit.map((m) => m.emoji);
    e.modelLabels = hit.map((m) => m.label);
    e.modelExclusive = true;
    modelMembers.push(e);
  }
  // 非内容条目（卡片头/层级/结构）命中 emoji 的提示
  for (const e of entries) {
    if (e.models.length > 0) continue;
    const hit = table.filter((m) => e.name.indexOf(m.emoji) >= 0);
    if (hit.length > 0) {
      issues.push({ level: 'warn', kind: 'non-content-entry-matches-model-emoji', identifier: e.identifier, name: e.name, role2: e.role2, emojis: hit.map((m) => m.emoji) });
    }
  }

  // 6.5) 规则 15（收窄版）：模型专属卡片降级
  //      生效条件（**两个都要满足**）：
  //        a) 这张卡片是它所在层级里**唯一的卡片**（r.cards.length === 1）
  //        b) 它名下的条目「全部」都是模型专属条目（每条的模型归属集合 e.models 都非空）
  //      命中后：
  //        - 卡片头降级成该层级的普通条目（cardDemoted=true，cardDemoteReason='model-exclusive-items'）
  //        - 名下条目变成该层级的裸放条目（card=null）→ 没有「原卡片」可用于镜像标注
  //        - 卡片从 r.cards 里移除 → 该层级必然变成「无卡片无变量」→ 按规则 8 不出 tab
  //      收窄的后果（用户裁定）：层级里只要还有别的卡片，本规则一律不动手 —— 那些卡片
  //      照旧是卡片，名下模型专属条目照旧是卡片内条目（仍镜像进「🤖 模型」tab）。
  //      本规则**不删除任何条目**：模型专属条目照旧进全局「🤖 模型」tab（步骤 7 按名字里的
  //      emoji 收集），所以层级 tab 消失不会让这些条目从面板上消失。
  //      本步骤必须排在 6)（模型归属）之后、7)（tab 组装）之前。
  //      同时留下一张全量扫描表 cardModelScan（每个层级每张卡片一行），供报告核对。
  const modelExclusiveDemotions = [];
  const cardModelScan = [];
  const modelExclusiveKeptNotSole = [];
  for (const r of layerRegions) {
    const keptCards = [];
    const demotedCards = [];
    for (const c of r.cards) {
      const modelItems = c.items.filter((it) => it.models.length > 0);
      const nonModelItems = c.items.filter((it) => it.models.length === 0);
      const allModelExclusive = c.items.length > 0 && nonModelItems.length === 0;
      const soleCardInLayer = r.cards.length === 1;
      const demote = allModelExclusive && soleCardInLayer;
      cardModelScan.push({
        layer: r.name,
        card: c.name,
        rawName: c.rawName,
        itemCount: c.items.length,
        modelExclusiveItemCount: modelItems.length,
        modelExclusiveItemNames: modelItems.map((it) => it.name),
        nonModelItemNames: nonModelItems.map((it) => it.name),
        allModelExclusive: allModelExclusive,
        soleCardInLayer: soleCardInLayer,
        layerCardCount: r.cards.length,
        verdict: demote ? 'demoted' : (allModelExclusive ? 'kept-not-sole-card' : 'kept'),
      });
      if (!demote) {
        keptCards.push(c);
        if (allModelExclusive) {
          modelExclusiveKeptNotSole.push({
            layer: r.name,
            card: c.name,
            mode: c.mode,
            headIdentifier: c.head.identifier,
            headName: c.head.name,
            headEnabled: c.head.enabled,
            layerCardCount: r.cards.length,
            layerOtherCards: r.cards.filter((x) => x !== c).map((x) => x.name),
            itemCount: c.items.length,
            itemNames: c.items.map((it) => it.name),
            itemIdentifiers: c.items.map((it) => it.identifier),
            itemModels: c.items.map((it) => it.models.slice()),
          });
        }
        continue;
      }
      demotedCards.push(c);
      c.demotedByModelRule = true;
      c.head.role2 = 'item';
      c.head.cardDemoted = true;
      c.head.cardDemoteReason = 'model-exclusive-items';
      c.head.cardName = null;
      c.head.inCard = null;
      c.head.demotedFromCard = c.name;
      for (const it of c.items) {
        it.card = null;
        it.inCard = null;
        it.demotedFromCard = c.name;
      }
      modelExclusiveDemotions.push({
        layer: r.name,
        card: c.name,
        rawName: c.rawName,
        mode: c.mode,
        headIdentifier: c.head.identifier,
        headName: c.head.name,
        headEnabled: c.head.enabled,
        headContentLength: c.head.contentLength,
        itemCount: c.items.length,
        itemNames: c.items.map((it) => it.name),
        itemIdentifiers: c.items.map((it) => it.identifier),
        itemModels: c.items.map((it) => it.models.slice()),
        openIndex: r.openIndex,
        closeIndex: r.closeIndex,
      });
    }
    if (demotedCards.length === 0) continue;
    r.cards = keptCards;
    // 段落与裸放条目重排：被降级的卡片头 + 名下条目都变成该层级的裸放条目（保持原有的先后顺序）
    const segs2 = [];
    const own = [];
    for (const seg of r.segments) {
      if (seg.type === 'item') {
        segs2.push(seg);
        own.push(seg.entry);
        continue;
      }
      if (seg.card.demotedByModelRule) {
        segs2.push({ type: 'item', entry: seg.card.head });
        own.push(seg.card.head);
        for (const it of seg.card.items) {
          segs2.push({ type: 'item', entry: it });
          own.push(it);
        }
        continue;
      }
      segs2.push(seg);
    }
    r.segments = segs2;
    r.ownItems = own;
    r.items = r.entryList.filter((c) => c.role2 === 'item');
    r.hasTab = r.cards.length > 0 || r.vars.length > 0;
    r.skipReason = r.hasTab ? null : '无卡片且无变量条目';
  }

  // 7) tab 组装
  const tabs = [];
  const skippedLayers = [];
  for (const r of layerRegions) {
    if (!r.hasTab) {
      skippedLayers.push({ name: r.name, reason: r.skipReason, items: r.items.slice(), index: r.openIndex, openIndex: r.openIndex, closeIndex: r.closeIndex });
      continue;
    }
    tabs.push({
      kind: 'layer',
      name: r.name,
      openIndex: r.openIndex,
      closeIndex: r.closeIndex,
      region: r,
      cards: r.cards.map((c) => ({
        name: c.name,
        mode: c.mode,
        headIdentifier: c.head.identifier,
        headEnabled: c.head.enabled,
        items: c.items,
        itemCount: c.items.length,
        source: 'layer',
      })),
      standaloneItems: r.ownItems.filter((x) => x.role2 === 'item'),
      varEntries: r.vars,
      varCards: [],
      modelMembers: [],
    });
  }
  for (const t of tabs) {
    for (const v of t.varEntries) {
      const built = buildVarCards(v);
      v.varCards = built.cards;
      t.varCards.push({ entry: v, cards: built.cards, allVars: built.allVars, numericVars: built.numericVars });
    }
  }

  const modelTab = {
    kind: 'model',
    name: '模型',
    displayName: '🤖 模型',
    global: true,
    cards: table.map((m) => ({ name: m.emoji + ' ' + m.label, emoji: m.emoji, label: m.label, mode: null, items: [], itemCount: 0, source: 'model' })),
    standaloneItems: [],
    varEntries: [],
    varCards: [],
    registryEntries: registryEntries.slice(),
    table: table.slice(),
  };
  for (let i = 0; i < modelTab.cards.length; i++) {
    const card = modelTab.cards[i];
    for (const e of modelMembers) {
      if (e.models.indexOf(card.emoji) < 0) continue;
      const originCard = e.card ? e.card.name : null;
      const originLayer = e.region && e.region.kind === 'layer' ? e.region.name : null;
      card.items.push({
        entry: e,
        identifier: e.identifier,
        name: e.name,
        models: e.models.slice(),
        originLayer: originLayer,
        originCard: originCard,
        originCardDemoted: e.demotedFromCard ? e.demotedFromCard : null,
        originIndex: e.index,
        isMirror: originCard !== null,
        onlyInModelTab: originCard === null,
      });
    }
    card.itemCount = card.items.length;
  }
  tabs.push(modelTab);

  // 8) 锁定条目
  const locked = entries
    .filter((e) => e.role2 === 'layer-locked')
    .map((e) => ({
      identifier: e.identifier,
      shortId: e.shortId,
      name: e.name,
      index: e.index,
      enabled: e.enabled,
      orderEnabled: e.orderEnabled,
      promptEnabled: e.promptEnabled,
      which: e.kind === 'layer-open' ? '层级开' : '层级闭',
      layerName: stripArrowEnds(e.name),
    }));
  const lockedDisabled = locked.filter((x) => x.enabled === false);

  // 9) 结构区
  const structureItems = entries.filter((e) => e.role2 === 'structure');
  const wrapperParts = entries.filter((e) => e.role2 === 'wrapper-part');
  const markers = entries.filter((e) => e.role2 === 'marker');

  // 10) 可达性核查：不在任何 tab、也不是结构区/锁定/marker 的条目
  //     inTab   = 作为「内容条目」出现在某个 tab 里
  //     inPanel = 出现在面板上（含卡片头：它在面板上显示为卡片标题）
  const inTab = new Set();
  const inPanel = new Set();
  const asCardHead = new Set();
  for (const t of tabs) {
    for (const c of t.cards) {
      if (c.headIdentifier) {
        inPanel.add(c.headIdentifier);
        asCardHead.add(c.headIdentifier);
      }
      for (const it of c.items) {
        const id = it.entry ? it.entry.identifier : it.identifier;
        inTab.add(id);
        inPanel.add(id);
      }
    }
    for (const it of t.standaloneItems) {
      inTab.add(it.identifier);
      inPanel.add(it.identifier);
    }
    for (const v of t.varEntries) {
      inTab.add(v.identifier);
      inPanel.add(v.identifier);
    }
  }
  const unreachable = entries.filter((e) => {
    if (inPanel.has(e.identifier)) return false;
    if (e.role2 === 'structure') return false;
    if (e.role2 === 'wrapper-part') return false;
    if (e.role2 === 'layer-locked') return false;
    if (e.role2 === 'marker') return false;
    if (e.role2 === 'model-registry') return false;
    return true;
  });

  // 11) 统计
  const panelEntries = entries.filter((e) => inPanel.has(e.identifier));
  const contentEntries = entries.filter((e) => inTab.has(e.identifier) && (e.role2 === 'item' || e.role2 === 'var'));
  const commented = panelEntries.filter((e) => e.commentFlat !== null && e.commentFlat.length > 0);
  const commentedContent = contentEntries.filter((e) => e.commentFlat !== null && e.commentFlat.length > 0);
  const withCommentFlat = panelEntries.filter((e) => e.commentFlat !== null && e.commentFlat.length > 0);
  const layerTabs = tabs.filter((t) => t.kind === 'layer');
  const allCards = [];
  for (const t of layerTabs) for (const c of t.cards) allCards.push(c);
  const modelMemberIds = [];
  for (const e of modelMembers) if (modelMemberIds.indexOf(e.identifier) < 0) modelMemberIds.push(e.identifier);
  let modelMirrorCount = 0;
  let modelTabOccurrences = 0;
  for (const c of modelTab.cards) {
    for (const it of c.items) {
      modelTabOccurrences++;
      if (it.isMirror) modelMirrorCount++;
    }
  }
  const stats = {
    orderLength: entries.length,
    promptCount: prompts.length,
    layerCount: layerRegions.length,
    wrapperCount: wrapperRegions.length,
    tabCount: tabs.length,
    layerTabCount: layerTabs.length,
    cardCount: allCards.length,
    modelCardCount: modelTab.cards.length,
    panelEntryCount: panelEntries.length,
    contentEntryCount: contentEntries.length,
    cardHeadCount: asCardHead.size,
    varEntryCount: entries.filter((e) => e.role2 === 'var').length,
    varCount: 0,
    rangeCardCount: 0,
    numberCardCount: 0,
    modelCount: table.length,
    modelMemberEntryCount: modelMemberIds.length,
    modelTabOccurrences: modelTabOccurrences,
    modelMirrorCount: modelMirrorCount,
    modelOnlyCount: modelMembers.filter((e) => !e.card).length,
    modelOnlyOccurrences: modelTabOccurrences - modelMirrorCount,
    structureCount: structureItems.length,
    wrapperPartCount: wrapperParts.length,
    markerCount: markers.length,
    lockedCount: locked.length,
    lockedDisabledCount: lockedDisabled.length,
    commentedCount: withCommentFlat.length,
    commentCoverage: panelEntries.length === 0 ? 0 : withCommentFlat.length / panelEntries.length,
    commentedContentCount: commentedContent.length,
    unreachableCount: unreachable.length,
    skippedLayerCount: skippedLayers.length,
    demotedCardHeadCount: entries.filter((e) => e.cardDemoted === true).length,
    emptyCardDemoteCount: entries.filter((e) => e.cardDemoteReason === 'empty').length,
    modelExclusiveCardDemoteCount: entries.filter((e) => e.cardDemoteReason === 'model-exclusive-items').length,
    modelExclusiveCardCount: modelExclusiveDemotions.length,
    modelExclusiveCardItemCount: modelExclusiveDemotions.reduce((n, d) => n + d.itemCount, 0),
    modelExclusiveAllModelCardCount: cardModelScan.filter((c) => c.allModelExclusive).length,
    modelExclusiveKeptNotSoleCount: modelExclusiveKeptNotSole.length,
  };
  for (const t of layerTabs) {
    for (const vc of t.varCards) {
      for (const c of vc.cards) {
        stats.varCount += c.type === 'range' ? 2 : 1;
        if (c.type === 'range') stats.rangeCardCount++;
        else stats.numberCardCount++;
      }
    }
  }

  return {
    meta: {
      characterId: orders[0].character_id,
      orderLength: entries.length,
      promptCount: prompts.length,
      presetName: preset.name,
    },
    entries: entries,
    regions: regions.map((r) => ({
      kind: r.kind,
      name: r.name,
      openIndex: r.openIndex,
      closeIndex: r.closeIndex,
      entryCount: r.closeIndex - r.openIndex + 1,
      innerCount: r.closeIndex - r.openIndex - 1,
      cardCount: r.kind === 'layer' ? r.cards.length : 0,
      varCount: r.kind === 'layer' ? r.vars.length : 0,
      hasTab: r.kind === 'layer' ? r.hasTab : false,
      skipReason: r.kind === 'layer' ? r.skipReason : '结构包裹区',
    })),
    layers: layerRegions.map((r) => ({
      name: r.name,
      openIndex: r.openIndex,
      closeIndex: r.closeIndex,
      hasTab: r.hasTab,
      skipReason: r.skipReason,
      cards: r.cards.map((c) => ({ name: c.name, rawName: c.rawName, mode: c.mode, items: c.items })),
      items: r.items,
      vars: r.vars,
      registries: r.registries,
      entries: r.entryList,
    })),
    wrappers: wrapperRegions.map((r) => ({
      name: r.name,
      openIndex: r.openIndex,
      closeIndex: r.closeIndex,
      entries: r.children.concat([r.openEntry, r.closeEntry]).sort((a, b) => a.index - b.index),
    })),
    tabs: tabs,
    modelTab: modelTab,
    modelTable: table,
    modelMembers: modelMembers,
    modelExclusiveDemotions: modelExclusiveDemotions,
    modelExclusiveKeptNotSole: modelExclusiveKeptNotSole,
    cardModelScan: cardModelScan,
    structure: { items: structureItems, wrapperParts: wrapperParts, markers: markers },
    locked: locked,
    lockedDisabled: lockedDisabled,
    skippedLayers: skippedLayers,
    unreachable: unreachable,
    panelEntries: panelEntries,
    contentEntries: contentEntries,
    commentedEntries: commented,
    commentedContentEntries: commentedContent,
    stats: stats,
    issues: issues,
  };
}


  /* ── 模型卡 / 条目卡的**结构**只有一份实现：src/scripts/_preset-cards.js（构建期内联）──
     🌟 预设设置面板内联的是同一份，所以向导的模型页与预设面板的模型 tab 同构
     （模型卡 = div.kami-card + 可点卡头 + 卡内条目网格），不会再各写一套（契约 §4.4）。 */
  /* ============================================================
 * 预设卡片（模型卡 / 条目卡）共享构建器
 * ------------------------------------------------------------
 * **不是独立脚本**：src/scripts/meta.json 里不登记它（与 _panel-gestures.js 同一个套路）。
 * 构建期由 build/kami-doc.mjs 的 expandPresetCards 内联进 40-预设设置.js 与 50-引导.js，
 * 两个脚本里各留一行占位注释（占位符常量名见 build/kami-doc.mjs 的 PRESET_CARDS_MARK）。
 * ⚠️ 本文件里**不许出现那串占位符字面量**：它会被内联进脚本，二次展开时就会自我复制
 * （展开器里有这条硬检查，撞上会直接构建失败）。
 *
 * 为什么要有这一份：同一枚组件（模型卡、条目卡）此前在两个脚本里各写一套 ——
 * 40 的 modelCardEl / itemEl 与 50 的 renderModel 各建一棵 DOM，于是「同一颗卡片
 * 在两块面板里长得不一样」。注释标记 ⓘ 与开关卡片高亮已经因为同源问题丢过两次
 * （契约 §4.4 的两条硬规则），这里是第三次收口：**只留一份结构实现**。
 *
 * 本模块只建**结构**：
 *   · 不写外观（一个 style 都不碰：颜色/尺寸/圆角全归皮肤，契约 §0）；
 *   · 不挂事件（click / keydown 由调用方自己挂，两块面板的行为不同）；
 *   · 不读全局（文档对象由调用方传进来：40 与 50 各有一个 HDOC，
 *     面板可能建在酒馆宿主页上，所以不能直接用 document）。
 *
 * 三个导出函数的第一个参数都是**文档对象**（doc），其余照调用方给的数据走：
 *   buildModelCard(doc, model, currentEmoji, opts) → div.kami-card
 *       结构 = 卡（data-kami-card-key）+ 卡头按钮（.kami-card-head.kami-btn--ghost，
 *       data-kami-model + aria-pressed + 当前态 .is-on）+ 卡内 grid（.kami-card-body > .kami-grid）
 *   buildItemCard(doc, item, group, opts) → button.kami-item.kami-card（有注释时返回外包层 .kami-item-note）
 *   buildItemsGrid(doc, items, group, opts) → div.kami-grid（里面一排 buildItemCard）
 *   noteMarkEl / noteBoxEl → ⓘ 标记 / 注释正文容器（两块面板 + 引导的变量卡共用同一形状）
 *
 * 入参形状（两块面板的调用方把数据摊成这个形状）：
 *   item  = { name, identifier, enabled, models, comment }
 *   group = { key, mode }   // key → data-kami-card；mode === '单选' 时加 data-kami-single
 *   opts  = {
 *     cardKey,          // 模型卡：写进 data-kami-card-key
 *     lock(item),       // 是否锁死（原生 disabled）—— 40 与本模块默认 item.locked
 *     noteText(item)    // 注释正文来源 —— 默认 item.comment（引导从 noteMap 取）
 *   }
 * ============================================================ */

function pcMake(doc, tag, cls, text) {
  var n = doc.createElement(tag);
  if (cls) { n.className = cls; }
  if (text != null && text !== '') { n.textContent = String(text); }
  return n;
}

/* ── 条目名里的 emoji：摘成卡片角标（**只改显示，预设里的名字一个字不动**） ──
   动机：条目名绝大多数是四个汉字，名字里那枚 emoji + 空格会把紧凑网格（约 110px 宽）
   顶到第二行。把 emoji 搬到卡片角上，文字那一行就整行腾出来了（用户裁定的做法）。

   判定规则：
     · 名字里**任何位置**的 emoji 都按出现顺序摘出来（真机上多 emoji 的名字
       是「开头一枚 + 结尾一枚」，如 `🐋 DS/GLM 💤`，不在开头连成一片）；
     · 一枚 emoji = 区域指示符对（国旗）｜键帽（# * 0-9 + FE0F? + U+20E3）
       ｜Extended_Pictographic + 可选变体选择符(FE0F/FE0E) + 可选肤色修饰符
         + 若干「ZWJ + 上面这一套」（家庭/职业等组合序列）；
     · 角标分配（用户裁定）：第 1 枚 → 左上角 "tl"、第 2 枚 → 右上角 "tr"、
       第 3 枚 → 左下角 "bl"、第 4 枚 → 右下角 "br"；**第 5 枚及以后原样留在文字里**
       （最多 4 个角标，罕见情况也不丢信息）；
     · 摘完剩下的文字（被摘走的位置补一个空格，再合并空白、去掉首尾空白）作为卡片显示文字；
     · 名字本身就全是 emoji（摘完没文字了）→ 一枚都不摘，整名照常显示，免得卡片空掉。
   aria-label 仍用**完整原名**（含 emoji），角标 aria-hidden，读屏不会丢也不会念两遍。 */
var PC_EMOJI_ONE = '(?:\p{Regional_Indicator}{2}|[0-9#*]\uFE0F?\u20E3|\p{Extended_Pictographic}(?:\uFE0F|\uFE0E)?[\u{1F3FB}-\u{1F3FF}]?(?:\u200D(?:\p{Extended_Pictographic}(?:\uFE0F|\uFE0E)?[\u{1F3FB}-\u{1F3FF}]?|[\u{1F3FB}-\u{1F3FF}]))*)';
var PC_EMOJI_ALL_RE = null;
var PC_CORNERS = ['tl', 'tr', 'bl', 'br'];   // 角标最多 4 枚：左上 → 右上 → 左下 → 右下（用户裁定）
/* ⓘ 注释标记占掉右上角（tr）时的 emoji 角表：tl → bl → br（最多 3 枚，第 4 枚起留在文字里） */
var PC_CORNERS_NO_TR = ['tl', 'bl', 'br'];
try { PC_EMOJI_ALL_RE = new RegExp(PC_EMOJI_ONE, 'gu'); }
catch (e) { PC_EMOJI_ALL_RE = null; }   // 老宿主不认 \p{...}/u 时：不摘角标，文字照常显示

function splitNameEmoji(rawName, max) {
  var name = (rawName === null || rawName === undefined) ? '' : String(rawName);
  var empty = { emojis: [], rest: name };
  if (!PC_EMOJI_ALL_RE) { return empty; }
  /* max = 最多摘几枚角标（默认 4）。ⓘ 占右上角时传 3：emoji 从左上角起排，
     摘满 3 枚后其余的整枚留在文字里，信息不丢。 */
  var cap = (max === undefined || max === null) ? PC_CORNERS.length : max;
  var found = [], keep = '', last = 0, m;
  /* 被摘走的 emoji 之间可能漏下一个「连接符」（ZWJ，零宽）——只清**匹配之外**的碎片，
     第 5 枚及以后整枚留在文字里，它内部的 ZWJ 必须原样保住 */
  var clean = function (s) { return s.replace(/‍/g, ''); };
  PC_EMOJI_ALL_RE.lastIndex = 0;
  while ((m = PC_EMOJI_ALL_RE.exec(name))) {
    if (!m[0]) { PC_EMOJI_ALL_RE.lastIndex++; continue; }
    keep += clean(name.slice(last, m.index));
    if (found.length < cap) { found.push(m[0]); }
    else { keep += m[0]; }          // 第 5 枚及以后：留在文字里
    keep += ' ';                    // 被摘走的位置补个空格，两边文字不会被粘到一起
    last = m.index + m[0].length;
  }
  keep += clean(name.slice(last));
  var rest = keep.replace(/[\s​]+/g, ' ').replace(/^ | $/g, '');
  if (!found.length || !rest) { return empty; }
  return { emojis: found, rest: rest };
}

/* ── 注释查看（没有注释就什么都别显示） ──
   2026-09-21 用户裁定改版：条目卡里的 ⓘ 从「名字后面的行内记号」变成**右上角角标**
   （顶掉原来留给第 2 枚 emoji 的位置，见 buildItemCard）—— 行内记号会把窄卡片
   （面板网格里约 100–150px）里的条目名挤到换行，同一行的卡片因此被撑高。
   卡片头里的 ⓘ（卡片组标题、变量卡）仍是行内记号：那一行宽，不会挤到名字。
   做法：
     · 标记 = 名字后面一枚 ⓘ，占一格的宽度（.kami-card-note 是契约 §4.2 已登记的类名，
       用 data-kami-note-mark 与展开出来的正文区分，不新增类名）；
