            warn('弹窗失败：' + ((e && e.message) || e));
            toast('warning', '发现新版本 ' + remote.version + '，但弹窗没弹出来（详见日志）', 8000);
            resolve(last);
          });
        });
      });
    })['catch'](function (e) {
      last.ok = false;
      last.error = (e && e.message) || String(e);
